insert into public.luminaria_bot_card_semantics(card_id, title, scene, keywords, clues, title_en, scene_en, keywords_en, clues_en) values
  ('001-abs.webp', 'Завтрак в холодильнике', 'Девушка открывает холодильник и видит внутри море с волнами; на краю полки спокойно сидит рыба в костюме с портфелем.', 'холодильник море волны вода рыба костюм портфель девушка кухня завтрак', ARRAY['Утро началось с прилива на кухне', 'На работу сегодня можно уплыть']::text[], 'Ocean in the Fridge', 'A young woman opens her refrigerator to find an ocean with rolling waves; a fish in a business suit sits on a shelf with a briefcase.', 'ocean, fridge, young, woman, opens, refrigerator, find, rolling, waves, fish, business, suit, sits, shelf, briefcase', ARRAY['The kitchen woke up with a tide', 'You could sail to work from here']::text[]),
  ('001-card.webp', 'Радужный мост', 'Белое крылатое существо летит над радужным мостом среди планет, пока из облаков за ним наблюдает огромное око.', 'крылья, белое существо, радужный мост, планеты, облака, огромное око, небо', ARRAY['На переправе сегодня проверяют даже мысли', 'Кто-то слишком внимательно следит за полётами']::text[], 'Rainbow Bridge', 'A white winged creature flies above a rainbow bridge among planets while a giant eye watches from the clouds.', 'winged creature, rainbow bridge, planets, clouds, giant eye, sky', ARRAY['At this crossing even thoughts are inspected', 'Someone is watching the flights a little too closely']::text[]),
  ('001-cos.webp', 'Парковка на Сатурне', 'Крошечный астронавт пытается припарковать красный луноход между двумя тележками в супермаркете на кольце Сатурна; инопланетянка-кассирша сканирует плавающую планету.', 'Сатурн, кольца планеты, астронавт, красный луноход, парковка, супермаркет, инопланетянка, касса', ARRAY['Место у входа занято до следующего оборота', 'Когда за хлебом пришлось кружить целую вечность']::text[], 'Parking on Saturn', 'A tiny astronaut tries to park a red rover between shopping carts in a supermarket on Saturn''s rings while an alien cashier scans a floating planet.', 'Saturn, rings, astronaut, red rover, parking, supermarket, alien cashier', ARRAY['The spot by the entrance is taken for another orbit', 'A quick grocery run took an eternity of circling']::text[]),
  ('001-meme.webp', 'Это нормально', 'Пёс спокойно сидит с чашкой чая в кафе, которое уже захлестнула огненная лава из вулкана.', 'это нормально, this is fine, пёс, собака, чай, чашка, кафе, огонь, лава, вулкан', ARRAY['Когда отчёт горит, но совещание по расписанию', 'Уровень тревоги: заварить ещё одну чашку']::text[], 'This Is Fine', 'A dog calmly drinks tea in a cafe as fiery lava from a volcano floods the room.', 'fine, dog, calmly, drinks, tea, cafe, fiery, lava, volcano, floods, room', ARRAY['The report is on fire, but the meeting is on schedule', 'Anxiety level: brew another cup']::text[]),
  ('002-abs.webp', 'Дождь на кассе', 'Покупатели стоят у кассы с корзинами, а по ленте вместо продуктов едут сердитые дождевые облака.', 'магазин супермаркет касса кассовая лента облака дождь покупатели корзины продавец', ARRAY['Погоду пробили отдельным чеком', 'Очередь задержалась из-за осадков']::text[], 'Storm Clouds at Checkout', 'Shoppers wait at a supermarket checkout while angry rain clouds ride the conveyor belt instead of groceries.', 'storm, clouds, checkout, shoppers, wait, supermarket, angry, rain, ride, conveyor, belt, groceries', ARRAY['They charged separately for the weather', 'The queue stalled because of a shower']::text[]),
  ('002-card.webp', 'Дождливый город', 'Женщина с прозрачным зонтом идёт по мокрой городской улице, где огни отражаются в лужах и дождь смягчает силуэты домов.', 'женщина, прозрачный зонт, дождь, город, мокрая улица, лужи, отражения', ARRAY['Прогноз обещал встречу с собственным отражением', 'Город решил сегодня говорить только шёпотом']::text[], 'Rainy City', 'A woman with a transparent umbrella walks down a wet city street as lights reflect in puddles and rain softens the buildings.', 'woman, clear umbrella, rain, city, wet street, puddles, reflections', ARRAY['The forecast promised a meeting with your reflection', 'The city decided to speak in whispers today']::text[]),
  ('002-cos.webp', 'НЛО на техосмотре', 'Ржавую летающую тарелку осматривает строгий механик-жук с фонариком, пока марсианская семья нервно ждёт у стойки техосмотра.', 'НЛО, летающая тарелка, техосмотр, ржавчина, механик-жук, фонарик, марсианская семья', ARRAY['По гарантии этот полёт уже не починить', 'Когда перед дальней дорогой нашли лишнюю гайку']::text[], 'UFO Inspection', 'A stern beetle mechanic examines a rusty flying saucer with a flashlight while a Martian family waits nervously at the inspection desk.', 'UFO, flying saucer, inspection, rust, beetle mechanic, flashlight, Martian family', ARRAY['That flight is well past its warranty', 'They found one extra bolt before a very long trip']::text[]),
  ('002-meme.webp', 'Женщина кричит на кота', 'Королева за роскошным столом сердито спорит с белым котом, который смотрит на неё совершенно невозмутимо.', 'женщина кричит на кота, woman yelling at cat, королева, белый кот, спор, пир, стол', ARRAY['Когда тебя обвинили в съеденном ужине без доказательств', 'Один говорит громче, другой увереннее']::text[], 'Woman Yelling at a Cat', 'An angry queen argues with an unbothered white cat across a lavish dinner table.', 'woman, yelling, cat, angry, queen, argues, unbothered, white, lavish, dinner, table', ARRAY['Accused of eating dinner without a shred of evidence', 'One side speaks louder; the other is more certain']::text[]),
  ('003-abs.webp', 'Автобус без конечной', 'Переполненный автобус растянулся вверх бесконечной лестницей; пассажиры сидят на ступенях между дверями и окнами.', 'автобус салон пассажиры лестница ступеньки общественный транспорт дорога', ARRAY['Следующая остановка где-то этажом выше', 'Проезд оплачивается после подъёма']::text[], 'Endless Staircase Bus', 'A crowded bus stretches upward into an endless staircase with passengers sitting on steps between its doors and windows.', 'endless, staircase, bus, crowded, stretches, upward, passengers, sitting, steps, doors, windows', ARRAY['The next stop is one floor higher', 'Pay your fare after the climb']::text[]),
  ('003-card.webp', 'Неоновый гонщик', 'Мотоциклист мчится на похожем на дракона неоновом байке через яркий розово-зелёный город будущего.', 'мотоциклист, неоновый байк, дракон, город, розовый, зелёный, скорость', ARRAY['Такси снова слишком буквально поняло слово огонь', 'На этом маршруте правила дорожного движения сдаются первыми']::text[], 'Neon Rider', 'A motorcyclist races on a dragon-shaped neon bike through a bright pink and green futuristic city.', 'motorcycle, neon bike, dragon, future city, pink, green, speed', ARRAY['The taxi took the word fire far too literally again', 'Traffic rules surrender first on this route']::text[]),
  ('003-cos.webp', 'Луна на вынос', 'Космический курьер на реактивном велосипеде везёт маленькую Луну в бумажном пакете мимо гигантской Земли, вид сбоку.', 'Луна, Земля, курьер, бумажный пакет, реактивный велосипед, доставка, космос', ARRAY['Заказ прибудет до наступления темноты', 'Когда размер порции не уточнили при оформлении']::text[], 'Moon Delivery', 'A space courier on a rocket bicycle carries a small moon in a paper bag past an enormous Earth.', 'moon, Earth, courier, paper bag, rocket bicycle, delivery, space', ARRAY['Your order will arrive before nightfall', 'Nobody specified the serving size at checkout']::text[]),
  ('003-meme.webp', 'Неверный парень', 'Парень на прогулке оборачивается вслед ожившему розовому пончику на каблуках, пока его спутница смотрит с упрёком.', 'неверный парень, distracted boyfriend, парень, девушка, пончик, каблуки, ревность, улица', ARRAY['Когда обещал экономить, но мимо прошла пекарня', 'Новый приоритет заметили раньше, чем он успел объясниться']::text[], 'Distracted Boyfriend', 'A man turns to stare at a living pink doughnut in heels while his girlfriend watches in disbelief.', 'distracted, boyfriend, man, turns, stare, living, pink, doughnut, heels, girlfriend, watches, disbelief', ARRAY['He promised to save money, then passed the bakery', 'She noticed his new priority before he could explain']::text[]),
  ('004-abs.webp', 'Пробка на кактусе', 'Мужчина с лейкой поливает балконный кактус, на котором вместо колючек выросла плотная автомобильная пробка.', 'кактус балкон лейка машина автомобили пробка дорожное движение растение дом', ARRAY['Даже поливать приходится по расписанию движения', 'Здесь затор вырос прямо в горшке']::text[], 'Traffic Jam Cactus', 'A man waters his balcony cactus, where a dense traffic jam has grown instead of thorns.', 'traffic, jam, cactus, man, waters, balcony, dense, has, grown, thorns', ARRAY['Even watering is subject to traffic rules', 'A jam grew right in the flowerpot']::text[]),
  ('004-card.webp', 'Огненная гора и кристалл', 'Над тёмным морем сталкиваются красный извергающийся вулкан и высокая серебристая кристальная башня.', 'вулкан, красная лава, кристальная башня, тёмное море, огонь, скалы', ARRAY['Соседи снова спорят о температуре в комнате', 'Один берег разгорячился, другой держит лицо']::text[], 'Fire Mountain and Crystal', 'A red erupting volcano and a tall silver crystal tower face each other across a dark sea.', 'volcano, red lava, crystal tower, dark sea, fire, rocks', ARRAY['The neighbors are arguing about the room temperature again', 'One shore is furious; the other keeps a cool face']::text[]),
  ('004-cos.webp', 'Кот-пилот в отпуске', 'Уставший кот в скафандре лежит в гамаке между двумя астероидами, а автопилот корабля крутит вокруг него лапшу.', 'кот, космонавт, скафандр, гамак, астероиды, корабль, автопилот, лапша, отпуск', ARRAY['Пусть смена сама разберётся с маршрутом', 'Наконец-то выходной на самой тихой орбите']::text[], 'Cat on Vacation', 'A tired cat in a spacesuit lounges in a hammock between asteroids while a ship''s autopilot twirls noodles around it.', 'cat, astronaut, spacesuit, hammock, asteroids, spaceship, autopilot, noodles', ARRAY['Let the next shift figure out the route', 'At last a day off on the quietest orbit']::text[]),
  ('004-meme.webp', '6–7', 'Подросток в баскетбольном зале делает жест шесть-семь, а ожившие цифры и игрок у кольца создают полный хаос.', 'шесть-семь, 6-7, six seven, подросток, жест руками, баскетбол, кольцо, цифры', ARRAY['Когда ответ на вопрос зависит от настроения табло', 'Счёт матча неожиданно стал главным героем']::text[], 'Six Seven', 'A teenager makes the six-seven gesture in a basketball gym as living numbers and players cause chaos.', 'six, seven, teenager, makes, gesture, basketball, gym, living, numbers, players, cause, chaos', ARRAY['The answer depends on the scoreboard''s mood', 'The match score stole the whole show']::text[]),
  ('005-abs.webp', 'Дедлайн на ножках', 'Офисный работник тянется к убегающим часам на ножках за стеклянной стеной высотного здания.', 'дедлайн срок часы будильник ноги офис работа мужчина стекло высотка погоня', ARRAY['Сроки опять быстрее сотрудников', 'Поймать время руками не получилось']::text[], 'Runaway Deadline', 'An office worker reaches for a clock running away on little legs behind the glass wall of a tower.', 'runaway, deadline, office, worker, reaches, clock, running, away, legs, glass, wall, tower', ARRAY['Deadlines are faster than the employees again', 'Nobody managed to catch time by hand']::text[]),
  ('005-card.webp', 'Садовник облаков', 'Человек на крыше поливает из ведра облака в форме птиц, парящие над городом, а из окна за ним наблюдают.', 'крыша, человек, ведро, полив, облака-птицы, город, окно', ARRAY['У погоды появился очень старательный садовник', 'Крылья требуют ухода чаще, чем комнатные растения']::text[], 'Cloud Gardener', 'A person on a roof waters bird-shaped clouds with a bucket above a city while someone watches from a window.', 'roof, person, bucket, watering, bird clouds, city, window', ARRAY['The weather hired a very diligent gardener', 'Wings need more care than houseplants']::text[]),
  ('005-cos.webp', 'Похищение коровы вверх ногами', 'Зелёные пришельцы спорят, как поднять корову в луче НЛО, пока корова сама тянет тарелку за шнурок как воздушный шар.', 'корова, НЛО, летающая тарелка, зелёные пришельцы, луч похищения, верёвка, воздушный шар', ARRAY['Похитители не учли, кто здесь держит поводок', 'Когда жертва сама решила выбрать направление']::text[], 'Cow Abduction Gone Wrong', 'Green aliens argue over how to lift a cow with a UFO beam while the cow pulls the saucer by a string like a balloon.', 'cow, UFO, flying saucer, green aliens, abduction beam, string, balloon', ARRAY['The kidnappers forgot who was holding the leash', 'The victim decided where the trip would go']::text[]),
  ('005-meme.webp', 'Doge', 'Пёс с царственным видом сидит на огромной горе печенья высоко над облаками и горами.', 'Doge, доге, собака сиба-ину, пёс, печенье, трон, гора, король', ARRAY['Очень богат, много хруста, вау', 'Бюджет на лакомства опять превысил бюджет королевства']::text[], 'Doge', 'A regal dog sits on a mountain of cookies high above the clouds.', 'doge, regal, dog, sits, mountain, cookies, high, clouds', ARRAY['Much wealth, many crunches, wow', 'The treat budget surpassed the kingdom''s entire treasury']::text[]),
  ('006-abs.webp', 'Прачечная с ужином', 'Девочка смотрит в огромную стиральную машину, внутри которой семья ужинает за накрытым столом среди вращающейся воды.', 'прачечная стиральная машина барабан семья ужин стол девочка вода бельё', ARRAY['Семейный вечер поставили на отжим', 'На ужин лучше не приходить в белом']::text[], 'Dinner in the Washing Machine', 'A girl looks into a giant washing machine where a family eats dinner at a set table amid swirling water.', 'dinner, washing, machine, girl, looks, family, eats, set, table, amid, swirling, water', ARRAY['Family dinner was put on the spin cycle', 'Do not wear white to this meal']::text[]),
  ('006-card.webp', 'Шахматное поле', 'На чёрно-белом поле стоят огромная коронованная шахматная фигура и красный шатёр со спящим человеком.', 'шахматы, чёрно-белое поле, корона, фигура, красный шатёр, спящий человек', ARRAY['Королевство поставило партию на паузу ради сна', 'Даже пешка иногда мечтает о короне']::text[], 'Chessboard Field', 'An enormous crowned chess piece and a red tent with a sleeping person stand on a black-and-white chessboard.', 'chessboard, black and white field, crown, chess piece, red tent, sleeping person', ARRAY['The kingdom paused the game for a nap', 'Even a pawn sometimes dreams of a crown']::text[]),
  ('006-cos.webp', 'Чёрная дыра для мусора', 'Дворник-робот метёт космический мусор прямо в крошечную чёрную дыру, которая недовольно выплёвывает носок и банановую кожуру.', 'робот-дворник, метла, космический мусор, чёрная дыра, носок, банановая кожура', ARRAY['Даже бездна отказалась принимать такой хлам', 'Генеральная уборка зашла слишком далеко']::text[], 'Robot Sweeps a Black Hole', 'A janitor robot sweeps space junk into a tiny black hole that spits out a sock and a banana peel in disgust.', 'janitor robot, space junk, black hole, sock, banana peel, broom', ARRAY['Even the abyss refused to take this rubbish', 'Spring cleaning went a little too far']::text[]),
  ('006-meme.webp', 'Grumpy Cat', 'Ворчливый кот хмурится на трибуне, пока под ним улыбающиеся облака участвуют в праздничном конкурсе.', 'Grumpy Cat, грустный кот, сердитый кот, облака, улыбки, конкурс, недовольство', ARRAY['Когда даже небо предлагает улыбнуться для фото', 'Жюри заранее поставило всем неудовлетворительно']::text[], 'Grumpy Cat', 'A scowling cat sits at a podium while smiling clouds take part in a festive contest below.', 'grumpy, cat, scowling, sits, podium, smiling, clouds, take, part, festive, contest', ARRAY['Even the sky asked for a smile in the photo', 'The judge gave everyone a failing grade in advance']::text[]),
  ('007-abs.webp', 'Тень на почте', 'На почте пожилая женщина показывает отделению самостоятельную тёмную тень, а рядом ждёт юноша с посылкой.', 'почта почтовое отделение тень женщина посылка коробка очередь письмо', ARRAY['Отправитель пришёл отдельно от себя', 'Эту посылку не завернёшь в бумагу']::text[], 'A Shadow at the Post Office', 'An elderly woman presents her independent dark shadow at the post office while a young man waits with a parcel.', 'shadow, post, office, elderly, woman, presents, independent, dark, young, man, waits, parcel', ARRAY['The sender arrived separately from himself', 'This parcel cannot be wrapped in paper']::text[]),
  ('007-card.webp', 'Зубастый цветок в пещере', 'В глубокой пещере вырос огромный зубастый цветок-гриб, вокруг которого собрались зрители и лежат кости.', 'пещера, зубастый цветок, гриб, зрители, скелеты, кости, пасть', ARRAY['Ботанический кружок опять забыл правила безопасности', 'На это представление лучше не покупать места у сцены']::text[], 'Toothy Flower in a Cave', 'An enormous carnivorous flower shaped like a mushroom grows in a deep cave among spectators and scattered bones.', 'cave, toothy flower, mushroom, spectators, skeletons, bones, mouth', ARRAY['The botany club forgot the safety rules again', 'Best not buy a front-row seat for this show']::text[]),
  ('007-cos.webp', 'Экзамен на невесомость', 'Космическая школа: маленький инопланетянин сдаёт экзамен по плаванию в воздухе, а учитель-осьминог ставит оценки щупальцами.', 'инопланетянин, космическая школа, экзамен, невесомость, плавание в воздухе, учитель-осьминог', ARRAY['Шпаргалка уплыла раньше начала урока', 'Когда контрольная буквально не даёт опереться на пол']::text[], 'School in Zero Gravity', 'A little alien takes a swimming exam in midair while an octopus teacher grades with its tentacles.', 'space school, alien student, swimming, zero gravity, octopus teacher, tentacles, exam', ARRAY['The cheat sheet floated away before class began', 'The test literally left nobody with a foot on the floor']::text[]),
  ('007-meme.webp', 'Nyan Cat', 'Пиксельный кот с радужным хвостом летит сквозь космическую прачечную между планетами и стиральными машинами.', 'Nyan Cat, ньян-кэт, пиксельный кот, радужный след, космос, планеты, стиральная машина', ARRAY['Режим стирки: бесконечное веселье', 'После него даже орбита пахнет конфетами']::text[], 'Nyan Cat', 'A pixel cat with a rainbow trail flies through a cosmic laundromat among planets and washing machines.', 'nyan, cat, pixel, rainbow, trail, flies, cosmic, laundromat, among, planets, washing, machines', ARRAY['Wash cycle: endless joy', 'Even the orbit smells of candy afterward']::text[]),
  ('008-abs.webp', 'Причёска из живой изгороди', 'Парикмахерша стрижёт клиенту голову, на которой вырос живой куст с ветками и листьями.', 'парикмахерская причёска волосы куст изгородь ветки листья ножницы зеркало клиент', ARRAY['Стрижка внезапно стала садовыми работами', 'Весна наступила прямо на макушке']::text[], 'Haircut for a Living Shrub', 'A hairdresser trims a client''s head where a living bush with leaves and branches has grown.', 'haircut, living, shrub, hairdresser, trims, client, head, bush, leaves, branches, has, grown', ARRAY['The haircut became a gardening job', 'Spring arrived right on top of his head']::text[]),
  ('008-card.webp', 'Орк в космосе', 'Зелёный орк в космическом шлеме плывёт среди астероидов; внутри его скафандра сияет маленькая планета.', 'орк, космонавт, шлем, скафандр, маленькая планета, астероиды, космос', ARRAY['Багаж на орбиту оказался куда тяжелее нормы', 'Внутренний мир сегодня прошёл техосмотр']::text[], 'Orc in Space', 'A green orc in a space helmet floats among asteroids with a small glowing planet inside his suit.', 'green orc, space helmet, asteroids, spacesuit, glowing planet', ARRAY['The baggage allowance for orbit was surprisingly strict', 'His inner world passed its inspection today']::text[]),
  ('008-cos.webp', 'Ракета на каблуках', 'Высокая серебряная ракета на блестящих каблуках уверенно шагает по подиуму из лунной пыли; астронавты фотографируют её снизу.', 'ракета, каблуки, лунный подиум, космическая мода, астронавты, фотоаппараты', ARRAY['Взлёт отложили ради выхода на дорожку', 'Когда двигатель решил сначала произвести впечатление']::text[], 'Rocket on the Runway', 'A tall silver rocket wearing shiny high heels strides down a lunar dust runway while astronauts photograph it.', 'silver rocket, high heels, catwalk, moon dust, astronauts, fashion', ARRAY['Launch was postponed for a walk down the runway', 'The engine wanted to make an entrance first']::text[]),
  ('008-meme.webp', 'Keyboard Cat', 'Кот в смокинге играет на клавишах пианино внутри лифта, который стремительно падает между домами.', 'Keyboard Cat, кот за клавиатурой, кот-пианист, пианино, лифт, падение, смокинг', ARRAY['Музыкант доиграет даже на первом этаже', 'Когда сопровождение звучит драматичнее самой поездки']::text[], 'Keyboard Cat', 'A tuxedo cat plays piano inside an elevator falling between buildings.', 'keyboard, cat, tuxedo, plays, piano, elevator, falling, buildings', ARRAY['The musician will finish the song on the ground floor', 'The soundtrack is more dramatic than the ride']::text[]),
  ('009-abs.webp', 'Ключ от подъезда', 'Жилец на наружной лестнице пытается открыть дверь гигантским золотым ключом, пока рядом наблюдает кот.', 'ключ золотой огромный дверь подъезд лестница дом мужчина кот замочная скважина', ARRAY['Для этой двери потребуется помощь грузчиков', 'Путь домой неожиданно стал тяжёлым']::text[], 'Giant Key at the Door', 'A resident on an outside staircase tries to open a door with a giant golden key while a cat watches.', 'key, door, resident, staircase, tries, open, golden, cat, watches', ARRAY['Moving this doorway will require a crew', 'The route home became unexpectedly heavy']::text[]),
  ('009-card.webp', 'Дракон на лунном шаре', 'Маленький красный дракон сидит на золотом воздушном шаре в форме луны среди звёзд и небесных серпов.', 'красный дракон, золотой лунный шар, звёзды, полумесяц, небо', ARRAY['Первый полёт получился удивительно тихим', 'Когда домик на небе наконец научился летать']::text[], 'Dragon on a Moon Balloon', 'A tiny red dragon rides a golden balloon shaped like the moon among stars and crescents.', 'red dragon, moon balloon, stars, crescents, golden balloon, sky', ARRAY['The first flight was strangely quiet', 'The little house in the sky finally learned to fly']::text[]),
  ('009-cos.webp', 'Завтрак у квазара', 'За кухонным столом на орбите пожилая инопланетянка жарит яичницу на мини-квазаре, а яйца улетают в открытый иллюминатор.', 'квазар, пожилая инопланетянка, яичница, яйца, космическая кухня, иллюминатор, орбита', ARRAY['Завтрак получился горячее любой плиты', 'Пока чайник кипит, омлет уже покинул кухню']::text[], 'Quasar Breakfast', 'An elderly alien fries eggs on a miniature quasar at an orbital kitchen table while the eggs fly toward an open porthole.', 'alien grandmother, fried eggs, quasar, orbital kitchen, porthole, breakfast', ARRAY['Breakfast came out hotter than any stove could manage', 'The omelet left the kitchen before the kettle boiled']::text[]),
  ('009-meme.webp', 'Longcat', 'Невероятно длинный белый кот растянулся мостом между двумя скалами над рекой молока.', 'Longcat, длиннокот, длинный кот, мост, река молока, скалы, водопад', ARRAY['Строительство переправы доверили самому гибкому соседу', 'Конец очереди уже на другом берегу']::text[], 'Longcat', 'An impossibly long white cat stretches between cliffs to form a bridge over a river of milk.', 'longcat, impossibly, long, white, cat, stretches, cliffs, form, bridge, river, milk', ARRAY['They hired the most flexible neighbor to build the crossing', 'The end of the line is already on the other shore']::text[]),
  ('010-abs.webp', 'Суп с целым городом', 'Двое взрослых заглядывают в огромную тарелку супа, где вместо овощей плавает освещённый миниатюрный город.', 'суп тарелка ложка город дома улицы еда кухня мужчина женщина', ARRAY['На обед подали целый район', 'Тут даже бульвару не хватает соли']::text[], 'City in the Soup', 'Two adults peer into a giant bowl of soup where a lit miniature city floats instead of vegetables.', 'city, soup, adults, peer, bowl, lit, miniature, floats, vegetables', ARRAY['A whole neighborhood was served for lunch', 'Even the boulevard could use more salt']::text[]),
  ('010-card.webp', 'Пикник на луне', 'Дети и кролики устроили пикник на фиолетовом лунном камне под огромной планетой с кольцами.', 'дети, кролики, пикник, лунный камень, фиолетовый, кольцевая планета', ARRAY['На выходных соседняя планета зовёт на чай', 'Скатерть забыли, зато вид из окна отменный']::text[], 'Picnic on the Moon', 'Children and rabbits picnic on a purple lunar rock beneath a huge ringed planet.', 'children, rabbits, picnic, purple moon rock, ringed planet, space', ARRAY['The neighboring planet invited us for tea this weekend', 'We forgot the tablecloth, but the view is excellent']::text[]),
  ('010-cos.webp', 'Почтальон-комета', 'Почтальон с огромной сумкой писем едет верхом на комете и бросает конверты в почтовые ящики на крошечных планетах.', 'почтальон, комета, сумка писем, конверты, почтовые ящики, маленькие планеты', ARRAY['Срочная доставка оставляет огненный след', 'Марки приклеили, адреса пришлось искать на лету']::text[], 'Comet Mailman', 'A mail carrier with an enormous bag rides a comet and drops letters into mailboxes on tiny planets.', 'mail carrier, comet, letters, mailboxes, tiny planets, space delivery', ARRAY['Express delivery leaves a fiery trail', 'The stamps were ready; the addresses were found in flight']::text[]),
  ('010-meme.webp', 'Chill Guy', 'Спокойный антропоморфный пёс в сером свитере стоит с руками в карманах среди летающих зонтов и бури.', 'Chill Guy, чилл гай, спокойный парень, пёс, серый свитер, руки в карманах, буря, зонты', ARRAY['Когда вокруг дедлайн, а у тебя внутренний выходной', 'Ветер нервничает за всех сразу']::text[], 'Chill Guy', 'A calm dog in a gray sweater stands with hands in pockets amid flying umbrellas and a storm.', 'chill, guy, calm, dog, gray, sweater, stands, hands, pockets, amid, flying, umbrellas, storm', ARRAY['Everything has a deadline except his inner weekend', 'The wind is nervous enough for everyone']::text[]),
  ('011-abs.webp', 'Elevator', 'Пожилой ботаник стоит у лифта рядом с подсолнухом в галстуке; за открытыми дверями видны разные времена года.', 'лифт ботаник подсолнух цветок галстук двери этажи весна зима времена года', ARRAY['Каждый этаж одет не по сезону', 'Сосед опять придержал дверь листьями']::text[], 'Elevator', 'An elderly botanist presses a lift button and each floor slides past as a different season; one impatient sunflower in a business tie holds the door.', 'elevator, elderly, botanist, presses, lift, button, floor, slides, past, different, season, impatient, sunflower, business, tie, holds, door', ARRAY['Every floor has dressed for a different season', 'The neighbor held the door open with leaves']::text[]),
  ('011-card.webp', 'Улитка в соборе', 'Человек верхом на огромной улитке едет по залу старинного собора, мимо арок и подвешенной птичьей клетки.', 'улитка, всадник, собор, арки, птичья клетка, медленная поездка', ARRAY['Опоздание здесь считается частью паломничества', 'Экспресс прибудет сразу после следующего века']::text[], 'Snail in the Cathedral', 'A person rides an enormous snail through an old cathedral past arches and a hanging birdcage.', 'giant snail, rider, cathedral, arches, birdcage, pilgrimage', ARRAY['Being late is part of the pilgrimage here', 'The express arrives sometime next century']::text[]),
  ('011-cos.webp', 'Планетная пробка', 'Вид сверху: разноцветные летающие тарелки застряли в пробке на орбите крошечного астероидного кольцевого перекрёстка, регулировщик-медуза машет флажками.', 'летающие тарелки, НЛО, пробка, астероид, кольцевой перекрёсток, медуза-регулировщик, флажки', ARRAY['Объезд займёт ещё три оборота', 'Когда даже пустота не спасает от часа пик']::text[], 'Orbital Traffic Jam', 'Colorful flying saucers are stuck in traffic around a tiny asteroid roundabout while a jellyfish traffic officer waves flags.', 'flying saucers, traffic jam, asteroid, roundabout, jellyfish, flags', ARRAY['The detour will take three more orbits', 'Even empty space cannot save you from rush hour']::text[]),
  ('011-meme.webp', 'Crying Cat', 'Рыжий кот с огромными влажными глазами держит пустую миску, пока вокруг него с неба падают рыбы.', 'Crying Cat, плачущий кот, рыжий кот, слеза, миска, рыбы, дождь', ARRAY['Еда почти рядом, но сервис всё равно ужасный', 'Когда вселенная услышала просьбу слишком буквально']::text[], 'Crying Cat', 'A ginger cat with huge wet eyes holds an empty bowl as fish rain from the sky.', 'crying, cat, ginger, huge, wet, eyes, holds, empty, bowl, fish, rain, sky', ARRAY['The food is almost here and the service is still terrible', 'The universe took a request much too literally']::text[]),
  ('012-abs.webp', 'Dentist', 'Пекарь лежит в стоматологическом кресле с открытым ртом, а встревоженный зуб осматривает его через лупу.', 'стоматолог дантист зуб пекарь кресло лупа рот больница хлеб', ARRAY['Пациента проверяет тот, кого обычно проверяют', 'На приёме поменялись местами с диагнозом']::text[], 'Dentist', 'A brave baker reclines in a dental chair while a nervous little tooth examines the dentist through a magnifying glass.', 'dentist, brave, baker, reclines, dental, chair, nervous, tooth, examines, magnifying, glass', ARRAY['The patient was examined by the usual suspect', 'At this appointment the diagnosis changed seats']::text[]),
  ('012-card.webp', 'Подземный поезд грибов', 'Паровоз прибывает на подземную станцию, освещённую огромными светящимися грибами; пассажиры ждут у платформы.', 'паровоз, подземная станция, светящиеся грибы, пассажиры, платформа, пещера', ARRAY['На этой ветке расписание составляют споры', 'Последняя остановка там, где светят шляпки']::text[], 'Underground Mushroom Train', 'A steam train arrives at an underground station lit by huge glowing mushrooms while passengers wait on the platform.', 'steam train, underground station, glowing mushrooms, passengers, platform', ARRAY['The timetable on this line is written in spores', 'Last stop: where the caps glow']::text[]),
  ('012-cos.webp', 'Марсианин в очереди', 'Высокий зелёный марсианин стоит последним в бесконечной очереди за кофе на Земле, держа номерок длиной с шарф.', 'зелёный марсианин, очередь за кофе, Земля, длинный номерок, кафе, ожидание', ARRAY['Уже прошёл несколько световых лет, а заказ ещё не готов', 'Межпланетное терпение проверяют у стойки']::text[], 'Martian Coffee Queue', 'A tall green Martian stands last in an endless coffee line on Earth holding a ticket as long as a scarf.', 'Martian, alien, coffee, queue, Earth, long ticket', ARRAY['He traveled light-years and the order still is not ready', 'Interplanetary patience is tested at the counter']::text[]),
  ('012-meme.webp', 'Moo Deng', 'Маленький блестящий бегемотик с открытой пастью пытается укусить большой зелёный поливочный шланг в зоопарке.', 'Moo Deng, Му Денг, бегемотик, карликовый бегемот, пасть, шланг, зоопарк', ARRAY['Размер маленький, характер на весь вольер', 'Когда полив внезапно оказался личным врагом']::text[], 'Moo Deng', 'A tiny shiny hippo tries to bite a large green garden hose at the zoo.', 'moo, deng, shiny, hippo, tries, bite, green, garden, hose, zoo', ARRAY['Small body, enough attitude for the whole enclosure', 'The sprinkler became a personal enemy']::text[]),
  ('013-abs.webp', 'Library', 'Ночная библиотекарша бережно ставит в банку тишину, пока подросток пытается вернуть грозовую тучу, спрятанную под курткой.', 'библиотека библиотекарь подросток книги тишина банка гроза туча молния', ARRAY['Возврат просрочили до первой грозы', 'В читальном зале снова слишком громко']::text[], 'Library', 'A night librarian stamps a borrowed silence in a glass jar; a teenager tries to return a noisy thunderstorm hidden under his coat.', 'library, night, librarian, stamps, borrowed, silence, glass, jar, teenager, tries, return, noisy, thunderstorm, hidden, coat', ARRAY['The return was overdue by one thunderstorm', 'The reading room is much too loud again']::text[]),
  ('013-card.webp', 'Крепость среди звёзд', 'Мрачная каменная крепость стоит на парящем обломке скалы посреди звёздной галактики.', 'каменная крепость, летающий остров, скала, галактика, звёзды, космос', ARRAY['Соседи снизу снова жалуются на гравитацию', 'Адрес есть, а дороги к нему никто не нашёл']::text[], 'Fortress Among the Stars', 'A dark stone fortress stands on a floating rock in the middle of a starry galaxy.', 'fortress, floating rock, stars, galaxy, dark stone castle', ARRAY['The neighbors downstairs complained about gravity again', 'There is an address, but nobody found the road']::text[]),
  ('013-cos.webp', 'Рыбалка на спутники', 'Космонавт в кресле ловит спутники магнитной удочкой из окна станции, а пойманный спутник клюёт на блестящий круассан.', 'космонавт, удочка, спутники, магнит, космическая станция, круассан, рыбалка', ARRAY['На наживку клюнуло что-то с антеннами', 'Улов опять требует обновления прошивки']::text[], 'Fishing for Satellites', 'An astronaut in a chair fishes for satellites through a station window with a magnetic rod and a shiny croissant for bait.', 'astronaut, satellite, fishing rod, magnet, space station, croissant', ARRAY['Something with antennas took the bait', 'The catch needs another firmware update']::text[]),
  ('013-meme.webp', 'Bongo Cat', 'Белый улыбающийся кот отбивает ритм лапами на двух больших барабанах-планетах среди звёзд.', 'Bongo Cat, бонго-кот, белый кот, барабаны, лапы, планеты, космос', ARRAY['У соседей опять репетиция на всю галактику', 'Когда настроение само нашло себе ударные']::text[], 'Bongo Cat', 'A smiling white cat taps a rhythm on two planet-sized drums among the stars.', 'bongo, cat, smiling, white, taps, rhythm, planet, sized, drums, among, stars', ARRAY['The neighbors are rehearsing across the whole galaxy again', 'The mood found its own percussion']::text[]),
  ('014-abs.webp', 'Gym', 'Худой мужчина поднимает крошечную гантель в зале, но его огромная тень поднимает всю стойку с тяжестями.', 'спортзал фитнес гантель тренер мужчина тень сила штанга зеркало', ARRAY['Здесь нагрузку берёт на себя отражение', 'Самая скромная тренировка удивила стены']::text[], 'Gym', 'A shy accountant lifts a tiny dumbbell while his enormous shadow lifts the whole gym; the trainer records a score with a pebble.', 'gym, shy, accountant, lifts, dumbbell, shadow, trainer, records, score, pebble', ARRAY['His reflection did all the heavy lifting', 'The smallest workout impressed the walls']::text[]),
  ('014-card.webp', 'Волшебный вокзал', 'Пёстрая толпа собирается у поезда на ярко освещённом вокзале с высоким сводом и разноцветными вывесками.', 'вокзал, поезд, толпа, свод, вывески, чемоданы, путешествие', ARRAY['Все направления открыты, кроме привычного', 'Время отправления написано мелом на чуде']::text[], 'Magic Train Station', 'A colorful crowd gathers by a train in a brightly lit station with a high vaulted roof and many signs.', 'train station, train, crowd, vaulted roof, signs, luggage, travel', ARRAY['Every destination is open except the familiar one', 'The departure time was chalked on a miracle']::text[]),
  ('014-cos.webp', 'Свадьба двух астероидов', 'Два небольших астероида в фате и бабочке обмениваются кольцами в невесомости, священник-робот держится за букет.', 'астероиды, свадьба, фата, бабочка, обручальные кольца, священник-робот, букет, невесомость', ARRAY['Пока нас не разлучит столкновение', 'Церемонию пришлось привязать к орбите']::text[], 'Asteroid Wedding', 'Two small asteroids in a veil and bow tie exchange rings in zero gravity while a robot officiant clings to a bouquet.', 'asteroids, wedding, veil, bow tie, rings, zero gravity, robot', ARRAY['Until collision do us part', 'They had to tie the ceremony to its orbit']::text[]),
  ('014-meme.webp', 'Popcat', 'Кот с неестественно широко открытой пастью вскрикивает перед будильником в спальне.', 'Popcat, попкэт, кот, открытая пасть, крик, будильник, спальня', ARRAY['Пять минут сна закончились очень громко', 'Когда утро ответило за тебя']::text[], 'Popcat', 'A cat with an unnaturally wide-open mouth yells at an alarm clock in a bedroom.', 'popcat, cat, unnaturally, wide, open, mouth, yells, alarm, clock, bedroom', ARRAY['Five more minutes ended very loudly', 'Morning answered the question for you']::text[]),
  ('015-abs.webp', 'Bakery', 'Хмурый пекарь месит облако в пекарне, а над улицей уже летит огромная буханка с крошками-птицами.', 'пекарня пекарь тесто облако хлеб булка буханка птицы рассвет окно', ARRAY['Аромат поднялся выше крыши', 'Сегодня выпечка не захотела лежать на прилавке']::text[], 'Bakery', 'At dawn a grumpy baker kneads a cloud like dough; the finished bread floats above the neighborhood and crumbs become little birds.', 'bakery, dawn, grumpy, baker, kneads, cloud, dough, finished, bread, floats, neighborhood, crumbs, become, birds', ARRAY['The smell rose above the roof', 'Today''s fresh batch refused to stay on the counter']::text[]),
  ('015-card.webp', 'Великанова тропа', 'Несколько волшебников стоят на длинном языке гигантского каменного лица над сказочным пейзажем и далёким светом.', 'волшебники, огромное лицо, язык, каменная голова, сказочный пейзаж, свет', ARRAY['Путь к истине оказался слишком разговорчивым', 'Пешеходная дорожка сегодня явно что-то скрывает']::text[], 'Giant''s Path', 'Several wizards stand on the long tongue of a giant stone face above a fairy-tale landscape.', 'wizards, giant face, tongue, stone head, fantasy landscape, light', ARRAY['The road to truth proved very talkative', 'This footpath is clearly hiding something']::text[]),
  ('015-cos.webp', 'Дракон-заправщик', 'Космический дракон заправляет межзвёздный автобус из огненного шланга, водитель-пингвин проверяет счётчик топлива.', 'космический дракон, заправка, автобус, огненный шланг, водитель-пингвин, топливо', ARRAY['Полный бак обещает очень жаркую поездку', 'На этой станции чек лучше не поджигать']::text[], 'Dragon Fuels the Space Bus', 'A space dragon fills an interstellar bus with a fiery hose while a penguin driver checks the fuel meter.', 'space dragon, interstellar bus, fire hose, penguin driver, fuel station', ARRAY['A full tank promises a very hot ride', 'Best not set the receipt alight at this station']::text[]),
  ('015-meme.webp', 'Наташа, вставай', 'Четыре разных кота нависают над кроватью и внимательно смотрят на проснувшегося человека в перевёрнутой комнате.', 'Наташа вставай, коты Наташа, четыре кота, кровать, утро, перевёрнутая комната', ARRAY['Дом уже упал, а ты всё ещё спишь', 'Совет директоров требует открыть глаза немедленно']::text[], 'Wake Up Natasha', 'Four cats loom over a bed and stare at a waking person in an upside-down room.', 'wake, natasha, four, cats, loom, bed, stare, waking, person, upside, room', ARRAY['The house has fallen and you are still asleep', 'The board of directors demands open eyes at once']::text[]),
  ('016-abs.webp', 'Crosswalk', 'Регулировщик останавливает поток офисных кресел на колёсиках у пешеходного перехода, пока прохожий ждёт зелёного света.', 'переход зебра регулировщик кресла офисные стулья колёсики знак стоп дорога прохожий', ARRAY['Обеденный перерыв выехал без сотрудников', 'Стулья опять заняли всю полосу']::text[], 'Crosswalk', 'A traffic warden holds up a stop sign to halt a stampede of office chairs crossing for lunch; a human commuter waits patiently.', 'crosswalk, traffic, warden, holds, stop, sign, halt, stampede, office, chairs, crossing, lunch, human, commuter, waits, patiently', ARRAY['The lunch break drove away without its employees', 'The chairs took up the entire lane again']::text[]),
  ('016-card.webp', 'Орк-пекарь', 'Орк-повар держит громадную румяную выпечку в форме дракона над заснеженной деревней.', 'орк, повар, пекарь, выпечка, дракон, зимняя деревня, снег', ARRAY['Ужин решил сначала научиться дышать огнём', 'В этой пекарне корочка считается подвигом']::text[], 'Orc Baker', 'An orc chef holds an enormous browned dragon-shaped pastry above a snowy village.', 'orc, chef, baker, pastry, dragon, snowy village, winter', ARRAY['Dinner decided to learn fire breathing first', 'In this bakery a crust counts as a heroic feat']::text[]),
  ('016-cos.webp', 'Пылесос для созвездий', 'Робот-домработник пылесосит звёздное небо длинной трубой, оставляя на месте созвездий аккуратные пустые квадраты.', 'робот-домработник, пылесос, созвездия, звёздное небо, длинная труба, пустые квадраты', ARRAY['После уборки стало слишком темно для мечтаний', 'Кто-то протёр небосвод до дыр']::text[], 'Vacuuming the Constellations', 'A housekeeper robot vacuums the starry sky with a long hose, leaving neat empty squares where constellations used to be.', 'robot, vacuum cleaner, stars, constellations, sky, empty squares', ARRAY['After the cleaning it was too dark to dream', 'Someone polished holes right through the sky']::text[]),
  ('016-meme.webp', 'Success Kid', 'Малыш с победно сжатым кулаком стоит в воде и держит песочный замок на фоне настоящего замка.', 'Success Kid, успешный малыш, ребёнок, кулак, песочный замок, море, победа', ARRAY['Когда построил дворец до обеда и ещё успел искупаться', 'План на день выполнен с первого кулачка']::text[], 'Success Kid', 'A toddler clenches a triumphant fist in the water while holding a sandcastle before a real castle.', 'success, kid, toddler, clenches, triumphant, fist, water, holding, sandcastle, before, real, castle', ARRAY['Built a palace before lunch and still went swimming', 'The day''s plan succeeded with one tiny fist']::text[]),
  ('017-abs.webp', 'Bank', 'Пожилая женщина получает из банкомата светящиеся полоски вчерашнего заката и складывает их в сумку.', 'банк банкомат женщина пенсионерка деньги закат вчера солнце свет сумка', ARRAY['Сбережения выдали вчерашним вечером', 'На счёте неожиданно нашлось немного света']::text[], 'Bank', 'A cautious retiree withdraws a handful of yesterday from an ATM; small sunset strips spill into her shopping bag.', 'bank, cautious, retiree, withdraws, handful, yesterday, atm, sunset, strips, spill, shopping, bag', ARRAY['Her savings arrived in yesterday''s evening light', 'There was a little daylight left in the account']::text[]),
  ('017-card.webp', 'Слон-гора и колокол', 'Белый зверь с зелёной гривой звонит в бронзовый колокол перед заснеженной горой, похожей на синего слона.', 'белый зверь, зелёная грива, колокол, снежная гора, синий слон, облака', ARRAY['Будильник для горных вершин оказался слишком маленьким', 'Тихий час закончился на другом конце долины']::text[], 'Elephant Mountain and Bell', 'A white beast with a green mane rings a bronze bell before a snowy mountain shaped like a blue elephant.', 'white beast, green mane, bell, snowy mountain, blue elephant, clouds', ARRAY['The alarm clock for mountain peaks was far too small', 'Quiet time ended on the far side of the valley']::text[]),
  ('017-cos.webp', 'Лунный огород', 'Пенсионерка-астронавт поливает лунные грядки из чайника; из серой пыли растут огромные светящиеся огурцы и один зонтик.', 'пенсионерка, астронавт, лунный огород, чайник, грядки, светящиеся огурцы, зонтик', ARRAY['Урожай созреет раньше ближайшего рейса домой', 'Пожалуйста, не наступайте на соседний кратер']::text[], 'Lunar Cucumber Garden', 'A retired astronaut waters moon beds with a kettle while giant glowing cucumbers and one umbrella grow from gray dust.', 'astronaut, moon garden, kettle, glowing cucumbers, umbrella, lunar dust', ARRAY['The harvest will ripen before the next flight home', 'Please do not step on the neighboring crater']::text[]),
  ('017-meme.webp', 'Disaster Girl', 'Девочка с загадочной улыбкой смотрит в камеру, пока за её спиной горит причудливый замок из тостов.', 'Disaster Girl, девочка-катастрофа, девочка, улыбка, пожар, горящий замок, тосты', ARRAY['Когда сказала, что завтрак будет с огоньком', 'Лицо человека, который точно ничего не трогал']::text[], 'Disaster Girl', 'A smiling girl looks at the camera while a strange castle made of toast burns behind her.', 'disaster, girl, smiling, looks, camera, strange, castle, made, toast, burns', ARRAY['She did say breakfast would be exciting', 'The face of someone who definitely touched nothing']::text[]),
  ('018-abs.webp', 'Cinema', 'Из киноэкрана в зал льётся водопад, зрители раскрывают зонты, а работник пытается вытереть воду шваброй.', 'кинотеатр экран фильм вода водопад дождь зрители зонты попкорн швабра', ARRAY['Этот сеанс лучше смотреть в плаще', 'Спецэффекты дошли до последнего ряда']::text[], 'Cinema', 'A cinema usher mops up escaped rain from the movie screen while the audience raises umbrellas and popcorn floats like life rafts.', 'cinema, usher, mops, escaped, rain, movie, screen, audience, raises, umbrellas, popcorn, floats, life, rafts', ARRAY['Better wear a raincoat to this showing', 'The special effects reached the last row']::text[]),
  ('018-card.webp', 'Спящий ледяной гигант', 'Огромный синий ледяной зверь спит среди гор и узорчатого снега, словно сама зима свернулась клубком.', 'синий гигант, ледяной зверь, сон, горы, снег, зима, узоры', ARRAY['Весна пока не решается его будить', 'Самая большая подушка на свете снова замёрзла']::text[], 'Sleeping Ice Giant', 'An enormous blue icy beast sleeps among snowy patterned mountains as though winter curled up for a nap.', 'blue ice giant, sleeping beast, mountains, patterned snow, winter', ARRAY['Spring still does not dare wake him', 'The world''s largest pillow froze again']::text[]),
  ('018-cos.webp', 'Инопланетянин с чемоданом', 'Розовый пришелец тащит через вокзал чемодан, который оказался больше его самого и из которого торчат щупальца и комнатное растение.', 'розовый инопланетянин, огромный чемодан, вокзал, щупальца, комнатное растение, путешествие', ARRAY['Ручная кладь оказалась сильнее хозяина', 'Когда взял в отпуск немного лишнего']::text[], 'Alien with Too Much Luggage', 'A pink alien drags a suitcase bigger than itself through a station; tentacles and a houseplant stick out.', 'pink alien, suitcase, tentacles, houseplant, station, luggage', ARRAY['The carry-on is stronger than its owner', 'Someone packed a little too much for vacation']::text[]),
  ('018-meme.webp', 'Side Eye Chloe', 'Девочка в оранжевом платье косо смотрит на семейный автомобиль, у которого внезапно выросли паучьи ноги.', 'Side Eye Chloe, Хлоя косой взгляд, девочка, автомобиль, паучьи лапы, удивление', ARRAY['Когда родители назвали это обычной поездкой', 'Вопросов больше, чем свободных мест в машине']::text[], 'Side Eye Chloe', 'A girl in an orange dress eyes a family car that has sprouted spider legs.', 'side, eye, chloe, girl, orange, dress, eyes, family, car, has, sprouted, spider, legs', ARRAY['The parents called this a normal road trip', 'More questions than empty seats in the car']::text[]),
  ('019-abs.webp', 'Flower shop', 'Флорист вручает покупателю букет из маленьких дверей, за каждой из которых виден отдельный сад.', 'цветочный магазин флорист букет маленькие двери сад цветы покупатель перчатки', ARRAY['В подарок можно выбрать собственный сад', 'За каждым лепестком оказалось новое место']::text[], 'Flower shop', 'A florist wraps a bouquet of polite little doors, each opening onto a different tiny garden; a customer chooses one with gardening gloves.', 'flower, shop, florist, wraps, bouquet, polite, doors, opening, onto, different, garden, customer, chooses, gardening, gloves', ARRAY['Give someone a garden of their own', 'Behind every petal was another place']::text[]),
  ('019-card.webp', 'Корабль над звёздным морем', 'Зелёный орк и светловолосый спутник плывут на длинном корабле под ночным небом над сияющим космическим морем.', 'орк, светловолосый спутник, длинный корабль, парус, море, звёзды, космос', ARRAY['Навигатор велел держаться второй звезды слева', 'Солёный ветер внезапно пахнет метеоритами']::text[], 'Ship Above the Starry Sea', 'A green orc and a blond companion sail a long ship beneath the night sky across a glowing cosmic sea.', 'green orc, blond companion, ship, starry sea, night sky, space', ARRAY['The navigator said to follow the second star on the left', 'The salty wind suddenly smelled of meteorites']::text[]),
  ('019-cos.webp', 'Космический парикмахер', 'Парикмахер-робот стрижёт комету на вращающемся кресле, собирая длинный огненный хвост в аккуратный пучок.', 'робот-парикмахер, комета, огненный хвост, стрижка, вращающееся кресло, пучок', ARRAY['После салона никто не узнаёт её по следу', 'Только кончики, просила клиентка длиной в полнеба']::text[], 'Comet Haircut', 'A robot hairdresser trims a comet in a spinning chair and ties its long fiery tail into a tidy bun.', 'robot hairdresser, comet, fiery tail, haircut, salon, bun', ARRAY['After the salon nobody recognized her trail', 'Just the ends, said the client who filled half the sky']::text[]),
  ('019-meme.webp', 'Hide the Pain Harold', 'Седой мужчина с натянутой улыбкой сидит за столом на офисном кресле, которое превратилось в колючий кактус.', 'Hide the Pain Harold, Гарольд скрывающий боль, седой мужчина, улыбка, кактус, офис, кресло', ARRAY['Когда работа нравится особенно остро', 'Улыбка согласилась, спина ещё не решила']::text[], 'Hide the Pain Harold', 'A gray-haired man forces a smile at a desk while his office chair turns into a prickly cactus.', 'hide, pain, harold, gray, haired, man, forces, smile, desk, office, chair, turns, prickly, cactus', ARRAY['He really enjoys his job, particularly the sharp bits', 'His smile agreed; his back has not decided']::text[]),
  ('020-abs.webp', 'Shoe repair', 'Сапожник прибивает новую подошву к потёртой радуге и сушит её рядом с грязным ботинком.', 'сапожник ремонт обуви радуга подошва ботинок молоток мастерская', ARRAY['После дождя понадобился ремонт неба', 'Даже ярким вещам иногда нужна новая подошва']::text[], 'Shoe repair', 'A cobbler fits a new sole onto a worn-out rainbow and hangs it above a single muddy boot to dry.', 'shoe, repair, cobbler, fits, sole, onto, worn, rainbow, hangs, single, muddy, boot, dry', ARRAY['The sky needed repairs after the rain', 'Even bright things need a new sole sometimes']::text[]),
  ('020-card.webp', 'Дракон-библиотекарь', 'Красный дракон уснул, обвившись вокруг книжных полок, пока рядом человек спокойно читает при свете лампы.', 'красный дракон, книги, библиотека, полки, читающий человек, лампа, сон', ARRAY['Тише, здесь даже пожар соблюдает тишину', 'Просроченную книгу лучше вернуть до пробуждения']::text[], 'Dragon Librarian', 'A red dragon sleeps curled around bookshelves while a person reads quietly beside a lamp.', 'red dragon, library, bookshelves, person reading, lamp, sleep', ARRAY['Even the fire obeys the silence rule here', 'Return the overdue book before he wakes']::text[]),
  ('020-cos.webp', 'Секретный бутерброд', 'Астронавт прячет бутерброд с огурцом от бдительного инопланетного инспектора под прозрачным шлемом, вид крупным планом.', 'астронавт, бутерброд, огурец, прозрачный шлем, инопланетный инспектор, тайная еда', ARRAY['Контрабанда пахнет обедом', 'Спрятал перекус так надёжно, что теперь не достать']::text[], 'Forbidden Space Sandwich', 'An astronaut hides a cucumber sandwich from a watchful alien inspector beneath a transparent helmet.', 'astronaut, cucumber sandwich, alien inspector, helmet, contraband', ARRAY['The smuggled goods smell like lunch', 'He hid the snack so well he can no longer reach it']::text[]),
  ('020-meme.webp', 'Absolute Cinema', 'Седой режиссёр в пустом кинотеатре восхищённо разводит руками перед экраном с фильмом о танцующем чайнике.', 'Absolute Cinema, абсолютное кино, режиссёр, кинотеатр, экран, танцующий чайник, восторг', ARRAY['Когда бюджет ушёл на один гениальный кадр', 'Зрителей нет, но шедевр уже состоялся']::text[], 'Absolute Cinema', 'A gray-haired director gestures with awe at a film of a dancing kettle in an empty cinema.', 'absolute, cinema, gray, haired, director, gestures, awe, film, dancing, kettle, empty', ARRAY['The entire budget went into one brilliant shot', 'No audience yet, but the masterpiece is complete']::text[]),
  ('021-abs.webp', 'Pharmacy', 'Фармацевт выдаёт женщине в бумажном стаканчике час сна; посетительница прижимает к себе подушку больше себя.', 'аптека фармацевт лекарство сон подушка женщина бумажный стаканчик усталость', ARRAY['Один час отдыха отпускают без рецепта', 'Покупательница принесла собственную постель']::text[], 'Pharmacy', 'A pharmacist dispenses one tiny hour of sleep in a paper cup while a customer carries a pillow larger than herself.', 'pharmacy, pharmacist, dispenses, hour, sleep, paper, cup, customer, carries, pillow, larger, than, herself', ARRAY['One hour of rest requires no prescription', 'The customer brought her own bed']::text[]),
  ('021-card.webp', 'Самурай и белый лис', 'Воин с мечом встречает большого белого многохвостого лиса на ночной улице японского города под полной луной.', 'самурай, меч, белый лис, много хвостов, луна, японская улица, ночь', ARRAY['Дуэль отменили ради очень старого знакомства', 'У этого незнакомца слишком много способов попрощаться']::text[], 'Samurai and White Fox', 'A sword-bearing warrior meets a large white fox with many tails on a moonlit Japanese city street.', 'samurai, sword, white fox, many tails, Japanese street, full moon', ARRAY['The duel was canceled for an old acquaintance', 'This stranger has too many ways to say goodbye']::text[]),
  ('021-cos.webp', 'Балет на астероиде', 'Балерина-робот грациозно танцует на неровном астероиде, а маленькие камни кружатся вокруг неё как публика в театре.', 'робот-балерина, астероид, балет, танец, камни, космический театр', ARRAY['Зрители кружатся быстрее артистки', 'Даже неровная сцена не испортила поклон']::text[], 'Robot Ballerina', 'A robot ballerina dances on an uneven asteroid while little rocks circle her like a theater audience.', 'robot ballerina, asteroid, dancing, rocks, theater audience', ARRAY['The audience spins faster than the performer', 'Even an uneven stage could not spoil the bow']::text[]),
  ('021-meme.webp', 'Monkey Puppet Side Eye', 'Плюшевая обезьянка в жёлтом костюме подозрительно косится в сторону, пока позади рушится громадный торт.', 'Monkey Puppet Side Eye, обезьянка косой взгляд, кукла, жёлтый костюм, торт, подозрение', ARRAY['Когда услышал шум за спиной и решил не уточнять', 'Я ничего не видел, особенно крем на потолке']::text[], 'Side-Eye Monkey Puppet', 'A plush monkey in a yellow suit glances sideways as a giant cake collapses behind it.', 'side, eye, monkey, puppet, plush, yellow, suit, glances, sideways, cake, collapses', ARRAY['He heard a noise behind him and chose not to ask', 'I saw nothing, especially the icing on the ceiling']::text[]),
  ('022-abs.webp', 'Swimming pool', 'Спасатель у бассейна свистит процессии ванн с людьми внутри, синхронно плывущих по дорожкам.', 'бассейн спасатель свисток ванны купание синхронное плавание вода люди', ARRAY['Соревнование перенесли из ванной комнаты', 'За нарушение дорожки сегодня оштрафуют сантехнику']::text[], 'Swimming pool', 'A lifeguard blows a whistle at a neat procession of bathtubs doing synchronized swimming while their owners sit on the edge.', 'swimming, pool, lifeguard, blows, whistle, neat, procession, bathtubs, doing, synchronized, owners, sit, edge', ARRAY['The race moved out of the bathroom', 'The plumbing will be fined for changing lanes']::text[]),
  ('022-card.webp', 'Полет на лунной бабочке', 'Синяя крылатая бабочка несёт мальчика над полем цветов, где вдали видны сказочные планеты.', 'синяя бабочка, мотылёк, мальчик, полёт, цветочное поле, планеты', ARRAY['Билет туда продают только во сне', 'Самый лёгкий транспорт оказался размером с дом']::text[], 'Flight on a Moon Butterfly', 'A large blue butterfly carries a boy above a field of flowers with fantastic planets in the distance.', 'blue butterfly, boy, flight, flowers, fantasy planets, sky', ARRAY['Tickets are sold only in dreams', 'The lightest vehicle turned out to be the size of a house']::text[]),
  ('022-cos.webp', 'НЛО потеряло луч', 'Пилот тарелки растерянно ищет отвалившийся тракторный луч под диваном космического корабля; рядом сидит довольная корова.', 'НЛО, потерянный луч, тракторный луч, диван, пилот, корова, летающая тарелка', ARRAY['Ключи от машины нашлись, а главная функция — нет', 'Пропажа лежала там, где никто не ожидал искать']::text[], 'Lost Tractor Beam', 'A UFO pilot searches under the spaceship sofa for a missing tractor beam while a contented cow sits nearby.', 'UFO, pilot, tractor beam, sofa, spaceship, cow', ARRAY['The keys turned up, but the main feature did not', 'The missing thing was where nobody thought to look']::text[]),
  ('022-meme.webp', 'Roll Safe', 'Хитро улыбающийся мужчина касается виска под дырявой крышей и держит зонт прямо внутри комнаты.', 'Roll Safe, парень у виска, хитрый план, мужчина, зонт, дырявая крыша, дождь', ARRAY['Проблемы с крышей нет, если улица уже дома', 'Гениальное решение появилось на третьей протечке']::text[], 'Roll Safe', 'A sly man taps his temple beneath a leaking roof and holds an umbrella indoors.', 'roll, safe, sly, man, taps, temple, beneath, leaking, roof, holds, umbrella, indoors', ARRAY['There is no roof problem if outdoors is already inside', 'The brilliant solution came after the third leak']::text[]),
  ('023-abs.webp', 'Bookshop', 'Огромная раскрытая книга затягивает продавщицу внутрь страницы, а покупатели держат её за ноги между стеллажами.', 'книжный магазин библиотека книга продавщица страницы ветер покупатели стеллажи', ARRAY['Сюжет слишком увлёк даже продавца', 'Последнюю страницу пришлось спасать всем магазином']::text[], 'Bookshop', 'A bespectacled bookseller is pulled through a page by the wind of an enormous paperback; two customers anchor her by her shoes.', 'bookshop, bespectacled, bookseller, pulled, page, wind, paperback, customers, anchor, shoes', ARRAY['The plot swept away even the bookseller', 'The whole shop had to rescue the last page']::text[]),
  ('023-card.webp', 'Астроном и кот', 'Пожилой астроном с телескопом смотрит на светящиеся созвездия, а рядом сидит кот.', 'астроном, телескоп, кот, звёзды, созвездия, небо, ночь', ARRAY['Помощник уже вычислил, где завтра будет ужин', 'Ответ в небе нашёлся раньше вопроса']::text[], 'Astronomer and Cat', 'An elderly astronomer looks through a telescope at glowing constellations while a cat sits beside him.', 'old astronomer, telescope, constellations, cat, stars', ARRAY['The assistant already calculated tomorrow''s dinner', 'The answer appeared in the sky before the question']::text[]),
  ('023-cos.webp', 'Сон космического кита', 'Огромный звёздный кит спит вертикально в космосе, а на его спине маленькие города разворачивают ночной рынок.', 'космический кит, звёзды, сон, города на спине, ночной рынок, космос', ARRAY['Не будите хозяина, пока открыт базар', 'Целый город качается в такт чужому дыханию']::text[], 'Sleeping Star Whale', 'A giant starry whale sleeps upright in space while small towns set up a night market on its back.', 'whale, stars, space, sleeping, towns, night market', ARRAY['Do not wake the landlord while the market is open', 'An entire city rocks to someone else''s breathing']::text[]),
  ('023-meme.webp', 'Sad Hamster', 'Крошечный хомяк с огромными печальными глазами играет на скрипке в пустом зале старого вокзала.', 'Sad Hamster, грустный хомяк, хомяк, слёзы, скрипка, вокзал, одиночество', ARRAY['Когда твой поезд ушёл, а оркестр остался', 'Самая печальная мелодия на самой маленькой платформе']::text[], 'Sad Hamster', 'A tiny hamster with enormous sorrowful eyes plays violin in an empty old train station.', 'sad, hamster, sorrowful, eyes, plays, violin, empty, train, station', ARRAY['His train left but the orchestra remained', 'The saddest tune on the smallest platform']::text[]),
  ('024-abs.webp', 'Car wash', 'Грозовое облако на крошечной машине въезжает на автомойку и выезжает оттуда сияющим солнцем.', 'автомойка машина автомобиль облако гроза дождь солнце щётки работник', ARRAY['После мойки прогноз резко улучшился', 'Эта машина привезла плохую погоду']::text[], 'Car wash', 'A mechanic watches a tiny thundercloud drive its own car through spinning brushes; at the exit the cloud emerges perfectly sunny.', 'car, wash, mechanic, watches, thundercloud, drive, spinning, brushes, exit, cloud, emerges, perfectly, sunny', ARRAY['The forecast improved after a quick wash', 'This little car brought some terrible weather']::text[]),
  ('024-card.webp', 'Королева оригами', 'Белая королева сидит на троне из острых складчатых форм посреди светлой равнины под тёмным затмением.', 'королева, белое платье, складчатый трон, оригами, затмение, равнина, красная ткань', ARRAY['Королевский указ сложили вчетверо', 'Даже солнце здесь боится помять костюм']::text[], 'Origami Queen', 'A white queen sits on a throne of sharp folded shapes on a pale plain beneath a dark eclipse.', 'queen, origami, folded throne, white plain, eclipse, paper', ARRAY['The royal decree was folded into quarters', 'Even the sun is afraid of wrinkling its suit here']::text[]),
  ('024-cos.webp', 'Пицца на орбите', 'Повар в магнитных ботинках подбрасывает пиццу, которая превращается в вращающуюся мини-галактику с сырными кольцами.', 'повар, пицца, магнитные ботинки, мини-галактика, сырные кольца, орбита', ARRAY['Тесто раскрутилось до размеров меню', 'Когда ужин решил стать отдельной вселенной']::text[], 'Galaxy Pizza', 'A cook in magnetic boots tosses a pizza that turns into a spinning miniature galaxy with rings of cheese.', 'cook, magnetic boots, pizza, galaxy, cheese rings, space', ARRAY['The dough spun beyond the edges of the menu', 'Dinner decided to become a universe of its own']::text[]),
  ('024-meme.webp', 'Ancient Aliens', 'Взволнованный исследователь разводит руки перед гигантской пирамидой из телевизоров, над которой парит тарелка.', 'Ancient Aliens, древние пришельцы, исследователь, пирамида, телевизоры, НЛО, теория', ARRAY['Когда пульт исчез и объяснение нашлось само', 'Наука просила доказательства, а получила антенну']::text[], 'Ancient Aliens', 'An excited researcher spreads his hands before a giant pyramid of televisions with a flying saucer above.', 'ancient, aliens, excited, researcher, spreads, hands, before, pyramid, televisions, flying, saucer', ARRAY['The remote vanished and the explanation found itself', 'Science asked for proof and got an antenna']::text[]),
  ('025-abs.webp', 'Farmers market', 'На рынке торговец продаёт банки, внутри которых шепчут крошечные рты; покупательница слушает одну у прилавка.', 'рынок торговец банка стеклянная банка сплетни рот шёпот покупательница овощи', ARRAY['Новости уже расфасовали по банкам', 'Этот товар лучше не открывать при соседях']::text[], 'Farmers market', 'A vendor stacks gossip in jars while a skeptical shopper holds one to her ear and hears its tiny lips whisper.', 'farmers, market, vendor, stacks, gossip, jars, skeptical, shopper, holds, ear, hears, lips, whisper', ARRAY['The news has already been packed in jars', 'Best not open this purchase near the neighbors']::text[]),
  ('025-card.webp', 'Светящийся хлеб', 'Женщина несёт сияющую буханку по тёмной улице, а у её ног крадётся чёрный кот.', 'женщина, светящийся хлеб, буханка, тёмная улица, чёрный кот, ночь', ARRAY['За этим ужином можно идти без фонаря', 'Соседи попросили оставить кусочек рассвета']::text[], 'Glowing Bread', 'A woman carries a luminous loaf through a dark street while a black cat creeps by her feet.', 'woman, glowing bread, loaf, dark street, black cat, light', ARRAY['You can find dinner without a lantern', 'The neighbors asked for a slice of dawn']::text[]),
  ('025-cos.webp', 'Зонт от метеоритов', 'Деловой пришелец идёт по луне под маленьким зонтом, отбивая им дождь из разноцветных метеоритов.', 'деловой пришелец, зонт, луна, дождь метеоритов, разноцветные камни, защита', ARRAY['Погода опять требует каску вместо прогноза', 'На собеседование пришёл без единой царапины']::text[], 'Meteor Shower Umbrella', 'A businesslike alien walks on the moon beneath a small umbrella against a shower of colorful meteorites.', 'alien, moon, umbrella, meteor shower, colorful meteorites', ARRAY['The forecast calls for a helmet instead', 'He arrived at the interview without a scratch']::text[]),
  ('025-meme.webp', 'Conspiracy Board', 'Детектив в комнате с доской улик и красными нитями пытается раскрыть дело об одной пропавшей носке.', 'Conspiracy Board, доска заговоров, детектив, красные нити, улики, пропавшая носка', ARRAY['Стирка уже закончилась, расследование только началось', 'Все подозреваемые были в одном ящике']::text[], 'Conspiracy Board', 'A detective follows red strings on an evidence board to solve the case of a missing sock.', 'conspiracy, board, detective, follows, red, strings, evidence, solve, case, missing, sock', ARRAY['Laundry is done; the investigation has just begun', 'Every suspect was in the same drawer']::text[]),
  ('026-abs.webp', 'Train platform', 'Уставший скрипач ждёт на перроне поезда из соединённых будильников, который ведёт сонная черепаха в фуражке.', 'вокзал перрон поезд будильники часы черепаха проводник скрипач чемодан', ARRAY['Расписание движется, но очень неспешно', 'На этот рейс лучше не ставить будильник']::text[], 'Train platform', 'A tired violinist waits for a train made of neatly linked alarm clocks; the conductor is a sleepy tortoise with a cap.', 'train, platform, tired, violinist, waits, made, neatly, linked, alarm, clocks, conductor, sleepy, tortoise, cap', ARRAY['The timetable moves, just not very quickly', 'Do not set an alarm for this service']::text[]),
  ('026-card.webp', 'Каменный великан с облаком', 'Покрытый мхом каменный великан держит маленькую дождевую тучу над цветами, пока рядом играют дети.', 'каменный великан, мох, маленькая туча, дождь, цветы, дети', ARRAY['Самый большой садовник поливает точечно', 'Погоду сегодня носят в ладони']::text[], 'Stone Giant with a Cloud', 'A moss-covered stone giant holds a small rain cloud above flowers while children play nearby.', 'stone giant, moss, rain cloud, flowers, children, garden', ARRAY['The biggest gardener waters one spot at a time', 'Someone is carrying the weather in a palm']::text[]),
  ('026-cos.webp', 'Суд над роботом-пылесосом', 'В инопланетном суде робота-пылесоса обвиняют в краже колец Сатурна; судья-ящерица изучает улику в форме крошки.', 'судья-ящерица, инопланетный суд, робот-пылесос, кольца Сатурна, крошка, обвинение', ARRAY['Улика застряла где-то в фильтре', 'Его обвиняют в слишком тщательной уборке']::text[], 'Saturn''s Missing Rings', 'An alien court accuses a robot vacuum of stealing Saturn''s rings while a lizard judge studies a crumb.', 'alien court, robot vacuum, Saturn, rings, lizard judge, evidence', ARRAY['The evidence is somewhere in the filter', 'The charge is cleaning a little too thoroughly']::text[]),
  ('026-meme.webp', 'Is This a Pigeon', 'Человек указывает на лампу, пролетающую над городской улицей, будто принимает её за птицу.', 'Is This a Pigeon, это голубь, человек указывает пальцем, летающая лампа, птица, город', ARRAY['Когда контрольная по биологии была слишком давно', 'Летает — значит, наверное, живое']::text[], 'Is This a Pigeon?', 'A person points at a flying lamp over a city street, mistaking it for a bird.', 'pigeon, person, points, flying, lamp, city, street, mistaking, bird', ARRAY['The biology test was a long time ago', 'If it flies, it must be alive, probably']::text[]),
  ('027-abs.webp', 'Tailor''s impossible zipper', 'Портной пытается справиться с гигантской молнией-застёжкой, которая разделила мастерскую на лето и снежную зиму.', 'портной ателье молния застёжка зима снег лето одежда шитьё ткань', ARRAY['Одним движением сменили сезон', 'Примерочная не договорилась с погодой']::text[], 'Tailor''s impossible zipper', 'A giant floor zipper splits the tailor shop into summer and winter.', 'tailor, impossible, zipper, floor, splits, shop, summer, winter', ARRAY['One quick move changed the season', 'The fitting room could not agree with the weather']::text[]),
  ('027-card.webp', 'Лунный воин', 'Чёрно-белый воин с копьём стоит на серпе луны над спящей женщиной среди облаков.', 'воин, копьё, полумесяц, луна, спящая женщина, облака, чёрно-белый', ARRAY['Охрана снов снова вышла в ночную смену', 'Страж поднялся туда, где заканчиваются лестницы']::text[], 'Moon Warrior', 'A black-and-white warrior with a spear stands on a crescent moon above a sleeping woman among clouds.', 'warrior, spear, crescent moon, sleeping woman, clouds', ARRAY['The dream guard is on the night shift again', 'The watchman climbed where ladders end']::text[]),
  ('027-cos.webp', 'Планета на поводке', 'Ребёнок-инопланетянин выгуливает крошечную планету на поводке, а планета оставляет за собой след из миниатюрных облаков.', 'ребёнок-инопланетянин, маленькая планета, поводок, облака, прогулка, космос', ARRAY['На прогулке снова нельзя заходить за горизонт', 'Хозяин собирает облака в пакетик']::text[], 'Walking a Pet Planet', 'An alien child walks a tiny planet on a leash as it leaves miniature clouds behind.', 'alien child, pet planet, leash, tiny clouds, walk', ARRAY['No wandering beyond the horizon on this walk', 'The owner picks up the clouds in a little bag']::text[]),
  ('027-meme.webp', 'Confused Math Lady', 'Озадаченная женщина смотрит на чайник без ручки, пока вокруг её головы висят формулы, фигуры и ложки.', 'Confused Math Lady, женщина с формулами, задумчивость, чайник, ложки, геометрия', ARRAY['Задача со звёздочкой появилась на кухне', 'Когда ответ вроде есть, но за него не ухватиться']::text[], 'Confused Math Lady', 'A puzzled woman studies a handleless kettle while formulas, shapes and spoons float around her head.', 'confused, math, lady, puzzled, woman, studies, handleless, kettle, formulas, shapes, spoons, float, head', ARRAY['An advanced problem appeared in the kitchen', 'The answer is there, but there is nothing to grab']::text[]),
  ('028-abs.webp', 'Restaurant', 'Официант подаёт салат, в котором маленькие офисные дома спорят за последний зелёный лист.', 'ресторан официант салат тарелка город дома офисные здания зелень лист ужин', ARRAY['За гарнир разгорелся городской спор', 'На тарелке сегодня очень тесно']::text[], 'Restaurant', 'A waiter serves a salad in which small office buildings argue over the last leaf; the diner politely offers them a fork.', 'restaurant, waiter, serves, salad, which, office, buildings, argue, last, leaf, diner, politely, offers, fork', ARRAY['A citywide argument broke out over the garnish', 'There is very little room on today''s plate']::text[]),
  ('028-card.webp', 'Лес под плащом', 'Женщина в тёмном плаще распахивает его, открывая внутри крошечный освещённый лес с деревьями.', 'женщина, плащ, миниатюрный лес, деревья, свет, секрет', ARRAY['В карманах места не хватило для весны', 'Гардероб снова оказался шире мира']::text[], 'Forest Beneath a Cloak', 'A woman opens her dark cloak to reveal a tiny illuminated forest growing inside it.', 'woman, dark cloak, miniature forest, trees, light', ARRAY['There was no room for spring in her pockets', 'The wardrobe turned out to be wider than the world']::text[]),
  ('028-cos.webp', 'Космическое караоке', 'Три инопланетянина в блестящих костюмах поют в микрофоны на лунной сцене, а звуковые волны складываются в смешные планеты.', 'три пришельца, караоке, микрофоны, лунная сцена, планеты, звуковые волны', ARRAY['После припева пришлось перенастроить орбиты', 'Соседи услышали концерт за несколько световых лет']::text[], 'Moon Pop Concert', 'Three aliens in shiny suits sing into microphones on a lunar stage while sound waves form silly planets.', 'aliens, shiny suits, microphones, moon stage, sound waves, planets', ARRAY['The orbits needed retuning after the chorus', 'The neighbors heard the concert light-years away']::text[]),
  ('028-meme.webp', 'Panik Kalm Panik', 'Один и тот же нарисованный человечек на трёх кадрах сперва пугается, затем успокаивается и снова пугается ожившего тостера.', 'Panik Kalm Panik, паника спокойствие паника, человечек, тостер, три кадра', ARRAY['Я всё исправил. Кажется. Нет, не исправил', 'Каждая новая проверка делает результат хуже']::text[], 'Panik Kalm Panik', 'Three panels show the same drawn figure fearing, then trusting, then fearing a living toaster.', 'panik, kalm, panels, show, same, drawn, figure, fearing, then, trusting, living, toaster', ARRAY['I fixed it. I think. No, I did not', 'Every new check makes the result worse']::text[]),
  ('029-abs.webp', 'Repair shop', 'Мастер открыл смартфон, и из него вылетела стая бумажных птиц-мыслей к изумлённой хозяйке.', 'ремонт смартфон телефон мастерская бумажные птицы мысли экран женщина инструменты', ARRAY['Непрочитанное наконец вырвалось наружу', 'В памяти устройства оказалось слишком много крыльев']::text[], 'Repair shop', 'A technician unscrews a broken smartphone and releases a flock of tiny unread thoughts as paper birds; owner reaches for one.', 'repair, shop, technician, unscrews, broken, smartphone, releases, flock, unread, thoughts, paper, birds, owner, reaches', ARRAY['The unread messages finally escaped', 'There were too many wings in the device''s memory']::text[]),
  ('029-card.webp', 'Гость в пасти чудовища', 'Тёмная фигура в красном стоит у раскрытой пасти огромного ночного чудовища с длинными зубами.', 'ночное чудовище, пасть, длинные зубы, тёмная фигура, красная одежда, ночь', ARRAY['Вход бесплатный, но выход надо заслужить', 'Самая неудачная дверь в этом городе']::text[], 'Visitor in the Monster''s Mouth', 'A dark figure in red stands before the open jaws of an enormous nocturnal monster with long teeth.', 'figure in red, monster, open mouth, teeth, night, dark', ARRAY['Admission is free; getting out must be earned', 'The least inviting doorway in town']::text[]),
  ('029-cos.webp', 'Лифт между галактиками', 'Уставший курьер в лифте держит кнопку «другая галактика», пока двери открываются прямо в океан с плавающим диваном.', 'лифт, галактики, курьер, кнопка, океан, плавающий диван, открытые двери', ARRAY['На нужном этаже опять нужен купальник', 'Когда служебная поездка вышла далеко за адрес']::text[], 'Elevator to Another Galaxy', 'A tired courier holds the elevator button for another galaxy as the doors open onto an ocean with a floating sofa.', 'courier, elevator, other galaxy, ocean, floating sofa', ARRAY['The right floor requires a swimsuit again', 'The work trip went far beyond the address']::text[]),
  ('029-meme.webp', 'Bernie Mittens', 'Седой мужчина в тёплых варежках и маске сидит один на складном стуле посреди роскошного бала.', 'Bernie Mittens, Берни Сандерс в варежках, седой мужчина, складной стул, бал, маска', ARRAY['Пришёл на праздник со своим уровнем комфорта', 'Дресс-код сдался перед здравым смыслом']::text[], 'Bernie in Mittens', 'An elderly man in warm mittens and a mask sits alone on a folding chair at a fancy ball.', 'bernie, mittens, elderly, man, warm, mask, sits, alone, folding, chair, fancy, ball', ARRAY['He brought his own level of comfort to the party', 'The dress code surrendered to common sense']::text[]),
  ('030-abs.webp', 'Bus stop', 'На мокрой остановке женщина стоит под огромным зонтом, а скамейка рядом уходит прочь на резиновых сапогах.', 'автобусная остановка дождь зонтик женщина скамейка резиновые сапоги лужа', ARRAY['Место ожидания устало ждать первым', 'Под таким дождём даже мебель ушла домой']::text[], 'Bus stop', 'A woman waits under a giant umbrella held by a miniature raincoat, while the bench slowly walks away on rubber-boot feet.', 'bus, stop, woman, waits, umbrella, held, miniature, raincoat, bench, slowly, walks, away, rubber, boot, feet', ARRAY['The place to wait got tired of waiting first', 'Even the furniture went home in this rain']::text[]),
  ('030-card.webp', 'Огр плетёт сияющую косу', 'Зелёный великан у фьорда заплетает длинную синюю косу, сияющую на фоне северных огней.', 'зелёный великан, огр, синяя коса, плетение, фьорд, северное сияние', ARRAY['Утренние сборы растянулись на целый фьорд', 'Парикмахерская принимает клиентов размером с гору']::text[], 'Ogre Braids a Glowing Plait', 'A green giant beside a fjord braids a long blue glowing plait beneath the northern lights.', 'green ogre, giant, blue braid, fjord, northern lights, hair', ARRAY['Getting ready in the morning took an entire fjord', 'This salon serves mountain-sized customers']::text[]),
  ('030-cos.webp', 'Пончик затмил солнце', 'Гигантский пончик медленно проходит перед звёздным солнцем; крошечный астроном в ужасе сверяет это с рецептом.', 'гигантский пончик, затмение, солнце, астроном, рецепт, сладости, космос', ARRAY['Темнота оказалась с сахарной глазурью', 'Учёные попросили не откусывать доказательство']::text[], 'Doughnut Eclipse', 'A giant doughnut passes before a starry sun while a tiny astronomer checks the event against a recipe.', 'doughnut, eclipse, sun, astronomer, recipe, sugar icing', ARRAY['Darkness turned out to have sugar icing', 'The scientists asked us not to eat the evidence']::text[]),
  ('030-meme.webp', 'UNO Draw 25', 'Упрямый игрок сидит за столом с огромной горой карт, хотя мог бы просто закрыть открытое окно.', 'UNO Draw 25, уно возьми 25, карточная игра, игрок, гора карт, окно, упрямство', ARRAY['Когда проще взять ещё двадцать проблем, чем решить одну', 'Руки заняты, принцип всё ещё свободен']::text[], 'UNO Draw 25', 'A stubborn player sits behind a huge pile of cards instead of simply closing an open window.', 'uno, draw, stubborn, player, sits, huge, pile, cards, simply, closing, open, window', ARRAY['Taking twenty more problems seemed easier than solving one', 'His hands are full, but his principles are free']::text[]),
  ('031-abs.webp', 'Pet shop', 'В зоомагазине продавец подбирает поводок воспитанному перекати-полю, пока собака оплачивает покупку костью.', 'зоомагазин продавец собака поводок кость перекати-поле прилавок питомец', ARRAY['Покупатель сегодня сам приносит оплату', 'Самый послушный питомец катится без лап']::text[], 'Pet shop', 'A shopkeeper carefully sells a leash to a very well-behaved tumbleweed; a dog at the counter pays with a bone.', 'pet, shop, shopkeeper, carefully, sells, leash, well, behaved, tumbleweed, dog, counter, pays, bone', ARRAY['Today''s customer brought his own payment', 'The best-behaved pet rolls without paws']::text[]),
  ('031-card.webp', 'Ведьма на ложке', 'Ведьма летит на огромной ложке над замёрзшим озером под луной и заснеженными вершинами.', 'Баба-яга, баба яга, ведьма, ступа, избушка на курьих ножках, огромная ложка, полёт, замёрзшее озеро, луна, снег', ARRAY['Для супа сегодня понадобится небо', 'Столовый прибор ушёл в самостоятельное путешествие']::text[], 'Witch on a Spoon', 'A witch flies on an enormous spoon above a frozen lake beneath the moon and snowy peaks.', 'Baba Yaga, witch, mortar, chicken-legged hut, giant spoon, frozen lake, moon, snowy mountains, flight', ARRAY['Today''s soup calls for the whole sky', 'A piece of cutlery went traveling by itself']::text[]),
  ('031-cos.webp', 'Черепаха-навигатор', 'Космический корабль летит на панцире мудрой черепахи, которая выбирает маршрут, разглядывая карту вверх ногами.', 'мудрая черепаха, космический корабль, панцирь, карта вверх ногами, навигация, астероиды', ARRAY['Прибудем поздно, но зато с легендой', 'Капитан знает путь, просто не торопится']::text[], 'Turtle Spaceship', 'A spaceship travels on the shell of a wise turtle choosing its route from an upside-down map.', 'spaceship, turtle, shell, upside-down map, route', ARRAY['We will arrive late, but with a great story', 'The captain knows the way and simply takes her time']::text[]),
  ('031-meme.webp', 'Two Buttons', 'Взволнованный супергерой не может выбрать между двумя огромными кнопками с солнцем и луной.', 'Two Buttons, две кнопки, потный супергерой, выбор, солнце, луна', ARRAY['Когда оба варианта кажутся неправильным временем суток', 'На собеседовании спросили, кто ты утром и вечером']::text[], 'Two Buttons', 'A nervous superhero cannot choose between two enormous buttons bearing the sun and moon.', 'buttons, nervous, superhero, cannot, choose, bearing, sun, moon', ARRAY['Both choices seem like the wrong time of day', 'The interview asked who he is in the morning and evening']::text[]),
  ('032-abs.webp', 'School hallway', 'Учитель гонится по коридору за контрольной, сложившейся в бумажный самолёт; следом бегут ластики.', 'школа учитель коридор контрольная бумажный самолётик ластики тетрадь экзамен', ARRAY['Работа сама сбежала с проверки', 'Сегодня оценки летят быстрее учеников']::text[], 'School hallway', 'A teacher chases a runaway examination paper that folds itself into a paper airplane and leads a swarm of erasers.', 'school, hallway, teacher, chases, runaway, examination, paper, folds, itself, airplane, leads, swarm, erasers', ARRAY['The assignment escaped before anyone could grade it', 'Today the marks fly faster than the students']::text[]),
  ('032-card.webp', 'Тени в детской', 'В комнате мать обнимает детей, пока их тени на стенах превращаются в высоких причудливых чудовищ.', 'мать, дети, спальня, тени, чудовища, стены, страх', ARRAY['Перед сном воображение опять не выключили', 'Свет погас, и у семейного портрета появились когти']::text[], 'Shadows in the Nursery', 'A mother hugs her children in a room while their wall shadows become tall strange monsters.', 'mother, children, nursery, shadows, wall, monsters, hug', ARRAY['Nobody turned off the imagination at bedtime', 'The lights went out and the family portrait grew claws']::text[]),
  ('032-cos.webp', 'Прачечная Млечного Пути', 'Инопланетная прачка загружает спиральную галактику в стиральную машину, рядом ждёт груда светящихся носков.', 'инопланетная прачка, Млечный Путь, галактика, стиральная машина, светящиеся носки', ARRAY['После отжима звёзды распределятся ровнее', 'Один носок снова потерялся в бесконечности']::text[], 'Galaxy Laundry', 'An alien laundress loads a spiral galaxy into a washing machine beside a pile of glowing socks.', 'alien, washing machine, spiral galaxy, glowing socks, laundry', ARRAY['After the spin cycle the stars will be distributed evenly', 'One sock got lost in infinity again']::text[]),
  ('032-meme.webp', 'Фарм ауры', 'Мальчик уверенно танцует на носу лодки, которая мчится через огромные волны, пока другие едва справляются с греблей.', 'фарм ауры, aura farming, танец на лодке, мальчик, волны, гребцы, океан', ARRAY['Когда у команды аврал, а у тебя собственный клип', 'Чем сильнее качает, тем увереннее поза']::text[], 'Aura Farming', 'A boy dances confidently on the prow of a boat amid huge waves while everyone else struggles to row.', 'aura, farming, boy, dances, confidently, prow, boat, amid, huge, waves, everyone, else, struggles, row', ARRAY['The crew is in crisis and he is filming his own music video', 'The rougher the waves, the stronger the pose']::text[]),
  ('033-abs.webp', 'Coffee stand', 'Бариста наливает кофе, а из бумажного стакана вылезает крошечный сонный человек в тапочках.', 'кофейня бариста кофе эспрессо стакан понедельник сонный человек тапочки', ARRAY['Начало недели опять вылезло из чашки', 'Заказ бодрости пришёл с задержкой']::text[], 'Coffee stand', 'A barista pours espresso into a paper cup and an entire tiny Monday crawls out, yawning and wearing slippers.', 'coffee, stand, barista, pours, espresso, paper, cup, entire, monday, crawls, yawning, wearing, slippers', ARRAY['Monday climbed right out of the cup again', 'The order for energy arrived late']::text[]),
  ('033-card.webp', 'Дракон за чаем', 'Маленький зелёный дракон пьёт чай с мышонком за уютным столом в деревенском доме.', 'зелёный дракон, мышь, чай, стол, уютный дом, чашки', ARRAY['На этот визит хватило одной чашки и смелости', 'Самый горячий гость обещал дуть осторожно']::text[], 'Dragon at Tea', 'A tiny green dragon drinks tea with a mouse at a cozy table in a village house.', 'green dragon, mouse, tea, table, cozy house, village', ARRAY['One cup and a little courage were enough for this visit', 'The hottest guest promised to blow gently']::text[]),
  ('033-cos.webp', 'Космонавт и гигантская ложка', 'Астронавт плывёт по космосу с огромной ложкой, пытаясь зачерпнуть суп из туманности, вид от первого лица.', 'астронавт, гигантская ложка, суп из туманности, космос, рука, звёзды', ARRAY['На обед предложили целое небо', 'Ещё один глоток — и понадобится новая миска']::text[], 'Nebula Soup', 'An astronaut floats through space with an enormous spoon trying to scoop soup from a nebula.', 'astronaut, spoon, soup, nebula, space, lunch', ARRAY['The lunch special was the entire sky', 'One more sip and we will need a bigger bowl']::text[]),
  ('033-meme.webp', 'One Does Not Simply', 'Путник пытается пролезть в крошечную дверь величественного магазина среди каменных стен и узких ступеней.', 'One Does Not Simply, просто так не войти, путник, маленькая дверь, магазин, порог', ARRAY['Инструкция звучала легко до знакомства с входом', 'Когда ключ нашёлся, а размер дверей забыли указать']::text[], 'One Does Not Simply', 'A traveler struggles to enter a tiny door in a grand stone shop with narrow steps.', 'does, not, simply, traveler, struggles, enter, door, grand, stone, shop, narrow, steps', ARRAY['The instructions sounded easy until he saw the entrance', 'The key was found; nobody mentioned the door''s size']::text[]),
  ('034-abs.webp', 'Snail coronation', 'Садовник заглядывает в сарай и видит улиток на ковровой дорожке: одна в короне, остальные собрались на церемонию.', 'садовник сарай улитки корона трон церемония ковёр сад', ARRAY['Самую медленную коронацию дождались не все', 'Во дворце наконец выбрали терпеливого правителя']::text[], 'Snail coronation', 'A gardener discovers a snail coronation inside his shed.', 'snail, coronation, gardener, discovers, shed', ARRAY['Not everyone stayed for the slowest coronation', 'At last the palace chose a patient ruler']::text[]),
  ('034-card.webp', 'Пустая сцена', 'На почти пустой тёмной сцене остались театральные маски и одинокий башмак под слабым светом рампы.', 'театр, тёмная сцена, маски, башмак, рампа, пустота', ARRAY['Занавес закрыли, а чей-то выход забыли', 'Аплодисменты уже кончились, загадка ещё нет']::text[], 'Empty Stage', 'Theater masks and a lonely shoe remain on an almost empty dark stage under a dim spotlight.', 'empty stage, theater masks, lone shoe, spotlight, darkness', ARRAY['The curtain fell, but someone forgot an exit', 'The applause ended; the mystery did not']::text[]),
  ('034-cos.webp', 'Марсианский день рождения', 'На красной пустынной планете пришельцы несут торт со свечами в шлемах, а именинник-дикобраз загадывает желание.', 'Марс, день рождения, пришельцы, торт, свечи, дикобраз, космические шлемы', ARRAY['Задувать свечи лучше до посадки гостей', 'Праздник получился колючим и очень красным']::text[], 'Birthday on a Red Planet', 'Aliens wearing helmets carry a candlelit cake across a red desert planet while a porcupine birthday guest makes a wish.', 'aliens, birthday cake, candles, porcupine, red planet, desert', ARRAY['Best blow out the candles before the guests land', 'The party was prickly and very red']::text[]),
  ('034-meme.webp', 'Overly Attached Girlfriend', 'Девушка с чрезмерно пристальным взглядом лежит в постели и внимательно следит за часами будильника.', 'Overly Attached Girlfriend, навязчивая девушка, пристальный взгляд, будильник, часы, спальня', ARRAY['Я просто проверяю, почему ты не ответил в 7:01', 'Даже время попросило немного личного пространства']::text[], 'Overly Attached Girlfriend', 'A girl with an intense stare lies in bed watching an alarm clock closely.', 'overly, attached, girlfriend, girl, intense, stare, lies, bed, watching, alarm, clock, closely', ARRAY['I am only checking why you did not reply at 7:01', 'Even time asked for a little personal space']::text[]),
  ('035-abs.webp', 'Hardware store', 'В строительном магазине лестницы с глазами и руками спорят друг с другом, пока покупатель решает, какую взять.', 'хозяйственный магазин лестницы стремянки покупатель инструменты глаза руки спор', ARRAY['Выбор высоты вызвал настоящий скандал', 'Полки поссорились из-за верхней ступени']::text[], 'Hardware store', 'A contractor tries to choose a ladder; each ladder argues with its reflection about how high it should reach.', 'hardware, store, contractor, tries, choose, ladder, argues, reflection, about, how, high, should, reach', ARRAY['Choosing a height caused quite a scandal', 'The shelves argued over the top rung']::text[]),
  ('035-card.webp', 'Луна в кресле-качалке', 'Улыбающийся круглый лунный житель сидит в кресле-качалке рядом с мышами и телескопом среди звёзд.', 'улыбающаяся луна, кресло-качалка, мыши, телескоп, звёзды, ночь', ARRAY['Бабушка небосвода опять не хочет спать', 'Наблюдатель сам стал самым круглым объектом']::text[], 'Moon in a Rocking Chair', 'A smiling round moon dweller sits in a rocking chair among mice and a telescope beneath the stars.', 'moon face, rocking chair, mice, telescope, stars', ARRAY['Grandmother of the night sky refuses to sleep again', 'The observer became the roundest object himself']::text[]),
  ('035-cos.webp', 'Библиотека забытых планет', 'Маленькая библиотекарша-робот расставляет крошечные планеты-книги на высоких полках; одна планета чихает созвездиями.', 'робот-библиотекарь, книги-планеты, полки, библиотека, созвездия, лестница', ARRAY['Тихо, здесь даже миры говорят шёпотом', 'Верните эту историю до следующей эпохи']::text[], 'Library of Planet Books', 'A small robot librarian shelves tiny planet books while one world sneezes constellations.', 'robot librarian, planet books, shelves, constellations, library', ARRAY['Quiet, even entire worlds whisper in here', 'Return this story before the next age begins']::text[]),
  ('035-meme.webp', 'Ждун', 'Серое складчатое существо с длинным носом терпеливо сидит на стуле среди множества часов в пустом зале.', 'Ждун, Homunculus Loxodontus, серое существо, длинный нос, ожидание, стул, часы', ARRAY['Заявка принята, ответ будет в следующем тысячелетии', 'Когда очередь давно стала частью интерьера']::text[], 'The Waiting One', 'A gray wrinkled creature with a long nose waits among many clocks in an empty hall.', 'waiting, gray, wrinkled, creature, long, nose, waits, among, many, clocks, empty, hall, homunculus, loxodontus', ARRAY['Your request is accepted; the answer comes next millennium', 'The queue has become part of the furniture']::text[]),
  ('036-abs.webp', 'Taxi', 'Таксист смотрит в зеркало заднего вида и видит там вчерашних пассажиров на далёкой улице.', 'такси водитель зеркало заднего вида пассажиры вчера машина город вечер', ARRAY['Поездка закончилась, а прощание всё ещё идёт', 'В этом зеркале тариф считают за прошлое']::text[], 'Taxi', 'A cab driver checks the rear-view mirror and finds yesterday''s passengers still waving from a tiny distant street inside it.', 'taxi, cab, driver, checks, rear, view, mirror, finds, yesterday, passengers, still, waving, distant, street', ARRAY['The ride ended, but the farewell went on', 'This mirror charges for the past']::text[]),
  ('036-card.webp', 'Лента для дождевой тучи', 'Человек среди зелёного луга поднимает длинную красную ленту к маленькой дождевой туче, рядом пасутся овцы.', 'человек, красная лента, дождевая туча, луг, овцы, дождь', ARRAY['Подарок небу завернули прямо на пастбище', 'Дождь сегодня решили уговорить по-хорошему']::text[], 'Ribbon for a Rain Cloud', 'A person in a green meadow lifts a long red ribbon toward a small rain cloud while sheep graze nearby.', 'person, red ribbon, rain cloud, meadow, sheep, gift', ARRAY['They wrapped a present for the sky in the pasture', 'Today they tried asking the rain nicely']::text[]),
  ('036-cos.webp', 'Космический голубь', 'Обычный голубь в шлеме сидит на антенне космической станции, а вокруг него пристроились удивлённые инопланетные голуби.', 'голубь, шлем, антенна станции, инопланетные голуби, космос, птица', ARRAY['Земной гость уже освоился лучше экипажа', 'Кормить пассажира просили только за пределами станции']::text[], 'Pigeon at the Space Station', 'An ordinary pigeon in a helmet perches on a space station antenna among amazed alien pigeons.', 'pigeon, helmet, space station, antenna, alien pigeons', ARRAY['The visitor from Earth settled in faster than the crew', 'Please feed the passenger outside the station']::text[]),
  ('036-meme.webp', 'Кот Вжух', 'Пушистый рыжий кот в бумажном колпаке машет волшебной палочкой, и билеты взлетают над очередью.', 'кот Вжух, вжух, рыжий кот, волшебная палочка, билеты, очередь, касса', ARRAY['Когда билет закончился, а чудо только началось', 'Очередь исчезла быстрее, чем кассир нашёл сдачу']::text[], 'Magic Ginger Cat', 'A fluffy orange cat in a paper hat waves a wand as tickets fly above a queue.', 'magic, ginger, cat, fluffy, orange, paper, hat, waves, wand, tickets, fly, queue', ARRAY['The tickets ran out just as the magic began', 'The line vanished faster than the cashier found change']::text[]),
  ('037-abs.webp', 'Museum cloakroom', 'Гардеробщица принимает пальто, из карманов которого высыпается целая зима со снежинками.', 'гардероб пальто старик служащая вешалка снег зима карманы', ARRAY['На хранение сдали целый сезон', 'В карманах нашлась погода похолоднее']::text[], 'Museum cloakroom', 'An attendant takes an old man''s coat, and the coat carries off his whole winter in its pockets as snowflakes.', 'museum, cloakroom, attendant, takes, man, coat, carries, off, winter, pockets, snowflakes', ARRAY['An entire season was checked into storage', 'The pockets held colder weather than expected']::text[]),
  ('037-card.webp', 'Всадница с фонарём', 'Женщина в красном плаще едет на тёмной лошади через ночной лес, освещая дорогу фонарём.', 'женщина, красный плащ, лошадь, фонарь, ночной лес, деревья', ARRAY['Последний огонёк выбрал дорогу без указателей', 'В темноте её узнают раньше, чем слышат копыта']::text[], 'Rider with a Lantern', 'A woman in a red cloak rides a dark horse through a forest at night, lighting the path with a lantern.', 'woman, red cloak, dark horse, lantern, night forest, rider', ARRAY['The last little light chose a road without signs', 'In the dark they recognize her before the hoofbeats']::text[]),
  ('037-cos.webp', 'Вулкан варит какао', 'Марсианский вулкан извергает горячее какао и маршмеллоу, туристы с кружками выстроились на безопасном хребте.', 'марсианский вулкан, горячее какао, маршмеллоу, туристы, кружки, лава, красная планета', ARRAY['Извержение объявили началом кофейного перерыва', 'Опасно близко, зато очень вкусно пахнет']::text[], 'Cocoa Volcano', 'A Martian volcano erupts hot cocoa and marshmallows as tourists line up with mugs on a safe ridge.', 'Mars, volcano, cocoa, marshmallows, tourists, mugs', ARRAY['The eruption marked the start of a coffee break', 'Dangerously close, but it smells delicious']::text[]),
  ('037-meme.webp', 'Ничоси', 'Белый нарисованный человечек с широко открытым ртом заглядывает в холодильник, где вместо еды сияет целая галактика.', 'Ничоси, удивлённый человечек, белый персонаж, холодильник, галактика, планеты, восторг', ARRAY['Когда в поисках ужина нашёл новую вселенную', 'Открываешь дверцу на секунду, зависаешь на эпоху']::text[], 'What a Surprise', 'A white cartoon figure gapes into a refrigerator that contains an entire glowing galaxy.', 'what, surprise, white, cartoon, figure, gapes, refrigerator, contains, entire, glowing, galaxy', ARRAY['Went looking for dinner and found a new universe', 'Opened the door for a second; stared for an era']::text[]),
  ('038-abs.webp', 'Picnic', 'Пара раскладывает плед для пикника, а кусок газона на ножках сворачивается и просится с ними домой.', 'пикник плед трава газон пара парк корзина живой кусок земли', ARRAY['После прогулки домой захотела сама поляна', 'Место для отдыха оказалось очень общительным']::text[], 'Picnic', 'A young couple lays out a blanket; a small patch of lawn rolls itself up and asks to be taken home.', 'picnic, young, couple, lays, blanket, patch, lawn, rolls, itself, asks, taken, home', ARRAY['The meadow wanted to come home too', 'The picnic spot was unusually sociable']::text[]),
  ('038-card.webp', 'Музыкальная карусель чудовищ', 'Грифон, огр и дракон играют на инструментах, стоя на круглой музыкальной подставке среди облаков.', 'грифон, огр, дракон, музыкальные инструменты, карусель, подставка, облака', ARRAY['Ансамбль репетировал до изобретения тишины', 'Каждый музыкант здесь умеет немного рычать']::text[], 'Musical Carousel of Monsters', 'A griffin, an ogre and a dragon play instruments on a round musical platform among clouds.', 'griffin, ogre, dragon, instruments, carousel, music, clouds', ARRAY['The band rehearsed before silence was invented', 'Every musician here knows how to growl a little']::text[]),
  ('038-cos.webp', 'НЛО на мойке', 'Два механических осьминога моют летающую тарелку пенными щупальцами, а пилот проверяет блеск на отражении луны.', 'НЛО, мойка, два механических осьминога, щупальца, пена, летающая тарелка, луна', ARRAY['После полировки даже звёзды отражаются лучше', 'Четырёх рук на такую уборку не хватило']::text[], 'Octopus Spaceship Wash', 'Two mechanical octopuses scrub a flying saucer with foamy tentacles while its pilot checks the moon''s reflection.', 'robot octopuses, UFO, flying saucer, foam, tentacles, moon', ARRAY['After polishing, even the stars reflect more brightly', 'Four hands were never going to be enough']::text[]),
  ('038-meme.webp', 'Philosoraptor', 'Зелёный раптор задумчиво сидит в обсерватории перед огромным яйцом и звёздным окном.', 'Philosoraptor, философораптор, раптор, динозавр, яйцо, обсерватория, звёзды', ARRAY['Если сначала была скорлупа, кто придумал завтрак', 'Мысль настолько глубокая, что до неё не долетает свет']::text[], 'Philosoraptor', 'A green raptor ponders a huge egg in an observatory before a starry window.', 'philosoraptor, green, raptor, ponders, huge, egg, observatory, before, starry, window', ARRAY['If the shell came first, who invented breakfast?', 'A thought so deep that light cannot reach it']::text[]),
  ('039-abs.webp', 'Office copier', 'Секретарша копирует скрепку, а из аппарата маршируют всё новые скрепки с лицами и руками.', 'офис копир ксерокс скрепка скрепки секретарша бумага принтер', ARRAY['Тираж оказался слишком самостоятельным', 'Одна канцелярская мелочь собрала целую армию']::text[], 'Office copier', 'A secretary photocopies a single paper clip and a line of increasingly proud metal clip creatures marches out.', 'office, copier, secretary, photocopies, single, paper, clip, line, increasingly, proud, metal, creatures, marches', ARRAY['The print run developed its own plans', 'One office trifle assembled a whole army']::text[]),
  ('039-card.webp', 'Великан под чёрным плащом', 'Огромный коронованный человек в чёрном плаще укрывает маленькую женщину с белым зонтом на снежном берегу.', 'великан, корона, чёрный плащ, женщина, белый зонт, снег, берег', ARRAY['Самая большая крыша уместилась на плечах', 'Зонтик пожаловался, что его снова опередили']::text[], 'Giant Beneath a Black Cloak', 'A crowned giant in a black cloak shelters a small woman with a white umbrella on a snowy shore.', 'giant, crown, black cloak, woman, white umbrella, snow, shore', ARRAY['The largest roof fit across his shoulders', 'The umbrella complained that someone got there first again']::text[]),
  ('039-cos.webp', 'Вечеринка в шлеме', 'В прозрачном шлеме астронавта проходит крошечная дискотека: танцуют лягушка, робот и один серьёзный бутерброд.', 'скафандр, прозрачный шлем, дискотека внутри, лягушка, робот, бутерброд, танцы', ARRAY['В голове сегодня целая вечеринка', 'Снаружи тишина, внутри уже третий бис']::text[], 'Disco Inside a Space Helmet', 'A tiny disco inside an astronaut''s helmet features a dancing frog, robot and very serious sandwich.', 'astronaut, space helmet, disco, frog, robot, sandwich', ARRAY['There is a whole party inside his head today', 'Outside is quiet; inside they are on their third encore']::text[]),
  ('039-meme.webp', 'Queen Never Cry', 'Маленькая принцесса с короной сидит невозмутимо, хотя вокруг неё плачут придворные и падает люстра.', 'Queen Never Cry, королева не плачет, младенец, принцесса, корона, придворные, люстра', ARRAY['Во дворце паника, у руководства тихий час', 'Когда проблемы есть у всех, кроме главной']::text[], 'Queen Never Cry', 'A little crowned princess sits calmly as courtiers weep and a chandelier falls.', 'queen, never, cry, crowned, princess, sits, calmly, courtiers, weep, chandelier, falls', ARRAY['Panic in the palace; management is taking a nap', 'Everyone has a problem except the person in charge']::text[]),
  ('040-abs.webp', 'Ice cream cart', 'Продавец у моря кладёт закат в вафельный рожок, пока голуби спорят за последние светящиеся капли.', 'мороженое рожок продавец закат солнце море набережная голуби', ARRAY['Последнюю порцию вечера разобрали у воды', 'Птицы тоже захотели попробовать сумерки']::text[], 'Ice cream cart', 'An ice cream vendor scoops a sunset into a cone while two pigeons argue over the last glowing drop.', 'ice, cream, cart, vendor, scoops, sunset, cone, pigeons, argue, last, glowing, drop', ARRAY['The last serving of evening sold out by the sea', 'Even the birds wanted a taste of dusk']::text[]),
  ('040-card.webp', 'Коса северного сияния', 'Зелёная великанша сидит у фьорда и заплетает длинные синие волосы, похожие на поток света в небе.', 'великанша, зелёная кожа, синие волосы, коса, фьорд, северное сияние', ARRAY['На причёску ушёл весь вечер и половина неба', 'В этой долине ветер работает стилистом']::text[], 'Northern Lights Braid', 'A green giantess sits beside a fjord braiding long blue hair that resembles a ribbon of light in the sky.', 'green giantess, blue braid, fjord, northern lights, hair', ARRAY['The hairstyle took all evening and half the sky', 'In this valley the wind works as a stylist']::text[]),
  ('040-cos.webp', 'Астронавт доит созвездие', 'Фермер в скафандре доит на табурете созвездие в форме коровы, направляя звёздное молоко в бидон.', 'астронавт-фермер, созвездие-корова, звёздное молоко, табурет, бидон, космос', ARRAY['Утренний надой светится до самого вечера', 'На ферме сегодня слишком высокие пастбища']::text[], 'Milking a Cow Constellation', 'A farmer in a spacesuit milks a cow-shaped constellation into a metal can while sitting on a stool.', 'farmer, spacesuit, cow constellation, star milk, stool, can', ARRAY['This morning''s milk will glow all evening', 'The pastures are unusually high on this farm']::text[]),
  ('040-meme.webp', 'Turkish Shooter', 'Седой стрелок в белой футболке с рукой в кармане спокойно целится на турнире в парящие мыльные пузыри.', 'Turkish Shooter, турецкий стрелок, Юсуф Дикеч, пистолет, футболка, пузырь, турнир', ARRAY['Когда пришёл без подготовки и всё равно попал', 'Одна рука работает, другая отдыхает']::text[], 'Turkish Shooter', 'A gray-haired marksman casually aims at floating soap bubbles with one hand in his pocket.', 'turkish, shooter, gray, haired, marksman, casually, aims, floating, soap, bubbles, hand, pocket', ARRAY['Showed up unprepared and still hit the target', 'One hand works; the other is on vacation']::text[]),
  ('041-abs.webp', 'Apartment move', 'Грузчик несёт коробку с целой миниатюрной квартирой внутри; крошечный жилец держит ему дверь.', 'переезд грузчик коробка квартира миниатюрный дом мебель жилец дверь лестница', ARRAY['Квартиру удалось унести в одних руках', 'Хозяин попросил не трясти прихожую']::text[], 'Apartment move', 'A mover carries a cardboard box that contains a whole apartment; its miniature occupant holds the door open for him.', 'apartment, move, mover, carries, cardboard, box, contains, miniature, occupant, holds, door, open, him', ARRAY['The apartment fit in one pair of hands', 'The owner asked him not to shake the hallway']::text[]),
  ('041-card.webp', 'Ледяные музыканты', 'Синий великан с барабаном играет напротив прозрачного голубого музыканта в заснеженной долине.', 'ледяной великан, барабан, голубой призрак, музыканты, снег, горы', ARRAY['Репетиция звучала так громко, что замёрз воздух', 'Один играет громко, второй похож на эхо']::text[], 'Ice Musicians', 'A blue giant plays a drum opposite a transparent blue musician in a snowy valley.', 'blue giant, drum, transparent musician, snowy valley, music', ARRAY['The rehearsal was so loud it froze the air', 'One plays loudly; the other looks like an echo']::text[]),
  ('041-cos.webp', 'Пиратская станция', 'Робот-пират с пластмассовой саблей захватывает орбитальную станцию, где единственная добыча — огромная банка маринованных огурцов.', 'робот-пират, пластмассовая сабля, орбитальная станция, маринованные огурцы, банка', ARRAY['Сокровище хрустит, но в сундук не помещается', 'Захват корабля прошёл ради закуски']::text[], 'Pirate Robot''s Pickle Treasure', 'A robot pirate with a plastic saber captures an orbital station whose only treasure is a huge jar of pickles.', 'robot pirate, plastic saber, orbital station, giant pickle jar', ARRAY['The treasure crunches but will not fit in the chest', 'They captured the whole ship for a snack']::text[]),
  ('041-meme.webp', 'Elmo Fire', 'Маленькая красная пушистая кукла радостно раскинула руки перед горящими офисными принтерами и взрывами.', 'Elmo Fire, Элмо в огне, красная кукла, пожар, принтеры, офис, радость', ARRAY['Пятница наконец дошла до отдела печати', 'Когда ошибка в отчёте уже не имеет значения']::text[], 'Elmo Fire', 'A little red fuzzy puppet spreads its arms joyfully before burning office printers.', 'elmo, fire, red, fuzzy, puppet, spreads, arms, joyfully, before, burning, office, printers', ARRAY['Friday finally reached the printing department', 'The report''s error no longer matters']::text[]),
  ('042-abs.webp', 'Seamstress', 'Женщина зашивает дырку в сумочке, из которой строем убегают пуговицы с ножками.', 'швея сумка сумочка игла нитка дырка пуговицы маленькие человечки', ARRAY['Все мелочи решили покинуть карман', 'Починка превратилась в массовый побег']::text[], 'Seamstress', 'A woman mends a hole in her handbag; through it a small marching band escapes in single file carrying buttons.', 'seamstress, woman, mends, hole, handbag, marching, band, escapes, single, file, carrying, buttons', ARRAY['Every little thing decided to leave the pocket', 'A simple repair turned into a mass escape']::text[]),
  ('042-card.webp', 'Поле пустых стульев', 'На пустынном поле стоят десятки пустых стульев, среди них выделяется один синий; рядом лежат музыкальные вещи.', 'пустые стулья, синий стул, поле, скрипка, сапоги, одиночество', ARRAY['Все места заняты отсутствием', 'Оркестр ушёл, а публика так и не пришла']::text[], 'Field of Empty Chairs', 'Dozens of empty chairs stand in a barren field, one blue chair among them and musical objects nearby.', 'empty chairs, blue chair, barren field, musical objects, orchestra', ARRAY['Every seat is taken by absence', 'The orchestra left and the audience never came']::text[]),
  ('042-cos.webp', 'Космический садовник', 'Садовник с лейкой подстригает живую спиральную галактику как куст, на ветках растут крошечные луны.', 'садовник, лейка, галактика-куст, спиральная галактика, маленькие луны, космический сад', ARRAY['Весной пришлось подрезать всю бесконечность', 'Плоды созреют после следующего оборота']::text[], 'Trimming the Galaxy', 'A gardener prunes a living spiral galaxy like a shrub with tiny moons growing on its branches.', 'gardener, watering can, spiral galaxy, shrub, tiny moons', ARRAY['Spring pruning took care of the whole infinity', 'The fruit will ripen after the next orbit']::text[]),
  ('042-meme.webp', 'This is Sparta', 'Воин в красном плаще с силой сталкивает в пропасть громадный будильник вместо врага.', 'This is Sparta, это Спарта, воин, будильник, пинок, пропасть, красный плащ', ARRAY['Утро получило решительный отказ', 'Когда кнопки отложить уже недостаточно']::text[], 'This Is Sparta', 'A red-cloaked warrior kicks an enormous alarm clock into a chasm instead of an enemy.', 'sparta, red, cloaked, warrior, kicks, alarm, clock, chasm, enemy', ARRAY['Morning received a very firm refusal', 'The snooze button was no longer enough']::text[]),
  ('043-abs.webp', 'Fishmonger', 'Покупательница выбирает рыбу на рынке, но большая рыба на льду указывает плавником прямо на неё.', 'рыбный рынок продавец покупательница рыба прилавок лёд плавник спор', ARRAY['Покупку выбирают с обеих сторон прилавка', 'У этого товара есть собственное мнение']::text[], 'Fishmonger', 'A customer points to a fresh fish, but the fish points back to the customer on a chalk-free display; the seller looks embarrassed.', 'fishmonger, customer, points, fresh, fish, but, back, chalk, free, display, seller, looks, embarrassed', ARRAY['The purchase chose from both sides of the counter', 'This product has an opinion of its own']::text[]),
  ('043-card.webp', 'Чашки с облаками', 'На цветущем лугу стоят маленькие чашки и цветы, а над посудой клубятся крошечные облака.', 'чашки, облака, луг, цветы, чай, маленькие тучи', ARRAY['К чаю подали прогноз погоды', 'В этом кафе всегда немного пасмурно']::text[], 'Cups of Clouds', 'Small cups and flowers sit in a blooming meadow while tiny clouds curl above the dishes.', 'cups, clouds, flowers, meadow, tea, dishes', ARRAY['The weather forecast came with the tea', 'The cafe is always a little overcast']::text[]),
  ('043-cos.webp', 'Собака за штурвалом', 'Пушистая собака случайно ведёт исследовательский корабль лапой, пока команда инопланетян показывает ей лакомство.', 'пушистая собака, штурвал корабля, лапа, пришельцы, лакомство, космический полёт', ARRAY['Курс на ближайший магазин вкусностей', 'Команда поняла, кто здесь главный, слишком поздно']::text[], 'Dog at the Helm', 'A fluffy dog accidentally pilots a research spaceship with one paw while the alien crew offers treats.', 'fluffy dog, spaceship, pilot, paw, aliens, treats', ARRAY['Set a course for the nearest treat store', 'The crew learned who was in charge too late']::text[]),
  ('043-meme.webp', 'Dramatic Chipmunk', 'Бурундук резко поворачивается к зрителям на сцене маленького театра, словно услышал неожиданный секрет.', 'Dramatic Chipmunk, драматичный бурундук, бурундук, сцена, театр, резкий взгляд', ARRAY['Когда за спиной произнесли твоё имя', 'Пауза длилась секунду, эффект — целую вечность']::text[], 'Dramatic Chipmunk', 'A chipmunk turns sharply toward the audience on a tiny theater stage as if it heard a secret.', 'dramatic, chipmunk, turns, sharply, toward, audience, theater, stage, heard, secret', ARRAY['Someone said his name behind his back', 'The pause lasted one second; the effect lasted ages']::text[]),
  ('044-abs.webp', 'Rooftop antennas', 'На крыше электрик распутывает спутниковые тарелки с лицами; над ними кружат облачка с велосипедами из их снов.', 'крыша электрик антенны спутниковые тарелки провода лица сон велосипед облака', ARRAY['Соседние крыши опять подслушали друг друга', 'Даже антеннам снится дорога']::text[], 'Rooftop antennas', 'An electrician untangles satellite dishes listening to one another''s dreams; visible dream bubbles contain tiny bicycles.', 'rooftop, antennas, electrician, untangles, satellite, dishes, listening, another, dreams, visible, dream, bubbles, contain, bicycles', ARRAY['The neighboring rooftops listened in again', 'Even antennas dream of the open road']::text[]),
  ('044-card.webp', 'Лавка теней', 'Волшебник стоит среди цветного ночного рынка, где между фонарями и тканями висят странные человеческие силуэты.', 'волшебник, рынок, фонари, ткани, висячие силуэты, тени, ночь', ARRAY['Здесь продают то, что обычно ходит за тобой', 'После закрытия лавки никто не бросает тень']::text[], 'Shadow Shop', 'A wizard stands in a colorful night market where strange human silhouettes hang between lanterns and fabrics.', 'wizard, night market, shadows, silhouettes, lanterns, fabrics', ARRAY['Here they sell what usually follows you', 'After closing time nobody casts a shadow']::text[]),
  ('044-cos.webp', 'Ракета из холодильника', 'Старый холодильник отрывается от кухонного пола и летит в космос, дверца открыта, внутри сияет целая звёздная система.', 'старый холодильник, космическая ракета, открытая дверца, звёздная система внутри, кухня', ARRAY['В поисках ужина открылся новый маршрут', 'Кухонная техника решила переехать без хозяев']::text[], 'Flying Refrigerator', 'An old refrigerator lifts off the kitchen floor and flies into space with a shining star system inside its open door.', 'refrigerator, kitchen, flying, space, star system, open door', ARRAY['Looking for dinner opened up a new route', 'The kitchen appliance moved out without its owners']::text[]),
  ('044-meme.webp', 'Ermahgerd', 'Девочка с косичками радостно бежит по улице, прижимая к груди стопку оживших книг с большими глазами.', 'Ermahgerd, эрмагёрд, девочка, косички, книги, восторг, улица', ARRAY['Когда библиотека наконец выпустила продолжение', 'Счастье весит больше, чем весь рюкзак']::text[], 'Ermahgerd', 'A pigtailed girl runs happily down the street carrying a stack of living books with big eyes.', 'ermahgerd, pigtailed, girl, runs, happily, street, carrying, stack, living, books, big, eyes', ARRAY['The library finally released the sequel', 'Happiness weighs more than her backpack']::text[]),
  ('045-abs.webp', 'Bicycle shop', 'Ребёнок оседлал маленький велосипед с огромными колёсами-пончиками, а мастер серьёзно проверяет давление.', 'веломагазин велосипед колёса пончики ребёнок мастер насос шины', ARRAY['Эта поездка выглядит слишком сладкой', 'На шиномонтаже неожиданно пахнет глазурью']::text[], 'Bicycle shop', 'A child tries out a tiny bicycle whose wheels are two enormous spinning donuts; mechanic solemnly checks tire pressure.', 'bicycle, shop, child, tries, wheels, spinning, donuts, mechanic, solemnly, checks, tire, pressure', ARRAY['This ride looks far too sweet', 'The tire shop smells unexpectedly like icing']::text[]),
  ('045-card.webp', 'Зверь в библиотеке', 'Огромный мохнатый зверь читает книги в библиотеке с астрономическими приборами, пока рядом стоит бронированный страж.', 'мохнатый зверь, книги, библиотека, астрономия, броня, страж', ARRAY['Читательский билет у него размером с дверь', 'Тишину здесь охраняют очень убедительно']::text[], 'Beast in the Library', 'A huge furry beast reads among books and astronomy instruments while an armored guard stands nearby.', 'furry beast, library, books, astronomy instruments, armored guard', ARRAY['His library card is the size of a door', 'Silence is guarded very convincingly here']::text[]),
  ('045-cos.webp', 'Улитка на гиперскорости', 'Космическая улитка обгоняет ракету по кольцу Сатурна, оставляя блестящий след, похожий на скоростную трассу.', 'космическая улитка, ракета, кольца Сатурна, гиперскорость, след, гонка', ARRAY['Тише едешь — неожиданно всех обгонишь', 'Скоростной рекорд установил самый терпеливый']::text[], 'Space Snail Overtakes a Rocket', 'A cosmic snail races past a rocket on Saturn''s rings, leaving a glittering trail like a highway.', 'space snail, rocket, Saturn rings, race, glittering trail', ARRAY['Slow and steady suddenly beat everyone', 'The most patient traveler set the speed record']::text[]),
  ('045-meme.webp', 'Coffin Dance', 'Четверо носильщиков в чёрных костюмах танцуют с гробом по нотному мосту под оранжевым небом.', 'Coffin Dance, танец с гробом, носильщики, чёрные костюмы, музыка, мост, танец', ARRAY['Когда финал оказался ритмичнее всей вечеринки', 'Слишком торжественный выход из чата']::text[], 'Coffin Dance', 'Four pallbearers in black suits dance with a coffin across a musical bridge beneath an orange sky.', 'coffin, dance, four, pallbearers, black, suits, musical, bridge, beneath, orange, sky', ARRAY['The finale had more rhythm than the whole party', 'A dramatic departure from the chat']::text[]),
  ('046-abs.webp', 'Clinic waiting room', 'В больничной очереди рядом с пациенткой сидят цифры на стульях в шарфах, ожидая своего вызова.', 'поликлиника очередь цифры числа пациентка стулья шарфы зал ожидания', ARRAY['Даже номер устал ждать приёма', 'Место в очереди заняло отдельное кресло']::text[], 'Clinic waiting room', 'A patient waits while the numbers in a queue patiently wait in chairs themselves, each wearing a scarf.', 'clinic, waiting, room, patient, waits, numbers, queue, patiently, wait, chairs, themselves, wearing, scarf', ARRAY['Even the number got tired of waiting', 'A place in line took its own chair']::text[]),
  ('046-card.webp', 'Фиолетовый лесной гость', 'Светящееся фиолетовое существо прячется среди деревьев, а из темноты за ним следят многочисленные глаза.', 'фиолетовое существо, свет, лес, деревья, глаза, темнота', ARRAY['Наблюдателей здесь оказалось больше, чем деревьев', 'Один светлячок нечаянно раскрыл секрет леса']::text[], 'Purple Forest Visitor', 'A glowing purple creature hides among trees while many eyes watch it from the dark.', 'purple creature, glowing forest, trees, many eyes, darkness', ARRAY['There were more watchers than trees', 'One firefly accidentally gave away the forest''s secret']::text[]),
  ('046-cos.webp', 'Планетарный будильник', 'Робот-звонарь бьёт по маленькой планете огромным будильником, и из кратеров выскакивают сонные человечки.', 'робот-звонарь, планета, огромный будильник, кратеры, сонные человечки, пробуждение', ARRAY['Просыпайтесь, сегодня уже другой оборот', 'Один звонок разбудил целый мир']::text[], 'Planet Alarm Clock', 'A robot bell-ringer strikes a small planet with an enormous alarm clock and sleepy people pop from its craters.', 'robot, alarm clock, planet, craters, sleepy people', ARRAY['Wake up; it is already another orbit', 'One ring woke an entire world']::text[]),
  ('046-meme.webp', 'Buff Doge vs Cheems', 'Огромный мускулистый пёс с пакетами продуктов идёт рядом с маленьким робким псом на городской улице.', 'Buff Doge vs Cheems, качок Доге и Чимс, собаки, мускулы, пакеты продуктов, контраст', ARRAY['Один несёт все покупки, второй моральную поддержку', 'Когда вчера и сегодня по-разному ходят в магазин']::text[], 'Buff Doge vs Cheems', 'A muscular dog carries all the groceries beside a small timid dog on a city street.', 'buff, doge, cheems, muscular, dog, carries, groceries, timid, city, street', ARRAY['One carries the bags; the other offers moral support', 'Yesterday and today shop very differently']::text[]),
  ('047-abs.webp', 'Park fountain', 'Садовник у фонтана отступает от каменных рыб, которые выплёвывают разноцветные зонты вместо воды.', 'парк фонтан садовник каменные рыбы зонты вода прохожие', ARRAY['Вода пришла с собственной защитой от дождя', 'Прогулка потребовала сразу несколько куполов']::text[], 'Park fountain', 'A gardener hoses a public fountain, but the stone fish spits out umbrellas instead of water; joggers dodge the umbrellas.', 'park, fountain, gardener, hoses, public, but, stone, fish, spits, umbrellas, water, joggers, dodge', ARRAY['The water brought its own protection from rain', 'This walk called for several roofs at once']::text[]),
  ('047-card.webp', 'Сани через снег', 'Женщина едет на санях, запряжённых оленями, через зимний лес и замёрзшее озеро под бледным небом.', 'женщина, сани, олени, снег, зимний лес, озеро, путешествие', ARRAY['Зимнее такси снова выбрало короткий путь через лес', 'Следы на льду ведут туда, где ещё горит свет']::text[], 'Sleigh Through the Snow', 'A woman rides a reindeer-drawn sleigh through a winter forest and across a frozen lake beneath a pale sky.', 'woman, sleigh, reindeer, winter forest, frozen lake, snow', ARRAY['The winter taxi took the shortcut through the woods again', 'Tracks on the ice lead to the last lit window']::text[]),
  ('047-cos.webp', 'Алиены учатся печь', 'Четырёхрукий инопланетянин печёт пирог по земной книге, но вместо начинки в духовку случайно закатилось НЛО.', 'четырёхрукий инопланетянин, земная книга рецептов, пирог, духовка, НЛО, кухня', ARRAY['По рецепту требовалась начинка, а не транспорт', 'Остудить перед взлётом забыли']::text[], 'UFO Pie', 'A four-armed alien bakes from an Earth cookbook but accidentally rolls a UFO into the oven instead of filling.', 'four-armed alien, pie, Earth cookbook, oven, UFO', ARRAY['The recipe called for filling, not transport', 'They forgot to let it cool before takeoff']::text[]),
  ('047-meme.webp', 'Stonks', 'Деловой манекен торжествует за ресторанным столом перед графиком роста, построенным из макарон.', 'Stonks, стонкс, манекен, бизнес, график роста, макароны, деньги', ARRAY['Инвестиции в ужин неожиданно пошли вверх', 'Финансовый отчёт пахнет сыром']::text[], 'Stonks', 'A business mannequin celebrates at a restaurant table before a rising graph made of pasta.', 'stonks, business, mannequin, celebrates, restaurant, table, before, rising, graph, made, pasta', ARRAY['The dinner investment unexpectedly went up', 'The financial report smells like cheese']::text[]),
  ('048-abs.webp', 'Ticket booth', 'Продавец билетов в цирке вручает прохожему маленькую дверь вместо билета, и тот с сомнением ставит ногу на порог.', 'цирк касса билеты продавец маленькая дверь дверца порог прохожий шатёр', ARRAY['Вход в представление можно унести с собой', 'Билет оказался настоящим испытанием']::text[], 'Ticket booth', 'A circus ticket seller hands a commuter a small door instead of a ticket; the man hesitates with one foot on the threshold.', 'ticket, booth, circus, seller, hands, commuter, door, man, hesitates, foot, threshold', ARRAY['You can carry the entrance home with you', 'The ticket turned out to be the real test']::text[]),
  ('048-card.webp', 'Синий кузнец', 'Огромный синий великан работает у красной кузнечной печи, а рядом ждёт рыжий волк.', 'синий великан, кузнец, красная печь, огонь, кузница, рыжий волк', ARRAY['Кто-то заказал искру размером с дверь', 'Подмастерье сегодня особенно пушистый']::text[], 'Blue Blacksmith', 'An enormous blue giant works at a red forge while a red wolf waits nearby.', 'blue giant, blacksmith, forge, red furnace, red wolf', ARRAY['Someone ordered a spark the size of a door', 'The apprentice is particularly fluffy today']::text[]),
  ('048-cos.webp', 'Космическое такси', 'Таксист-ящерица везёт трёх очень разных пришельцев на заднем сиденье через туманность, счётчик показывает расстояние в смешках.', 'таксист-ящерица, инопланетные пассажиры, такси, туманность, счётчик, космическая дорога', ARRAY['Поездка стоит семь шуток и один поворот', 'Пассажиры спорили о маршруте до самой звезды']::text[], 'Nebula Taxi', 'A lizard taxi driver carries three very different aliens through a nebula while the meter counts distance in laughs.', 'lizard driver, taxi, aliens, nebula, laugh meter', ARRAY['The ride costs seven jokes and one turn', 'The passengers argued about the route all the way to the star']::text[]),
  ('048-meme.webp', 'Circle in Triangle Factory', 'На конвейере фабрики треугольников внезапно появляется большой синий шар, изумляя рабочих.', 'Circle in Triangle Factory, круг на фабрике треугольников, конвейер, синий шар, фигуры, рабочие', ARRAY['Когда прошёл собеседование не в тот отдел', 'Каждый продукт идеален, кроме самого интересного']::text[], 'Circle in Triangle Factory', 'A large blue sphere appears on a conveyor in a triangle factory, baffling the workers.', 'circle, triangle, factory, blue, sphere, appears, conveyor, baffling, workers', ARRAY['A candidate showed up for the wrong department', 'Every product was perfect except the most interesting one']::text[]),
  ('049-abs.webp', 'Pet veterinarian', 'В ветеринарной клинике обеспокоенная женщина принесла увядшее растение, а рыжий кот-врач осматривает его с блокнотом.', 'ветеринар кот врач растение цветок листья клиника женщина стетоскоп блокнот', ARRAY['Пациенту рекомендовали больше солнца', 'Врач впервые попросил поливать больного']::text[], 'Pet veterinarian', 'A worried woman brings her houseplant to a vet; the plant lies on the examination table with a thermometer while the cat takes notes.', 'pet, veterinarian, worried, woman, brings, houseplant, vet, plant, lies, examination, table, thermometer, cat, takes, notes', ARRAY['The patient was prescribed more sunlight', 'For once the doctor asked someone to water the patient']::text[]),
  ('049-card.webp', 'Гора с живым сердцем', 'Гигантская каменная фигура с башнями на плечах возвышается над ущельем, а в её трещинах светится красная лава.', 'каменный гигант, гора, башни, лава, трещины, маленький человек', ARRAY['Старая крепость наконец встала размять ноги', 'Снаружи камень, внутри слишком горячие новости']::text[], 'Mountain with a Living Heart', 'A giant stone figure with towers on its shoulders rises above a gorge with red lava glowing in its cracks.', 'stone giant, towers, gorge, lava, mountain, glowing cracks', ARRAY['The old fortress finally got up to stretch its legs', 'Stone on the outside, fiery news within']::text[]),
  ('049-cos.webp', 'Метеоритный душ', 'Космонавт принимает душ под маленьким водопадом метеоритов, намыливая шлем губкой в форме звезды.', 'космонавт, душ, метеориты, губка в форме звезды, шлем, вода, космос', ARRAY['После такого купания шлем лучше не снимать', 'Вода закончилась, но поток всё ещё идёт']::text[], 'Meteor Shower Bath', 'An astronaut showers under a small waterfall of meteorites, scrubbing a helmet with a star-shaped sponge.', 'astronaut, shower, meteorites, helmet, star sponge', ARRAY['Best not remove the helmet after this bath', 'The water ran out, but the shower did not']::text[]),
  ('049-meme.webp', 'Epic Handshake', 'Две огромные мускулистые руки сцепляются над столом переговоров, под которым внезапно извергается вулкан.', 'Epic Handshake, эпическое рукопожатие, руки, сила, стол, вулкан, союз', ARRAY['Нашли общий язык и сломали переговорную', 'Когда компромисс оказался слишком горячим']::text[], 'Epic Handshake', 'Two massive muscular hands clasp across a negotiating table above an erupting volcano.', 'epic, handshake, massive, muscular, hands, clasp, negotiating, table, erupting, volcano', ARRAY['They found common ground and broke the meeting room', 'The compromise was much too hot']::text[]),
  ('050-abs.webp', 'Apartment bathroom', 'Мужчина бреется у зеркала: борода растёт только у отражения, а у него в руке остаётся бесполезная бритва.', 'ванная мужчина зеркало отражение борода бритьё бритва раковина', ARRAY['Утренний уход достался не тому лицу', 'Чисто выбрился только один из двоих']::text[], 'Apartment bathroom', 'A man shaves his reflection, but only the mirror grows a beard; he holds the razor outside, baffled.', 'apartment, bathroom, man, shaves, reflection, but, mirror, grows, beard, holds, razor, baffled', ARRAY['The morning routine reached the wrong face', 'Only one of them ended up clean-shaven']::text[]),
  ('050-card.webp', 'Улиточная карета', 'Лис или маленький путник встречает в осеннем лесу светящуюся карету с раковиной улитки.', 'улитка, раковина, карета, лис, путник, осенний лес, свет', ARRAY['Медленная доставка уже почти сказочно близко', 'Карету нашли, осталось уговорить её поторопиться']::text[], 'Snail Carriage', 'A fox or small traveler meets a glowing carriage with a snail shell in an autumn forest.', 'snail carriage, shell, fox, traveler, glowing carriage, autumn forest', ARRAY['The slow delivery is almost magically close', 'We found the carriage; now persuade it to hurry']::text[]),
  ('050-cos.webp', 'Дипломатия с картошкой', 'Серьёзный посол вручает инопланетному королю картофелину на бархатной подушке, вокруг охрана салютует вилками.', 'посол, инопланетный король, картофелина, бархатная подушка, охрана, вилки, дипломатия', ARRAY['Межпланетный мир держится на одном клубне', 'Королевский подарок лучше подавать горячим']::text[], 'Potato for the Alien King', 'A serious envoy offers an alien king a potato on a velvet pillow while guards salute with forks.', 'envoy, alien king, potato, velvet pillow, guards, forks', ARRAY['Interplanetary peace rests on a single tuber', 'The royal gift is best served hot']::text[]),
  ('050-meme.webp', 'Pedro Raccoon', 'Круглый енот вертится как волчок на зеркальном диско-шаре, пока вокруг стоят серьёзные лесные звери.', 'Pedro Raccoon, енот Педро, енот, танец, диско-шар, лесные звери, вечеринка', ARRAY['Когда ты единственный услышал музыку', 'Вечеринка началась без согласования с лесом']::text[], 'Pedro Raccoon', 'A round raccoon spins like a top on a mirrored disco ball while serious forest animals watch.', 'pedro, raccoon, round, spins, top, mirrored, disco, ball, serious, forest, animals, watch', ARRAY['He was the only one who heard the music', 'The party began without consulting the forest']::text[]),
  ('051-abs.webp', 'Rooftop laundry', 'Женщина развешивает бельё на крыше, и наволочка на верёвке раздувается парусом для крошечного моряка-носка.', 'крыша бельё верёвка наволочка парус лодка носок женщина стирка', ARRAY['Стирка неожиданно отправилась в плавание', 'На верёвке появился маленький капитан']::text[], 'Rooftop laundry', 'An aunt hangs laundry and a pillowcase inflates into a miniature sailboat carrying a sock captain.', 'rooftop, laundry, aunt, hangs, pillowcase, inflates, miniature, sailboat, carrying, sock, captain', ARRAY['The laundry unexpectedly set sail', 'A tiny captain appeared on the line']::text[]),
  ('051-card.webp', 'Пчела с планеты-мёда', 'Старик собирает мёд из улья, похожего на маленькую планету, над которой кружит гигантская пчела.', 'старик, мёд, улей, планета, огромная пчела, соты', ARRAY['На завтрак хватит одной капли целой вселенной', 'Пчеловодство вышло далеко за пределы сада']::text[], 'Bee from the Honey Planet', 'An old man gathers honey from a hive shaped like a small planet while a giant bee circles overhead.', 'old man, honey, hive, tiny planet, giant bee, honeycomb', ARRAY['One drop of the universe is plenty for breakfast', 'Beekeeping has gone far beyond the garden']::text[]),
  ('051-cos.webp', 'Призрачная заправка', 'На пустынной луне призрачный заправщик наливает свет в бак прозрачного космического скутера, стоящего вертикально.', 'призрачный заправщик, пустынная луна, свет, прозрачный скутер, космическая заправка', ARRAY['Бак пустой, зато дорога видна насквозь', 'На этой станции топливо исчезает красиво']::text[], 'Ghostly Moon Gas Station', 'A ghostly attendant fills the tank of a transparent space scooter with light on a deserted moon.', 'ghost, gas station, moon, transparent scooter, glowing fuel', ARRAY['The tank is empty, but you can see the whole road through it', 'The fuel vanishes beautifully at this station']::text[]),
  ('051-meme.webp', 'Screaming Marmot', 'Сурок на горной вершине кричит в огромный бронзовый чайник под ярким небом.', 'Screaming Marmot, кричащий сурок, сурок, гора, чайник, крик, Альпы', ARRAY['Когда вода закипела раньше терпения', 'Объявление для всей долины без микрофона']::text[], 'Screaming Marmot', 'A marmot screams into a giant bronze kettle atop a mountain beneath a bright sky.', 'screaming, marmot, screams, bronze, kettle, atop, mountain, beneath, bright, sky', ARRAY['The water boiled before his patience did', 'An announcement for the entire valley without a microphone']::text[]),
  ('052-abs.webp', 'Newsstand', 'В газетном киоске продавец выдаёт зонт из чистого газетного листа; лужи на улице складываются в завтрашний прогноз.', 'газетный киоск газеты зонтик дождь продавец покупатель лужи прогноз погоды', ARRAY['Новости сегодня спасают от осадков', 'Прогноз напечатался прямо на тротуаре']::text[], 'Newsstand', 'A vendor hands out umbrellas made from blank newspapers while the pavement displays tomorrow''s weather as puddle shapes.', 'newsstand, vendor, hands, umbrellas, made, blank, newspapers, pavement, displays, tomorrow, weather, puddle, shapes', ARRAY['Today''s news will keep the rain off', 'Tomorrow''s forecast printed itself on the pavement']::text[]),
  ('052-card.webp', 'Парад драконов', 'Яркие драконы проходят праздничным парадом по улице парящего города под солнцем и разноцветными бабочками.', 'драконы, парад, праздник, город, солнце, бабочки, яркие краски', ARRAY['Праздничный салют сегодня дышит сам', 'Улица решила надеть все цвета сразу']::text[], 'Dragon Parade', 'Bright dragons march in a festive parade through a floating city beneath the sun and colorful butterflies.', 'dragons, parade, floating city, sun, butterflies, festival, bright colors', ARRAY['The fireworks learned to breathe on their own', 'The street put on every color at once']::text[]),
  ('052-cos.webp', 'Космический шахматист', 'Пожилой пришелец играет в шахматы с чёрной дырой; исчезающие фигуры возвращаются в виде маленьких котят.', 'пожилой пришелец, шахматы, чёрная дыра, исчезающие фигуры, котята, космическая партия', ARRAY['Проигранные фигуры вернулись с усами', 'Соперник поглощает всё, кроме чувства юмора']::text[], 'Chess with a Black Hole', 'An elderly alien plays chess with a black hole; captured pieces return as tiny kittens.', 'elderly alien, chess, black hole, kittens, pieces', ARRAY['The lost pieces came back with whiskers', 'The opponent swallows everything but his sense of humor']::text[]),
  ('052-meme.webp', 'Sneezing Panda', 'Маленькая панда чихает так сильно, что рядом рушится высокая бамбуковая башня.', 'Sneezing Panda, чихающая панда, панда, чих, бамбук, башня, падение', ARRAY['Самый короткий способ отменить строительство', 'Будь здоров — сказала вся деревня']::text[], 'Sneezing Panda', 'A little panda sneezes so hard that a tall bamboo tower collapses beside it.', 'sneezing, panda, sneezes, hard, tall, bamboo, tower, collapses', ARRAY['The shortest way to cancel construction', 'The whole village said bless you']::text[]),
  ('053-abs.webp', 'Fast food kitchen', 'Повар на кухне подбрасывает блин, который превращается в летающую тарелку; коллега машет лопаткой как диспетчер.', 'кухня повар блин сковорода летающая тарелка НЛО лопатка ресторан', ARRAY['Завтрак запросил разрешение на взлёт', 'На кухне снова задержали посадку']::text[], 'Fast food kitchen', 'A cook flips a pancake that refuses to land and becomes a small hovering UFO; colleague raises a spatula like an air-traffic baton.', 'fast, food, kitchen, cook, flips, pancake, refuses, land, becomes, hovering, ufo, colleague, raises, spatula, air, traffic, baton', ARRAY['Breakfast requested clearance for takeoff', 'Another landing was delayed in the kitchen']::text[]),
  ('053-card.webp', 'Викинг и мировой змей', 'Бородатый викинг заплетает длинное зелёное тело огромного змея на заснеженном берегу.', 'викинг, борода, мировой змей, зелёная чешуя, коса, снег, берег', ARRAY['С таким клиентом парикмахер пропустит обед', 'Самая длинная причёска в северных легендах']::text[], 'Viking and the World Serpent', 'A bearded Viking braids the long green body of a huge serpent on a snowy shore.', 'Viking, beard, world serpent, green scales, braid, snow, shore', ARRAY['The hairdresser will miss lunch with this client', 'The longest hairstyle in northern legend']::text[]),
  ('053-cos.webp', 'Чайная церемония в вакууме', 'Два астронавта пытаются налить чай в невесомости, чайный шар парит между ними и отражает смешные лица.', 'два астронавта, чайная церемония, невесомость, чайный шар, отражения, космическая станция', ARRAY['Налить в чашку оказалось сложнее, чем долететь', 'Пауза на обед зависла посередине комнаты']::text[], 'Tea in Zero Gravity', 'Two astronauts try to pour tea in weightlessness as a tea sphere floats between them reflecting funny faces.', 'astronauts, tea, zero gravity, floating sphere, cups', ARRAY['Pouring a cup was harder than reaching orbit', 'The lunch break hung in the middle of the room']::text[]),
  ('053-meme.webp', 'Dancing Baby', 'Танцующий малыш задаёт ритм параду строгих роботов на городской площади под красным солнцем.', 'Dancing Baby, танцующий малыш, младенец, роботы, парад, танец, город', ARRAY['Они получили команду маршировать, а выучили джайв', 'Самый маленький хореограф взял смену под контроль']::text[], 'Dancing Baby', 'A dancing toddler sets the rhythm for a parade of stern robots in a city square.', 'dancing, baby, toddler, sets, rhythm, parade, stern, robots, city, square', ARRAY['They were told to march and learned to jive', 'The smallest choreographer took over the shift']::text[]),
  ('054-abs.webp', 'Storage locker', 'Женщина открывает шкафчик, откуда марширует толпа маленьких календарных карточек с чемоданами.', 'шкаф шкафчик женщина календарь карточки встречи дела чемоданы очередь', ARRAY['Все планы разом вышли из хранения', 'Забытые встречи уже собрали чемоданы']::text[], 'Storage locker', 'A woman opens a locker to retrieve a suitcase; hundreds of tiny appointment cards walk out carrying their own luggage.', 'storage, locker, woman, opens, retrieve, suitcase, hundreds, appointment, cards, walk, carrying, luggage', ARRAY['All the plans came out of storage at once', 'Forgotten meetings have already packed their bags']::text[]),
  ('054-card.webp', 'Домик-раковина', 'Небольшой освещённый дом в форме морской раковины плывёт по тихому морю под огромной луной.', 'дом, морская раковина, море, луна, окна, ночь, плавучий дом', ARRAY['Адрес меняется с каждым приливом', 'Когда переезд доверили течению']::text[], 'Shell House', 'A small illuminated house shaped like a seashell floats on a calm sea beneath an enormous moon.', 'house, seashell, sea, moon, windows, night, floating home', ARRAY['The address changes with every tide', 'When the current handled the move']::text[]),
  ('054-cos.webp', 'Робот заблудился в себе', 'Маленький робот изучает карту собственного живота и обнаруживает там лестницу, ведущую к пляжу с зонтиком.', 'маленький робот, карта собственного живота, лестница, пляж, зонтик, внутренний мир', ARRAY['Искал инструкцию, нашёл отпуск внутри себя', 'Маршрут до моря начинается где-то под крышкой']::text[], 'Robot''s Inner Beach', 'A small robot studies a map of its own belly and discovers a staircase leading to a beach and umbrella.', 'robot, map, belly, staircase, beach, umbrella', ARRAY['It looked for instructions and found a vacation inside', 'The route to the sea starts under the cover']::text[]),
  ('054-meme.webp', 'Skeleton Banging Shield', 'Разъярённый скелет в броне бьёт мечом по щиту, разбрасывая вокруг тарелки и ложки.', 'Skeleton Banging Shield, скелет бьёт по щиту, скелет, броня, меч, щит, тарелки', ARRAY['Когда позвали ужинать слишком торжественно', 'Соседи снизу уже выучили этот ритм']::text[], 'Skeleton Banging Shield', 'An angry armored skeleton bangs a sword on its shield, scattering plates and spoons.', 'skeleton, banging, shield, angry, armored, bangs, sword, scattering, plates, spoons', ARRAY['Someone called everyone to dinner too formally', 'The downstairs neighbors already know the rhythm']::text[]),
  ('055-abs.webp', 'Flowering pothole', 'Рабочие регулируют машины вокруг ямы в асфальте, где вырос цветущий сад; оранжевый конус его поливает.', 'дорога яма выбоина цветы клумба машины рабочие конус полив движение', ARRAY['Ремонт дороги неожиданно зацвёл', 'Объезд устроили ради самого маленького сада']::text[], 'Flowering pothole', 'Road workers politely guide cars around a pothole filled with blossoming flowers; one orange construction cone waters them.', 'flowering, pothole, road, workers, politely, guide, cars, filled, blossoming, flowers, orange, construction, cone, waters', ARRAY['Road repairs suddenly began to bloom', 'The detour was built for the smallest garden']::text[]),
  ('055-card.webp', 'Пойманный закат', 'Путник держит сияющую раму с закатом посреди оживлённой сумеречной улицы, где видны часы и прохожие.', 'путник, рамка, светящийся закат, улица, часы, прохожие, сумерки', ARRAY['Он унёс домой последние пять минут вечера', 'Время пришлось вставить в рамку']::text[], 'Captured Sunset', 'A traveler holds a glowing frame containing a sunset on a busy twilight street with clocks and passersby.', 'traveler, frame, sunset, street, clocks, people, twilight', ARRAY['He brought home the last five minutes of evening', 'Time had to be put in a frame']::text[]),
  ('055-cos.webp', 'Космическая доставка цветов', 'Инопланетная курьерша вручает букет из миниатюрных спутников гигантскому одинокому планетному кольцу.', 'инопланетная курьерша, букет спутников, одинокая планета, кольцо, доставка цветов', ARRAY['Подарок совершит вокруг адресата полный оборот', 'Даже самый далёкий сосед достоин внимания']::text[], 'Satellite Bouquet', 'An alien courier gives a bouquet of miniature satellites to a giant lonely planetary ring.', 'alien courier, bouquet, satellites, planetary ring, gift', ARRAY['The present will circle its recipient once', 'Even the most distant neighbor deserves a little attention']::text[]),
  ('055-meme.webp', 'Kermit Sipping Tea', 'Зелёная кукольная лягушка пьёт чай на театральном балконе и смотрит на город, охваченный сплетнями.', 'Kermit Sipping Tea, лягушонок Кермит пьёт чай, лягушка, чашка, театр, сплетни', ARRAY['Я ничего не утверждаю, просто завариваю факты', 'Когда всё видишь и остаёшься зрителем']::text[], 'Kermit Sipping Tea', 'A green puppet frog drinks tea on a theater balcony above a city buzzing with gossip.', 'kermit, sipping, tea, green, puppet, frog, drinks, theater, balcony, city, buzzing, gossip', ARRAY['I am not making claims; I am brewing facts', 'He saw everything and stayed in the audience']::text[]),
  ('056-abs.webp', 'Ski shop', 'В лыжном магазине продавец складывает снежные горы в коробку, пока шарф покупателя завязывается в санки.', 'лыжный магазин продавец покупатель снег горы зима шарф санки коробка', ARRAY['Зимний отпуск уместили в покупку', 'Горы продают вместе с упаковкой']::text[], 'Ski shop', 'A clerk tries to fold winter into a shopping bag while a shopper''s scarf ties itself into a sled.', 'ski, shop, clerk, tries, fold, winter, shopping, bag, shopper, scarf, ties, itself, sled', ARRAY['The entire winter holiday fit in one purchase', 'The mountains come with their own box']::text[]),
  ('056-card.webp', 'Кит над кораблём', 'Длинный корабль викингов плывёт по ледяному морю под огромным парящим китом, за которым сияет ночное небо.', 'кит, корабль викингов, ледяное море, лодка, звёзды, небо', ARRAY['Небо сегодня решило проверить глубину', 'Моряки посмотрели вверх и забыли про компас']::text[], 'Whale Above the Ship', 'A long Viking ship sails across an icy sea beneath a huge floating whale and a glowing night sky.', 'whale, Viking ship, icy sea, boat, stars, night sky', ARRAY['Today the sky decided to measure the depths', 'The sailors looked up and forgot the compass']::text[]),
  ('056-cos.webp', 'Луна в стиральной корзине', 'Астронавт несёт луну в плетёной корзине для белья по станции, из кратера торчат разноцветные носки.', 'астронавт, Луна, корзина для белья, цветные носки, кратер, космическая станция', ARRAY['Стиральная машина снова занята целым миром', 'Когда носкам выделили отдельное небесное тело']::text[], 'Moon Laundry', 'An astronaut carries the moon in a wicker laundry basket through a station with colorful socks sticking out of a crater.', 'astronaut, moon, laundry basket, socks, crater, space station', ARRAY['The washing machine is occupied by a whole world again', 'Someone gave the socks their own celestial body']::text[]),
  ('056-meme.webp', 'Злая копия', 'Зелёный лягушонок спорит с собственной тёмной копией в плаще среди высоких кривых зеркал.', 'злая копия, Evil Kermit, лягушонок, зеркало, двойник, тень, плащ, спор', ARRAY['Когда внутренний голос наконец показал лицо', 'Совет был плохой, зато очень убедительный']::text[], 'Evil Kermit', 'A green frog argues with its dark cloaked double among tall crooked mirrors.', 'evil, kermit, green, frog, argues, dark, cloaked, double, among, tall, crooked, mirrors', ARRAY['The inner voice finally showed its face', 'Bad advice, delivered very convincingly']::text[]),
  ('057-abs.webp', 'Pizza delivery', 'Курьер открывает коробку с пиццей и видит внутри круговую развязку с миниатюрными машинами вместо начинки.', 'доставка курьер пицца коробка круговая развязка машины пробка дорога', ARRAY['Доставка застряла прямо в заказе', 'На ужин сегодня очередь по кругу']::text[], 'Pizza delivery', 'A delivery rider opens a pizza box: inside is a tiny roundabout full of impatient miniature cars instead of toppings.', 'pizza, delivery, rider, opens, box, roundabout, full, impatient, miniature, cars, toppings', ARRAY['Delivery got stuck inside the order', 'Tonight''s dinner keeps going in circles']::text[]),
  ('057-card.webp', 'Лавка на астероиде', 'Маленькая лавка с дымящейся трубой стоит на отдельном астероиде; у входа видны волшебник и сказочное существо.', 'лавка, маленький дом, астероид, космос, труба, волшебник, существо', ARRAY['Доставка за пределы орбиты оплачивается отдельно', 'Единственный магазин, где соседей нет даже в телескоп']::text[], 'Shop on an Asteroid', 'A tiny shop with a smoking chimney sits alone on an asteroid while a wizard and a strange creature wait by the entrance.', 'shop, tiny house, asteroid, space, chimney, wizard, creature', ARRAY['Delivery beyond orbit costs extra', 'The only shop whose neighbors need a telescope']::text[]),
  ('057-cos.webp', 'Осьминог-диспетчер', 'Осьминог с восемью телефонами разводит потоки комет на переполненном космическом перекрёстке, вид строго сверху.', 'осьминог, диспетчер, восемь телефонов, кометы, космический перекрёсток, пробка', ARRAY['Все линии заняты, но движение ещё живо', 'На этой работе рук всё равно не хватает']::text[], 'Octopus Traffic Controller', 'An octopus with eight phones directs comet traffic at a crowded space intersection.', 'octopus, eight phones, comets, traffic, space intersection', ARRAY['All lines are busy, but the traffic still moves', 'Even eight hands are not enough for this job']::text[]),
  ('057-meme.webp', 'Pepe Sad Frog', 'Печальная зелёная лягушка сидит у лужи в осеннем городе и отпускает бумажный кораблик.', 'Pepe Sad Frog, грустный Пепе, Пепе лягушка, бумажный кораблик, лужа, дождь, осень', ARRAY['Отправил надежду почтой, но адрес размыло', 'Когда отпуск кончился ещё до поездки']::text[], 'Sad Pepe', 'A sad green frog sits by a puddle in an autumn city and releases a paper boat.', 'sad, pepe, green, frog, sits, puddle, autumn, city, releases, paper, boat', ARRAY['Mailed his hopes, but the rain blurred the address', 'The holiday ended before the journey began']::text[]),
  ('058-abs.webp', 'Telephone booth', 'Женщина у телефонной будки тянет из трубки длинную белую ленту тишины, а голуби на площади внимательно слушают.', 'телефон будка трубка женщина тишина лента голуби площадь звонок', ARRAY['Самый длинный разговор прошёл без слов', 'Даже птицы ждут продолжения звонка']::text[], 'Telephone booth', 'A woman answers a ringing payphone and holds a long ribbon of quiet; nearby pigeons lean in to listen.', 'telephone, booth, woman, answers, ringing, payphone, holds, long, ribbon, quiet, nearby, pigeons, lean, listen', ARRAY['The longest call contained no words', 'Even the birds are waiting for the next sentence']::text[]),
  ('058-card.webp', 'Сад внутри великана', 'Спящий каменный великан лежит у замка, а в полости его груди маленькие люди устроили зелёный сад.', 'каменный великан, сон, сад, люди, грудь, замок, мох', ARRAY['Лучшее место для огорода нашлось у самого сердца', 'Хозяин проснётся и очень удивится урожаю']::text[], 'Garden Inside a Giant', 'A sleeping stone giant lies by a castle while tiny people tend a green garden in a hollow in his chest.', 'stone giant, sleep, garden, little people, chest, castle, moss', ARRAY['The best place for a garden was close to the heart', 'The owner will be surprised by the harvest']::text[]),
  ('058-cos.webp', 'Сырная планета', 'Мышь-исследователь прокладывает тоннель в планете из сыра, а из каждого отверстия выглядывает крошечный пришелец.', 'мышь-исследователь, сырная планета, тоннель, отверстия, крошечные пришельцы, космос', ARRAY['Путешествие обещало быть очень вкусным', 'Соседей обнаружили только после первого укуса']::text[], 'Mouse on a Cheese Planet', 'An explorer mouse tunnels through a cheese planet while tiny aliens peek from every hole.', 'mouse, cheese planet, tunnels, little aliens, holes', ARRAY['The journey promised to be delicious', 'They discovered the neighbors after the first bite']::text[]),
  ('058-meme.webp', 'Вы продаёте рыбов', 'За деревянным прилавком огромный серьёзный кот показывает покупателю одну нелепо длинную рыбу.', 'вы продаёте рыбов, кот с рыбой, огромный кот, длинная рыба, прилавок, покупатель', ARRAY['Ассортимент узкий, зато очень длинный', 'Когда клиент спросил без лишних уточнений']::text[], 'Do You Sell Fish?', 'A huge serious cat behind a wooden counter shows a shopper one absurdly long fish.', 'you, sell, fish, huge, serious, cat, wooden, counter, shows, shopper, absurdly, long', ARRAY['The selection is narrow but extremely long', 'The customer asked without any extra details']::text[]),
  ('059-abs.webp', 'Apartment mailboxes', 'Пожилой мужчина открыл почтовый ящик, и оттуда вышел крошечный сосед с цветком и чемоданом.', 'почтовый ящик почта письмо старик сосед миниатюрный человек цветок чемодан', ARRAY['Вместо письма приехал целый жилец', 'Адресат оказался меньше конверта']::text[], 'Apartment mailboxes', 'A retired man opens his mailbox; a small wind-up neighbor steps out carrying a flower and a tiny suitcase.', 'apartment, mailboxes, retired, man, opens, mailbox, wind, neighbor, steps, carrying, flower, suitcase', ARRAY['A whole tenant arrived instead of a letter', 'The addressee was smaller than the envelope']::text[]),
  ('059-card.webp', 'Комната под водой', 'Обычная спальня с кроватью стала подводным миром, где между мебелью плавают медузы и рыбы.', 'спальня, кровать, подводный мир, медузы, рыбы, мебель, вода', ARRAY['Перед сном окно забыли закрыть от океана', 'Будильник теперь звенит где-то на дне']::text[], 'Underwater Room', 'An ordinary bedroom with a bed has become an underwater world where jellyfish and fish swim between the furniture.', 'bedroom, bed, underwater, jellyfish, fish, furniture, water', ARRAY['Someone forgot to close the window against the ocean', 'The alarm clock now rings somewhere on the seabed']::text[]),
  ('059-cos.webp', 'НЛО на пикнике', 'Инопланетная семья устроила пикник на перевёрнутой тарелке-НЛО; скатерть улетает, а бутерброды держатся магнитами.', 'инопланетная семья, НЛО, летающая тарелка, пикник, скатерть, бутерброды, магниты', ARRAY['Скатерть улетела раньше первого тоста', 'Обед на свежем вакууме требует особой посуды']::text[], 'Upside-Down UFO Picnic', 'An alien family picnics on an overturned UFO while the tablecloth flies away and magnets hold the sandwiches.', 'alien family, picnic, upside-down UFO, tablecloth, magnetic sandwiches', ARRAY['The tablecloth took off before the first toast', 'Lunch in the fresh vacuum requires special dishes']::text[]),
  ('059-meme.webp', 'Wojak Doomer', 'Грустный схематичный парень стоит в ночном городе у киоска, где за витриной продаются звёзды.', 'Wojak Doomer, думер, вояк, грустный парень, ночной киоск, звёзды, одиночество', ARRAY['Даже вечность сегодня закрывается в девять', 'Когда хотелось купить немного смысла на сдачу']::text[], 'Doomer Wojak', 'A sad cartoon man stands by a nighttime kiosk selling stars in a lonely city.', 'doomer, wojak, sad, cartoon, man, stands, nighttime, kiosk, selling, stars, lonely, city', ARRAY['Even eternity closes at nine tonight', 'He wanted to buy a little meaning with the change']::text[]),
  ('060-abs.webp', 'Wedding planner', 'Организатор праздника пытается поместить огромный свадебный торт в раскрытый ежедневник, пока свечи изображают жениха и невесту.', 'свадьба планировщик торт ежедневник книга свечи жених невеста цветы', ARRAY['Торжество вышло за пределы расписания', 'Двое главных гостей уже горят от нетерпения']::text[], 'Wedding planner', 'A planner struggles to fit a gigantic wedding cake into a small appointment book; two candles behave like impatient bride and groom.', 'wedding, planner, struggles, fit, gigantic, cake, appointment, book, candles, behave, impatient, bride, groom', ARRAY['The celebration spilled beyond the calendar', 'The two guests of honor are burning with impatience']::text[]),
  ('060-cos.webp', 'Уборка после биг-бэнга', 'Молодая богиня в резиновых перчатках подметает искры после создания вселенной огромной метлой.', 'богиня, резиновые перчатки, огромная метла, искры, создание вселенной, Большой взрыв, уборка', ARRAY['Праздник сотворения закончился генеральной уборкой', 'Мелкие крошки оказались новыми мирами']::text[], 'Cleaning After Creation', 'A young goddess in rubber gloves sweeps up sparks after creating the universe with an enormous broom.', 'goddess, rubber gloves, broom, sparks, creation, universe', ARRAY['The creation party ended with a thorough cleanup', 'The tiny crumbs turned out to be new worlds']::text[]),
  ('060-meme.webp', 'NPC Wojak', 'Толпа одинаковых серых человечков синхронно окружила единственный цветок и смотрит на него.', 'NPC Wojak, НПС вояк, одинаковые люди, толпа, серые человечки, цветок, одинаковость', ARRAY['У всех своё мнение, и оно почему-то одно', 'Необычное событие обнаружено всей улицей одновременно']::text[], 'NPC Wojak', 'A crowd of identical gray cartoon people surrounds a single flower and stares at it together.', 'npc, wojak, crowd, identical, gray, cartoon, people, surrounds, single, flower, stares, together', ARRAY['They all have opinions, and somehow the same one', 'The entire street noticed the unusual event at once']::text[]),
  ('061-abs.webp', 'Public sauna', 'Старик сидит в сауне за шахматным столом, а пар над ним складывается в серьёзное собрание людей.', 'сауна баня пар шахматы старик заседание собрание полотенце', ARRAY['Даже отдых превратился в совещание', 'У этой партии слишком много невидимых советчиков']::text[], 'Public sauna', 'An old chess player sits in steam that forms a perfectly serious office meeting around him; a towel serves as chairperson.', 'public, sauna, chess, player, sits, steam, forms, perfectly, serious, office, meeting, him, towel, serves, chairperson', ARRAY['Even relaxation turned into a meeting', 'This game has too many invisible advisers']::text[]),
  ('061-card.webp', 'Буря в бутылке', 'Светловолосая женщина стоит у стеклянной бутылки, в которой бушует маленькое море с грозой.', 'женщина, стеклянная бутылка, буря, море, гроза, тёмная комната', ARRAY['Погода поместилась на полке, характер — нет', 'Открывать только в случае затянувшейся тишины']::text[], 'Storm in a Bottle', 'A blond woman stands beside a glass bottle containing a tiny stormy sea and thunderclouds.', 'woman, glass bottle, storm, tiny sea, thunder, dark room', ARRAY['The weather fit on a shelf, but its temper did not', 'Open only if the silence goes on too long']::text[]),
  ('061-cos.webp', 'Космический курьер пиццы', 'Курьер на реактивных роликах доставляет пиццу в кратер, где её ждёт голодный лунный кролик в галстуке.', 'курьер пиццы, реактивные ролики, лунный кратер, голодный кролик, галстук, доставка', ARRAY['Горячее доставили до полного оборота', 'Клиент ждал у самой глубокой двери']::text[], 'Pizza for a Moon Rabbit', 'A courier on rocket skates brings pizza to a crater where a hungry moon rabbit in a tie waits.', 'courier, rocket skates, pizza, crater, moon rabbit, tie', ARRAY['The hot order arrived before the next full orbit', 'The customer waited at the deepest doorway']::text[]),
  ('061-meme.webp', 'Chad vs Virgin', 'На солнечном состязании мускулистый силач и худой соперник несут по огромному арбузу.', 'Chad vs Virgin, Чад против девственника, качок, худой соперник, арбуз, соревнование', ARRAY['Одна покупка, два совершенно разных подхода', 'Когда поход за фруктами стал олимпийской дисциплиной']::text[], 'Chad vs Virgin', 'A muscular strongman and a skinny rival carry enormous watermelons in a sunny contest.', 'chad, virgin, muscular, strongman, skinny, rival, carry, watermelons, sunny, contest', ARRAY['One purchase, two very different approaches', 'Shopping for fruit became an Olympic sport']::text[]),
  ('062-abs.webp', 'Elevator repair', 'Механик стоит на застрявшем лифте в шахте, где трос стал спагетти; маленькая мышь накручивает его на вилку.', 'лифт шахта механик трос спагетти макароны мышь вилка ремонт', ARRAY['Поломку решили подать на обед', 'Подъём зависит от очень голодного мастера']::text[], 'Elevator repair', 'A mechanic stands atop a stalled elevator car; its cable has turned into a long cooked spaghetti strand, and a mouse twirls it onto a fork.', 'elevator, repair, mechanic, stands, atop, stalled, car, cable, has, turned, long, cooked, spaghetti, strand, mouse, twirls, onto, fork', ARRAY['The breakdown was served for lunch', 'The ascent depends on a very hungry mechanic']::text[]),
  ('062-card.webp', 'Олень с замком в рогах', 'Фигура в капюшоне протягивает огонь белому оленю, в чьих огромных рогах стоит маленький замок.', 'белый олень, замок, рога, человек в капюшоне, свеча, луна, лес', ARRAY['На экскурсию в этот дворец лучше взять морковь', 'Огонёк указал дорогу туда, где нет тропы']::text[], 'Deer with a Castle in Its Antlers', 'A hooded figure offers a flame to a white deer whose enormous antlers hold a small castle.', 'white deer, castle, antlers, hooded figure, candle, moon, forest', ARRAY['Bring a carrot for the palace tour', 'A small light showed the way where there was no path']::text[]),
  ('062-cos.webp', 'Дирижёр метеоритов', 'Вид из-за плеча: дирижёр размахивает ложкой, управляя оркестром метеоритов, которые выстраиваются в музыкальные ноты.', 'дирижёр, ложка, оркестр метеоритов, музыкальные ноты, астероиды, космос', ARRAY['Один взмах — и небо попало в такт', 'Главное не уронить ритм на соседний город']::text[], 'Meteor Orchestra', 'A conductor waves a spoon to direct meteors into musical notes across the sky.', 'conductor, spoon, meteors, orchestra, musical notes, sky', ARRAY['One wave and the whole sky found the beat', 'Just do not drop the rhythm on the next town']::text[]),
  ('062-meme.webp', 'AI Baby Holding Laugh', 'Малыш с лукавой улыбкой прикрывает рот ладонью, пока взрослые на заднем плане спорят с роботом-няней.', 'AI Baby Holding Laugh, малыш сдерживает смех, ребёнок, робот-няня, спор, улыбка', ARRAY['Когда система объяснила правила, а пользователь знает секрет', 'Смеяться нельзя, но удержаться невозможно']::text[], 'Baby Holding Back Laughter', 'A mischievous baby covers its smile while adults argue with a robot nanny behind it.', 'baby, holding, back, laughter, mischievous, covers, smile, adults, argue, robot, nanny, laugh', ARRAY['The system explained the rules; the user knows a secret', 'Laughing is forbidden, but impossible to resist']::text[]),
  ('063-abs.webp', 'Antique shop', 'Хозяин антикварной лавки заводит старые часы, из которых выходит миниатюрный латунный парад.', 'антикварный магазин часы циферблат механизм латунь маленькие человечки парад старик', ARRAY['Прошлое вышло строем из шкафа', 'Покупка попросила показать дорогу']::text[], 'Antique shop', 'A customer winds an old clock and an entire tiny brass parade walks out of the dial, politely asking for directions.', 'antique, shop, customer, winds, clock, entire, brass, parade, walks, dial, politely, asking, directions', ARRAY['The past marched out of the cupboard', 'The purchase asked for directions home']::text[]),
  ('063-cos.webp', 'Инопланетный конкурс бород', 'Три разноцветных пришельца соревнуются в длине бород, одна борода обвила планету и держит на орбите чайник.', 'три пришельца, конкурс бород, длинная борода, планета, чайник, космическая мода', ARRAY['Победителю понадобится отдельная орбита', 'Когда уход за собой занял половину неба']::text[], 'Interplanetary Beard Contest', 'Three colorful aliens compare beards; one beard wraps around a planet and holds a kettle in orbit.', 'aliens, beard contest, planet, orbit, kettle', ARRAY['The winner will need a separate orbit', 'Grooming took up half the sky']::text[]),
  ('063-meme.webp', 'Crying Wojak', 'Схематичный грустный человечек улыбается под маской, а чёрный зонт над ним плачет вместо него.', 'Crying Wojak, плачущий вояк, маска улыбки, человечек, зонт, слёзы, дождь', ARRAY['Улыбка в порядке, прогноз — нет', 'Когда держишься молодцом только на аватарке']::text[], 'Crying Wojak', 'A sad cartoon man smiles behind a mask while a black umbrella above him cries in his place.', 'crying, wojak, sad, cartoon, man, smiles, mask, black, umbrella, him, cries, place', ARRAY['The smile is fine; the forecast is not', 'Doing great, at least in the profile picture']::text[]),
  ('064-abs.webp', 'Mailbox at night', 'Ночной почтальон обнаруживает спящий почтовый ящик под клетчатым одеялом; фонарь рядом держит чашку чая.', 'почтальон почтовый ящик письмо ночь одеяло фонарь чашка чай улица', ARRAY['Письма придётся доставить после сна', 'Даже фонарь сделал перерыв на чай']::text[], 'Mailbox at night', 'A postal carrier finds the mailbox asleep under a tiny blanket, refusing letters; a streetlamp holds a cup of tea.', 'mailbox, night, postal, carrier, finds, asleep, blanket, refusing, letters, streetlamp, holds, cup, tea', ARRAY['The letters will have to wait until morning', 'Even the lamp stopped for tea']::text[]),
  ('064-card.webp', 'Деревья внутри хранительницы', 'Прозрачная женщина стоит в лунном лесу, а сквозь её тело видны деревья и ветви, будто она сама часть чащи.', 'прозрачная женщина, деревья внутри, лес, луна, ветви, дух природы', ARRAY['Её можно увидеть, если перестать искать', 'Корни помнят то, что забыли люди']::text[], 'Trees Within the Guardian', 'A translucent woman stands in a moonlit forest with trees and branches visible through her body as though she belongs to the woods.', 'transparent woman, forest guardian, trees, branches, moonlight, woodland', ARRAY['You can see her when you stop looking', 'The roots remember what people forgot']::text[]),
  ('064-cos.webp', 'Гравитация ушла обедать', 'В столовой станции вся еда и экипаж зависли у потолка, а на столе лежит записка от гравитации и пустая чашка.', 'невесомость, столовая, еда у потолка, экипаж станции, пустая чашка, записка, гравитация', ARRAY['Обед ушёл наверх без разрешения повара', 'Самый важный сотрудник взял перерыв']::text[], 'Gravity''s Lunch Break', 'Food and crew float against the ceiling of a station cafeteria beside a note from gravity and an empty cup.', 'space cafeteria, floating food, crew, zero gravity, ceiling, note', ARRAY['Lunch went upstairs without the chef''s permission', 'The most important employee took a break']::text[]),
  ('064-meme.webp', 'Yes Chad', 'Невозмутимый сильный мужчина кивает говорящему каменному лицу в цветущей горной долине.', 'Yes Chad, да Чад, сильный мужчина, каменное лицо, согласие, горы, цветы', ARRAY['Да, даже если вопрос задал валун', 'Спор закончился раньше первого аргумента']::text[], 'Yes Chad', 'A calm muscular man nods to a talking stone face in a blooming mountain valley.', 'yes, chad, calm, muscular, man, nods, talking, stone, face, blooming, mountain, valley', ARRAY['Yes, even if a boulder asked the question', 'The argument ended before the first point']::text[]),
  ('065-abs.webp', 'Public chess table', 'Игрок двигает ладью на уличной шахматной доске, а фигура раскрывается в жилой дом с крошечным жильцом.', 'шахматы ладья фигура доска дом башня жилец руки парк игра', ARRAY['Этот ход потребует разрешения на строительство', 'Сосед сверху следит за партией']::text[], 'Public chess table', 'A player moves a rook; the rook unfolds into a tiny apartment tower and its resident waves at the opposing queen.', 'public, chess, table, player, moves, rook, unfolds, apartment, tower, resident, waves, opposing, queen', ARRAY['This move will need a building permit', 'The upstairs neighbor is watching the match']::text[]),
  ('065-card.webp', 'Двери в лесу', 'Ребёнок в красном плаще стоит перед богато украшенной дверью среди деревьев и других таинственных входов.', 'ребёнок, красный плащ, двери, лес, ключи, загадочный вход', ARRAY['На прогулку вышли, а вернуться можно в другой мир', 'Нужный выход спрятался среди слишком многих ответов']::text[], 'Doors in the Forest', 'A child in a red cloak stands before an ornate door among trees and other mysterious entrances.', 'child, red cloak, ornate door, forest, trees, portals', ARRAY['A walk outside could end in another world', 'The right exit hid among too many answers']::text[]),
  ('065-cos.webp', 'Космический музей носков', 'Экскурсовод-робот показывает туристам один гигантский носок, внутри которого вращается музейная мини-галактика.', 'робот-экскурсовод, музей, гигантский носок, мини-галактика внутри, туристы, витрина', ARRAY['Пропажа из прачечной получила собственный зал', 'Экспонат пахнет тайной нескольких поколений']::text[], 'Museum of the Giant Sock', 'A robot guide shows tourists a giant sock with a miniature galaxy turning inside it.', 'robot guide, tourists, giant sock, miniature galaxy, museum', ARRAY['The missing laundry got its own exhibit', 'The artifact smells of generations of mystery']::text[]),
  ('065-meme.webp', 'Trollface', 'Огромное хитро ухмыляющееся лицо выглядывает из арки над городком, заключённым в прозрачный шар.', 'Trollface, троллфейс, хитрая ухмылка, лицо, город, прозрачный шар, розыгрыш', ARRAY['Когда сказал, что это совсем маленький сюрприз', 'Город ещё не понял, кто придумал правила']::text[], 'Trollface', 'A giant mischievous face peers from an arch above a town enclosed in a transparent sphere.', 'trollface, mischievous, face, peers, arch, town, enclosed, transparent, sphere', ARRAY['He called it a very small surprise', 'The town has yet to learn who made the rules']::text[]),
  ('066-abs.webp', 'Seaside kiosk', 'На пляже продавец сдаёт туристке напрокат сложенную тень как зонтик, пока её собственная тень сердито наблюдает.', 'пляж море туристка продавец тень зонт солнце навес прокат', ARRAY['От солнца спрятались в чужом силуэте', 'Отпуск заставил даже тень ревновать']::text[], 'Seaside kiosk', 'A beach vendor rents out neatly folded shadows as sun umbrellas; a tourist tries one on while their own shadow pouts.', 'seaside, kiosk, beach, vendor, rents, neatly, folded, shadows, sun, umbrellas, tourist, tries, shadow, pouts', ARRAY['She hid from the sun in someone else''s outline', 'Even her shadow got jealous on vacation']::text[]),
  ('066-card.webp', 'Булочная облаков', 'На уютном рынке пекари продают пышные облака как хлеб среди корзин, прилавков и тёплого света.', 'булочная, облака, хлеб, пекарь, рынок, корзины, выпечка', ARRAY['К завтраку взяли что-нибудь воздушное', 'Свежая партия скоро принесёт дождь']::text[], 'Cloud Bakery', 'Bakers at a cozy market sell fluffy clouds like bread among baskets, stalls and warm lights.', 'bakery, bakers, cloud bread, market, baskets, stalls, warm light', ARRAY['Something light and airy for breakfast', 'The fresh batch may bring rain']::text[]),
  ('066-cos.webp', 'Марсианский почтальон на коньках', 'Почтальон в тяжёлом скафандре катится на коньках по ледяному Марсу, доставляя открытку самому себе.', 'почтальон, тяжёлый скафандр, коньки, ледяной Марс, открытка самому себе, красная планета', ARRAY['Доставить поздравление быстрее собственных шагов', 'Адресат и отправитель встретились на льду']::text[], 'Mail to Myself on Mars', 'A mail carrier in a heavy spacesuit skates across icy Mars to deliver a postcard to himself.', 'mail carrier, spacesuit, ice skates, Mars, postcard', ARRAY['Deliver the greeting faster than your own footsteps', 'Sender and recipient met on the ice']::text[]),
  ('066-meme.webp', 'Rage Guy', 'Сердитый нарисованный человечек с огромным усилием пытается открыть банку с соленьями на кухне.', 'Rage Guy, яростный парень, злой человечек, банка, крышка, кухня, злость', ARRAY['Великая битва за один огурец', 'Когда крышка упрямее всего рабочего дня']::text[], 'Rage Guy', 'An angry cartoon man strains to open a jar of pickles in a kitchen.', 'rage, guy, angry, cartoon, man, strains, open, jar, pickles, kitchen', ARRAY['The great battle for a single pickle', 'The lid is more stubborn than the whole workday']::text[]),
  ('067-abs.webp', 'Child''s homework', 'Отец помогает дочке с задачей, но цифры покидают тетрадь и прячутся за комнатным растением.', 'домашнее задание математика цифры тетрадь отец дочь растение стол школа', ARRAY['Ответы разбежались ещё до проверки', 'Задача отказалась сидеть на странице']::text[], 'Child''s homework', 'A father helps with math homework while the numbers climb off the page and hide behind a houseplant.', 'child, homework, father, helps, math, numbers, climb, off, page, hide, houseplant', ARRAY['The answers ran away before the test', 'The problem refused to stay on the page']::text[]),
  ('067-card.webp', 'Звёздный кролик над рынком', 'Огромный светящийся кролик из звёзд парит над шумным цветным рынком и праздничными столами.', 'кролик, созвездие, звёзды, рынок, праздник, столы, ночной город', ARRAY['Покупатели забыли список, увидев небо', 'Сегодня на ярмарке продают даже удачу']::text[], 'Starry Rabbit Above the Market', 'An enormous glowing rabbit made of stars floats above a busy colorful market and festive tables.', 'star rabbit, glowing rabbit, market, stars, festival, tables', ARRAY['The shoppers forgot their lists when they looked up', 'Even luck is for sale at this fair']::text[]),
  ('067-cos.webp', 'Звёздный паромщик', 'Бородатый паромщик перевозит пассажиров через реку космоса на деревянной лодке, гребёт гигантской зубной щёткой.', 'бородатый паромщик, деревянная лодка, река космоса, пассажиры, зубная щётка, весло', ARRAY['Переправа сегодня особенно хорошо чистит зубы', 'На другой берег можно попасть только по старинке']::text[], 'Ferry Across the Space River', 'A bearded ferryman rows passengers across a river of space in a wooden boat using a giant toothbrush.', 'ferryman, beard, wooden boat, space river, giant toothbrush', ARRAY['This crossing is unusually good for your teeth', 'The other bank can only be reached the old-fashioned way']::text[]),
  ('067-meme.webp', 'Forever Alone', 'Одинокий схематичный человечек ужинает при свечах напротив собственной тени в пустой комнате.', 'Forever Alone, навсегда один, одинокий человечек, ужин, свечи, тень, стол', ARRAY['Забронировал столик на двоих и не соврал', 'Собеседник всегда согласен, но не платит за ужин']::text[], 'Forever Alone', 'A lonely cartoon man dines by candlelight opposite his own shadow in an empty room.', 'forever, alone, lonely, cartoon, man, dines, candlelight, opposite, shadow, empty, room', ARRAY['Booked a table for two and did not lie', 'The companion always agrees but never pays']::text[]),
  ('068-abs.webp', 'Sewing factory', 'Уставшая швея сшивает на столе летний закат и снежную зиму, а по шву едет крошечный велосипедист.', 'швея швейная машина ткань шов лето зима закат снег велосипедист выходные', ARRAY['Выходные пришлось соединять вручную', 'Два сезона встретились на одном стежке']::text[], 'Sewing factory', 'A tired worker stitches together two halves of a broken weekend; a tiny bicycle rolls along the seam.', 'sewing, factory, tired, worker, stitches, together, halves, broken, weekend, bicycle, rolls, along, seam', ARRAY['The weekend had to be sewn together by hand', 'Two seasons met along a single stitch']::text[]),
  ('068-card.webp', 'Кукловод над битвой', 'Маска кукловода и тонкие нити возвышаются над маленькими вооружёнными фигурами, сражающимися на сцене у воды.', 'кукловод, маска, нити, марионетки, воины, битва, вода', ARRAY['Герои спорят, кто первым перережет сценарий', 'Война оказалась репетицией чужих рук']::text[], 'Puppeteer Above the Battle', 'A puppeteer''s mask and fine strings loom over tiny armed figures fighting on a stage beside water.', 'puppeteer, mask, strings, puppets, battle, stage, water', ARRAY['The heroes argued over who would cut the script first', 'The war was a rehearsal in someone else''s hands']::text[]),
  ('068-cos.webp', 'Летающий холодильник-пилот', 'Холодильник с глазами и маленькими крыльями ведёт стаю спутников через астероидное поле, показывая поворот дверцей.', 'крылатый холодильник, глаза, дверца, стая спутников, астероидное поле, полёт', ARRAY['Техника снова возглавила экспедицию', 'Поворот показали дверцей вместо крыла']::text[], 'Flying Refrigerator Leads Satellites', 'A winged refrigerator with eyes leads a flock of satellites through an asteroid field, signaling turns with its door.', 'flying refrigerator, wings, satellites, asteroid field, door', ARRAY['The appliance is leading the expedition again', 'It signaled the turn with a door instead of a wing']::text[]),
  ('068-meme.webp', 'Me Gusta', 'Гротескное довольное лицо рассматривает огромный яркий бутерброд у окна кухни.', 'Me Gusta, мне нравится, довольное лицо, бутерброд, еда, кухня, удовольствие', ARRAY['Выглядит странно, но первый укус всё объяснил', 'Когда вкус победил здравый смысл']::text[], 'Me Gusta', 'A grotesquely pleased face examines a giant bright sandwich by a kitchen window.', 'gusta, grotesquely, pleased, face, examines, bright, sandwich, kitchen, window', ARRAY['It looks strange, but the first bite explains everything', 'Taste defeated common sense']::text[]),
  ('069-abs.webp', 'Car dealership', 'Продавщица показывает клиенту крошечную машину в коробке, но её громкий сигнал оглушает весь автосалон.', 'автосалон продавщица клиент автомобиль маленькая машина коробка сигнал клаксон', ARRAY['Размер не предупредил о громкости', 'Пробный гудок услышали все покупатели']::text[], 'Car dealership', 'A saleswoman presents a miniature sedan in a shoe box, but its horn is too loud for the entire showroom.', 'car, dealership, saleswoman, presents, miniature, sedan, shoe, box, but, horn, too, loud, entire, showroom', ARRAY['The small size gave no warning of the noise', 'Every customer heard the test honk']::text[]),
  ('069-card.webp', 'Рыба с крепостью', 'Гигантская золотая рыба несёт на спине целую крепость, а маленький человек наблюдает с берега.', 'золотая рыба, крепость, замок, спина рыбы, берег, человек, вода', ARRAY['Замок решил уплыть от налогов', 'Рыбак поймал бы её, но где хранить такую находку']::text[], 'Fish Carrying a Fortress', 'A giant golden fish carries an entire fortress on its back while a small person watches from shore.', 'golden fish, fortress, castle, shore, small person, water', ARRAY['The castle swam away from its taxes', 'A fisherman would catch it, but where would he put it']::text[]),
  ('069-cos.webp', 'Селфи с пришельцем', 'Астронавт пытается сделать селфи с застенчивым трёхглазым пришельцем, но камера всё время снимает только их ботинки.', 'астронавт, трёхглазый пришелец, селфи, камера, ботинки, космическая фотография', ARRAY['На память осталась только обувь', 'Самый застенчивый знакомый не попал в кадр']::text[], 'Alien Selfie Mishap', 'An astronaut tries to take a selfie with a shy three-eyed alien, but the camera keeps capturing only their boots.', 'astronaut, selfie, three-eyed alien, camera, boots', ARRAY['Only the shoes made it into the memory', 'The shyest new friend missed every photograph']::text[]),
  ('069-meme.webp', 'Y U NO Guy', 'Возмущённый нарисованный человек с раскинутыми руками спорит с банкоматом, который выдаёт осенние листья.', 'Y U NO Guy, почему ты не, возмущённый человечек, банкомат, листья, деньги, осень', ARRAY['Снял наличные, получил пейзаж', 'Когда финансовая система перешла на сезонную валюту']::text[], 'Y U NO Guy', 'An outraged cartoon man argues with an ATM dispensing autumn leaves instead of money.', 'guy, outraged, cartoon, man, argues, atm, dispensing, autumn, leaves, money', ARRAY['Withdrew cash and received a landscape', 'The banking system switched to seasonal currency']::text[]),
  ('070-abs.webp', 'Waiting at airport', 'Путешественник у ленты багажа смотрит на чемодан в виде уютного домика с трубой, из которой вылетает тост.', 'аэропорт багажная лента чемодан дом труба тост путешественник самолёт', ARRAY['С собой разрешили взять целую кухню', 'Багаж уже приготовил завтрак']::text[], 'Waiting at airport', 'A passenger checks a suitcase shaped like a cozy house; a small chimney emits breakfast toast instead of smoke.', 'waiting, airport, passenger, checks, suitcase, shaped, cozy, house, chimney, emits, breakfast, toast, smoke', ARRAY['He was allowed to pack an entire kitchen', 'The luggage had already made breakfast']::text[]),
  ('070-card.webp', 'Подводные сёстры', 'Две светлые женщины держатся за руки под водой, а над ними светится громадная медуза.', 'две женщины, подводный мир, руки, медуза, свет, море', ARRAY['На глубине тоже нужен тот, кто не отпустит руку', 'Самый тихий разговор состоялся под куполом']::text[], 'Sisters Underwater', 'Two fair-haired women hold hands underwater beneath a huge glowing jellyfish.', 'two sisters, women, hands, underwater, glowing jellyfish, sea', ARRAY['Even down here you need someone who will not let go', 'The quietest conversation happened under the dome']::text[]),
  ('070-cos.webp', 'Облако на поводке', 'Маленький робот выгуливает пушистое грозовое облако на поводке, облако украдкой поливает цветы на астероиде.', 'маленький робот, грозовое облако, поводок, дождь, цветы, астероид, прогулка', ARRAY['Питомец снова промочил соседский сад', 'На прогулку забыли взять собственный зонтик']::text[], 'Robot Walks a Storm Cloud', 'A little robot walks a fluffy thundercloud on a leash while it secretly waters flowers on an asteroid.', 'robot, storm cloud, leash, flowers, asteroid, rain', ARRAY['The pet soaked the neighbor''s garden again', 'They forgot to bring an umbrella for the walk']::text[]),
  ('070-meme.webp', 'Okay Guy', 'Маленький серый человечек смиренно принимает медаль за последнее место, пока мимо ползут улитки.', 'Okay Guy, окей парень, серый человечек, медаль, улитки, забег, последнее место', ARRAY['Ну ладно, зато финиш всё-таки существует', 'Когда спортивные амбиции ушли вперёд без тебя']::text[], 'Okay Guy', 'A tiny gray cartoon man accepts a last-place medal while snails crawl past him.', 'okay, guy, gray, cartoon, man, accepts, last, place, medal, snails, crawl, past, him', ARRAY['Oh well, the finish line does exist', 'The sporting ambition went on without him']::text[]),
  ('071-abs.webp', 'Pumpkin patch', 'Фермер собирает на грядке часы, выросшие среди тыкв с сонными лицами и цепкими зелёными усами.', 'фермер огород тыквы часы будильник грядка растение утро сон', ARRAY['Урожай опять не хочет просыпаться', 'Осень созрела точно по расписанию']::text[], 'Pumpkin patch', 'A farmer harvests an alarm clock growing on a vine; every pumpkin opens one sleepy eye and resists waking.', 'pumpkin, patch, farmer, harvests, alarm, clock, growing, vine, opens, sleepy, eye, resists, waking', ARRAY['The harvest refuses to wake up again', 'Autumn ripened right on schedule']::text[]),
  ('071-card.webp', 'Кит-дом среди звёзд', 'Огромный кит плывёт в космосе, а внутри его прозрачного тела видны целые комнаты и маленькие жители.', 'кит, космос, дом внутри кита, комнаты, люди, звёзды, корабль', ARRAY['В этом доме переезд случается во сне', 'Соседи говорят, что их район иногда поёт']::text[], 'Whale House Among the Stars', 'A huge whale swims through space with rooms and tiny residents visible inside its transparent body.', 'whale, space, transparent body, rooms, people, stars, house', ARRAY['In this house you move while you sleep', 'The neighbors say their district sometimes sings']::text[]),
  ('071-cos.webp', 'Боулинг по планетам', 'Космические кегли из планет выстроились в ряд, гигантский шар-пончик катится к ним по звёздной дорожке.', 'космический боулинг, планеты-кегли, шар-пончик, звёздная дорожка, удар', ARRAY['После страйка придётся заново собирать систему', 'Когда игра стала слишком масштабной для одного зала']::text[], 'Planet Bowling', 'Planets line up as bowling pins while a giant doughnut ball rolls toward them along a starry lane.', 'planets, bowling pins, doughnut ball, stars, lane', ARRAY['After the strike they will have to rebuild the system', 'The game grew too large for one bowling alley']::text[]),
  ('071-meme.webp', 'Мистер Дудец', 'Танцующий скелет играет на золотой трубе, из которой вылетают маленькие танцующие кости.', 'Мистер Дудец, Doot Doot, скелет, труба, кости, танец, музыка', ARRAY['Музыка звучит прямо из глубины души — если она есть', 'Оркестр собрался буквально по частям']::text[], 'Doot Doot', 'A dancing skeleton plays a golden trumpet that releases tiny dancing bones.', 'doot, dancing, skeleton, plays, golden, trumpet, releases, bones', ARRAY['The music comes from deep within, if there is anything there', 'The orchestra assembled itself piece by piece']::text[]),
  ('072-abs.webp', 'Municipal office', 'Служащая ставит печать на документ, и штамп превращается в крошечную лавочку для ожидающего посетителя.', 'учреждение чиновник служащая печать штамп документ бумага очередь лавочка посетитель', ARRAY['Для ожидания выдали собственную мебель', 'Бумага официально продлила очередь']::text[], 'Municipal office', 'A clerk stamps a citizen''s form; the stamp transforms into a tiny wooden bench for the citizen to sit and wait longer.', 'municipal, office, clerk, stamps, citizen, form, stamp, transforms, wooden, bench, sit, wait, longer', ARRAY['They issued furniture for the wait', 'The paperwork officially extended the queue']::text[]),
  ('072-card.webp', 'Всадник на неоновой рыбе', 'Гонщик летит по киберпанковому городу верхом на гигантском карпе кои среди неоновых вывесок.', 'гонщик, карп кои, большая рыба, неоновый город, киберпанк, вывески', ARRAY['Общественный транспорт снова сбежал из аквариума', 'На этом маршруте пробки случаются в воздухе']::text[], 'Rider on a Neon Fish', 'A rider flies through a cyberpunk city on a giant koi carp among neon signs.', 'rider, koi carp, giant fish, cyberpunk city, neon signs, flying', ARRAY['Public transport escaped from the aquarium again', 'Traffic jams happen in the air on this route']::text[]),
  ('072-cos.webp', 'Космический врач', 'Доктор-лягушка слушает стетоскопом пульс маленькой планеты, а пациент показывает язык в форме кометы.', 'доктор-лягушка, стетоскоп, маленькая планета, пациент, язык-комета, космическая медицина', ARRAY['Пульс есть, но вращается не по расписанию', 'Больному прописали отдых на один оборот']::text[], 'Frog Doctor for a Planet', 'A frog doctor listens to a tiny planet''s pulse while the patient sticks out a comet-shaped tongue.', 'frog doctor, stethoscope, planet, comet tongue, patient', ARRAY['The pulse is there, but its rotation is off schedule', 'The patient was prescribed one orbit of rest']::text[]),
  ('072-meme.webp', 'Упоротый лис', 'Нелепо застывший рыжий лис с выпученными глазами сидит на стуле среди музейных витрин.', 'упоротый лис, Stoned Fox, рыжий лис, чучело, музей, выпученные глаза, стул', ARRAY['Когда зашёл на выставку и сам стал экспонатом', 'Взгляд человека, которому только что объяснили шутку']::text[], 'Stoned Fox', 'A stiff orange fox with bulging eyes sits on a chair among museum displays.', 'stoned, fox, stiff, orange, bulging, eyes, sits, chair, among, museum, displays', ARRAY['Went to an exhibition and became an exhibit', 'The look of someone who just had a joke explained']::text[]),
  ('073-abs.webp', 'Window cleaner', 'Мойщик окон на высотке стирает зимнюю метель со стекла, открывая за ним тёплый закат; птица выбирает сторону.', 'мойщик окон небоскрёб стекло зима снег лето закат птица ведро швабра', ARRAY['Погоду сменили одним движением руки', 'По ту сторону стекла уже другое время года']::text[], 'Window cleaner', 'A cleaner wipes a skyscraper window, revealing an entirely different weather system on the other side; a bird checks which side to fly on.', 'window, cleaner, wipes, skyscraper, revealing, entirely, different, weather, system, other, side, bird, checks, which, fly', ARRAY['One wipe changed the weather', 'It is already another season beyond the glass']::text[]),
  ('073-card.webp', 'Семейный портрет с тайной', 'Старинная семья позирует для мрачного чёрно-белого портрета в комнате, над которой нависает странный скелет.', 'семья, старинный портрет, чёрно-белая фотография, дети, скелет, комната', ARRAY['Семейный альбом лучше открывать при свете', 'Лишний родственник снова попал в кадр']::text[], 'Family Portrait with a Secret', 'An old-fashioned family poses for a gloomy black-and-white portrait beneath a strange looming skeleton.', 'family portrait, black and white, family, skeleton, gloomy room', ARRAY['Open the family album with the lights on', 'An extra relative made it into the picture again']::text[]),
  ('073-cos.webp', 'Пальто для астероида', 'Портной-робот примеряет к неровному астероиду клетчатое пальто с рукавами, в одном рукаве уже поселился спутник.', 'робот-портной, астероид, клетчатое пальто, рукава, спутник, примерка, космос', ARRAY['Размер нестандартный, зато посадка по орбите', 'На примерку пришёл целый каменный клиент']::text[], 'Coat for an Asteroid', 'A robot tailor fits an uneven asteroid with a plaid coat while a satellite lives in one sleeve.', 'robot tailor, asteroid, plaid coat, sleeves, satellite', ARRAY['An unusual size, but the orbital fit is perfect', 'An entire rocky customer came for a fitting']::text[]),
  ('073-meme.webp', 'Ugandan Knuckles', 'Крошечный красный ёжик проводит экскурсию по запутанному лабиринту улиц, где повсюду нарисованы стрелки.', 'Ugandan Knuckles, угандийский Наклз, красный ёжик, лабиринт, стрелки, дорога', ARRAY['Проводник уверен, что знает путь, но стрелок слишком много', 'Когда кратчайший маршрут неожиданно стал квестом']::text[], 'Ugandan Knuckles', 'A tiny red hedgehog leads a tour through a maze of streets covered in arrows.', 'ugandan, knuckles, red, hedgehog, leads, tour, maze, streets, covered, arrows', ARRAY['The guide is sure of the way; there are too many arrows', 'The shortcut turned into a quest']::text[]),
  ('074-abs.webp', 'Art class', 'На уроке рисования красный стул выходит из картины и спорит с художницей, требуя отдыха от позирования.', 'урок рисования художница кисть холст картина красный стул мольберт краски', ARRAY['Модель первой закончила сеанс', 'Изображение больше не желает сидеть смирно']::text[], 'Art class', 'An adult student paints a chair; the painted chair pulls itself out of the canvas and demands a model''s break.', 'art, class, adult, student, paints, chair, painted, pulls, itself, canvas, demands, model, break', ARRAY['The model was first to end the session', 'The portrait refused to sit still any longer']::text[]),
  ('074-card.webp', 'Кит между планетами', 'Огромный синий кит плывёт между звёздами и планетами, а вокруг него летят белые птицы.', 'синий кит, космос, планеты, звёзды, белые птицы, полёт', ARRAY['Океан закончился, а путешествие — нет', 'Кто-то слишком буквально попросил больше простора']::text[], 'Whale Between Planets', 'A huge blue whale swims among stars and planets while white birds fly around it.', 'blue whale, planets, stars, white birds, space, sky', ARRAY['The ocean ended, but the journey did not', 'Someone asked a little too literally for more room']::text[]),
  ('074-cos.webp', 'Инопланетная рыночная площадь', 'С высоты птичьего полёта: круглый рынок на астероиде, торговцы продают банки с северным сиянием и живые зонтики.', 'круглый рынок на астероиде, пришельцы, банки с северным сиянием, живые зонтики, торговцы', ARRAY['На ярмарке продают погоду в стеклянной таре', 'Сдачу здесь дают маленькими чудесами']::text[], 'Aurora Market', 'Merchants on a round asteroid market sell jars of northern lights and living umbrellas.', 'asteroid market, jars, northern lights, aurora, living umbrellas', ARRAY['The fair sells weather in glass containers', 'They give small miracles as change here']::text[]),
  ('074-meme.webp', 'Big Chungus', 'Гигантский пухлый серый кролик с самодовольной улыбкой пытается устроиться на слишком маленьком стуле.', 'Big Chungus, большой Чунгус, толстый кролик, серый кролик, маленький стул, улыбка', ARRAY['Мебель обещала выдержать любого — до знакомства', 'Размер проблемы понятен без измерительной ленты']::text[], 'Big Chungus', 'A huge chubby gray rabbit with a smug smile tries to sit on a much too small chair.', 'big, chungus, huge, chubby, gray, rabbit, smug, smile, tries, sit, much, too, chair', ARRAY['The furniture promised to hold anyone until they met', 'No measuring tape is needed to see the problem']::text[]),
  ('075-abs.webp', 'Camping store', 'Покупательница раскрывает маленькую палатку в магазине, и из неё вырастает целый лес с водопадом, пугая продавца.', 'туристический магазин палатка лес деревья водопад продавец покупательница кемпинг', ARRAY['В комплекте обнаружился целый поход', 'Магазин не рассчитывал на такой размер природы']::text[], 'Camping store', 'A shopper opens a tiny tent display and an enormous forest spills out, politely pushing the salesperson aside.', 'camping, store, shopper, opens, tent, display, forest, spills, politely, pushing, salesperson, aside', ARRAY['An entire hike came included in the box', 'The shop was not prepared for this much nature']::text[]),
  ('075-card.webp', 'Королевский пир призраков', 'Нарядная женщина в розовом сидит за роскошным столом с кубками и цветами среди бледных придворных и причудливых существ.', 'женщина в розовом, королевский пир, стол, кубки, цветы, придворные, дворец', ARRAY['На этом приёме соседей по столу лучше не расспрашивать', 'Праздник затянулся на несколько эпох']::text[], 'Royal Feast of Ghosts', 'A finely dressed woman in pink sits at a lavish table with goblets and flowers among pale courtiers and strange creatures.', 'woman in pink, royal feast, goblets, flowers, ghosts, courtiers, banquet', ARRAY['Do not ask too much about your dinner companions', 'The celebration lasted several centuries']::text[]),
  ('075-cos.webp', 'Космический дирижабль-арбуз', 'Полосатый арбуз с пропеллером перевозит пассажиров между спутниками, капитан-муравей смотрит в подзорную трубу.', 'арбуз-дирижабль, пропеллер, пассажиры, спутники, капитан-муравей, подзорная труба', ARRAY['На борту пахнет летом даже зимой', 'Самый сладкий рейс отправляется без посадочной полосы']::text[], 'Flying Watermelon Shuttle', 'A striped watermelon with a propeller carries passengers between moons while an ant captain looks through a spyglass.', 'watermelon, propeller, passengers, moons, ant captain, spyglass', ARRAY['The cabin smells like summer even in winter', 'The sweetest flight leaves without a runway']::text[]),
  ('075-meme.webp', 'Chicken Jockey', 'Маленький зелёный блочный всадник несётся верхом на огромной белой курице сквозь переполненный кинотеатр.', 'Chicken Jockey, куриный наездник, Майнкрафт, зелёный всадник, белая курица, кинотеатр', ARRAY['На этом сеансе зрители стали спецэффектами', 'Когда курьер выбрал самый шумный вход']::text[], 'Chicken Jockey', 'A tiny green blocky rider races on a huge white chicken through a crowded movie theater.', 'chicken, jockey, green, blocky, rider, races, huge, white, crowded, movie, theater', ARRAY['The audience became the special effects', 'The courier chose the loudest possible entrance']::text[]),
  ('076-abs.webp', 'Foot massage', 'Массажист разминает подошвы туристических ботинок, из которых сыплются крошечные горы; хозяин дремлет рядом.', 'массаж массажист ботинки обувь подошва горы туризм путешественник ноги', ARRAY['После похода устала даже обувь', 'Горы пришлось вытряхивать из подошв']::text[], 'Foot massage', 'A massage therapist kneads the soles of hiking boots while their owner naps; tiny mountains fall out like pebbles.', 'foot, massage, therapist, kneads, soles, hiking, boots, owner, naps, mountains, fall, pebbles', ARRAY['Even the footwear was tired after the hike', 'They had to shake mountains out of the soles']::text[]),
  ('076-card.webp', 'Кот танцует в заброшенном дворце', 'Чёрный кот в кружевном воротнике танцует один в зале с цветочными люстрами, свечами, масками и мышами-музыкантами.', 'кот кошка дворец бал танец мыши маски люстра свечи', ARRAY['Бал начался, когда гости исчезли', 'Оркестр играет только для одного']::text[], 'Dancing Cat in an Abandoned Palace', 'A black cat wearing a lace collar dances alone in a palace hall lit by floral chandeliers and candles while mice play music.', 'black cat, lace collar, dance, palace, chandeliers, candles, masks, musician mice', ARRAY['The ball began after every guest went home', 'An orchestra with an audience of one']::text[]),
  ('076-cos.webp', 'Охотник за тенью НЛО', 'Пришелец с сачком гонится по поверхности луны за собственной огромной тенью в форме летающей тарелки.', 'пришелец, сачок, тень НЛО, лунная поверхность, летающая тарелка, погоня', ARRAY['Поймать себя сложнее, чем казалось', 'Добыча растёт вместе с солнцем']::text[], 'Alien Chases Its Own Shadow', 'An alien with a net chases its enormous flying-saucer-shaped shadow across the moon.', 'alien, net, moon, shadow, flying saucer silhouette', ARRAY['Catching yourself proved harder than expected', 'The quarry grows with the rising sun']::text[]),
  ('076-meme.webp', 'Gorilla Glue Girl', 'Женщина в салоне тянет за намертво застывшую причёску, пока парикмахеры смотрят на неё в ужасе.', 'Gorilla Glue Girl, Горилла Глю, женщина, застывшие волосы, салон, парикмахер, клей', ARRAY['Укладка продержится дольше любого обещания', 'Когда инструкция на флаконе была важнее моды']::text[], 'Gorilla Glue Girl', 'A woman in a salon pulls at a hopelessly stiff hairstyle while horrified hairdressers watch.', 'gorilla, glue, girl, woman, salon, pulls, hopelessly, stiff, hairstyle, horrified, hairdressers, watch', ARRAY['The styling will outlast every promise', 'The bottle instructions mattered more than fashion']::text[]),
  ('077-abs.webp', 'City gardener', 'Садовник подстригает живую изгородь, на которой вместо листьев светятся маленькие светофоры; прохожие им подчиняются.', 'садовник изгородь куст светофор красный зелёный свет дорога прохожие ножницы', ARRAY['Городскую очередь теперь регулирует зелень', 'Сад решил сам управлять движением']::text[], 'City gardener', 'A gardener trims a hedge whose leaves are small impatient traffic lights; pedestrians obey its color changes.', 'city, gardener, trims, hedge, leaves, impatient, traffic, lights, pedestrians, obey, color, changes', ARRAY['The greenery now directs city traffic', 'The garden decided to control the road itself']::text[]),
  ('077-card.webp', 'Кит над лодкой северного сияния', 'Огромный белый кит плывёт по небу над кораблём викингов и девушкой под зелёным северным сиянием.', 'кит лодка корабль викинги северное сияние небо море девушка', ARRAY['Самый большой пассажир северного рейса', 'Море однажды поднялось выше облаков']::text[], 'Whale Above the Northern Lights Boat', 'A huge white whale swims through the sky above a Viking ship and a girl beneath green northern lights.', 'white whale, Viking ship, girl, aurora borealis, green sky, northern lights', ARRAY['The biggest passenger on the northern route', 'One night the sea rose above the clouds']::text[]),
  ('077-cos.webp', 'Суп из комет', 'Кухонный повар помешивает суп в кратере длинной ложкой, из кастрюли выпрыгивают крошечные хвостатые кометы.', 'повар, суп в кратере, длинная ложка, маленькие кометы, кастрюля, космическая кухня', ARRAY['Первое блюдо опять пытается улететь', 'Рецепт требует держаться подальше от хвоста']::text[], 'Comet Soup', 'A cook stirs soup in a crater with a long spoon as tiny tailed comets leap from the pot.', 'cook, soup, crater, spoon, pot, small comets', ARRAY['The first course is trying to fly away again', 'The recipe says to keep clear of the tail']::text[]),
  ('077-meme.webp', 'Salt Bae', 'Повар эффектно сыплет соль на огромный круглый пирог, похожий на луну.', 'Salt Bae, Солт Бэ, повар, соль, жест рукой, огромный пирог, луна', ARRAY['Секретный ингредиент — очень театральное запястье', 'Когда ужин требует отдельной церемонии']::text[], 'Salt Bae', 'A chef theatrically sprinkles salt over a giant round pie shaped like the moon.', 'salt, bae, chef, theatrically, sprinkles, round, pie, shaped, moon', ARRAY['The secret ingredient is a dramatic wrist', 'Dinner requires its own ceremony']::text[]),
  ('078-abs.webp', 'Ferry', 'Капитан парома поит чаем маленькую живую волну, сидящую среди пассажиров у иллюминатора.', 'паром корабль капитан море волна чай чашки пассажиры иллюминатор', ARRAY['Море попросило место у окна', 'На борту появился пассажир без билета']::text[], 'Ferry', 'A ferry captain serves tea to a tiny tidal wave seated in the passenger cabin; passengers hold their cups steady.', 'ferry, captain, serves, tea, tidal, wave, seated, passenger, cabin, passengers, hold, cups, steady', ARRAY['The sea asked for a window seat', 'There is a passenger without a ticket on board']::text[]),
  ('078-card.webp', 'Призраки танцуют с медузой', 'Два скелета в плащах парят в тёмной воде вокруг светящейся фиолетовой медузы в шлеме викинга.', 'скелеты призраки смерть медуза вода море викинги свет', ARRAY['Даже после конца вечеринки никто не ушёл', 'Свидание на самом глубоком этаже']::text[], 'Ghosts Dance with a Jellyfish', 'Two cloaked skeletons float in dark water around a glowing purple jellyfish wearing a Viking helmet.', 'skeletons, ghosts, cloaks, purple jellyfish, Viking helmet, underwater, dance', ARRAY['The party ended, but nobody thought to leave', 'A date on the deepest floor']::text[]),
  ('078-cos.webp', 'Космический свадебный фотограф', 'Фотограф просит двух роботов-пылесосов поцеловаться на фоне заката за краем галактики, вспышка освещает созвездия.', 'свадьба роботов-пылесосов, фотограф, галактический закат, вспышка, созвездия', ARRAY['Молодожёны пообещали убираться вместе', 'На снимке от счастья засветилось всё небо']::text[], 'Robot Vacuum Wedding Photo', 'A photographer asks two robot vacuums to kiss at a galactic sunset as the flash lights the constellations.', 'photographer, robot vacuums, kiss, sunset, galaxy, flash', ARRAY['The newlyweds promised to clean together', 'Happiness overexposed the entire sky']::text[]),
  ('078-meme.webp', 'Chef''s Kiss', 'Усатый повар в белом колпаке восторженно целует пальцы перед круглым подгоревшим блином на сковороде.', 'Chef''s Kiss, поцелуй шефа, повар, колпак, блин, сковорода, восторг', ARRAY['Подгорело идеально, спорить бесполезно', 'Когда ошибки становятся фирменным рецептом']::text[], 'Chef''s Kiss', 'A mustached chef in a white hat kisses his fingers before a burnt pancake in a frying pan.', 'chef, kiss, mustached, white, hat, kisses, fingers, before, burnt, pancake, frying, pan', ARRAY['Perfectly burnt, and nobody can argue', 'Mistakes become the house special']::text[]),
  ('079-abs.webp', 'Office lunch', 'Работник открывает ланчбокс, и из него с воплем выскакивает крошечный понедельник; коллеги прячутся под столами.', 'офис обед ланчбокс контейнер понедельник маленький человек коллеги столы', ARRAY['Рабочая неделя выпрыгнула из еды', 'Лучше было заказать доставку']::text[], 'Office lunch', 'A worker opens a lunchbox and a miniature Monday morning springs out; the whole office ducks under their desks.', 'office, lunch, worker, opens, lunchbox, miniature, monday, morning, springs, ducks, desks', ARRAY['The workweek jumped out of lunch', 'Ordering delivery would have been safer']::text[]),
  ('079-card.webp', 'Затмение и золотые птицы', 'На тёмной пустоши человек выпускает цепочку светящихся золотых птиц к чёрному солнечному затмению.', 'затмение солнце луна птицы золото свет ночь человек пустошь', ARRAY['Когда погасло небо, зажгли запасной свет', 'Письма полетели прямо в темноту']::text[], 'Eclipse and Golden Birds', 'On a dark wasteland, a person releases a chain of glowing golden birds toward a black solar eclipse.', 'eclipse, golden birds, dark wasteland, person, glowing flock, black sun', ARRAY['When the sky went out, someone lit a spare', 'The letters flew straight into the dark']::text[]),
  ('079-cos.webp', 'Лифтёр на Юпитере', 'Маленький лифтёр в каске нажимает кнопки на огромном газовом гиганте, этажи обозначены облаками и молниями.', 'маленький лифтёр, каска, Юпитер, газовый гигант, облачные этажи, молнии, лифт', ARRAY['На следующем этаже возможна гроза', 'Кнопку нажали, а здание продолжает вращаться']::text[], 'Elevator on a Gas Giant', 'A tiny lift operator presses buttons on an enormous gas giant where clouds and lightning mark the floors.', 'lift operator, elevator, gas giant, clouds, lightning, floors', ARRAY['Thunderstorms are possible on the next floor', 'The button was pressed, but the building kept turning']::text[]),
  ('079-meme.webp', 'Tralalero Tralala', 'Акула в ярких кроссовках шагает по пляжу на человеческих ногах, перешагивая чайную чашку.', 'Tralalero Tralala, тралалеро тралала, акула, ноги, кроссовки, пляж, чашка', ARRAY['Море выпустило самого модного пешехода', 'Когда прогулка по берегу внезапно стала невозможной биологией']::text[], 'Tralalero Tralala', 'A shark in bright sneakers walks down a beach on human legs, stepping over a teacup.', 'tralalero, tralala, shark, bright, sneakers, walks, beach, human, legs, stepping, teacup', ARRAY['The sea sent out its most fashionable pedestrian', 'A walk on the shore became impossible biology']::text[]),
  ('080-abs.webp', 'Second-hand shop', 'Женщина примеряет жёлтое пальто, из карманов которого открываются разные годы и вылетают старые билеты-бабочки.', 'секонд-хенд пальто примерка карманы годы прошлое билеты бабочки женщина зеркало', ARRAY['В кармане нашлось путешествие назад', 'Старая одежда помнит больше хозяина']::text[], 'Second-hand shop', 'A customer tries on a coat whose pockets lead to different years; an old ticket falls out of one sleeve as a butterfly.', 'second, hand, shop, customer, tries, coat, pockets, lead, different, years, ticket, falls, sleeve, butterfly', ARRAY['A journey back waited in the pocket', 'Old clothes remember more than their owner']::text[]),
  ('080-card.webp', 'Кролик кормит дракона лапшой', 'Белый кролик в восточной одежде протягивает лапшу из миски огромному коричневому дракону; человек плывёт в бумажной лодке на фоне луны.', 'кролик заяц дракон лапша миска еда луна бумажная лодка', ARRAY['Ужин для того, кто мог бы съесть повара', 'Самое вежливое чудовище за столом']::text[], 'Rabbit Feeds a Dragon Noodles', 'A white rabbit in eastern clothes offers noodles from a bowl to a huge brown dragon while a person sails in a paper boat beneath the moon.', 'white rabbit, noodles, bowl, brown dragon, paper boat, moon, dinner', ARRAY['Dinner for someone who could eat the chef', 'The politest monster at the table']::text[]),
  ('080-cos.webp', 'Звёздная няня', 'Усатая инопланетянка укладывает спать россыпь маленьких звёзд в колыбель из лунного серпа.', 'инопланетная няня, маленькие звёзды, колыбель, серп Луны, сон, ночь', ARRAY['Пора спать, иначе утро не наступит', 'Одна колыбель светит за всю комнату']::text[], 'Alien Tucks Stars into Bed', 'A mustached alien woman puts little stars to sleep in a crescent-moon cradle.', 'alien woman, mustache, stars, bedtime, crescent moon, cradle', ARRAY['Go to sleep or morning will never arrive', 'One cradle lights the whole room']::text[]),
  ('080-meme.webp', 'Leonardo DiCaprio Cheers', 'Нарядный мужчина поднимает бокал на роскошном балу среди говорящих рыб и удивлённых гостей.', 'Leonardo DiCaprio Cheers, Ди Каприо с бокалом, тост, бал, рыбы, праздник', ARRAY['Когда произнёс тост и даже аквариум ответил', 'Праздник удался подозрительно глубоко']::text[], 'Leonardo DiCaprio Cheers', 'A dressed-up man raises a glass at a lavish ball among talking fish and surprised guests.', 'leonardo, dicaprio, cheers, dressed, man, raises, glass, lavish, ball, among, talking, fish, surprised, guests', ARRAY['He made a toast and even the aquarium replied', 'The party was suspiciously deep']::text[]),
  ('081-abs.webp', 'House painting', 'Маляр красит входную дверь синим, а краска убегает с кисти ручейком по тротуару.', 'маляр краска синяя дверь кисть ручей тротуар дом побег', ARRAY['Цвет решил не оставаться на месте', 'После ремонта улица стала немного синее']::text[], 'House painting', 'A painter paints a front door blue; the color climbs down the brush and runs away across the pavement as a tiny river.', 'house, painting, painter, paints, front, door, blue, color, climbs, brush, runs, away, pavement, river', ARRAY['The color refused to stay put', 'After the repairs the street was a little bluer']::text[]),
  ('081-card.webp', 'Паук плетёт звёздный дворец', 'Гигантский паук держит сеть из звёзд и планет между двумя полумесяцами; король и куклы стоят среди масок и зеркал.', 'паук паутина звёзды планеты луна король маски зеркало куклы', ARRAY['Всё королевство висит на ниточке', 'Ночное небо взяли в аренду для спектакля']::text[], 'Spider Weaves a Starry Palace', 'A giant spider holds a web of stars and planets between two crescent moons as a king and puppets stand among masks and mirrors.', 'giant spider, star web, planets, crescent moons, king, puppets, masks, mirrors', ARRAY['The whole kingdom hangs by a thread', 'They rented the night sky for a play']::text[]),
  ('081-cos.webp', 'Ракетный чайник', 'Огромный эмалированный чайник стартует с площадки, из носика вырывается пар в виде дракона, инженеры машут полотенцами.', 'ракетный чайник, эмалированный чайник, стартовая площадка, пар в форме дракона, инженеры, полотенца', ARRAY['Вода закипела и покинула кухню', 'Три, два, один — пора пить']::text[], 'Rocket Kettle', 'A huge enamel kettle launches as dragon-shaped steam bursts from its spout and engineers wave towels.', 'enamel kettle, rocket launch, dragon steam, engineers, towels', ARRAY['The water boiled and left the kitchen', 'Three, two, one: time for tea']::text[]),
  ('081-meme.webp', 'Leonardo DiCaprio Pointing', 'Мужчина с бокалом сидит перед экраном и изумлённо указывает на изображение собственной комнаты.', 'Leonardo DiCaprio Pointing, Ди Каприо показывает, мужчина, бокал, экран, узнавание', ARRAY['Подожди, это же мой диван!', 'Когда сюжет вдруг оказался слишком знакомым']::text[], 'Leonardo DiCaprio Pointing', 'A man with a drink points in astonishment at a screen showing his own room.', 'leonardo, dicaprio, pointing, man, drink, points, astonishment, screen, showing, room', ARRAY['Wait, that is my sofa!', 'The plot became unexpectedly familiar']::text[]),
  ('082-abs.webp', 'Tram stop', 'Контролёр на остановке проверяет билет у облака в розовых сапогах, которое аккуратно капает в чемодан.', 'трамвай остановка контролёр билет облако дождь розовые сапоги чемодан', ARRAY['Пассажир промочил документы ещё до посадки', 'Даже погоде пришлось купить проездной']::text[], 'Tram stop', 'A ticket inspector checks the ticket of a cloud wearing boots; the cloud drips politely into a little briefcase.', 'tram, stop, ticket, inspector, checks, cloud, wearing, boots, drips, politely, briefcase', ARRAY['The passenger soaked the papers before boarding', 'Even the weather had to buy a ticket']::text[]),
  ('082-card.webp', 'Ребёнок спит среди планет', 'Спящий ребёнок парит над кроватью в комнате, заполненной планетами, солнцем, луной и звёздами.', 'ребёнок сон кровать спальня под одеялом все миры вселенная планеты космос солнце луна звёзды', ARRAY['Перед сном вселенная заглянула в гости', 'Под одеялом не хватило места для всех миров']::text[], 'Child Sleeps Among Planets', 'A sleeping child floats over a bed in a room filled with planets, the sun, the moon and stars.', 'sleeping child, floating bed, bedroom, under blanket, all worlds, universe, planets, sun, moon, stars', ARRAY['The universe dropped by before bedtime', 'There was no room beneath the blanket for every world']::text[]),
  ('082-cos.webp', 'Шпионский кактус', 'Кактус в тёмных очках прячется на планете, передавая секретное сообщение через иголки летающему блюдцу.', 'кактус-шпион, тёмные очки, иголки, секретное сообщение, летающая тарелка, красная планета', ARRAY['Агент молчит, но его нельзя обнять', 'Секрет передали самым колючим способом']::text[], 'Secret Agent Cactus', 'A cactus in dark sunglasses hides on a planet and sends a secret message through its needles to a flying saucer.', 'cactus, sunglasses, planet, secret message, needles, UFO', ARRAY['The agent is silent, but impossible to hug', 'The secret traveled the prickliest way']::text[]),
  ('082-meme.webp', 'Confused Travolta', 'Растерянный мужчина в костюме стоит среди разноцветных дверей, которые висят без стен в пустом пространстве.', 'Confused Travolta, растерянный Траволта, мужчина, костюм, двери, поиск выхода', ARRAY['Вариантов много, адреса нет', 'Когда сказали проходи, но не уточнили куда']::text[], 'Confused Travolta', 'A bewildered suited man stands among colorful doors hanging in an empty space without walls.', 'confused, travolta, bewildered, suited, man, stands, among, colorful, doors, hanging, empty, space, without, walls', ARRAY['Plenty of choices, not one address', 'They said come in without saying where']::text[]),
  ('083-abs.webp', 'Maternity plant shop', 'Родительница везёт на прогулку дерево в детской коляске; ветки бросают прохожим игрушки-листья.', 'коляска дерево растение родительница младенец листья игрушки улица прогулка', ARRAY['Малыш вырос раньше первого шага', 'На прогулке раздают осенние подарки']::text[], 'Maternity plant shop', 'A new parent wheels a stroller carrying a potted tree; the tree throws leaf-shaped toys back at strangers.', 'maternity, plant, shop, parent, wheels, stroller, carrying, potted, tree, throws, leaf, shaped, toys, back, strangers', ARRAY['The baby grew before its first step', 'Autumn presents are being handed out on this walk']::text[]),
  ('083-card.webp', 'Кролик у грибного домика', 'Белый кролик с ключом сидит возле резной двери в огромном красном грибе посреди леса.', 'кролик заяц гриб мухомор дом дверь ключ лес', ARRAY['Соседний дом вырос после дождя', 'Ключ подходит к самому лесному адресу']::text[], 'Rabbit at the Mushroom House', 'A white rabbit holding a key sits by a carved door in a giant red mushroom in the forest.', 'white rabbit, key, red mushroom, carved door, forest, mushroom house', ARRAY['The house next door grew after the rain', 'The key fits the most woodland address']::text[]),
  ('083-cos.webp', 'Космическая качеля', 'Два ребёнка-пришельца качаются на качелях между крошечными лунами, один случайно перелетает через кольцо Сатурна.', 'дети-пришельцы, качели, две луны, кольцо Сатурна, полёт, космическая площадка', ARRAY['Размахнули так сильно, что отменили перемену', 'На этой площадке нужна страховка от орбиты']::text[], 'Alien Children on Cosmic Swings', 'Two alien children swing between tiny moons and one flies over Saturn''s rings.', 'alien children, swings, moons, Saturn rings, playground', ARRAY['They swung so hard that recess was canceled', 'This playground needs orbital insurance']::text[]),
  ('083-meme.webp', 'Sad Keanu', 'Грустный бородатый мужчина сидит на скамейке у воды и делит бутерброд с голубем.', 'Sad Keanu, грустный Киану, мужчина, скамейка, бутерброд, голубь, одиночество', ARRAY['Делить обед оказалось легче, чем мысли', 'Когда даже птица заметила твоё настроение']::text[], 'Sad Keanu', 'A sad bearded man sits by the water and shares a sandwich with a pigeon.', 'sad, keanu, bearded, man, sits, water, shares, sandwich, pigeon', ARRAY['Sharing lunch was easier than sharing his thoughts', 'Even the bird noticed his mood']::text[]),
  ('084-abs.webp', 'Music lesson', 'Учительница открывает рояль, и клавиши превращаются в лестницу, по которой робко поднимается ученик.', 'урок музыки пианино рояль клавиши лестница учительница ребёнок ученик', ARRAY['До первой ноты ещё нужно добраться', 'Урок требует подняться на целую октаву']::text[], 'Music lesson', 'A piano teacher opens the keyboard, and the keys rise into a miniature staircase walked by a timid student.', 'music, lesson, piano, teacher, opens, keyboard, keys, rise, miniature, staircase, walked, timid, student', ARRAY['There is a climb before the first note', 'The lesson requires an ascent of a whole octave']::text[]),
  ('084-card.webp', 'Улитка-рыцарь гонится за зайцем', 'Маленький всадник с копьём едет на улитке вслед за зайцем по сказочной лесной тропе.', 'улитка рыцарь всадник копьё заяц кролик гонка лес', ARRAY['Самый медленный обгон в королевстве', 'Турнир закончится к следующей весне']::text[], 'Snail Knight Chases a Hare', 'A tiny rider with a spear rides a snail after a hare along a fairy-tale forest path.', 'snail, knight, spear, rider, hare, forest path, chase', ARRAY['The slowest overtake in the kingdom', 'The tournament should finish by next spring']::text[]),
  ('084-cos.webp', 'Зоопарк невидимых зверей', 'Смотритель в скафандре кормит пустые клетки бананами, а посетители видят лишь плавающие следы лап.', 'космический зоопарк, невидимые звери, смотритель, скафандр, бананы, пустые клетки, следы лап', ARRAY['Корм исчез, а посетители всё ещё сомневаются', 'Никого не видно, но прогулка удалась']::text[], 'Invisible Space Zoo', 'A keeper in a spacesuit feeds bananas into empty cages while visitors see only floating pawprints.', 'zookeeper, spacesuit, bananas, empty cages, invisible animals, pawprints', ARRAY['The food vanished and the visitors still had doubts', 'Nobody was visible, but the walk went well']::text[]),
  ('084-meme.webp', 'Sad Pablo Escobar', 'Одинокий усатый мужчина сидит у большого пустого бассейна, рядом плавает лишь надувной розовый фламинго.', 'Sad Pablo Escobar, грустный Пабло Эскобар, усатый мужчина, бассейн, пустая вилла, фламинго', ARRAY['Дом огромный, а поговорить не с кем', 'Купил всё для вечеринки и забыл гостей']::text[], 'Sad Pablo Escobar', 'A lonely mustached man sits beside an empty pool with only an inflatable pink flamingo.', 'sad, pablo, escobar, lonely, mustached, man, sits, empty, pool, inflatable, pink, flamingo', ARRAY['The house is huge and nobody is there to talk to', 'Bought everything for the party except the guests']::text[]),
  ('085-abs.webp', 'Umbrella repair', 'Мастер раскрывает зонтик, внутри которого шумит солнечный пляж с морем и мячом; вода льётся прямо в мастерскую.', 'ремонт зонтов зонт пляж море вода мяч мастерская лето дождь', ARRAY['Починка выпустила наружу весь отпуск', 'От непогоды здесь прячут солнечный берег']::text[], 'Umbrella repair', 'A repairer tries to close an umbrella that contains a summer beach; one tiny beach ball bounces out onto the shop floor.', 'umbrella, repair, repairer, tries, close, contains, summer, beach, ball, bounces, onto, shop, floor', ARRAY['The repair released the entire vacation', 'Here they hide a sunny beach from bad weather']::text[]),
  ('085-card.webp', 'Небесный праздник гномов и дракона', 'Бородатые гномы пьют мёд на парящих пчёлах среди летающих замков; синий дракон льёт воду из кубка.', 'гномы пчёлы мёд замок небо дракон кубок водопад', ARRAY['Мёд выше облаков', 'На празднике даже дождь подают из кубка']::text[], 'Dwarves and Dragon Celebrate in the Sky', 'Bearded dwarves drink mead while riding floating bees among flying castles as a blue dragon pours water from a goblet.', 'dwarves, bees, mead, flying castles, blue dragon, goblet, clouds', ARRAY['The honey tastes better above the clouds', 'Even the rain comes served in a cup here']::text[]),
  ('085-cos.webp', 'Тапочки для ракеты', 'Инженеры надевают огромные пушистые тапочки на ноги посадочного модуля, чтобы он мягко ступал по луне.', 'инженеры, огромные пушистые тапочки, ракета, посадочный модуль, ноги, мягкая посадка, Луна', ARRAY['Главное приземлиться, не разбудив соседей', 'Техника безопасности стала неожиданно уютной']::text[], 'Slippers for the Moon Lander', 'Engineers fit giant fluffy slippers to a landing module so it can step softly on the moon.', 'engineers, moon lander, slippers, landing module, moon', ARRAY['The important thing is to land without waking the neighbors', 'Safety equipment became unexpectedly cozy']::text[]),
  ('085-meme.webp', 'John Travolta Pulp Dance', 'Пара танцует твист на чёрно-белом полу нарядного зала, похожем на шахматную доску.', 'John Travolta Pulp Dance, танец из Криминального чтива, пара, твист, шахматный пол, зал', ARRAY['Когда музыка убедила даже плитку двигаться', 'Самый странный вечер начался с одного шага']::text[], 'Pulp Fiction Dance', 'A couple dances the twist on a black-and-white checkered floor in an elegant hall.', 'pulp, fiction, dance, couple, dances, twist, black, white, checkered, floor, elegant, hall, john, travolta', ARRAY['The music convinced even the tiles to move', 'The strangest evening began with one step']::text[]),
  ('086-abs.webp', 'Parking garage', 'Парковщик выписывает штраф огромной черепахе, на панцире которой аккуратно припаркован скутер.', 'парковка гараж черепаха панцирь скутер мотоцикл штраф парковщик', ARRAY['Самое медленное место заняли без разрешения', 'За стоянку на спине тоже придётся платить']::text[], 'Parking garage', 'A parking attendant issues a ticket to a large resting tortoise whose shell holds a neatly parked scooter.', 'parking, garage, attendant, issues, ticket, resting, tortoise, shell, holds, neatly, parked, scooter', ARRAY['The slowest parking spot was taken without permission', 'You must pay to park on someone''s back']::text[]),
  ('086-card.webp', 'Древний лесной страж с фонарём', 'Старый древесный великан несёт светящийся фонарь по реке среди домов на ветвях и ночного леса.', 'дерево великан лес страж фонарь река лодка дом ночь', ARRAY['Фонарщик старше самого леса', 'Дорогу домой несут в ладони']::text[], 'Ancient Forest Guardian with a Lantern', 'An old tree giant carries a glowing lantern along a river among houses built in branches and a nighttime forest.', 'tree giant, forest guardian, lantern, river, tree houses, branches, night', ARRAY['The lamplighter is older than the woods', 'The way home fits in one hand']::text[]),
  ('086-cos.webp', 'Метеоритный почтальон', 'Каменный метеорит в маленькой фуражке несёт письма на спине сквозь дождь спутников.', 'метеорит-почтальон, камень, фуражка, письма на спине, спутники, космическая почта', ARRAY['Доставка буквально свалилась с неба', 'На обратном пути он уже будет звездой']::text[], 'Meteor Mail Carrier', 'A stone meteorite in a tiny cap carries letters on its back through a rain of satellites.', 'meteorite, cap, letters, mail carrier, satellites', ARRAY['The delivery literally fell from the sky', 'On the way back it will be a star']::text[]),
  ('086-meme.webp', 'The Rock Eyebrow', 'Огромный мускулистый мужчина выразительно поднимает бровь перед крошечным сердитым мышонком.', 'The Rock Eyebrow, Скала поднял бровь, Дуэйн Джонсон, мышонок, мускулы, удивление', ARRAY['Когда самый маленький в комнате решил угрожать', 'Одна бровь сказала больше, чем целая речь']::text[], 'The Rock Eyebrow', 'A huge muscular man raises an expressive eyebrow at a tiny angry mouse.', 'rock, eyebrow, huge, muscular, man, raises, expressive, angry, mouse', ARRAY['The smallest creature in the room made a threat', 'One eyebrow said more than a speech']::text[]),
  ('087-abs.webp', 'House party', 'На вечеринке хозяйка выставила пустые бокалы, в каждом из которых поселилось разноцветное существо-настроение.', 'вечеринка бокалы стаканы гости хозяйка настроение цветные существа напитки', ARRAY['Каждому гостю налили его характер', 'Разговоры начались ещё до первого тоста']::text[], 'House party', 'A hostess sets out empty glasses; each glass fills with a different mood as a guest approaches, visible as a colored little creature.', 'house, party, hostess, sets, empty, glasses, glass, fills, different, mood, guest, approaches, visible, colored, creature', ARRAY['Every guest was served their own personality', 'The conversations began before the first toast']::text[]),
  ('087-card.webp', 'Девушка и кот у дворцовой арки', 'Девушка в светлом платье стоит в залитом солнцем дворце у арок; рядом идёт кот, за окнами видны зелёные сады.', 'девушка женщина кот дворец арки сад солнце платье', ARRAY['Гостья между двумя садами', 'Тишина нашла себе компанию']::text[], 'Girl and Cat by the Palace Arch', 'A girl in a light dress stands by arches in a sunlit palace while a cat walks beside her and green gardens appear beyond the windows.', 'girl, cat, palace, arches, sunlight, windows, green gardens', ARRAY['A visitor caught between two gardens', 'Silence finally found some company']::text[]),
  ('087-cos.webp', 'Планетный маникюр', 'Космический мастер красит ногти крошечной планете кисточкой размером с небоскрёб, жители держат образцы лака.', 'космический мастер, маникюр, ногти планеты, огромная кисточка, жители, образцы лака', ARRAY['На один палец ушёл весь годовой запас краски', 'Выбор цвета обсудили на общем собрании']::text[], 'Planet Manicure', 'A cosmic stylist paints a tiny planet''s nails with a skyscraper-sized brush while residents hold color samples.', 'planet, manicure, paintbrush, stylist, residents, nail polish', ARRAY['One finger used up the annual supply of paint', 'They voted on the color at a town meeting']::text[]),
  ('087-meme.webp', 'The Rock Driving', 'Двое пассажиров в машине обмениваются подозрительными взглядами, пока навигатор превращается в птицу.', 'The Rock Driving, Скала в машине, автомобиль, пассажиры, взгляды, навигатор, птица', ARRAY['Маршрут пересчитан, здравый смысл — нет', 'Когда водитель услышал от навигатора чириканье']::text[], 'The Rock Driving', 'Two passengers exchange suspicious looks in a car as the navigator turns into a bird.', 'rock, driving, passengers, exchange, suspicious, looks, car, navigator, turns, bird', ARRAY['Route recalculated; common sense has not', 'The GPS began to chirp']::text[]),
  ('088-abs.webp', 'Street sweeper', 'Дворник сгребает осенние листья, но каждый превращается в маленькое комнатное растение и снова укореняется.', 'дворник метла грабли осень листья растения цветы улица уборка', ARRAY['Уборка решила начать всё сначала', 'Падать с деревьев оказалось лишь первым этапом']::text[], 'Street sweeper', 'A sweeper gathers fallen autumn leaves; each leaf unfolds into a tiny complete houseplant, refusing to be swept.', 'street, sweeper, gathers, fallen, autumn, leaves, leaf, unfolds, complete, houseplant, refusing, swept', ARRAY['The cleanup decided to start over', 'Falling from the tree was only the beginning']::text[]),
  ('088-card.webp', 'Карнавал льва и летучих мышей', 'Лев жонглирует фазами луны на цирковой арене; над ним летают крылатые существа, а внизу толпятся рогатые зрители.', 'лев цирк карнавал луна летучие мыши демоны колесо обозрения жонглёр', ARRAY['Цирк объявил затмение', 'Сегодня на арене выступает сама ночь']::text[], 'Lion and Bats Carnival', 'A lion juggles phases of the moon in a circus ring while winged creatures fly overhead and horned spectators crowd below.', 'lion, circus, moon phases, juggling, bats, wings, horned audience', ARRAY['The circus has announced an eclipse', 'Tonight the darkness takes center stage']::text[]),
  ('088-cos.webp', 'Перевёрнутый космодром', 'Ракеты стоят потолком вниз на космодроме внутри пещеры, диспетчер с зонтом проверяет расписание по луже.', 'ракеты вверх ногами, перевёрнутый космодром, пещера, диспетчер, зонт, лужа, старт', ARRAY['Вылет по расписанию, направление уточняется', 'При посадке просят держаться за потолок']::text[], 'Upside-Down Rocket Port', 'Rockets stand upside down inside a cave spaceport while an umbrella-carrying dispatcher checks a puddle for the schedule.', 'rockets, upside down, cave, spaceport, dispatcher, umbrella, puddle', ARRAY['Departure is on time; direction is still under review', 'Please hold onto the ceiling during landing']::text[]),
  ('088-meme.webp', 'Shaq Hot Ones', 'Огромный баскетболист в испуге отшатывается от крошечной капли острого соуса на столе.', 'Shaq Hot Ones, Шак острый соус, баскетболист, Шакил О''Нил, испуг, капля, перец', ARRAY['Соперник размером с каплю победил гиганта', 'Когда слово слегка в меню оказалось обманом']::text[], 'Shaq Hot Ones', 'A giant basketball player recoils from a tiny drop of hot sauce on a table.', 'shaq, hot, ones, basketball, player, recoils, drop, sauce, table', ARRAY['An opponent the size of a drop beat the giant', 'The word mild on the menu was a lie']::text[]),
  ('089-abs.webp', 'Butcher shop', 'Продавец разрезает арбуз и находит внутри зелёный летний парк с дорожками и маленьким солнцем.', 'рынок арбуз продавец нож покупательница парк лето деревья фрукт', ARRAY['Одну дольку можно съесть как отпуск', 'Сочная покупка скрывала целый пейзаж']::text[], 'Butcher shop', 'A butcher delicately slices an enormous watermelon and finds a little summer park inside it; customer asks for a thin slice of sunshine.', 'butcher, shop, delicately, slices, watermelon, finds, summer, park, customer, asks, thin, slice, sunshine', ARRAY['You could eat a vacation in one slice', 'The juicy purchase concealed an entire landscape']::text[]),
  ('089-card.webp', 'Скелет кита несёт огненную птицу', 'Вышитый скелет кита шагает по пустыне; внутри его рёбер сидит красная птица, впереди сияет золотое солнце.', 'кит скелет кости птица феникс пустыня солнце река корабли', ARRAY['В пустыне наконец нашли море', 'Огонь путешествует внутри старых костей']::text[], 'Whale Skeleton Carries a Firebird', 'An embroidered whale skeleton walks through the desert with a red bird perched inside its ribs and a golden sun ahead.', 'whale skeleton, red bird, firebird, desert, ribs, golden sun', ARRAY['At last they found a sea in the desert', 'A small flame travels inside old bones']::text[]),
  ('089-cos.webp', 'Инопланетянин и земной пылесос', 'Пришелец в панике изучает земной пылесос, который засасывает звёздную карту и начинает указывать маршрут к холодильнику.', 'пришелец, земной пылесос, звёздная карта, маршрут к холодильнику, комната, паника', ARRAY['Навигатор проглотил дорогу к ужину', 'Незнакомая техника знает дом лучше хозяина']::text[], 'Vacuum Cleaner Navigator', 'An alien studies an Earth vacuum cleaner as it swallows a star map and points the way to the refrigerator.', 'alien, vacuum cleaner, star map, navigator, refrigerator', ARRAY['The navigator swallowed the route to dinner', 'Strange technology knows the house better than its owner']::text[]),
  ('089-meme.webp', 'Michael Jordan Crying', 'Плачущий баскетболист стоит в саду, где из его слёз растут баскетбольные мячи.', 'Michael Jordan Crying, плачущий Майкл Джордан, баскетболист, слёзы, сад, мячи', ARRAY['Даже поражение дало богатый урожай', 'Когда эмоции вышли на площадку раньше тебя']::text[], 'Crying Michael Jordan', 'A crying basketball player stands in a garden where basketballs grow from his tears.', 'crying, michael, jordan, basketball, player, stands, garden, basketballs, grow, tears', ARRAY['Even defeat produced a rich harvest', 'Emotions took the court before he did']::text[]),
  ('090-abs.webp', 'Aquarium maintenance', 'Уборщик моет стекло большого аквариума, а рыбы изнутри одновременно чистят его отражение своими крошечными скребками.', 'аквариум уборщик рыбы стекло отражение скребок ведро вода чистка', ARRAY['По обе стороны стекла назначили уборку', 'Рыбы решили помочь, но каждый по-своему']::text[], 'Aquarium maintenance', 'A custodian cleans the outside of a giant fish tank while the fish clean his reflection from the inside using miniature squeegees.', 'aquarium, maintenance, custodian, cleans, fish, tank, clean, reflection, using, miniature, squeegees', ARRAY['Cleaning was scheduled on both sides of the glass', 'The fish helped in their own strange way']::text[]),
  ('090-card.webp', 'Лодка под китом на водопаде', 'Женщина плывёт на лодке с красным зонтом вниз по огромному водопаду; над ней летит кит под северным сиянием.', 'кит лодка женщина красный зонт водопад северное сияние луна', ARRAY['Пассажир над краем света', 'Зонт не поможет, если река падает с неба']::text[], 'Boat Beneath a Whale at a Waterfall', 'A woman in a boat with a red umbrella descends a huge waterfall while a whale flies above her beneath the northern lights.', 'woman, boat, red umbrella, waterfall, flying whale, aurora borealis', ARRAY['A passenger near the edge of the world', 'An umbrella is little help when the river falls from the sky']::text[]),
  ('090-cos.webp', 'Космический почтальон на страусе', 'Астронавт скачет верхом на страусе по кольцам Сатурна, одной рукой вручает конверт одинокой луне.', 'астронавт-почтальон, страус, кольца Сатурна, письмо, одинокая луна, скачка', ARRAY['Экспресс-доставка оставляет след из перьев', 'До адресата ещё один круг и одно упрямое седло']::text[], 'Ostrich Courier on Saturn', 'An astronaut rides an ostrich along Saturn''s rings and delivers a letter to a lonely moon.', 'astronaut, ostrich, Saturn rings, letter, moon, courier', ARRAY['Express delivery leaves a trail of feathers', 'One more orbit and one stubborn saddle to go']::text[]),
  ('090-meme.webp', 'Obama Medal', 'Торжественный чиновник в костюме сам себе вручает огромную медаль в форме печенья.', 'Obama Medal, Обама награждает себя, медаль, чиновник, печенье, церемония', ARRAY['Победитель конкурса назначил себя жюри', 'Награду можно сразу съесть, если никто не смотрит']::text[], 'Obama Gives Himself a Medal', 'A solemn official awards himself a huge cookie-shaped medal.', 'obama, gives, himself, medal, solemn, official, awards, huge, cookie, shaped', ARRAY['The winner appointed himself the judge', 'The prize can be eaten if nobody is watching']::text[]),
  ('091-abs.webp', 'Laundry folding', 'Отец складывает простыню с движущимся ночным небом внутри, а кот устраивается в самом тёмном углу.', 'стирка простыня бельё отец кот ночь звёзды ткань кровать', ARRAY['Перед сном пришлось свернуть целое небо', 'Кот выбрал место потемнее']::text[], 'Laundry folding', 'A father folds a bedsheet that contains a moving starless night sky; a sleepy cat chooses the darkest corner.', 'laundry, folding, father, folds, bedsheet, contains, moving, starless, night, sky, sleepy, cat, chooses, darkest, corner', ARRAY['The whole sky had to be folded before bed', 'The cat chose the darkest corner']::text[]),
  ('091-card.webp', 'Великаны пьют чай с драконами', 'Два улыбающихся великана пьют чай и едят торт вместе с маленькими драконами за столом на мосту над облаками.', 'великаны драконы чай торт мост замки облака чаепитие', ARRAY['Чаепитие на головокружительной высоте', 'Торт пришлось строить как крепость']::text[], 'Giants Have Tea with Dragons', 'Two smiling giants drink tea and eat cake with small dragons at a table on a bridge above the clouds.', 'giants, tea, cake, small dragons, bridge, clouds, table', ARRAY['Tea at a dizzying height', 'They had to build the cake like a fortress']::text[]),
  ('091-cos.webp', 'Кофейня у края вселенной', 'Бариста с четырьмя руками рисует пенкой на кофе спиральную галактику, за окном космический край загибается как ковёр.', 'бариста с четырьмя руками, кофе, пенка-галактика, край вселенной, окно, кофейня', ARRAY['Заказали маленький, получили бесконечный', 'За окном кончается карта, но не меню']::text[], 'Four-Armed Galactic Barista', 'A four-armed barista draws a spiral galaxy in coffee foam while the edge of space curls like a rug outside.', 'barista, four arms, coffee foam, spiral galaxy, edge of space', ARRAY['They ordered a small cup and got infinity', 'The map ends outside, but the menu keeps going']::text[]),
  ('091-meme.webp', 'Три двойника', 'Трое героев в цветных масках указывают друг на друга перед кассой кинотеатра.', 'Spider-Man Pointing, три двойника, три Человека-паука, супергерои, маски, указывают пальцем', ARRAY['Когда каждый утверждает, что билет купил другой', 'Секрет раскрыт, но сразу в трёх экземплярах']::text[], 'Spider-Man Pointing', 'Three masked superheroes point at one another outside a movie theater ticket booth.', 'spider, man, pointing, masked, superheroes, point, another, movie, theater, ticket, booth', ARRAY['Everybody says somebody else bought the tickets', 'The secret came out in triplicate']::text[]),
  ('092-abs.webp', 'Kitchen spice rack', 'Повариха открывает банку терпения, но оттуда выскакивает её беспокойная миниатюрная копия и переставляет кастрюли.', 'кухня повариха банка специи терпение маленькая копия кастрюли шкаф', ARRAY['Запас спокойствия немедленно разбежался', 'Помощница из банки только добавила суеты']::text[], 'Kitchen spice rack', 'A cook opens a jar of patience, but a restless miniature version of herself jumps out and starts rearranging every pot.', 'kitchen, spice, rack, cook, opens, jar, patience, but, restless, miniature, version, herself, jumps, starts, rearranging, pot', ARRAY['The supply of calm immediately ran away', 'The helper from the jar only added chaos']::text[]),
  ('092-card.webp', 'Сонная луна и радужный город', 'Лунное лицо улыбается над разноцветным городом; лодка плывёт по радужной дороге среди планет и звёзд.', 'луна лицо радуга город лодка планеты звёзды сон', ARRAY['Радуга прогуливает ночь', 'Город уснул прямо посреди путешествия']::text[], 'Sleepy Moon and Rainbow City', 'A smiling moon face shines above a colorful city while a boat sails along a rainbow road among planets and stars.', 'smiling moon, rainbow city, boat, rainbow road, planets, stars', ARRAY['The rainbow is playing hooky after dark', 'The city fell asleep halfway through its journey']::text[]),
  ('092-cos.webp', 'НЛО в пробке на Земле', 'Летающая тарелка стоит среди земных машин на светофоре, водитель-инопланетянин нервно сигналит световым лучом.', 'НЛО, летающая тарелка, земная пробка, автомобили, светофор, водитель-пришелец, световой сигнал', ARRAY['Мог прилететь издалека, но застрял у перекрёстка', 'Даже для гостей с неба красный всё ещё красный']::text[], 'UFO at a Red Light', 'A flying saucer waits among Earth cars at a traffic light while its alien driver honks with a beam of light.', 'UFO, flying saucer, Earth cars, traffic light, alien driver', ARRAY['It crossed space only to get stuck at an intersection', 'Even visitors from the sky have to stop for red']::text[]),
  ('092-meme.webp', 'Rickroll', 'Рыжеволосый певец с микрофоном внезапно появляется посреди офиса и танцует перед удивлёнными сотрудниками.', 'Rickroll, рикролл, Рик Эстли, рыжий певец, микрофон, офис, неожиданный танец', ARRAY['Открыл рабочую ссылку и получил целый концерт', 'Этот сюрприз обещает никогда не уходить']::text[], 'Rickroll', 'A red-haired singer with a microphone appears in an office and dances before astonished workers.', 'rickroll, red, haired, singer, microphone, appears, office, dances, before, astonished, workers', ARRAY['Opened a work link and got a concert', 'This surprise promises never to leave']::text[]),
  ('093-abs.webp', 'Morning jog', 'Девушка бежит на месте, пока тротуар-лента прокручивает мимо неё весь город; собака спокойно сидит рядом.', 'бег пробежка тротуар беговая дорожка город девушка собака улица', ARRAY['Город решил бегать вместо спортсменки', 'На этой тренировке пейзаж устал первым']::text[], 'Morning jog', 'A jogger runs in place while the sidewalk treadmill walks the whole city past her; a dog sits and enjoys the scenery.', 'morning, jog, jogger, runs, place, sidewalk, treadmill, walks, city, past, dog, sits, enjoys, scenery', ARRAY['The city decided to run instead of the athlete', 'On this treadmill the scenery tired first']::text[]),
  ('093-card.webp', 'Самурай пьёт чай под тенью дракона', 'Два воина в японских доспехах пьют чай под красным солнцем; над храмами нависает огромная чёрная голова дракона.', 'самурай воин чай дракон красное солнце японский храм журавли', ARRAY['Перемирие под красным солнцем', 'Самый грозный гость не попросил чашку']::text[], 'Samurai Take Tea in a Dragon''s Shadow', 'Two warriors in Japanese armor drink tea under a red sun while an enormous black dragon head looms over the temples.', 'samurai, tea, Japanese armor, red sun, black dragon, temples', ARRAY['A truce beneath the red sun', 'The fiercest guest never asked for a cup']::text[]),
  ('093-cos.webp', 'Гигантский космический пельмень', 'Горячий пельмень величиной с планету дрейфует в космосе, экипаж маленького корабля изучает его со смотровой ложки.', 'гигантский пельмень, космос, горячая еда, корабль, ложка, экипаж, планета', ARRAY['Ужин потребует корабль побольше', 'Сначала решили исследовать, потом добавили сметану']::text[], 'Planet-Sized Dumpling', 'A hot dumpling the size of a planet drifts through space while a tiny ship crew examines it from an observation spoon.', 'dumpling, planet, space, spaceship, giant spoon, food', ARRAY['Dinner will require a bigger ship', 'They began with research and ended with sour cream']::text[]),
  ('093-meme.webp', 'Batman Slapping Robin', 'Суровый герой в чёрном плаще останавливает юного напарника резким жестом огромной перчатки над городом.', 'Batman Slapping Robin, Бэтмен даёт пощёчину Робину, герой, плащ, перчатка, напарник', ARRAY['Когда твоя идея не прошла проверку одним движением', 'Наставник решил прервать презентацию раньше второго слайда']::text[], 'Batman Slapping Robin', 'A stern caped hero stops his young partner with a huge gloved gesture above a city.', 'batman, slapping, robin, stern, caped, hero, stops, young, partner, huge, gloved, gesture, city', ARRAY['The idea failed the test in one move', 'The mentor cut off the presentation before slide two']::text[]),
  ('094-abs.webp', 'Public restroom', 'Уборщик меняет зеркало в общественном туалете, но старое отражение человека осталось ждать своей очереди у раковины.', 'туалет уборщик зеркало отражение мужчина раковина очередь чистка', ARRAY['Уходить отказалась только копия', 'Даже отражению пришлось подождать умывания']::text[], 'Public restroom', 'A janitor replaces a mirror, but the old mirror reflection waits politely in line for the sink before leaving.', 'public, restroom, janitor, replaces, mirror, but, reflection, waits, politely, line, sink, before, leaving', ARRAY['Only the copy refused to leave', 'Even a reflection had to wait its turn to wash']::text[]),
  ('094-card.webp', 'Парусник плывёт к полумесяцу', 'Крошечная лодка с золотым парусом идёт по морю облаков под гигантским полумесяцем и звёздами.', 'лодка корабль парусник море облака полумесяц луна звёзды', ARRAY['Плыть туда, где кончается небо', 'Ночной рейс без берегов']::text[], 'Sailboat Heads for the Crescent Moon', 'A tiny boat with a golden sail crosses a sea of clouds beneath an enormous crescent moon and stars.', 'sailboat, golden sail, sea of clouds, crescent moon, stars', ARRAY['Sail until the sky runs out', 'A night crossing with no shore']::text[]),
  ('094-cos.webp', 'Астронавт потерял верх', 'Космонавт ищет верх и низ в комнате невесомости, пока стрелки на стенах спорят и показывают в разные стороны.', 'астронавт, невесомость, стрелки в разные стороны, верх и низ, космическая комната', ARRAY['Инструкция говорит встать, но не объясняет куда', 'Потолок уже третий раз поменялся местами с полом']::text[], 'Which Way Is Up?', 'An astronaut searches for up and down in a weightless room as arrows on the walls argue in every direction.', 'astronaut, zero gravity, room, arrows, ceiling, floor', ARRAY['The instructions say stand up but never say where', 'The ceiling has traded places with the floor three times']::text[]),
  ('094-meme.webp', 'Facepalm Captain', 'Пожилой лысый капитан космического корабля закрывает лицо ладонью на фоне летящих бумаг.', 'Captain Picard Facepalm, Пикар фейспалм, капитан, ладонь у лица, космический корабль, бумаги', ARRAY['Когда стажёр снова нажал красную кнопку', 'Объяснять уже поздно, молчать ещё рано']::text[], 'Captain Picard Facepalm', 'An elderly bald spaceship captain covers his face with one hand as papers fly behind him.', 'captain, picard, facepalm, elderly, bald, spaceship, covers, face, hand, papers, fly, him', ARRAY['The intern pressed the red button again', 'Too late to explain, too early to stay silent']::text[]),
  ('095-abs.webp', 'Lost property desk', 'Сотрудница бюро находок держит в клетке забытый смех, а пришедший человек узнаёт его по звуку.', 'бюро находок клетка птица смех женщина служащая посетитель забытая вещь', ARRAY['Потерю узнали прежде, чем увидели', 'В клетке оказалось то, что невозможно удержать']::text[], 'Lost property desk', 'A bored attendant catalogs a forgotten laugh in a small birdcage; its owner recognizes it from the sound.', 'lost, property, desk, bored, attendant, catalogs, forgotten, laugh, birdcage, owner, recognizes, sound', ARRAY['They recognized the lost thing before seeing it', 'The cage held what nobody could contain']::text[]),
  ('095-card.webp', 'Водолаз смотрит в окно подводного дома', 'В старинной водолазной маске человек стоит на дне среди рыб и медуз перед окном в солнечный сад; рядом велосипед и аквариум.', 'водолаз скафандр подводный дом окно сад рыбы медузы велосипед аквариум', ARRAY['За стеклом внезапно стало суше', 'Путь домой ведёт вверх по ступеням']::text[], 'Diver Looks into an Underwater Home', 'A person in an antique diving helmet stands on the seabed among fish and jellyfish before a window onto a sunny garden, beside a bicycle and an aquarium.', 'diver, diving helmet, underwater house, fish, jellyfish, window, garden, bicycle, aquarium', ARRAY['The other side of the glass is unexpectedly dry', 'The way home leads up the stairs']::text[]),
  ('095-cos.webp', 'Лунный фокусник', 'Фокусник-кролик достаёт из цилиндра целое созвездие, зрители-пришельцы аплодируют антеннами.', 'фокусник-кролик, цилиндр, созвездие, зрители-пришельцы, магия, астероидная сцена', ARRAY['Аплодисменты разлетелись дальше реквизита', 'Из шляпы достали слишком много света']::text[], 'Rabbit Magician''s Constellation', 'A rabbit magician pulls an entire constellation from a top hat while alien spectators applaud with antennae.', 'rabbit, magician, top hat, constellation, alien audience', ARRAY['The applause flew farther than the stage props', 'They pulled too much light out of the hat']::text[]),
  ('095-meme.webp', 'Gru''s Plan', 'Злодей в чёрном шарфе показывает на стенде три картинки своего плана и обнаруживает, что в финале сам оказался в банке.', 'Gru''s Plan, план Грю, злодей, доска, три схемы, банка, провал плана', ARRAY['Первые два шага блестящие, третий надо было читать заранее', 'Когда презентация сама раскрыла подвох']::text[], 'Gru''s Plan', 'A villain presents three pictures of his plan and realizes that the last one puts him inside a jar.', 'gru, plan, villain, presents, pictures, realizes, last, puts, him, jar', ARRAY['The first two steps were brilliant; he should have read the third', 'The presentation revealed its own trap']::text[]),
  ('096-abs.webp', 'Dentist waiting room', 'В очереди к стоматологу сидят пациенты с журналами, а гигантская зубная щётка пытается пройти без очереди.', 'стоматолог поликлиника очередь зубная щётка пациент журнал врач кресла', ARRAY['Самый длинный посетитель спешит первым', 'Утреннюю гигиену вызвали к врачу']::text[], 'Dentist waiting room', 'A patient reads a magazine while a giant toothbrush tries to sneak in ahead of everyone in the queue.', 'dentist, waiting, room, patient, reads, magazine, toothbrush, tries, sneak, ahead, everyone, queue', ARRAY['The tallest visitor wants to go first', 'Morning hygiene was called in to see the doctor']::text[]),
  ('096-card.webp', 'Воин и гигантские рыбы среди волн', 'Воин в доспехах стоит на лодке среди бурных волн; над ним выпрыгивают огромные серебристые рыбы у японского храма.', 'самурай воин лодка волны шторм рыбы карпы японский храм', ARRAY['Шторм плывёт против течения', 'Обычная рыбалка вышла из-под контроля']::text[], 'Warrior and Giant Fish Among Waves', 'An armored warrior stands in a boat amid rough waves as enormous silver fish leap above him near a Japanese temple.', 'warrior, armor, boat, storm, waves, giant silver fish, Japanese temple', ARRAY['The storm is swimming against the current', 'An ordinary fishing trip got out of hand']::text[]),
  ('096-cos.webp', 'Сатурн в шарфе', 'Маленькая портниха вяжет гигантский полосатый шарф вокруг Сатурна, используя спутник как клубок пряжи.', 'Сатурн планета кольца спутник портниха вязаный шарф пряжа', ARRAY['Даже гигантам зимой дует в шею', 'Космический дресс-код на октябрь']::text[], 'Saturn in a Scarf', 'A tiny seamstress knits an enormous striped scarf around Saturn, using one of its moons as a ball of yarn.', 'Saturn, planet, rings, moon, seamstress, knitted scarf, yarn', ARRAY['Even giants feel a chill around the neck in winter', 'A cosmic dress code for October']::text[]),
  ('096-meme.webp', 'Ballerina Cappuccina', 'Балерина с чашкой капучино вместо головы танцует на огромном белом блюдце под театральными огнями.', 'Ballerina Cappuccina, балерина капучина, чашка кофе, балет, блюдце, сцена', ARRAY['Утро вышло на сцену и закружилось', 'Один неловкий поклон — и зрителям нужен сахар']::text[], 'Ballerina Cappuccina', 'A ballerina with a cappuccino cup for a head dances on a giant white saucer beneath theater lights.', 'ballerina, cappuccina, cappuccino, cup, head, dances, white, saucer, beneath, theater, lights', ARRAY['Morning stepped onstage and began to spin', 'One awkward bow and the audience will need sugar']::text[]),
  ('097-abs.webp', 'Kite shop', 'В магазине воздушных змеев бумажный календарь поднимает покупателя над полом, пока продавец держит верёвку.', 'воздушный змей календарь бумага покупатель магазин полёт верёвка продавец', ARRAY['Расписание унесло человека раньше отпуска', 'Планы на ветер оказались буквальными']::text[], 'Kite shop', 'A shopkeeper tests a kite made from a tiny office calendar; it pulls an adult customer''s feet just off the ground.', 'kite, shop, shopkeeper, tests, made, office, calendar, pulls, adult, customer, feet, just, off, ground', ARRAY['The schedule carried him away before vacation', 'Plans thrown to the wind became literal']::text[]),
  ('097-card.webp', 'Лев с зонтом у лестницы в небо', 'Лев в короне держит красный зонтик у лестницы из облаков; по ступеням поднимается человек в красном плаще.', 'лев корона зонт лестница облака небо человек плащ', ARRAY['Зонтик для восхождения', 'Королевская встреча назначена на облаке']::text[], 'Lion with an Umbrella by the Sky Staircase', 'A crowned lion holds a red umbrella beside a staircase made of clouds as a person in a red cloak climbs upward.', 'lion, crown, red umbrella, cloud staircase, person, red cloak', ARRAY['An umbrella for the climb', 'The royal appointment is on a cloud']::text[]),
  ('097-cos.webp', 'Космический автобус без дверей', 'Жёлтый школьный автобус летит боком через туманность, пассажиры заходят через люк на крыше по верёвочной лестнице.', 'жёлтый школьный автобус, космос, туманность, люк на крыше, верёвочная лестница, пассажиры', ARRAY['Остановка есть, вход придётся искать сверху', 'Школьный маршрут опять стал слишком живописным']::text[], 'School Bus Through a Nebula', 'A yellow school bus flies sideways through a nebula while students climb through a roof hatch on a rope ladder.', 'yellow school bus, nebula, roof hatch, rope ladder, students', ARRAY['The stop is here; find the entrance above', 'The school route became picturesque again']::text[]),
  ('097-meme.webp', 'Peace Was Never an Option', 'Белый гусь с тупым столовым ножом в клюве угрожающе смотрит на прохожих на мирной деревенской дороге.', 'Peace Was Never an Option, мир не вариант, гусь, нож, деревня, угроза', ARRAY['Переговоры закончились ещё до первого гогота', 'Когда тихий двор выбрал драматичный сценарий']::text[], 'Peace Was Never an Option', 'A white goose with a blunt table knife in its beak glares at passersby on a quiet village road.', 'peace, never, option, white, goose, blunt, table, knife, beak, glares, passersby, quiet, village, road', ARRAY['Negotiations ended before the first honk', 'The peaceful yard chose a dramatic plot']::text[]),
  ('098-abs.webp', 'Bike lane', 'Рабочий рисует зелёную велодорожку, и из мокрой краски прорастают крошечные велосипеды перед изумлённым курьером.', 'велодорожка велосипед краска дорожный рабочий курьер улица зелёная полоса', ARRAY['Маршрут начал выращивать транспорт', 'Свежую разметку лучше не топтать']::text[], 'Bike lane', 'A traffic painter draws a new bicycle lane and actual tiny bicycles sprout from wet paint; a courier tries not to step on them.', 'bike, lane, traffic, painter, draws, bicycle, actual, bicycles, sprout, wet, paint, courier, tries, not, step', ARRAY['The route began growing its own transport', 'Best not step on the fresh road markings']::text[]),
  ('098-card.webp', 'Кухня внутри огромной тыквы', 'Повара и маленький дракон готовят звёздный суп и хлеб в многоэтажной кухне внутри разрезанной тыквы.', 'тыква кухня повара суп звёзды хлеб дракон печь часы', ARRAY['Ужин в доме с толстой кожурой', 'Рецепт для полуночного неба']::text[], 'Kitchen Inside a Giant Pumpkin', 'Cooks and a small dragon prepare starry soup and bread in a multistory kitchen inside a cut-open pumpkin.', 'pumpkin, kitchen, cooks, small dragon, soup, bread, stars', ARRAY['Dinner in a house with a thick skin', 'A recipe for the midnight sky']::text[]),
  ('098-cos.webp', 'Марсианская стирка мозга', 'Пришельцы развешивают свежевыстиранные мысли на бельевой верёвке между двумя кратерами, мысли имеют форму облачков.', 'пришельцы, стирка мозга, мысли-облака, бельевая верёвка, кратеры, Марс', ARRAY['После сушки идеи стали немного легче', 'Ветер разнёс все вчерашние мысли по соседям']::text[], 'Thoughts on the Clothesline', 'Aliens hang freshly washed cloud-shaped thoughts between two craters to dry.', 'aliens, thoughts, clothesline, clouds, craters, laundry', ARRAY['The ideas felt lighter after drying', 'Yesterday''s thoughts blew into the neighbors'' yard']::text[]),
  ('098-meme.webp', 'White Rabbit Time', 'Белый кролик в зелёном жилете показывает карманные часы над городом, который спешит по кругу.', 'White Rabbit Time, белый кролик с часами, Алиса, часы, спешка, город', ARRAY['Опаздывать можно даже стоя на месте', 'Когда расписание догоняет тебя первым']::text[], 'White Rabbit Time', 'A white rabbit in a green vest holds up a pocket watch above a city rushing in circles.', 'white, rabbit, time, green, vest, holds, pocket, watch, city, rushing, circles', ARRAY['You can be late while standing still', 'The timetable caught you first']::text[]),
  ('099-abs.webp', 'Kitchen sink', 'Сантехник заглядывает в раковину, где под струёй воды рыбки выстроились на купание, а резиновая утка дежурит спасателем.', 'раковина кран вода сантехник рыбы рыбки резиновая утка купание ванна', ARRAY['Водопровод записался на водные процедуры', 'За порядком следит самый жёлтый спасатель']::text[], 'Kitchen sink', 'A plumber opens the tap to find a tiny orderly line of fish waiting for a bath; a rubber duck acts as lifeguard.', 'kitchen, sink, plumber, opens, tap, find, orderly, line, fish, waiting, bath, rubber, duck, acts, lifeguard', ARRAY['The plumbing signed up for a swim', 'The yellowest lifeguard keeps watch']::text[]),
  ('099-card.webp', 'Мебель устроила чаепитие для людей', 'Огромное красное кресло пьёт чай; стол, часы, тостер и другая мебель с лицами окружают крошечных испуганных людей.', 'кресло мебель чай стол часы тостер люди лица дом', ARRAY['Сегодня гости сами оказались на блюде', 'Хозяева комнаты наконец заговорили']::text[], 'Furniture Hosts Tea for Humans', 'An enormous red armchair drinks tea while a table, clock, toaster and other furniture with faces surround tiny frightened people.', 'red armchair, tea, living furniture, table, clock, toaster, tiny humans', ARRAY['Today the guests were served on the platter', 'The owners of the room finally spoke']::text[]),
  ('099-cos.webp', 'Пылесос на свидании', 'Робот-пылесос дарит букет магнитных крошек другому роботу под звёздным фонарём, оба смущённо мигают.', 'два робота-пылесоса, свидание, букет магнитных крошек, звёздный фонарь, мигающие огни', ARRAY['Он подарил ей то, что обычно убирают', 'Первое свидание прошло очень чисто']::text[], 'Robot Vacuum Date', 'A robot vacuum gives another robot a bouquet of magnetic crumbs beneath a starry streetlamp.', 'robot vacuums, bouquet, magnetic crumbs, date, stars', ARRAY['He gave her what he usually cleans away', 'The first date went very cleanly']::text[]),
  ('099-meme.webp', 'Everything Is Cake', 'Повар разрезает ножом кроссовок, и внутри вместо обуви обнаруживаются яркие слои бисквита.', 'Everything Is Cake, всё торт, кроссовок, бисквит, повар, нож, удивление', ARRAY['После этого даже дивану перестали доверять', 'Когда реальность оказалась с кремовой прослойкой']::text[], 'Everything Is Cake', 'A chef cuts a sneaker to reveal bright layers of sponge cake inside.', 'everything, cake, chef, cuts, sneaker, reveal, bright, layers, sponge', ARRAY['After that nobody trusted the sofa', 'Reality had a layer of frosting']::text[]),
  ('100-abs.webp', 'Town laundromat roof', 'Мастер с лестницы спасает облако, зацепившееся за бельевую верёвку на крыше; облако держит потерянный носок.', 'крыша бельё верёвка облако туча носок лестница мастер стирка', ARRAY['Пропажу из стирки нашла погода', 'Зацепившийся гость не умеет спускаться']::text[], 'Town laundromat roof', 'A repairer climbs a ladder to rescue a cloud snagged on a laundry line; the cloud clutches one missing sock.', 'town, laundromat, roof, repairer, climbs, ladder, rescue, cloud, snagged, laundry, line, clutches, missing, sock', ARRAY['The weather found what the laundry had lost', 'The visitor is caught and cannot climb down']::text[]),
  ('100-card.webp', 'Девочка красит облако в розовый', 'Девочка стоит на стремянке в цветочном поле и большой кистью красит облако розовой краской; рядом овца и птицы.', 'девочка стремянка кисть краска розовое облако небо поле овца птицы', ARRAY['Небо заказало новый цвет', 'Рабочий день начинается выше крыши']::text[], 'Girl Paints a Cloud Pink', 'A girl on a stepladder in a field of flowers paints a cloud pink with a large brush while a sheep and birds watch.', 'girl, stepladder, pink cloud, paintbrush, flowers, sheep, birds', ARRAY['The sky ordered a new color', 'This workday begins above the rooftops']::text[]),
  ('100-cos.webp', 'Космический цирк теней', 'На сцене астероида артист показывает фонарём тени чудовищ, а сами чудовища сидят в первом ряду с попкорном.', 'космический цирк, театр теней, фонарь, чудовища, астероидная сцена, попкорн', ARRAY['Публика узнала себя раньше финала', 'Пугали только тех, кто сам умеет пугать']::text[], 'Monster Shadow Show', 'A performer on an asteroid stage casts monster shadows with a flashlight while the real monsters eat popcorn in front.', 'asteroid stage, performer, flashlight, monster shadows, audience, popcorn', ARRAY['The audience recognized itself before the finale', 'The only ones frightened already knew how to frighten']::text[]),
  ('100-meme.webp', 'SpongeBob Tired', 'Жёлтая морская губка из последних сил тянется к стулу, хотя позади всего один пройденный шаг.', 'SpongeBob Tired, уставший Губка Боб, жёлтая губка, стул, усталость, шаг', ARRAY['Первый пункт плана выполнен, пора в отпуск', 'Когда дорога до кухни потребовала героизма']::text[], 'Tired SpongeBob', 'A yellow sea sponge reaches desperately for a chair after walking only one step.', 'tired, spongebob, yellow, sea, sponge, reaches, desperately, chair, after, walking, step', ARRAY['Completed the first task; time for a holiday', 'Getting to the kitchen took heroic effort']::text[]),
  ('101-abs.webp', 'Office birthday', 'На офисном дне рождения свеча на торте выросла в костёр, и сотрудники уселись вокруг него вместо работы.', 'офис день рождения торт свеча костёр сотрудники праздник работа', ARRAY['Праздник незаметно стал походом', 'Сегодня отчёты подождут у огня']::text[], 'Office birthday', 'A team lights one candle on a cake; the flame grows into a tiny campfire and everyone sits around it telling stories instead of working.', 'office, birthday, team, lights, candle, cake, flame, grows, campfire, everyone, sits, telling, stories, working', ARRAY['The office party quietly turned into camping', 'Today''s reports can wait beside the fire']::text[]),
  ('101-card.webp', 'Панда и замок под красным солнцем', 'Чёрная панда с силуэтом японского замка на животе сидит под красным солнцем среди бабочек и гор.', 'панда медведь японский замок красное солнце бабочки горы', ARRAY['Крепость спряталась в объятиях', 'Солнце садится прямо на доспехи']::text[], 'Panda and Castle Beneath a Red Sun', 'A black panda with the silhouette of a Japanese castle on its belly sits beneath a red sun among butterflies and mountains.', 'panda, Japanese castle, red sun, butterflies, mountains', ARRAY['A fortress hidden in an embrace', 'The sunset lands right on the armor']::text[]),
  ('101-cos.webp', 'Дождь из зонтиков', 'На планете с перевёрнутой гравитацией разноцветные зонты падают вверх и раскрываются вокруг удивлённого почтальона.', 'почтальон, разноцветные зонтики, обратная гравитация, дождь вверх, планета', ARRAY['Прогноз обещал осадки, но перепутал направление', 'Крышу пришлось искать под ногами']::text[], 'Umbrellas Fall Upward', 'On a world with reversed gravity, colorful umbrellas fall upward around a surprised mail carrier.', 'reversed gravity, umbrellas, mail carrier, planet, falling upward', ARRAY['The forecast got the direction of the rain wrong', 'They had to search for the roof beneath their feet']::text[]),
  ('101-meme.webp', 'Угрюмый сосед', 'Фиолетовый осьминог из окна недовольно смотрит на шумный соседский праздник с пузырями.', 'Squidward, Сквидвард, угрюмый сосед, осьминог, окно, праздник, пузыри', ARRAY['Соседи опять веселятся с нарушением тишины', 'Он мечтал о спокойствии, а получил фейерверк из воды']::text[], 'Squidward', 'A purple octopus glares from a window at the noisy bubble party next door.', 'squidward, purple, octopus, glares, window, noisy, bubble, party, next, door', ARRAY['The neighbors are having fun in violation of the quiet hours', 'He asked for peace and got underwater fireworks']::text[]),
  ('102-abs.webp', 'Supermarket freezer', 'Сотрудница магазина раскладывает овощи в морозилке, где крошечная полярная экспедиция несёт гигантскую морковь как знамя.', 'супермаркет морозилка овощи морковь полярники экспедиция снег продавщица', ARRAY['Путь к ужину оказался севернее ожидаемого', 'Флаг отряда сегодня съедобный']::text[], 'Supermarket freezer', 'A clerk arranges frozen vegetables while a tiny polar expedition crosses one shelf carrying an oversized carrot as a flag.', 'supermarket, freezer, clerk, arranges, frozen, vegetables, polar, expedition, crosses, shelf, carrying, oversized, carrot, flag', ARRAY['Dinner was farther north than anyone expected', 'The expedition''s flag is edible today']::text[]),
  ('102-card.webp', 'Джинн хранит караван в бутылке', 'Синий джинн держит расколотую золотую сферу и павлинье перо; внутри стеклянной бутылки идёт караван по пустыне.', 'джинн бутылка караван верблюды пустыня павлинье перо золотая сфера луна', ARRAY['Путешествие заперли в бутылке', 'Желание оказалось больше своей тары']::text[], 'Genie Keeps a Caravan in a Bottle', 'A blue genie holds a cracked golden sphere and a peacock feather while a desert caravan travels inside a glass bottle.', 'blue genie, caravan, glass bottle, desert, golden sphere, peacock feather', ARRAY['The journey was sealed inside a bottle', 'The wish was bigger than its container']::text[]),
  ('102-cos.webp', 'Космический археолог', 'Археолог расчёсывает поверхность древней планеты кисточкой, обнаруживая под песком огромную кнопку лифта.', 'археолог, кисточка, древняя планета, песок, огромная кнопка лифта, раскопки', ARRAY['Раскопки нашли этаж, которого нет на карте', 'Прошлое оказалось с очень удобным входом']::text[], 'Planet Archaeologist Finds a Lift', 'An archaeologist brushes sand from an ancient planet and uncovers an enormous elevator button.', 'archaeologist, ancient planet, brush, sand, elevator button', ARRAY['The dig found a floor missing from every map', 'The past came with a surprisingly convenient entrance']::text[]),
  ('102-meme.webp', 'Patrick Wallet', 'Розовая морская звезда спорит с зелёным продавцом за прилавком о кошельке, который держит в руках.', 'Patrick Wallet, Патрик кошелёк, морская звезда, кошелёк, продавец, спор', ARRAY['Очевидное доказательство снова не сработало', 'Когда логика зашла в магазин и потерялась']::text[], 'Patrick''s Wallet', 'A pink starfish argues with a green shopkeeper about the wallet he is holding.', 'patrick, wallet, pink, starfish, argues, green, shopkeeper, about, holding', ARRAY['The obvious evidence failed again', 'Logic walked into the shop and got lost']::text[]),
  ('103-abs.webp', 'Neighborhood playground', 'Родительница толкает качели с огромным списком покупок вместо ребёнка, и на каждом взлёте одно дело исчезает.', 'детская площадка качели список покупок бумага родительница парк дела', ARRAY['Дела решились сами во время прогулки', 'Каждый взмах облегчает расписание']::text[], 'Neighborhood playground', 'A parent pushes a swing carrying their own giant shopping list; every swing erases one item as it reaches the top.', 'neighborhood, playground, parent, pushes, swing, carrying, shopping, list, erases, item, reaches, top', ARRAY['The chores solved themselves during a walk', 'Every swing made the calendar lighter']::text[]),
  ('103-card.webp', 'Тень под красным солнцем', 'Худой человек стоит под красным солнцем на тёмной улице, пока другая фигура склоняется над огромной чёрной тенью.', 'красное солнце, тёмная улица, человек, чёрная тень, силуэт, тревога', ARRAY['Полдень почему-то ведёт себя как полночь', 'Не всё, что следует за тобой, хочет отстать']::text[], 'Shadow Beneath a Red Sun', 'A thin person stands under a red sun on a dark street while another figure bends over an enormous black shadow.', 'red sun, dark street, person, enormous shadow, figure', ARRAY['For some reason noon is behaving like midnight', 'Not everything that follows you wants to be left behind']::text[]),
  ('103-cos.webp', 'Инопланетный супермаркет', 'Вид от первого лица из тележки: покупатель-пришелец тянется за банкой с северным сиянием на верхней полке.', 'инопланетный супермаркет, тележка, банка с северным сиянием, высокий стеллаж, покупатель', ARRAY['Покупка светится, но достать её непросто', 'На верхней полке снова лежит целое небо']::text[], 'Aurora on the Top Shelf', 'An alien shopper reaches from a cart for a jar of northern lights on the highest store shelf.', 'alien shopper, cart, jar, northern lights, top shelf', ARRAY['The purchase glows but is hard to reach', 'The entire sky is on the top shelf again']::text[]),
  ('103-meme.webp', 'Доктор Ливси', 'Трое старинных моряков бодро шагают по деревянной палубе, а за ними будто маршируют даже бочки.', 'Доктор Ливси, доктор Ливси мем, моряки, пиратский корабль, палуба, бочки, марш', ARRAY['Так уверенно идут только те, кто не читал маршрут', 'Даже груз решил поддержать хороший настрой']::text[], 'Doctor Livesey Walk', 'Three old-fashioned sailors stride along a wooden deck while barrels seem to march behind them.', 'doctor, livesey, walk, fashioned, sailors, stride, along, wooden, deck, barrels, seem, march', ARRAY['Only people who skipped the route can walk that confidently', 'Even the cargo decided to stay upbeat']::text[]),
  ('104-abs.webp', 'Office elevator', 'Курьерша смотрит сквозь стекло лифта на этажи с разными маленькими вторниками; бумажный самолётик не хочет выходить.', 'офис лифт этажи курьерша вторник бумажный самолёт стекло работа', ARRAY['Рабочая неделя повторилась на каждом этаже', 'Письмо решило не доезжать до адресата']::text[], 'Office elevator', 'A delivery woman looks through glass walls of an elevator where every floor is a different miniature Tuesday; a paper airplane refuses to get off.', 'office, elevator, delivery, woman, looks, glass, walls, floor, different, miniature, tuesday, paper, airplane, refuses, get, off', ARRAY['The workweek repeated on every floor', 'The letter refused to reach its recipient']::text[]),
  ('104-card.webp', 'Окно в подводный мир', 'Среди зелёного луга стоит круглое зеркало-портал, за которым виден голубой океан с кораллами и морскими существами.', 'круглый портал, зеркало, подводный мир, океан, кораллы, луг, черепаха', ARRAY['Прогулка по лугу внезапно потребовала ласты', 'По ту сторону стекла погода совсем другая']::text[], 'Window into the Underwater World', 'A round mirror portal stands in a green meadow and opens onto a blue ocean full of coral and sea creatures.', 'mirror portal, meadow, ocean, coral, sea creatures, round window', ARRAY['A stroll through the meadow suddenly called for flippers', 'The weather is different on the other side of the glass']::text[]),
  ('104-cos.webp', 'Луна играет в прятки', 'Космический ребёнок закрывает глаза, а луна прячется за крошечным астероидом, откуда виден её огромный светящийся край.', 'Луна, космический ребёнок, прятки, астероид, светящийся край, игра', ARRAY['Спрятаться за маленьким камнем было смелой идеей', 'Подсказка видна даже с другой стороны неба']::text[], 'Moon Plays Hide-and-Seek', 'A space child shuts their eyes while the moon hides behind a tiny asteroid with its bright edge still showing.', 'space child, moon, hide and seek, asteroid, glowing edge', ARRAY['Hiding behind that pebble was a bold idea', 'The clue can be seen from across the sky']::text[]),
  ('104-meme.webp', 'Жадный краб', 'Красный краб обнимает кассовый аппарат на троне посреди дворца, заваленного золотыми монетами.', 'Mr Krabs, мистер Крабс, жадный краб, касса, золото, монеты, деньги', ARRAY['Любовь всей жизни умеет выдавать чек', 'Когда депозиту построили личный дворец']::text[], 'Mr. Krabs', 'A red crab hugs a cash register on a throne in a palace filled with gold coins.', 'krabs, red, crab, hugs, cash, register, throne, palace, filled, gold, coins', ARRAY['The love of his life prints receipts', 'He built a private palace for the deposit']::text[]),
  ('105-abs.webp', 'Bench committee of lost gloves', 'На парковой лавке потерянные перчатки устроили собрание и обвиняют дворника в пропаже варежки.', 'парк лавка перчатки варежка дворник потерянные вещи собрание осень', ARRAY['Потерянные вещи начали расследование', 'На скамейке не хватает одного свидетеля']::text[], 'Bench committee of lost gloves', 'Lost gloves accuse a street cleaner of a missing mitten.', 'bench, committee, lost, gloves, accuse, street, cleaner, missing, mitten', ARRAY['The lost things started their own investigation', 'One witness is missing from the bench']::text[]),
  ('105-card.webp', 'Замок на обеденном столе', 'За красным праздничным столом стоят тарелка с миниатюрным замком и странные гости в синем готическом зале.', 'миниатюрный замок, тарелка, красная скатерть, готический зал, гости, пир', ARRAY['Королевство подали с гарниром', 'Официант предупреждал не трогать башни']::text[], 'Castle on the Dinner Table', 'A plate holding a miniature castle sits on a red banquet table among strange guests in a blue Gothic hall.', 'miniature castle, dinner table, plate, banquet, Gothic hall, guests', ARRAY['The kingdom came with a side dish', 'The waiter warned us not to touch the towers']::text[]),
  ('105-cos.webp', 'Велосипед для чёрной дыры', 'Изобретатель-робот прикручивает педали к чёрной дыре, которая уже уехала вместе с мастерской.', 'робот-изобретатель, велосипед, педали, чёрная дыра, мастерская, космос', ARRAY['Пока собирали транспорт, он уехал вместе с гаражом', 'Тормоза забыли поставить до начала эксперимента']::text[], 'Black Hole Bicycle', 'A robot inventor attaches pedals to a black hole that already rode away with the workshop.', 'robot inventor, black hole, pedals, workshop, bicycle', ARRAY['The vehicle left with the garage before it was finished', 'They forgot the brakes before starting the experiment']::text[]),
  ('105-meme.webp', 'Popcorn Reaction', 'Поп-звезда в красной кожаной куртке с предвкушением ест попкорн в тёмном кинотеатре.', 'Michael Jackson Popcorn, Майкл Джексон с попкорном, попкорн, кино, реакция, красная куртка', ARRAY['Скандал только начался, а закуска уже готова', 'Когда чужой спор лучше любого фильма']::text[], 'Michael Jackson Popcorn', 'A pop star in a red leather jacket eagerly eats popcorn in a dark movie theater.', 'michael, jackson, popcorn, pop, star, red, leather, jacket, eagerly, eats, dark, movie, theater', ARRAY['The scandal has just begun and the snack is ready', 'Someone else''s argument beats any movie']::text[]),
  ('106-abs.webp', 'Vegetable stall', 'Продавец на овощном рынке спорит с огромной луковицей в очках, требующей место в первом ряду прилавка.', 'рынок овощи лук луковица очки продавец прилавок спор морковь', ARRAY['Из-за места на витрине скоро заплачут все', 'Покупатель оказался меньше товара']::text[], 'Vegetable stall', 'A vegetable seller negotiates with a stubborn enormous onion that wears reading glasses and demands a place in the front row.', 'vegetable, stall, seller, negotiates, stubborn, onion, wears, reading, glasses, demands, place, front, row', ARRAY['Everyone will cry over this place in the display', 'The customer is smaller than the product']::text[]),
  ('106-card.webp', 'Девушка и стеклянный волк', 'Девушка в зелёном платье протягивает руки к прозрачному волку, внутри которого виден заснеженный лес.', 'девушка, стеклянный волк, прозрачное тело, зимний лес внутри, снег, миска', ARRAY['Он прозрачный, но его намерения ещё загадка', 'Зима нашла себе четыре лапы']::text[], 'Girl and Glass Wolf', 'A girl in a green dress reaches toward a transparent wolf with a snowy forest visible inside it.', 'girl, green dress, transparent wolf, glass wolf, snowy forest', ARRAY['You can see through him, but not his intentions', 'Winter has found itself four paws']::text[]),
  ('106-cos.webp', 'Робот-экскурсовод', 'Робот-гид показывает туристам одну и ту же планету с разных сторон, но каждый раз уверенно называет её новой.', 'робот-экскурсовод, туристы, планета с разных сторон, экран, космическая экскурсия', ARRAY['Пятый новый мир слишком похож на первый', 'Гид увереннее карты, хотя маршрут идёт по кругу']::text[], 'Robot Tour Guide''s Same Planet', 'A robot guide shows tourists the same planet from several sides and confidently calls it a new world each time.', 'robot guide, tourists, planet, tour, orbit', ARRAY['The fifth new world looked strangely like the first', 'The guide trusted himself more than the map']::text[]),
  ('106-meme.webp', 'Anakin Padme Four Panels', 'Четыре кадра показывают, как рыцарь уверенно говорит принцессе, она сначала улыбается, потом настораживается, а он замолкает.', 'Anakin Padme Four Panels, Энакин и Падме, четыре кадра, рыцарь, принцесса, улыбка, тревога', ARRAY['Улыбка исчезала с каждой секундой объяснения', 'Когда тишина ответила хуже любых слов']::text[], 'Anakin and Padme Four Panels', 'Four panels show a knight speaking to a princess; she smiles, grows worried, and he falls silent.', 'anakin, padme, four, panels, show, knight, speaking, princess, smiles, grows, worried, falls, silent', ARRAY['Her smile faded with each second of explanation', 'The silence answered worse than any words']::text[]),
  ('107-abs.webp', 'Car mechanic', 'Автомеханик открыл капот красной машины и обнаружил внутри уютную крошечную гостиную с мебелью; хозяин стучится снаружи.', 'машина автомобиль капот двигатель механик гостиная мебель дом красное авто ремонт', ARRAY['У двигателя появились домашние обязанности', 'Ремонт пришлось согласовывать с жильцами']::text[], 'Car mechanic', 'A mechanic opens a car hood and finds a tiny neatly furnished living room in the engine bay; the car''s owner knocks politely.', 'car, mechanic, opens, hood, finds, neatly, furnished, living, room, engine, bay, owner, knocks, politely', ARRAY['The engine has household duties now', 'The repairs needed approval from the tenants']::text[]),
  ('107-card.webp', 'Живое солнце над руинами', 'Улыбающееся огромное солнце сияет над мрачными руинами, а внизу сидит белый кролик.', 'улыбающееся солнце, руины, тёмный город, белый кролик, свет, небо', ARRAY['Даже конец света сегодня выглядит слишком бодрым', 'Кто-то забыл сказать утру, что город спит']::text[], 'Living Sun Above the Ruins', 'A huge smiling sun shines above gloomy ruins while a white rabbit sits below.', 'smiling sun, ruins, white rabbit, morning, sunlight', ARRAY['Even the end of the world looks far too cheerful today', 'Someone forgot to tell morning that the city was asleep']::text[]),
  ('107-cos.webp', 'Космическая сова-пилот', 'Сова в лётных очках ведёт маленький корабль лапами, карта маршрута приклеена к её крылу.', 'сова-пилот, лётные очки, маленький корабль, крыло, карта маршрута, космос', ARRAY['Ночной рейс ведёт лучший специалист по темноте', 'Маршрут приклеили туда, где его трудно потерять']::text[], 'Owl Pilots a Spaceship', 'An owl in flight goggles pilots a small spaceship with its feet and keeps the route map attached to a wing.', 'owl, flight goggles, spaceship, map, wing, night', ARRAY['The night flight has the best expert in darkness', 'They pinned the route where it could not get lost']::text[]),
  ('107-meme.webp', 'Jerry Smug', 'Маленькая коричневая мышь стоит с самодовольной улыбкой и руками в боки перед огромной ловушкой для кота.', 'Jerry Smug, самодовольный Джерри, мышь, ловушка, кот, улыбка, хитрость', ARRAY['План сработал ещё до появления противника', 'Когда маленький размер не мешает большим амбициям']::text[], 'Smug Jerry', 'A little brown mouse grins with hands on hips before a huge trap meant for a cat.', 'smug, jerry, brown, mouse, grins, hands, hips, before, huge, trap, meant, cat', ARRAY['The plan worked before the opponent arrived', 'Small size did not stop a big ambition']::text[]),
  ('108-abs.webp', 'Public fountain coin', 'Ребёнок бросает монету в фонтан, а из воды поднимается лестница желаний с маленькими бытовыми предметами.', 'фонтан монета желание ребёнок вода лестница вещи парк', ARRAY['Одной мелочи хватило на целую очередь чудес', 'Просьба вылезла из воды с полезными вещами']::text[], 'Public fountain coin', 'A child drops one coin into a fountain, and a little staircase of wishes climbs out, each carrying an absurd practical household object.', 'public, fountain, coin, child, drops, staircase, wishes, climbs, carrying, absurd, practical, household, object', ARRAY['One small coin bought a queue of miracles', 'The wish climbed out with useful little things']::text[]),
  ('108-card.webp', 'Рыбак у бесконечной лестницы', 'Тёмный рыбак стоит по колено в воде с удочкой перед каменной лестницей, уходящей спиралью в облака.', 'рыбак, удочка, вода, каменная лестница, облака, спираль, руины', ARRAY['Он так долго ждал клёва, что дорога выросла вверх', 'Здесь можно поймать ответ или подняться за ним']::text[], 'Fisherman at the Endless Staircase', 'A dark fisherman stands knee-deep in water with a fishing rod before a stone staircase spiraling into the clouds.', 'fisherman, fishing rod, water, stone staircase, spiral, clouds', ARRAY['He waited so long for a bite that the road grew upward', 'Catch the answer here or climb up to find it']::text[]),
  ('108-cos.webp', 'Планетная почта без адреса', 'Курьер держит письмо без адреса, а вокруг него десятки планет протягивают одинаковые почтовые ящики.', 'курьер, письмо без адреса, десятки планет, одинаковые почтовые ящики, космическая почта', ARRAY['Кому-то очень нужно письмо, но неизвестно кому', 'Все соседи уверяют, что это точно им']::text[], 'Letter Without an Address', 'A courier holds an unaddressed letter as dozens of planets extend identical mailboxes toward it.', 'courier, letter, planets, mailboxes, missing address', ARRAY['Someone urgently needs the letter, but who?', 'Every neighbor insists it must be theirs']::text[]),
  ('108-meme.webp', 'Duolingo Owl', 'Зелёная сова с огромными глазами и подозрительно дружелюбной улыбкой стоит на пороге с напоминанием об уроках.', 'Duolingo Owl, сова Дуолинго, зелёная сова, урок языка, дверь, уведомление', ARRAY['Пропустил один урок — получил личный визит', 'Самый вежливый кошмар твоего расписания']::text[], 'Duolingo Owl', 'A green owl with huge eyes and a suspiciously friendly smile appears at the door to remind you about lessons.', 'duolingo, owl, green, huge, eyes, suspiciously, friendly, smile, appears, door, remind, you, about, lessons', ARRAY['Missed one lesson and got a personal visit', 'The politest nightmare on your schedule']::text[]),
  ('109-abs.webp', 'Morning newspaper', 'Пенсионер разворачивает газету за завтраком, и из складок встаёт целый город с башнями; тост сползает со стола.', 'газета новости пенсионер завтрак город здания башни бумага тост стол', ARRAY['Утренние новости выросли до размеров улицы', 'Завтрак не выдержал такого масштаба']::text[], 'Morning newspaper', 'A pensioner unfolds the newspaper and an entire foldable city block rises from it, causing his breakfast toast to slide downhill.', 'morning, newspaper, pensioner, unfolds, entire, foldable, city, block, rises, causing, breakfast, toast, slide, downhill', ARRAY['The morning news grew into a whole street', 'Breakfast could not withstand the scale']::text[]),
  ('109-card.webp', 'Замок под лоскутным одеялом', 'Каменный замок с жёлтыми окнами укрыт большим узорчатым одеялом, а рядом дремлет тёмный дракон.', 'замок, узорчатое одеяло, дракон, ночь, светящиеся окна, сон', ARRAY['Даже крепости иногда мёрзнут по ночам', 'Охранник наконец разрешил всем поспать']::text[], 'Castle Beneath a Patchwork Quilt', 'A stone castle with yellow windows hides under a large patterned quilt while a dark dragon dozes nearby.', 'castle, quilt, blanket, yellow windows, sleeping dragon, night', ARRAY['Even fortresses get cold at night', 'The guard finally let everyone sleep']::text[]),
  ('109-cos.webp', 'Галактика на скейтборде', 'Подросток-пришелец катается на скейтборде по плоской спиральной галактике, звёзды вылетают как искры из-под колёс.', 'подросток-пришелец, скейтборд, спиральная галактика, звёзды, искры, космос', ARRAY['Разогнался так, что дорожка стала бесконечной', 'После трюка пришлось собирать свет за собой']::text[], 'Skateboard Across the Galaxy', 'An alien teenager skates along a flat spiral galaxy as stars spark from beneath the wheels.', 'alien teenager, skateboard, spiral galaxy, stars, sparks', ARRAY['He sped up until the track became endless', 'After the trick they had to collect the light']::text[]),
  ('109-meme.webp', 'Tuxedo Winnie Pooh', 'Плюшевый медведь смотрит в зеркала на две версии себя: простую с мёдом и нарядную в смокинге.', 'Tuxedo Winnie Pooh, Винни Пух в смокинге, медведь, мёд, зеркало, костюм, элегантность', ARRAY['То же самое, только с английским акцентом', 'Когда обычный перекус получил новое название']::text[], 'Tuxedo Winnie-the-Pooh', 'A teddy bear sees two versions of himself in mirrors: one holding honey and one in a tuxedo.', 'tuxedo, winnie, pooh, teddy, bear, sees, versions, himself, mirrors, holding, honey', ARRAY['The same thing, just with a posher name', 'An ordinary snack got a rebrand']::text[]),
  ('110-abs.webp', 'Night bus depot', 'Ночной уборщик подметает депо, а карта маршрута сбежала со стены и обвилась вокруг спящего автобуса шарфом.', 'автобус депо ночь уборщик метла маршрут карта шарф общественный транспорт', ARRAY['Последний рейс укутали до утра', 'Расписание решило поспать вместе с машиной']::text[], 'Night bus depot', 'A cleaner sweeps a bus parked for the night; the route map has escaped the wall and winds around the bus like a sleeping scarf.', 'night, bus, depot, cleaner, sweeps, parked, route, map, has, escaped, wall, winds, sleeping, scarf', ARRAY['The last service was tucked in until morning', 'The timetable decided to sleep with the bus']::text[]),
  ('110-card.webp', 'Олень из зеркала', 'Светящийся белый олень выходит из высокого зеркала среди тёмного леса, а рядом стоит путешественник.', 'белый олень, зеркало, портал, лес, путешественник, рога, отражение', ARRAY['Отражение первым решилось сделать шаг', 'В этой чаще выход находится по ту сторону']::text[], 'Deer from the Mirror', 'A glowing white deer steps out of a tall mirror in a dark forest beside a traveler.', 'white deer, mirror, glowing antlers, dark forest, traveler', ARRAY['The reflection was the first to take a step', 'In these woods the exit lies on the other side']::text[]),
  ('110-cos.webp', 'Усатый спутник', 'Маленький спутник Земли отрастил густые усы и расчесывает их антенной, пока космонавты делают серьёзные записи.', 'усатый спутник, Луна, Земля, антенна как расчёска, космонавты, записи, усы', ARRAY['Возраст солидный, уход за внешностью строгий', 'Наблюдатели записали новую странность и промолчали']::text[], 'Mustached Moon', 'A tiny satellite of Earth grows a thick mustache and combs it with an antenna while astronauts take serious notes.', 'Earth moon, satellite, mustache, antenna, astronauts', ARRAY['An impressive age calls for impressive grooming', 'The observers recorded another oddity and said nothing']::text[]),
  ('110-meme.webp', 'Pikachu Surprise Reimagined', 'Маленький жёлтый зверёк с круглыми глазами изумлённо смотрит на городские фонари, которые зажглись после его кнопки.', 'Surprised Pikachu, удивлённый Пикачу, жёлтый зверёк, фонари, кнопка, удивление', ARRAY['Нажал посмотреть что будет — и действительно было', 'Когда последствия собственных действий застали врасплох']::text[], 'Surprised Pikachu', 'A small yellow creature stares at city lights that switched on after it pressed a button.', 'surprised, pikachu, yellow, creature, stares, city, lights, switched, after, pressed, button', ARRAY['Pressed it to see what would happen; something happened', 'Surprised by the consequences of his own action']::text[]),
  ('111-card.webp', 'Трон огромного мотылька', 'Человек в плаще стоит перед каменным троном, где восседает огромный белый мотылёк с раскинутыми крыльями.', 'гигантский мотылёк, трон, крылья, человек в плаще, каменный зал', ARRAY['Корону забыли, зато плащ виден издалека', 'На аудиенцию сегодня лучше не брать свечу']::text[], 'Throne of the Giant Moth', 'A cloaked person stands before a stone throne occupied by an enormous white moth with outstretched wings.', 'giant moth, stone throne, cloaked person, white wings, audience', ARRAY['They forgot the crown, but the cloak can be seen for miles', 'Best not bring a candle to this audience']::text[]),
  ('112-card.webp', 'Лиса на небесной лестнице', 'Рыжая лиса поднимается по светящейся голубой лестнице к золотому замку на вершине скалы среди грозовых облаков.', 'рыжая лиса, светящаяся лестница, замок, скала, грозовые облака, молния', ARRAY['К вершине ведёт дорога только для самых хитрых', 'Последняя ступень обещает больше, чем первая']::text[], 'Fox on the Stairway to the Sky', 'A red fox climbs a glowing blue staircase toward a golden castle on a cliff amid storm clouds.', 'red fox, blue staircase, golden castle, cliff, storm clouds', ARRAY['Only the cleverest find the road to the top', 'The last step promises more than the first']::text[]),
  ('201-pop.webp', 'Матрица', 'Две ладони предлагают красную и синюю таблетки; из красной выплывает крошечный пассажир в плаще по зелёному цифровому дождю.', 'Матрица Нео Морфеус красная таблетка синяя таблетка выбор ладони капсулы код зелёные цифры плащ', ARRAY['У этой аптечки есть побочный эффект — правда', 'Инструкция по выходу из привычного мира не прилагается']::text[], 'The Matrix', 'Two hands offer red and blue pills; a tiny coated passenger sails from the red one through green digital rain.', 'matrix, hands, offer, red, blue, pills, coated, passenger, sails, green, digital, rain', ARRAY['This medicine has truth as a side effect', 'No instructions for leaving the familiar world']::text[]),
  ('202-pop.webp', 'Шоу Трумана', 'Крошечный человек поднимается по белой лестнице из моря и отгибает нарисованное небо, за которым наблюдает огромный глаз.', 'Шоу Трумана Труман лестница море небо обои глаз камера наблюдение декорация свобода', ARRAY['Когда небосвод оказался декорацией', 'За кулисами даже облака следят за тобой']::text[], 'The Truman Show', 'A tiny man climbs white stairs from the sea and peels back a painted sky beneath a giant watching eye.', 'truman, show, man, climbs, white, stairs, sea, peels, back, painted, sky, beneath, watching, eye', ARRAY['The sky turned out to be scenery', 'Even the clouds are watching backstage']::text[]),
  ('203-pop.webp', 'Во все тяжкие', 'Огромная пицца лежит на крыше дома словно солнце; внизу сердитый лысый мужчина с коробкой смотрит наверх.', 'Во все тяжкие Breaking Bad Уолтер Уайт Хайзенберг пицца крыша дом лысый мужчина очки коробка', ARRAY['Ужин поднялся по карьерной лестнице выше хозяина', 'Домашний конфликт теперь видно из космоса']::text[], 'Breaking Bad', 'A huge pizza lies on a house roof like the sun while an angry bald man with a box stares up from below.', 'breaking, bad, huge, pizza, lies, house, roof, sun, angry, bald, man, box, stares', ARRAY['Dinner climbed higher than its owner', 'The family argument is visible from space now']::text[]),
  ('204-pop.webp', 'Унесённые призраками', 'Безликий в затопленном вагоне держит золотой самородок; в отражении золото превращается в маленькую светящуюся рыбу.', 'Унесённые призраками Безликий Каонаси поезд вагон вода золото самородок рыба дух', ARRAY['Покупать дружбу здесь бесполезно', 'Самое дорогое уплыло без билета']::text[], 'Spirited Away', 'A faceless spirit holds a gold nugget in a flooded train while its reflection becomes a glowing fish.', 'spirited, away, faceless, spirit, holds, gold, nugget, flooded, train, reflection, becomes, glowing, fish', ARRAY['Friendship cannot be bought at this station', 'The most precious thing swam off without a ticket']::text[]),
  ('205-pop.webp', 'Мой сосед Тоторо', 'Большой лесной дух прячется под листом, но маленькая туча льёт дождь прямо под его укрытием; рядом сухая девочка с зонтом.', 'Мой сосед Тоторо Тоторо лесной дух девочка дождь туча лист зонт жёлтые сапоги', ARRAY['Когда укрытие устроило персональный ливень', 'Прогноз погоды оказался слишком адресным']::text[], 'My Neighbor Totoro', 'A large forest spirit shelters under a leaf as a small cloud rains directly on it while a dry girl stands nearby with an umbrella.', 'neighbor, totoro, forest, spirit, shelters, leaf, cloud, rains, directly, dry, girl, stands, nearby, umbrella', ARRAY['The shelter brought its own private shower', 'The forecast was far too personal']::text[]),
  ('206-pop.webp', 'Начало', 'Складчатый город изгибается огромной лестницей в небе; крошечный человек падает с его края, а наверху балансирует волчок.', 'Начало Inception Кобб сон волчок складной город лестница небоскрёбы падение', ARRAY['Архитектору пора проснуться до сдачи проекта', 'Рабочий день сложился в несколько этажей сна']::text[], 'Inception', 'A folded city bends into a staircase in the sky as a tiny man falls from it and a spinning top balances above.', 'inception, folded, city, bends, staircase, sky, man, falls, spinning, top, balances', ARRAY['The architect must wake before the deadline', 'The workday folded into several floors of sleep']::text[]),
  ('207-pop.webp', 'Игра престолов', 'Крошечный король сидит на тающем розовом троне из мечей, пока дракон снизу подогревает его пламенем.', 'Игра престолов железный трон король корона мечи дракон огонь розовое мороженое власть', ARRAY['Тронный зал внезапно попросили убрать в морозилку', 'Корону получил тот, кто первым доел власть']::text[], 'Game of Thrones', 'A tiny king sits on a melting pink sword throne while a dragon heats it from below.', 'game, thrones, king, sits, melting, pink, sword, throne, dragon, heats', ARRAY['The throne room needs to go in the freezer', 'The crown went to whoever ate power first']::text[]),
  ('208-pop.webp', 'Игра в кальмара', 'Огромная круглая сахарная печенька удерживает внутри куклу, а маленькая участница на краю освобождает её иглой.', 'Игра в кальмара Squid Game кукла Ёнхи печенье дальгона игла участница круг игра', ARRAY['Инспектор правил сам попал в испытание', 'Когда сладкое наказание поменялось местами с судьёй']::text[], 'Squid Game', 'A giant round sugar cookie holds a doll captive while a small player works to free it with a needle.', 'squid, game, round, sugar, cookie, holds, doll, captive, player, works, free, needle', ARRAY['The referee got trapped in the game', 'A sweet punishment switched places with its judge']::text[]),
  ('209-pop.webp', 'Тетрадь смерти', 'Мрачный длиннорукий бог смерти тянется к гигантскому красному яблоку и нервно запутывает собственные руки.', 'Тетрадь смерти Death Note Рюк синигами бог смерти яблоко красное тетрадь длинные руки', ARRAY['Бессмертие бессильно перед перекусом', 'Самый страшный в комнате боится остаться без десерта']::text[], 'Death Note', 'A long-armed dark god of death reaches for a giant red apple and tangles its own arms.', 'death, note, long, armed, dark, god, reaches, red, apple, tangles, arms', ARRAY['Immortality is no match for snack time', 'The scariest guest fears losing dessert']::text[]),
  ('210-pop.webp', 'Ван-Пис', 'Резиновый пират в соломенной шляпе растянулся над морем, где маленький корабль попал в огромную петлю приключений.', 'Ван-Пис One Piece Луффи пират соломенная шляпа красная лента корабль море волна резиновые руки', ARRAY['Отпуск растянулся дальше горизонта', 'Капитан прихватил приключение за край']::text[], 'One Piece', 'A rubber pirate in a straw hat stretches across the sea while a small ship enters a giant loop of adventure.', 'piece, rubber, pirate, straw, hat, stretches, sea, ship, enters, loop, adventure', ARRAY['The vacation stretched past the horizon', 'The captain grabbed adventure by its edge']::text[]),
  ('211-pop.webp', 'Титаник', 'Маленький корабль с парой на носу плывёт над огромным айсбергом, а под водой океан превращён в танцевальный зал.', 'Титаник Titanic Джек Роза корабль пароход нос айсберг океан пара танец', ARRAY['Свидание забронировали прямо у ледяного соседа', 'Романтика опять не заметила препятствия']::text[], 'Titanic', 'A small ship with a couple on its bow sails above a huge iceberg while the sea below becomes a ballroom.', 'titanic, ship, couple, bow, sails, huge, iceberg, sea, becomes, ballroom', ARRAY['The date was booked beside an icy neighbor', 'Romance missed the obstacle again']::text[]),
  ('212-pop.webp', 'Парк юрского периода', 'Тираннозавр в балетных туфельках нервно пробирается мимо стакана воды среди джунглей; вдали ворота парка.', 'Парк юрского периода Jurassic Park тираннозавр динозавр балет пуанты стакан вода джунгли ворота', ARRAY['Крупнейший артист боится наступить мимо сцены', 'Тихий шаг весом в несколько тонн']::text[], 'Jurassic Park', 'A tyrannosaur in ballet shoes tiptoes past a glass of water in a jungle near the park gates.', 'jurassic, park, tyrannosaur, ballet, shoes, tiptoes, past, glass, water, jungle, gates', ARRAY['The largest performer fears missing the stage', 'A quiet step weighing several tons']::text[]),
  ('213-pop.webp', 'Друзья', 'Трое друзей пытаются протащить запутавшийся оранжевый диван по невозможной лестнице; на стене стоит чашка кофе.', 'Друзья Friends Росс Рэйчел Чендлер диван лестница переезд трое друзей кофе квартира', ARRAY['Переезд проверил дружбу на прочность', 'Главное — поворачивать, даже если лестница против']::text[], 'Friends', 'Three friends struggle to move a tangled orange couch up an impossible staircase beside a cup of coffee.', 'friends, struggle, move, tangled, orange, couch, impossible, staircase, cup, coffee', ARRAY['Moving house put friendship to the test', 'Keep turning, even if the stairs disagree']::text[]),
  ('214-pop.webp', 'Очень странные дела', 'Девочка с вафлей смотрит на чудовище, опутанное праздничными огнями, у разлома между обычной комнатой и тёмным лесом.', 'Очень странные дела Stranger Things Одиннадцать Демогоргон Изнанка девочка вафля монстр гирлянда разлом лес', ARRAY['Праздничный декор завёлся с другой стороны стены', 'Гости пришли на вафли через неправильную дверь']::text[], 'Stranger Things', 'A girl with a waffle faces a monster wrapped in festive lights near a rift between a room and dark forest.', 'stranger, things, girl, waffle, faces, monster, wrapped, festive, lights, rift, room, dark, forest', ARRAY['The decorations came alive on the other side', 'The guests came for waffles through the wrong door']::text[]),
  ('215-pop.webp', 'Наруто', 'Ниндзя и его копии выясняют отношения в огромной миске рамена; рыбная лепёшка плавает как спасательный круг.', 'Наруто Naruto ниндзя клоны рамен лапша миска рыбная лепёшка Коноха оранжевая одежда', ARRAY['Размножил проблему, а обед остался один', 'План спасения утонул в горячем бульоне']::text[], 'Naruto', 'A ninja and his clones bicker in a huge bowl of ramen as a fish cake floats like a lifebuoy.', 'naruto, ninja, clones, bicker, huge, bowl, ramen, fish, cake, floats, lifebuoy', ARRAY['He multiplied the problem, not the lunch', 'The rescue plan drowned in hot broth']::text[]),
  ('216-pop.webp', 'Назад в будущее', 'Серебристая машина мчится по огромным часам среди молний, пока взъерошенный изобретатель пытается завести их ключом.', 'Назад в будущее Back to the Future Марти Док Делориан DeLorean машина времени часы молния башня ключ', ARRAY['Опоздать вчера оказалось технически возможно', 'Механик чинит расписание ударом молнии']::text[], 'Back to the Future', 'A silver car races across a huge clock amid lightning while a wild-haired inventor tries to wind it.', 'back, future, silver, car, races, huge, clock, amid, lightning, wild, haired, inventor, tries, wind, delorean', ARRAY['Being late yesterday became technically possible', 'The mechanic fixes the schedule with lightning']::text[]),
  ('217-pop.webp', 'Пираты Карибского моря', 'Пират балансирует в утлой лодке, а щупальца кракена вежливо протягивают ему розовый надувной круг.', 'Пираты Карибского моря Джек Воробей пират лодка море кракен щупальца надувной круг утка корабль', ARRAY['Морское чудовище предложило страховку', 'Капитан держит лицо, пока помощь выглядит нелепо']::text[], 'Pirates of the Caribbean', 'A pirate balances in a tiny boat as a kraken politely offers a pink inflatable ring.', 'pirates, caribbean, pirate, balances, boat, kraken, politely, offers, pink, inflatable, ring', ARRAY['The sea monster offered insurance', 'The captain keeps his dignity while rescue looks ridiculous']::text[]),
  ('218-pop.webp', 'Гарри Поттер', 'Огромный чемодан заглатывает красный поезд, а возмущённая белая сова пытается захлопнуть крышку на вокзале.', 'Гарри Поттер Хогвартс Хогвартс-экспресс поезд чемодан сова Букля вокзал магия', ARRAY['Сборы в школу вышли за пределы багажа', 'Даже сова не подписывалась на такой переезд']::text[], 'Harry Potter', 'A huge suitcase swallows a red train while an indignant white owl tries to shut it at the station.', 'harry, potter, huge, suitcase, swallows, red, train, indignant, white, owl, tries, shut, station', ARRAY['Packing for school exceeded the baggage allowance', 'Even the owl did not agree to this move']::text[]),
  ('219-pop.webp', 'Властелин колец', 'Огромное золотое кольцо парит перед искривлённой тёмной башней с огненным глазом; маленький вулкан льёт лаву.', 'Властелин колец Lord of the Rings Саурон кольцо всевластия глаз башня Барад-дур Мордор Роковая гора вулкан лава', ARRAY['Ювелирное изделие требует слишком много внимания', 'Контроль качества ведётся одним большим глазом']::text[], 'The Lord of the Rings', 'A huge gold ring floats before a twisted dark tower with a fiery eye and a small lava-spewing volcano.', 'lord, rings, huge, gold, ring, floats, before, twisted, dark, tower, fiery, eye, lava, spewing, volcano', ARRAY['One piece of jewelry demands far too much attention', 'Quality control is done by one enormous eye']::text[]),
  ('220-pop.webp', 'Уэнсдей', 'Девушка в чёрном танцует на клетчатом полу, а её тень превращается в самостоятельную руку с красным ботинком.', 'Уэнсдей Wednesday Аддамс Вещь танец чёрное платье косички рука тень дискотека клетчатый пол', ARRAY['Тень решила танцевать лучше хозяйки', 'У этой вечеринки слишком самостоятельные конечности']::text[], 'Wednesday', 'A girl in black dances on a checkered floor as her shadow becomes an independent hand with a red shoe.', 'wednesday, girl, black, dances, checkered, floor, shadow, becomes, independent, hand, red, shoe', ARRAY['The shadow decided it dances better than its owner', 'This party has remarkably independent limbs']::text[]),
  ('221-pop.webp', 'Доктор Кто', 'Путешественник обнимает гигантскую планету с кольцами в огромном космическом зале за дверью синей будки; снаружи мокрый переулок.', 'Доктор Кто Doctor Who ТАРДИС синяя будка путешественник планета кольца космос консоль дождь переулок', ARRAY['Снаружи помещается зонт, внутри — вся галактика', 'Уборка дома заняла целую вселенную']::text[], 'Doctor Who', 'A traveler embraces a giant ringed planet in a vast space hall behind a blue police box door on a wet alley.', 'doctor, traveler, embraces, ringed, planet, vast, space, hall, blue, police, box, door, wet, alley', ARRAY['Outside there is room for an umbrella; inside, a galaxy', 'Cleaning this house took an entire universe']::text[]),
  ('222-pop.webp', 'Сейлор Мун', 'Девушка с длинными золотыми хвостами запуталась в лентах, а чёрная кошка держит их огромной прищепкой в форме луны над городом.', 'Сейлор Мун Sailor Moon Усаги Луна кошка волшебница лунный серп прищепка золотые хвосты ленты планеты', ARRAY['Магическое превращение отправили сушиться', 'Даже небесным телам нужен день большой стирки']::text[], 'Sailor Moon', 'A girl with long golden pigtails tangles in ribbons as a black cat holds them with a moon-shaped clothespin.', 'sailor, moon, girl, long, golden, pigtails, tangles, ribbons, black, cat, holds, shaped, clothespin', ARRAY['The magical transformation went out to dry', 'Even heavenly bodies need laundry day']::text[]),
  ('223-pop.webp', 'Атака титанов', 'Огромный титан неловко убирает пыль у стены и маленьких домиков, пока крошечный разведчик сердится на крыше.', 'Атака титанов Attack on Titan титан великан разведчик плащ стена дома крыша пыль уборка', ARRAY['Генеральная уборка переросла хозяина', 'Когда сосед чихнул — пришлось перестраивать район']::text[], 'Attack on Titan', 'A huge titan awkwardly dusts a wall and tiny houses while a small scout fumes on a roof.', 'attack, titan, huge, awkwardly, dusts, wall, houses, scout, fumes, roof', ARRAY['Spring cleaning outgrew the owner', 'One sneeze from the neighbor meant rebuilding the district']::text[]),
  ('224-pop.webp', 'Ходячий замок', 'Пёстрый замок на ножках в розовых тапках отказывается идти, а маленький огненный демон подталкивает его мехами на холме.', 'Ходячий замок Howl''s Moving Castle Хаул Кальцифер замок ножки розовые тапки огненный демон холмы трубы', ARRAY['Дом прогуливает собственную прогулку', 'Тренер по кардио оказался размером с искру']::text[], 'Howl''s Moving Castle', 'A colorful walking castle in pink slippers refuses to move while a tiny fire demon pushes it uphill with bellows.', 'howl, moving, castle, colorful, walking, pink, slippers, refuses, move, fire, demon, pushes, uphill, bellows, spirited', ARRAY['The house is skipping its own walk', 'The fitness coach is the size of a spark']::text[]),
  ('225-pop.webp', 'Ванпанчмен', 'Лысый герой с белым плащом скучающе держит корзинку с яйцами и чек, пока гигантская капуста раздвигает дома.', 'Ванпанчмен One Punch Man Сайтама лысый супергерой белый плащ капуста корзина яйца магазин чек', ARRAY['Сверхсила бессильна перед списком покупок', 'Главная битва недели случилась в овощном отделе']::text[], 'One-Punch Man', 'A bored bald hero carries eggs and a receipt while a giant cabbage pushes buildings apart.', 'punch, man, bored, bald, hero, carries, eggs, receipt, cabbage, pushes, buildings, apart', ARRAY['Superpowers cannot defeat the shopping list', 'This week''s main battle happened in the vegetable aisle']::text[]),
  ('226-pop.webp', 'ВАЛЛ-И', 'Маленький жёлтый робот поливает растение, которое держит на себе тяжёлую Землю; за ним башни мусора и белый летающий робот.', 'ВАЛЛ-И WALL-E ЕВА робот Земля планета растение росток лейка мусор башни', ARRAY['Садоводство стало планетарной обязанностью', 'Маленькому ростку достался слишком большой горшок']::text[], 'WALL-E', 'A little yellow robot waters a plant supporting the heavy Earth among towers of rubbish and a white flying robot.', 'wall, yellow, robot, waters, plant, supporting, heavy, earth, among, towers, rubbish, white, flying', ARRAY['Gardening became a planetary duty', 'A tiny shoot got a very big pot']::text[]),
  ('227-pop.webp', 'Терминатор', 'Киборг в тёмных очках осторожно поддевает ножом тост из тостера; хлеб подскакивает с испуганной физиономией.', 'Терминатор Terminator T-800 киборг робот тёмные очки тостер тост хлеб нож кухня', ARRAY['Миссия на завтрак требует предельной точности', 'Железный человек впервые боится подгоревшего хлеба']::text[], 'The Terminator', 'A cyborg in dark glasses carefully pries toast from a toaster while the bread jumps in fright.', 'terminator, cyborg, dark, glasses, carefully, pries, toast, toaster, bread, jumps, fright', ARRAY['The breakfast mission demands extreme precision', 'The man of steel fears burnt bread for the first time']::text[]),
  ('228-pop.webp', 'Челюсти', 'Акула плывёт через море попкорна в огромном киноведре, опасаясь пляжного кресла в форме человеческих зубов.', 'Челюсти Jaws акула попкорн море ведро кинотеатр пляж зубы кресло', ARRAY['На этом сеансе хищник боится зрителей', 'Кто кого съест после титров — неясно']::text[], 'Jaws', 'A shark swims through a sea of popcorn in a giant movie bucket and fears a beach chair shaped like human teeth.', 'jaws, shark, swims, sea, popcorn, movie, bucket, fears, beach, chair, shaped, human, teeth', ARRAY['At this screening the predator fears the viewers', 'Who eats whom after the credits is unclear']::text[]),
  ('229-pop.webp', 'Чужой', 'Тёмный ксеноморф в коридоре космического корабля бережно ухаживает за цветком; хвост свернулся подставкой для горшка.', 'Чужой Alien ксеноморф космический корабль коридор цветок горшок хвост теплица планета', ARRAY['Самый нежный садовник на чужой планете', 'В космосе даже кошмар завёл комнатное растение']::text[], 'Alien', 'A dark xenomorph tends a flower in a spaceship corridor with its tail curled around the pot.', 'alien, dark, xenomorph, tends, flower, spaceship, corridor, tail, curled, pot', ARRAY['The gentlest gardener on another world', 'Even nightmares keep houseplants in space']::text[]),
  ('230-pop.webp', 'Охотники за привидениями', 'Зелёное привидение втягивает ловушка на городской улице; вдали белый зефирный великан спокойно пьёт чай.', 'Охотники за привидениями Ghostbusters Лизун Слаймер зелёный призрак ловушка зефирный человек Стей-Пафт город чай', ARRAY['Пылесос для сверхъестественного опять переполнен', 'Большой сладкий гость предпочёл чай битве']::text[], 'Ghostbusters', 'A trap sucks in a green ghost on a city street while a giant white marshmallow figure drinks tea nearby.', 'ghostbusters, trap, sucks, green, ghost, city, street, white, marshmallow, figure, drinks, tea, nearby', ARRAY['The supernatural vacuum is full again', 'The large sweet guest chose tea over battle']::text[]),
  ('231-pop.webp', 'Твин Пикс', 'Детектив у чашки кофе видит в ней извилистую дорогу к горам; сова с ложки указывает путь на фоне красных занавесей.', 'Твин Пикс Twin Peaks агент Купер детектив кофе чашка сова красная комната занавес горы лес ложка', ARRAY['Расследование утонуло в утреннем напитке', 'Птица знает дорогу, но говорить не собирается']::text[], 'Twin Peaks', 'A detective sees a winding road and mountains in his coffee cup as an owl points from a spoon before red curtains.', 'twin, peaks, detective, sees, winding, road, mountains, coffee, cup, owl, points, spoon, before, red, curtains', ARRAY['The investigation drowned in a morning drink', 'The bird knows the way and refuses to say']::text[]),
  ('232-pop.webp', 'Остаться в живых', 'Белый медведь с чемоданом выглядывает из тропического люка; в ветвях над ним застрял самолёт.', 'Остаться в живых Lost белый медведь остров джунгли люк чемодан самолёт дым', ARRAY['Отпуск потерял правильную климатическую зону', 'Багаж прибыл, объяснения — нет']::text[], 'Lost', 'A polar bear with a suitcase emerges from a tropical hatch beneath a plane caught in the trees.', 'lost, polar, bear, suitcase, emerges, tropical, hatch, beneath, plane, caught, trees', ARRAY['The holiday landed in the wrong climate zone', 'The luggage arrived; an explanation did not']::text[]),
  ('233-pop.webp', 'Покемон', 'Пикачу пытается запихнуть грозовую тучу в покебол, а молнии торчат наружу; на фоне грибы-розетки и холмы.', 'Покемон Pokémon Пикачу покебол молния электричество гроза туча грибы трава', ARRAY['Карманная погода не помещается в багаж', 'Электрик поймал больше, чем заказывали']::text[], 'Pokemon', 'Pikachu tries to squeeze a thundercloud into a Poke Ball while lightning sticks out among socket-shaped mushrooms.', 'pokemon, pikachu, tries, squeeze, thundercloud, poke, ball, lightning, sticks, among, socket, shaped, mushrooms, pok, mon', ARRAY['Pocket-sized weather does not fit in the luggage', 'The electrician caught more than requested']::text[]),
  ('234-pop.webp', 'Драконий жемчуг', 'Гоку готовит завтрак с сияющей боевой аурой; три драконьих шара лежат в тесте, будто яйца.', 'Драконий жемчуг Dragon Ball Гоку Саян драконьи шары аура завтрак блины сковорода кухня', ARRAY['Вселенская сила потребовалась ради завтрака', 'Даже тесто капитулировало перед энергией']::text[], 'Dragon Ball', 'Goku cooks breakfast with a glowing battle aura while three dragon balls sit in pancake batter like eggs.', 'dragon, ball, goku, cooks, breakfast, glowing, battle, aura, balls, sit, pancake, batter, eggs', ARRAY['Cosmic power was needed to make breakfast', 'Even the batter surrendered to the energy']::text[]),
  ('235-pop.webp', 'Ковбой Бибоп', 'Космический ковбой пытается готовить зелёный перец на двигателе корабля в тесной кухне; за окном луна как яичница.', 'Ковбой Бибоп Cowboy Bebop Спайк Шпигель космос корабль кухонная плита зелёный перец сковорода луна', ARRAY['Охота за ужином сорвалась на кухне корабля', 'Топливо нашлось, а продукты — почти нет']::text[], 'Cowboy Bebop', 'A space cowboy cooks green peppers on a ship engine in a tiny kitchen as the moon outside resembles a fried egg.', 'cowboy, bebop, space, cooks, green, peppers, ship, engine, kitchen, moon, resembles, fried, egg', ARRAY['The hunt for dinner failed in the ship''s kitchen', 'They found fuel, but almost no ingredients']::text[]),
  ('236-pop.webp', 'Интерстеллар', 'Астронавт пытается развесить носки возле чёрной дыры; робот подаёт прищепки, а книжные полки изгибаются в космос.', 'Интерстеллар Interstellar Купер ТАРС астронавт чёрная дыра носки прищепки робот книги гравитация', ARRAY['Гравитация испортила день стирки', 'Домашние дела вышли на межзвёздный уровень']::text[], 'Interstellar', 'An astronaut hangs socks beside a black hole while a robot hands over clothespins and bookshelves bend in space.', 'interstellar, astronaut, hangs, socks, black, hole, robot, hands, clothespins, bookshelves, bend, space', ARRAY['Gravity ruined laundry day', 'Household chores went interstellar']::text[]),
  ('237-pop.webp', 'Безумный Макс', 'Пустынный концертный грузовик на велосипедных колёсах несётся по песку; гитара извергает огонь, а механик крутит педали.', 'Безумный Макс Mad Max пустыня грузовик гитара огонь велосипедные колёса механик педали концерт', ARRAY['Апокалипсис держится на одном уставшем велосипедисте', 'Самый громкий концерт поехал на ручной тяге']::text[], 'Mad Max', 'A desert concert truck on bicycle wheels races across sand as a guitar spits fire and a mechanic pedals.', 'mad, max, desert, concert, truck, bicycle, wheels, races, sand, guitar, spits, fire, mechanic, pedals', ARRAY['The apocalypse depends on one exhausted cyclist', 'The loudest concert runs on human power']::text[]),
  ('238-pop.webp', 'Кунг-фу Панда', 'Большая панда тренирует боевой удар по гигантскому пельменю, пока маленький красный учитель стоит на палочках для еды.', 'Кунг-фу Панда Kung Fu Panda По Шифу панда красная панда учитель боевые искусства пельмень палочки монастырь', ARRAY['Дисциплина не выдержала запаха обеда', 'Мастерство измеряется расстоянием до перекуса']::text[], 'Kung Fu Panda', 'A large panda practices a fighting move against a giant dumpling while a little red teacher stands on chopsticks.', 'kung, panda, practices, fighting, move, against, dumpling, red, teacher, stands, chopsticks', ARRAY['Discipline could not withstand the smell of lunch', 'Mastery is measured by distance to a snack']::text[]),
  ('239-pop.webp', 'Рататуй', 'Маленький крыс-повар балансирует огромной ложкой между башней овощей и испуганным помидором; вдали парижские крыши.', 'Рататуй Ratatouille Реми крыса повар ложка овощи помидор Париж кухня Эйфелева башня', ARRAY['Шеф оказался меньше собственного гарнира', 'Вся кухня держится на одном крошечном решении']::text[], 'Ratatouille', 'A tiny rat chef balances a giant spoon between a tower of vegetables and a frightened tomato above Paris rooftops.', 'ratatouille, rat, chef, balances, spoon, tower, vegetables, frightened, tomato, paris, rooftops', ARRAY['The chef is smaller than his own garnish', 'The whole kitchen rests on one tiny decision']::text[]),
  ('240-pop.webp', 'Битлджус', 'Полосатое привидение возится с огромным червём на гладильной доске между кривыми домами; из утюга вьётся пар.', 'Битлджус Beetlejuice полосатый призрак червь полосы гладильная доска утюг пар кривые дома', ARRAY['В загробном мире опять не погладили костюм', 'Домашние хлопоты приняли чудовищный оборот']::text[], 'Beetlejuice', 'A striped ghost fusses over a giant worm on an ironing board between crooked houses as steam rises.', 'beetlejuice, striped, ghost, fusses, worm, ironing, board, crooked, houses, steam, rises', ARRAY['The afterlife forgot to iron the suit again', 'Housework took a monstrous turn']::text[]),
  ('241-pop.webp', 'Шерлок', 'Детектив с лупой рассматривает крошечные крошки на огромной тарелке с чашкой чая; улицы Лондона закручиваются вокруг блюдца.', 'Шерлок Sherlock Холмс детектив лупа чай чашка крошки тарелка Лондон расследование', ARRAY['Преступление века случилось за завтраком', 'Из-за одной крошки пришлось поднять весь город']::text[], 'Sherlock', 'A detective studies crumbs on a huge plate beside tea while London streets curl around the saucer.', 'sherlock, detective, studies, crumbs, huge, plate, tea, london, streets, curl, saucer', ARRAY['The crime of the century happened at breakfast', 'One crumb summoned an entire city']::text[]),
  ('242-pop.webp', 'Чёрное зеркало', 'Женщина держит крошечный телефон, а воздушные шары тянут её вверх по пастельной лестнице; тень отказывается следовать за ней.', 'Чёрное зеркало Black Mirror Нырок соцсети рейтинг лайки телефон женщина воздушные шары лестница тень', ARRAY['Одобрение подняло слишком высоко', 'Тень устала от идеального профиля']::text[], 'Black Mirror', 'A woman holds a small phone as balloons lift her up a pastel staircase while her shadow refuses to follow.', 'black, mirror, woman, holds, phone, balloons, lift, pastel, staircase, shadow, refuses, follow', ARRAY['Approval carried her far too high', 'Her shadow is tired of the perfect profile']::text[]),
  ('243-pop.webp', 'Акира', 'Красный мотоцикл несётся через неоновый город к чёрной спирали; искры превращаются в рыб в отражении луж.', 'Акира Akira Канэда красный мотоцикл Нео-Токио город спираль лужи искры', ARRAY['Поворот оказался глубже всей дороги', 'Скорость открыла лишний выход из города']::text[], 'Akira', 'A red motorcycle races through a neon city toward a black spiral as sparks turn into fish in puddle reflections.', 'akira, red, motorcycle, races, neon, city, toward, black, spiral, sparks, turn, fish, puddle, reflections', ARRAY['The turn went deeper than the road', 'Speed opened one exit too many from the city']::text[]),
  ('244-pop.webp', 'Истребитель демонов', 'Мечник в клетчатом шарфе едет на огромной синей волне, которая заодно стирает его одежду; коробка на ножках убегает от воды.', 'Истребитель демонов Demon Slayer Клинок рассекающий демонов Тандзиро Незуко мечник волна вода клетчатая одежда коробка глициния', ARRAY['Боевой приём неожиданно стал днём стирки', 'Самая сухая вещь в лесу решила сбежать']::text[], 'Demon Slayer', 'A swordsman in a checkered scarf rides a giant blue wave that washes his clothes while a box runs from the water.', 'demon, slayer, swordsman, checkered, scarf, rides, blue, wave, washes, clothes, box, runs, water', ARRAY['A fighting move turned into laundry day', 'The driest thing in the forest decided to escape']::text[]),
  ('245-pop.webp', 'Стальной алхимик', 'Мальчик с ситом и стальной великан удивлённо смотрят на выросший вместо опыта хлеб с плечами-круассанами в лабораторной кухне.', 'Стальной алхимик Fullmetal Alchemist Эдвард Элрик Альфонс доспехи алхимия обмен хлеб круассан мука лаборатория', ARRAY['Эквивалентный обмен закончился выпечкой', 'Научный опыт попросили подать к чаю']::text[], 'Fullmetal Alchemist', 'A boy with a sieve and a metal giant stare at bread with croissant shoulders growing from a laboratory experiment.', 'fullmetal, alchemist, boy, sieve, metal, stare, bread, croissant, shoulders, growing, laboratory, experiment', ARRAY['The exchange ended with fresh pastry', 'The science experiment asked to be served with tea']::text[]),
  ('246-pop.webp', 'Криминальное чтиво', 'Двое танцуют на полу закусочной, их тени скручиваются в чёрную виниловую пластинку, а из-под столика светится чемодан.', 'Криминальное чтиво Pulp Fiction Тарантино Винсент Миа танец закусочная винил пластинка светящийся чемодан', ARRAY['Неловкое свидание попало на пластинку', 'Главный секрет вечера спрятали под столом']::text[], 'Pulp Fiction', 'Two people dance in a diner as their shadows twist into a black vinyl record and a briefcase glows beneath a table.', 'pulp, fiction, people, dance, diner, shadows, twist, black, vinyl, record, briefcase, glows, beneath, table', ARRAY['An awkward date ended up on a record', 'The evening''s biggest secret is under the table']::text[]),
  ('247-pop.webp', 'Крёстный отец', 'Торжественный кот с красной розой в большом кресле управляет шахматной пешкой-мафиози, но его самого дёргает за нитки открывалка.', 'Крёстный отец The Godfather Корлеоне мафия кот роза кресло кукловод шахматы пешка открывалка', ARRAY['Даже у кукловода нашёлся хозяин', 'Предложение, от которого трудно отказаться кошке']::text[], 'The Godfather', 'A solemn cat with a red rose controls a mafia chess pawn from a grand chair while a can opener pulls his strings.', 'godfather, solemn, cat, red, rose, controls, mafia, chess, pawn, grand, chair, can, opener, pulls, strings', ARRAY['Even the puppeteer has an owner', 'An offer a cat could hardly refuse']::text[]),
  ('248-pop.webp', 'Бойцовский клуб', 'Два розовых куска мыла в боксёрских перчатках дерутся в раковине; пузыри от ударов показывают рушащиеся офисы.', 'Бойцовский клуб Fight Club Тайлер Дёрден мыло бокс раковина перчатки пузыри офис небоскрёб', ARRAY['Первое правило ванной — никому не говорить о драке', 'Каждый удар смывает ещё один рабочий день']::text[], 'Fight Club', 'Two pink bars of soap in boxing gloves fight in a sink as bubbles show collapsing offices.', 'fight, club, pink, bars, soap, boxing, gloves, sink, bubbles, show, collapsing, offices', ARRAY['The first rule of the bathroom is silence', 'Every punch washes away another workday']::text[]),
  ('249-pop.webp', 'Форрест Гамп', 'Мужчина на скамейке открыл коробку конфет, но каждая шоколадка отрастила кроссовки и убегает по дорожке в форме пера.', 'Форрест Гамп Forrest Gump скамейка шоколад конфеты коробка бег кроссовки перо парк', ARRAY['Сладкая жизнь убежала быстрее хозяина', 'Открыл коробку, а там уже стартовал марафон']::text[], 'Forrest Gump', 'A man on a bench opens a box of chocolates whose pieces grow sneakers and run down a feather-shaped path.', 'forrest, gump, man, bench, opens, box, chocolates, pieces, grow, sneakers, run, feather, shaped, path', ARRAY['The sweet life ran faster than its owner', 'He opened the box and a marathon began']::text[]),
  ('250-pop.webp', 'Побег из Шоушенка', 'Беглец радуется дождю из золотых ключей, но его тень всё ещё за решёткой; вдали тюремное здание похоже на бумажный корабль.', 'Побег из Шоушенка Shawshank Энди Дюфрейн тюрьма побег дождь ключи решётка тень свобода', ARRAY['На свободу вышел раньше собственной тени', 'После долгого заточения даже дождь отпер двери']::text[], 'The Shawshank Redemption', 'An escapee welcomes rain made of golden keys while his shadow remains behind bars and a paper-boat prison stands far away.', 'shawshank, redemption, escapee, welcomes, rain, made, golden, keys, shadow, remains, bars, paper, boat, prison, stands, far, away', ARRAY['He reached freedom before his own shadow', 'After so long, even the rain opened doors']::text[]),
  ('251-pop.webp', 'Зелёная миля', 'Огромный добрый заключённый держит светящуюся мышь; её королевская тень накрывает тюремный коридор с зелёным полом.', 'Зелёная миля Джон Коффи мышь Мистер Джинглс тюрьма заключённый коридор решётка зелёный пол подсолнухи', ARRAY['Самый маленький узник оказался главным', 'Чудо поместилось в ладонях великана']::text[], 'The Green Mile', 'A huge kind prisoner holds a glowing mouse whose royal shadow covers a prison corridor with a green floor.', 'green, mile, huge, kind, prisoner, holds, glowing, mouse, royal, shadow, covers, prison, corridor, floor', ARRAY['The smallest prisoner was in charge', 'A miracle fit in the giant''s hands']::text[]),
  ('252-pop.webp', 'Инопланетянин', 'Длинношеий пришелец едет в корзине велосипеда; луна похожа на огромное колесо, а цепь тянет за собой ночное небо.', 'Инопланетянин E.T. пришелец велосипед корзина полёт луна колесо мальчик пригород', ARRAY['Домой теперь добираются на педальной тяге', 'Когда поездка за угол стала межпланетной']::text[], 'E.T.', 'A long-necked alien rides in a bicycle basket as the moon becomes a giant wheel and the chain pulls the night sky.', 'long, necked, alien, rides, bicycle, basket, moon, becomes, wheel, chain, pulls, night, sky', ARRAY['The trip home runs on pedals now', 'A ride around the block turned interplanetary']::text[]),
  ('253-pop.webp', 'Сияние', 'Две одинаковые девочки держат половины гигантского гостиничного ключа-качелей; за ними кривой коридор и двери.', 'Сияние The Shining близнецы девочки отель Оверлук ключ коридор ковёр двери лифт', ARRAY['Номер оказался слишком велик для одного ключа', 'В этой гостинице коридор повторяет гостей']::text[], 'The Shining', 'Two identical girls hold halves of a giant hotel key like a seesaw before a crooked corridor of doors.', 'shining, identical, girls, hold, halves, hotel, key, seesaw, before, crooked, corridor, doors', ARRAY['The room was too large for one key', 'This hotel''s hallways repeat its guests']::text[]),
  ('254-pop.webp', 'Оно', 'Красный воздушный шар ведёт на поводке испуганного клоуна, который боится бумажного кораблика у ливневого стока.', 'Оно It Пеннивайз клоун красный шарик бумажный кораблик лужа дождь канализация сток', ARRAY['Пугало само попросилось домой', 'Кто кого ведёт на поводке в дождь?']::text[], 'It', 'A red balloon walks a frightened clown on a leash beside a paper boat and a storm drain.', 'red, balloon, walks, frightened, clown, leash, paper, boat, storm, drain', ARRAY['The monster asked to go home', 'Who is leading whom through the rain?']::text[]),
  ('255-pop.webp', 'Амели', 'Девушка в зелёном пальто погружает руку в мешок зерна; зёрна превращаются в звёзды, которые ловит садовый гном.', 'Амели Amélie Монмартр девушка чёрное каре зелёное пальто зерно мешок звёзды садовый гном Париж кафе', ARRAY['Маленькая радость разлетелась по всему небу', 'Секретное счастье поймали под зонтом']::text[], 'Amelie', 'A girl in a green coat dips her hand into grain that turns into stars caught by a garden gnome.', 'amelie, girl, green, coat, dips, hand, grain, turns, stars, caught, garden, gnome, lie', ARRAY['A little joy scattered across the entire sky', 'They caught a secret happiness beneath an umbrella']::text[]),
  ('256-pop.webp', 'Вечное сияние чистого разума', 'Двое на снежном пляже склеивают дом из тающего льда; от клейкой ленты отрываются разноцветные бабочки-воспоминания.', 'Вечное сияние чистого разума Eternal Sunshine Джоэл Клементина память забвение снежный пляж ледяной дом клейкая лента бабочки', ARRAY['Воспоминания не удержались даже на скотче', 'Слишком поздно чинить дом, который стирают из памяти']::text[], 'Eternal Sunshine of the Spotless Mind', 'Two people on a snowy beach tape together a melting ice house as colorful memory butterflies peel from the tape.', 'eternal, sunshine, spotless, mind, people, snowy, beach, tape, together, melting, ice, house, colorful, memory, butterflies, peel', ARRAY['Memories would not stay even under tape', 'Too late to repair a home being erased']::text[]),
  ('257-pop.webp', 'Ла-Ла Ленд', 'Пара в жёлтом платье и синем костюме танцует на клавишах над Лос-Анджелесом; фонарь на ножках крадёт свет рампы.', 'Ла-Ла Ленд La La Land Миа Себастьян танец пианино клавиши жёлтое платье синий костюм Лос-Анджелес фонарь', ARRAY['Третий на свидании оказался фонарём', 'Музыка подняла город над землёй']::text[], 'La La Land', 'A couple in yellow and blue dance on piano keys over Los Angeles while a walking streetlamp steals the spotlight.', 'land, couple, yellow, blue, dance, piano, keys, los, angeles, walking, streetlamp, steals, spotlight', ARRAY['The third person on the date was a lamp', 'The music lifted the whole city off the ground']::text[]),
  ('258-pop.webp', 'Джокер', 'Клоун в красном костюме танцует на лестнице-гармошке; голуби сжимают её края и меняют высоту ступенек.', 'Джокер Joker Артур Флек клоун красный костюм танец лестница гармошка голуби город', ARRAY['Лестница решила подыграть танцору', 'Путь вниз звучит подозрительно весело']::text[], 'Joker', 'A clown in a red suit dances down accordion-like stairs as pigeons squeeze them and change the steps.', 'joker, clown, red, suit, dances, accordion, stairs, pigeons, squeeze, change, steps', ARRAY['The stairs decided to join the dance', 'The way down sounds suspiciously cheerful']::text[]),
  ('259-pop.webp', 'Дюна', 'Путник верхом на гигантском песчаном черве поливает одинокий цветок; червь свернулся словно садовый шланг посреди пустыни.', 'Дюна Dune Пол Атрейдес Арракис пустыня песчаный червь фримены цветок шланг пряность затмение', ARRAY['Самый опасный садовый шланг в пустыне', 'На целой планете нашёлся один повод поливать']::text[], 'Dune', 'A traveler on a giant sandworm waters a single flower while the worm curls like a garden hose in the desert.', 'dune, traveler, sandworm, waters, single, flower, worm, curls, garden, hose, desert', ARRAY['The most dangerous garden hose in the desert', 'A whole planet found one reason to water']::text[]),
  ('260-pop.webp', 'Всё везде и сразу', 'Два камня с глазами медитируют в пустыне под затмением из чёрного бублика, затягивающего в себя чек.', 'Всё везде и сразу Everything Everywhere All at Once Эвелин камни глаза чёрный бублик бейгл мультивселенная чек пустыня', ARRAY['Вселенная решила прилечь и подумать', 'Бухгалтерия дошла до края всего']::text[], 'Everything Everywhere All at Once', 'Two rocks with eyes meditate in a desert beneath a black bagel eclipse swallowing a receipt.', 'everything, everywhere, once, rocks, eyes, meditate, desert, beneath, black, bagel, eclipse, swallowing, receipt', ARRAY['The universe lay down to think for a moment', 'Accounting reached the edge of everything']::text[]),
  ('261-pop.webp', 'Барби', 'Кукла в розовом комбинезоне строит игрушечный дом: её туфля на каблуке стала огромным подъёмным краном.', 'Барби Barbie кукла розовый дом мечты каблук туфля кран строительство пальмы расчёска', ARRAY['Идеальная жизнь потребовала каску', 'Обувь внезапно получила строительную лицензию']::text[], 'Barbie', 'A doll in pink overalls builds a toy house using her high heel as an enormous crane.', 'barbie, doll, pink, overalls, builds, toy, house, using, high, heel, crane', ARRAY['The perfect life required a hard hat', 'The shoe unexpectedly got a building license']::text[]),
  ('262-pop.webp', 'Субстанция', 'Розовое косметическое зеркало красит собственное отражение, требующее всё больше краски; по полу течёт зелёная косметика.', 'Субстанция The Substance зеркало отражение молодость красота макияж кисть косметика зелёная жидкость ванная', ARRAY['Отражение снова недовольно результатом', 'Идеальная внешность попросила ещё один слой']::text[], 'The Substance', 'A pink cosmetic mirror paints its own reflection, which demands more paint as green cosmetics spill across the floor.', 'substance, pink, cosmetic, mirror, paints, reflection, which, demands, more, paint, green, cosmetics, spill, floor', ARRAY['The reflection dislikes the result again', 'Perfection requested one more coat']::text[]),
  ('263-pop.webp', 'Лучше звоните Солу', 'Адвокат в ярком костюме балансирует на весах правосудия между крошечным судом и гигантской резиновой уткой.', 'Лучше звоните Солу Better Call Saul Сол Гудман адвокат оранжевый костюм весы правосудия суд утка документы пустыня', ARRAY['Дело было выиграно резиновым аргументом', 'Правосудие сегодня перевесила игрушка']::text[], 'Better Call Saul', 'A colorful lawyer balances on the scales of justice between a tiny court and a huge rubber duck.', 'better, call, saul, colorful, lawyer, balances, scales, justice, court, huge, rubber, duck', ARRAY['The case was won with a rubber argument', 'A toy outweighed justice today']::text[]),
  ('264-pop.webp', 'Как я встретил вашу маму', 'Синий валторновый рожок стал водной горкой; по нему под жёлтым зонтом спускается влюблённая пара над дождливым Нью-Йорком.', 'Как я встретил вашу маму How I Met Your Mother Тед Робин синяя валторна жёлтый зонт пара любовь Нью-Йорк дождь', ARRAY['История знакомства съехала с горки', 'Любовь нашла путь через непогоду']::text[], 'How I Met Your Mother', 'A blue French horn becomes a water slide for a couple under a yellow umbrella above rainy New York.', 'how, met, your, mother, blue, french, horn, becomes, water, slide, couple, yellow, umbrella, rainy, york', ARRAY['Their meeting story slid downhill', 'Love found a route through bad weather']::text[]),
  ('265-pop.webp', 'Теория большого взрыва', 'Учёный в красной футболке охраняет своё место на диване как планету за силовым полем; друг с попкорном невесомо улетает.', 'Теория большого взрыва Big Bang Theory Шелдон место на диване физик красная футболка силовое поле невесомость попкорн', ARRAY['Священная территория размером с подушку', 'Законы физики защищают любимое сиденье']::text[], 'The Big Bang Theory', 'A scientist in a red shirt guards his couch seat behind a force field while a friend with popcorn floats away.', 'big, bang, theory, scientist, red, shirt, guards, couch, seat, force, field, friend, popcorn, floats, away', ARRAY['Sacred territory the size of a cushion', 'Physics protects the favorite seat']::text[]),
  ('266-pop.webp', 'Офис', 'Стол в офисе превратился в гигантское желе с застрявшим степлером; служащий в очках пытается выудить его удочкой.', 'Офис The Office Джим Дуайт степлер желе офисный стол клерк очки удочка шкаф документы', ARRAY['Рабочий инструмент опять стал десертом', 'В понедельник пришлось ловить канцелярские принадлежности']::text[], 'The Office', 'An office desk becomes giant jelly trapping a stapler as a bespectacled worker fishes for it.', 'office, desk, becomes, jelly, trapping, stapler, bespectacled, worker, fishes', ARRAY['The work tool turned into dessert again', 'Monday required fishing for stationery']::text[]),
  ('267-pop.webp', 'Разделение', 'Один сотрудник как бы разделён на два кабинета: в одном танцует с маракасами, в другом поливает степлер; коридоры закручены петлёй.', 'Разделение Severance офис сотрудник две личности кабинет маракасы степлер растение коридор память', ARRAY['После работы не помню, кто поливал канцелярию', 'Один человек занял сразу два рабочих дня']::text[], 'Severance', 'One worker appears split between two offices: dancing with maracas in one and watering a stapler in the other.', 'severance, worker, appears, split, offices, dancing, maracas, watering, stapler, other', ARRAY['After work I forget who watered the stationery', 'One person filled two whole workdays']::text[]),
  ('268-pop.webp', 'Пацаны', 'Супергерой в плаще накачивает велосипедным насосом собственную огромную статую; голубь равнодушно сидит у неё на носу.', 'Пацаны The Boys Хоумлендер супергерой плащ статуя воздушный шар велосипедный насос голубь слава', ARRAY['Репутация требовала подкачать воздух', 'Монумент вырос, а впечатление — нет']::text[], 'The Boys', 'A caped superhero pumps air into a huge statue of himself while a pigeon sits on its nose.', 'boys, caped, superhero, pumps, air, huge, statue, himself, pigeon, sits, nose', ARRAY['The reputation needed a little more air', 'The monument grew; the impression did not']::text[]),
  ('269-pop.webp', 'Одни из нас', 'Жираф в заросшем заброшенном городе вручает маленькому путнику с рюкзаком горшок с папоротником.', 'Одни из нас The Last of Us Джоэл Элли жираф заброшенный город руины зелень папоротник горшок рюкзак грибы', ARRAY['После конца света кто-то всё-таки принёс цветы', 'Город зарос, зато подарок нашёл адресата']::text[], 'The Last of Us', 'A giraffe in an overgrown abandoned city offers a potted fern to a small traveler with a backpack.', 'last, giraffe, overgrown, abandoned, city, offers, potted, fern, traveler, backpack', ARRAY['Someone still brought flowers after the end of the world', 'The city grew wild, but the gift found its recipient']::text[]),
  ('270-pop.webp', 'Твоё имя', 'Двое на противоположных склонах распутывают красную нить, завязавшую летящую комету огромным бантом.', 'Твоё имя Your Name Мицуха Таки красная нить судьба комета горы закат город бант', ARRAY['Судьба завязала слишком тугой узел', 'Даже небесное тело попало в любовную путаницу']::text[], 'Your Name', 'Two people on opposite slopes untangle a red thread that tied a passing comet into a giant bow.', 'your, name, people, opposite, slopes, untangle, red, thread, tied, passing, comet, bow', ARRAY['Fate tied the knot too tightly', 'Even a celestial body got tangled in love']::text[]),
  ('271-pop.webp', 'Призрак в доспехах', 'Невидимый андроид-детектив обозначен только розовым зонтом, сапогами и дождём, который обводит её силуэт в неоновом городе.', 'Призрак в доспехах Ghost in the Shell Мотоко Кусанаги киборг андроид невидимость зонтик сапоги дождь неоновый город', ARRAY['Дождь нарисовал того, кого нельзя увидеть', 'Самый заметный прохожий здесь невидим']::text[], 'Ghost in the Shell', 'An invisible android detective is outlined only by rain, a pink umbrella and boots in a neon city.', 'ghost, shell, invisible, android, detective, outlined, rain, pink, umbrella, boots, neon, city', ARRAY['The rain drew the person you cannot see', 'The most noticeable passerby is invisible']::text[]),
  ('272-pop.webp', 'Евангелион', 'Огромный фиолетово-зелёный робот пытается усесться на крошечный складной стул в вагоне и держит сумку с обедом.', 'Евангелион Evangelion Ева-01 Евангелион меха робот поезд вагон стул сумка обед город', ARRAY['Даже гигантам приходится ездить в час пик', 'В вагоне больше не осталось места для коленей']::text[], 'Neon Genesis Evangelion', 'A giant purple-and-green robot tries to squeeze onto a tiny folding seat in a train carriage with a lunch bag.', 'neon, genesis, evangelion, purple, green, robot, tries, squeeze, onto, folding, seat, train, carriage, lunch, bag', ARRAY['Even giants have to travel at rush hour', 'No room for knees remains in this carriage']::text[]),
  ('273-pop.webp', 'Принцесса Мононоке', 'Белый волк расчесывает мох на древнем дереве гребнем из рогов; девушка в маске собирает опавшие листья.', 'Принцесса Мононоке Сан белый волк лес дерево мох рога гребень маска духи листья', ARRAY['Лесу записали уход за причёской', 'Самая дикая парикмахерская принимает по листьям']::text[], 'Princess Mononoke', 'A white wolf combs moss on an ancient tree with an antler comb while a masked girl gathers leaves.', 'princess, mononoke, white, wolf, combs, moss, ancient, tree, antler, comb, masked, girl, gathers, leaves', ARRAY['The forest booked a haircut', 'The wildest salon takes payment in leaves']::text[]),
  ('274-pop.webp', 'Ведьмина служба доставки', 'Юная ведьма на метле запуталась в гигантской бельевой верёвке; чёрный кот управляет движением двумя хлебными палочками.', 'Ведьмина служба доставки Кики Дзидзи ведьма чёрный кот метла красный бант верёвка бельё хлеб крыши посылки', ARRAY['Экспресс-доставка попала в день стирки', 'Диспетчер воздушного движения мурлычет']::text[], 'Kiki''s Delivery Service', 'A young witch on a broom tangles in a giant clothesline while a black cat directs traffic with breadsticks.', 'kiki, delivery, service, young, witch, broom, tangles, clothesline, black, cat, directs, traffic, breadsticks', ARRAY['Express delivery hit laundry day', 'The air traffic controller purrs']::text[]),
  ('275-pop.webp', 'Рыбка Поньо', 'Девочка-рыбка в красном бежит по гигантской волне, похожей на раскатываемый ковёр; жёлтое ведро тщетно пытается собрать океан.', 'Рыбка Поньо Ponyo Поньо рыба девочка море волна синий ковёр жёлтое ведро берег', ARRAY['Море решили свернуть перед уборкой', 'Маленькому ведру достался весь океан']::text[], 'Ponyo', 'A little fish girl in red runs over a giant wave like a rolled rug while a yellow bucket tries to catch the sea.', 'ponyo, fish, girl, red, runs, wave, rolled, rug, yellow, bucket, tries, catch, sea', ARRAY['They tried to roll up the ocean before cleaning', 'The smallest bucket got the whole sea']::text[]),
  ('276-pop.webp', 'Шоу Трумана: погода', 'Уставшая телевизионная туча пьёт кофе на лестнице над городком; человек внизу собирает зонтом свет софитов вместо дождя.', 'Шоу Трумана The Truman Show искусственная погода туча декорация солнце прожектор лестница зонтик кофе город', ARRAY['Прогноз объявил перерыв на кофе', 'Осадки заменили осветительным оборудованием']::text[], 'The Truman Show: Weather', 'A tired television cloud drinks coffee above a town while a man below catches spotlight beams instead of rain.', 'truman, show, weather, tired, television, cloud, drinks, coffee, town, man, catches, spotlight, beams, rain, second', ARRAY['The forecast took a coffee break', 'The rain was replaced by lighting equipment']::text[]),
  ('277-pop.webp', 'Матрица: ложка', 'Крошечный философ в чёрном пытается согнуть ложку, но та изгибает вокруг себя целое кафе; за окном зелёный цифровой дождь.', 'Матрица Matrix Нео ложка сгибание ложки кафе зелёный код красный и синий сахар реальность', ARRAY['Столовые приборы переписали законы комнаты', 'Проблема была не в металле, а в кафе']::text[], 'The Matrix: Spoon', 'A tiny black-coated philosopher bends a spoon that bends an entire cafe around itself amid green code rain.', 'matrix, spoon, black, coated, philosopher, bends, entire, cafe, itself, amid, green, code, rain, second', ARRAY['The cutlery rewrote the room''s laws', 'The problem was never the metal']::text[]),
  ('278-pop.webp', 'Начало: невесомость', 'Гостиничный коридор свернулся в колесо; двое людей в костюмах бегут внутри, а маленький волчок крутит всё снаружи.', 'Начало Inception сон отель коридор невесомость колесо волчок двое в костюмах', ARRAY['Номер в гостинице пошёл по кругу', 'Пока гости бегут, крошечный мотор спит']::text[], 'Inception: Weightlessness', 'A hotel corridor curls into a wheel as two suited people run inside and a small top spins it from outside.', 'inception, weightlessness, hotel, corridor, curls, wheel, suited, people, run, top, spins, second', ARRAY['The hotel room started going in circles', 'The smallest engine keeps dreaming']::text[]),
  ('279-pop.webp', 'Во все тяжкие: муха', 'Огромная муха в очках рассматривает маленького лысого химика через лупу посреди лаборатории.', 'Во все тяжкие Breaking Bad Уолтер Уайт Хайзенберг муха лысый химик очки лаборатория лупа жёлтый костюм', ARRAY['Лабораторный инспектор оказался с крыльями', 'Сегодня эксперимент наблюдает за учёным']::text[], 'Breaking Bad: Fly', 'A giant bespectacled fly examines a small bald chemist with a magnifying glass in a laboratory.', 'breaking, bad, fly, bespectacled, examines, bald, chemist, magnifying, glass, laboratory, second', ARRAY['The laboratory inspector came with wings', 'The experiment is watching the scientist today']::text[]),
  ('280-pop.webp', 'Игра престолов: зима', 'Снежинка в меховой мантии сидит на троне и феном сушит ледяную корону, случайно растапливая дворец; вдали драконы в шарфах.', 'Игра престолов Game of Thrones зима близко снежинка корона трон лёд фен драконы шарфы дворец', ARRAY['Монарх отменил собственный дворец феном', 'Холодный сезон переусердствовал с укладкой']::text[], 'Game of Thrones: Winter', 'A snowflake in a fur robe sits on a throne and hair-dries an icy crown, accidentally melting its palace.', 'game, thrones, winter, snowflake, fur, robe, sits, throne, hair, dries, icy, crown, accidentally, melting, palace, second', ARRAY['The monarch canceled his own palace with a hair dryer', 'The cold season overdid the styling']::text[]),
  ('281-pop.webp', 'Игра в кальмара: канат', 'Охранник в розовом и участник в зелёном тянут лакричный канат, пока гигантская улитка съедает его посередине.', 'Игра в кальмара Squid Game перетягивание каната охранник квадратная маска зелёный костюм лакрица улитка мост', ARRAY['Победителя определил самый медленный судья', 'Спор закончился обедом третьего участника']::text[], 'Squid Game: Tug of War', 'A pink guard and green player pull a licorice rope while a giant snail eats the middle.', 'squid, game, tug, war, pink, guard, green, player, pull, licorice, rope, snail, eats, middle, second', ARRAY['The slowest referee decided the winner', 'The contest became a third participant''s lunch']::text[]),
  ('282-pop.webp', 'Тетрадь смерти: контроль', 'Чёрная пустая тетрадь стала гигантской мышеловкой с яблоком-приманкой, а бог смерти спокойно читает на её спусковом крючке.', 'Тетрадь смерти Death Note Рюк синигами чёрная тетрадь яблоко мышеловка бог смерти книга', ARRAY['Ловушка ждала не того читателя', 'Угроза оказалась удобным креслом для чтения']::text[], 'Death Note: Control', 'A black notebook becomes a giant mousetrap baited with an apple while a death god reads on the trigger.', 'death, note, control, black, notebook, becomes, mousetrap, baited, apple, god, reads, trigger, second', ARRAY['The trap was waiting for the wrong reader', 'The threat made a comfortable reading chair']::text[]),
  ('283-pop.webp', 'Ван-Пис: сокровище', 'В открытом пиратском сундуке плещется целое море с кораблём; пират в соломенной шляпе тянет к монете резиновую руку, но сундук убегает.', 'Ван-Пис One Piece Луффи пират соломенная шляпа сундук сокровище монета море корабль резиновая рука', ARRAY['Сокровище захватило свой собственный океан', 'Морское путешествие поместилось в багаже']::text[], 'One Piece: Treasure', 'An open pirate chest contains a sea and ship while a straw-hatted pirate reaches for a coin with a rubber arm.', 'piece, treasure, open, pirate, chest, contains, sea, ship, straw, hatted, reaches, coin, rubber, arm, second', ARRAY['The treasure took over its own ocean', 'The sea voyage fit in the luggage']::text[]),
  ('284-pop.webp', 'Наруто: колокольчики', 'Два золотых тренировочных колокольчика в виде птиц гонятся за седым ниндзя в маске, прячущимся за маленьким оранжевым клоном.', 'Наруто Naruto Какаши Наруто ниндзя колокольчики тренировка седые волосы маска клон оранжевый костюм лес', ARRAY['Учебная тревога догнала учителя', 'Теперь награда сама преследует победителя']::text[], 'Naruto: Bells', 'Two golden bird-shaped training bells chase a gray-haired masked ninja hiding behind an orange clone.', 'naruto, bells, golden, bird, shaped, training, chase, gray, haired, masked, ninja, hiding, orange, clone, second', ARRAY['The practice alarm caught the teacher', 'Now the prize chases the winner']::text[]),
  ('285-pop.webp', 'Тоторо: транспорт', 'Большой лесной дух ждёт с билетом-листом, пока крошечный автобус-кот спит, свернувшись в чайной чашке.', 'Тоторо My Neighbor Totoro Котобус лесной дух автобус кот чашка лист билет остановка деревья', ARRAY['Общественный транспорт решил поспать', 'Пассажир оказался больше всей поездки']::text[], 'Totoro: Transport', 'A large forest spirit waits with a leaf ticket while a tiny cat bus sleeps curled in a teacup.', 'totoro, transport, forest, spirit, waits, leaf, ticket, cat, bus, sleeps, curled, teacup, second, neighbor', ARRAY['Public transport decided to nap', 'The passenger is bigger than the whole journey']::text[]),
  ('286-pop.webp', 'Унесённые призраками: баня', 'Пушистый дух сажи моется в крошечной фарфоровой ложке; маленькие угольки обмахивают его листьями перед баней из чайников.', 'Унесённые призраками Spirited Away сусуватари сажевые духи баня ложка угольки чайники пар конфета', ARRAY['Банный день устроили в столовом приборе', 'Для самого грязного гостя нашлась самая маленькая ванна']::text[], 'Spirited Away: Bathhouse', 'A fluffy soot spirit bathes in a porcelain spoon while little coals fan it with leaves before a kettle bathhouse.', 'spirited, away, bathhouse, fluffy, soot, spirit, bathes, porcelain, spoon, coals, fan, leaves, before, kettle, second', ARRAY['Bath day took place in the cutlery drawer', 'The dirtiest guest found the smallest tub']::text[]),
  ('287-pop.webp', 'Друзья: фонтан', 'Оранжевый диван стал лодкой в фонтане; шесть чашек кофе с разными лицами плывут под зонтиками-парусами.', 'Друзья Friends шесть друзей оранжевый диван фонтан чашки кофе зонтики лодка парк', ARRAY['Гостиная отправилась в плавание', 'Компания собралась на чашечку водопада']::text[], 'Friends: Fountain', 'An orange couch sails through a fountain while six expressive coffee cups float under umbrella sails.', 'friends, fountain, orange, couch, sails, six, expressive, coffee, cups, float, umbrella, second', ARRAY['The living room set sail', 'The gang met for a cup of waterfall']::text[]),
  ('288-pop.webp', 'Очень странные дела: велосипед', 'Четыре пустых велосипеда сами едут вверх колёсами по потолку фиолетового леса; розовая вафля-луна тянет их сиропом.', 'Очень странные дела Stranger Things Изнанка велосипеды четыре друга лес вверх ногами вафля портал сироп', ARRAY['Дорога уехала на другую сторону', 'Завтрак нарушил законы притяжения']::text[], 'Stranger Things: Bikes', 'Four empty bicycles ride upside down across the ceiling of a purple forest, pulled by a waffle moon.', 'stranger, things, bikes, four, empty, bicycles, ride, upside, ceiling, purple, forest, pulled, waffle, moon, second', ARRAY['The road escaped to the other side', 'Breakfast broke the rules of gravity']::text[]),
  ('289-pop.webp', 'Уэнсдей: виолончель', 'Мрачная девушка с косичками пилит смычком виолончели лунный серп; отдельная рука держит его как ноты.', 'Уэнсдей Wednesday Уэнсдей Аддамс Вещь виолончель смычок рука косички луна готика', ARRAY['Вечерняя музыка отпилила кусок неба', 'Лунный свет понадобился вместо партитуры']::text[], 'Wednesday: Cello', 'A gloomy girl plays a cello bow across a crescent moon while a detached hand holds the music.', 'wednesday, cello, gloomy, girl, plays, bow, crescent, moon, detached, hand, holds, music, second', ARRAY['The evening music sawed off part of the sky', 'Moonlight replaced the sheet music']::text[]),
  ('290-pop.webp', 'Титаник: оркестр', 'Три пингвина в бабочках играют на рояле посреди океана; клавиши становятся трапом для маленького лайнера, а айсберг аплодирует.', 'Титаник Titanic оркестр музыканты пингвины рояль лайнер корабль айсберг океан трап', ARRAY['Музыканты продолжили, даже когда сцена уплыла', 'Самый холодный зритель попросил бис']::text[], 'Titanic: Orchestra', 'Three bow-tied penguins play piano in the ocean as its keys become a gangway for a small liner and an iceberg applauds.', 'titanic, orchestra, bow, tied, penguins, play, piano, ocean, keys, become, gangway, liner, iceberg, applauds, second', ARRAY['The musicians kept playing after the stage floated away', 'The coldest audience member demanded an encore']::text[]),
  ('291-pop.webp', 'Парк юрского периода: яйцо', 'Маленький динозавр вылупился из огромного яйца-глобуса; янтарный комар смотрит на него, словно заботливый родитель.', 'Парк юрского периода Jurassic Park динозавр яйцо янтарь комар ДНК музей джунгли глобус', ARRAY['Семейное древо началось с укуса', 'Новорождённый обнаружил, что живёт в музее']::text[], 'Jurassic Park: Egg', 'A baby dinosaur hatches from a globe-shaped egg while an amber mosquito watches like a proud parent.', 'jurassic, park, egg, baby, dinosaur, hatches, globe, shaped, amber, mosquito, watches, proud, parent, second', ARRAY['The family tree began with one bite', 'The newborn discovered it lived in a museum']::text[]),
  ('292-pop.webp', 'Назад в будущее: скейт', 'Розовый ховерборд несут крошечные летающие будильники; путешественник в красном жилете балансирует над улицей.', 'Назад в будущее Back to the Future Марти Макфлай ховерборд скейт красный жилет будильники часы будущее', ARRAY['Полетели только часы, а доску пришлось нести', 'Будущее опять опоздало к назначенному времени']::text[], 'Back to the Future: Hoverboard', 'Tiny flying alarm clocks carry a pink hoverboard as a traveler in a red vest balances above the street.', 'back, future, hoverboard, flying, alarm, clocks, carry, pink, traveler, red, vest, balances, street, second', ARRAY['Only the clocks flew; the board needed carrying', 'The future was late for its own appointment']::text[]),
  ('293-pop.webp', 'Пираты Карибского моря: компас', 'Гигантский латунный компас стал островом с трамплином-стрелкой; пират медлит, пока сундук с сокровищами уплывает как рыба.', 'Пираты Карибского моря Pirates of the Caribbean Джек Воробей компас пират треуголка море остров сундук сокровище стрелка', ARRAY['Направление известно, а добыча уже смылась', 'Навигатор превратился в место для прыжка']::text[], 'Pirates of the Caribbean: Compass', 'A huge brass compass becomes an island with a springboard needle while a pirate hesitates and a treasure chest swims away.', 'pirates, caribbean, compass, huge, brass, becomes, island, springboard, needle, pirate, hesitates, treasure, chest, swims, away, second', ARRAY['The direction is known, but the loot is gone', 'The navigator turned into a diving board']::text[]),
  ('294-pop.webp', 'Гарри Поттер: шахматы', 'Огромный шахматный конь боится крошечной белой совы с пешкой; клетчатый пол переходит в движущиеся лестницы среди свечей.', 'Гарри Поттер Harry Potter Хогвартс волшебные шахматы конь пешка белая сова Букля лестницы свечи', ARRAY['Самая маленькая фигура объявила мат', 'Бояться здесь нужно не коня']::text[], 'Harry Potter: Chess', 'A huge chess knight fears a tiny white owl holding a pawn on a checkerboard that becomes moving staircases.', 'harry, potter, chess, huge, knight, fears, white, owl, holding, pawn, checkerboard, becomes, moving, staircases, second', ARRAY['The smallest piece called checkmate', 'The horse is not the one to fear here']::text[]),
  ('295-pop.webp', 'Властелин колец: путешествие', 'Крошечный домик хоббита на волосатых ногах тащит огромный рюкзак, а золотое кольцо катится впереди по зелёным холмам.', 'Властелин колец Lord of the Rings хоббит Фродо Шир дом нора круглая дверь рюкзак кольцо Мордор вулкан путешествие', ARRAY['Даже дом отправился в долгий поход', 'Украшение укатилось, а жильё бросилось следом']::text[], 'The Lord of the Rings: Journey', 'A tiny hobbit house on hairy feet carries a huge backpack as a gold ring rolls ahead over green hills.', 'lord, rings, journey, hobbit, house, hairy, feet, carries, huge, backpack, gold, ring, rolls, ahead, green, hills, lotr, second', ARRAY['Even the house set out on a long journey', 'The jewelry rolled away and home ran after it']::text[]),
  ('296-pop.webp', 'Покемон: планетарий', 'Открытый красно-белый покебол стал планетарием: в верхней половине сияют созвездия существ, в нижней пруд отражает серп луны; вокруг стоят пустые кресла.', 'Покемон Pokémon покебол красно-белая капсула планетарий созвездия существа пруд луна кресла небо коллекция', ARRAY['Целый мир поместился под одним куполом', 'Редкие создания спрятались среди звёзд']::text[], 'Pokemon: Planetarium', 'An open red-and-white Poke Ball becomes a planetarium with creature constellations above a moonlit pond.', 'pokemon, planetarium, open, red, white, poke, ball, becomes, creature, constellations, moonlit, pond, second, pok, mon', ARRAY['A whole world fit beneath one dome', 'The rare creatures hid among the stars']::text[]),
  ('297-pop.webp', 'Сейлор Мун: зеркало', 'Золотой серп луны смотрится в ручное зеркало и видит там удивлённую чёрную кошку; крошечная волшебница протирает стекло.', 'Сейлор Мун Sailor Moon Усаги Луна чёрная кошка лунный серп зеркало волшебница матроска крыши', ARRAY['Отражение решило стать домашним питомцем', 'Небесное светило не узнало себя в зеркале']::text[], 'Sailor Moon: Mirror', 'A golden crescent looks into a hand mirror and sees a surprised black cat while a tiny magical girl wipes the glass.', 'sailor, moon, mirror, golden, crescent, looks, hand, sees, surprised, black, cat, magical, girl, wipes, glass, second', ARRAY['The reflection decided to become a pet', 'The heavenly body did not recognize itself']::text[]),
  ('298-pop.webp', 'Драконий жемчуг: желание', 'Огромный зелёный дракон в очках собирает облачное кресло; семь оранжевых шаров служат винтами, а маленький герой держит молоток.', 'Драконий жемчуг Dragon Ball Шенрон Гоку дракон желание семь шаров звёзды очки кресло облако молоток', ARRAY['Исполнение желаний упёрлось в инструкцию', 'Для всемогущества не хватило одной отвёртки']::text[], 'Dragon Ball: Wish', 'A giant green dragon in glasses builds a cloud chair with seven orange balls as screws and a small hero holding a hammer.', 'dragon, ball, wish, green, glasses, builds, cloud, chair, seven, orange, balls, screws, hero, holding, hammer, second', ARRAY['Granting wishes got stuck on the instructions', 'Omnipotence was missing one screwdriver']::text[]),
  ('299-pop.webp', 'Стальной алхимик: обмен', 'Пустые доспехи меняют свою огромную тень на котёнка на рыночных весах; светловолосый спутник в красном возмущён.', 'Стальной алхимик Fullmetal Alchemist Альфонс Эдвард Элрик доспехи обмен алхимия котёнок тень весы рынок', ARRAY['Цена сделки оказалась очень пушистой', 'За новую дружбу пришлось расплатиться тенью']::text[], 'Fullmetal Alchemist: Exchange', 'Empty armor trades its huge shadow for a kitten on market scales as a blond companion in red protests.', 'fullmetal, alchemist, exchange, empty, armor, trades, huge, shadow, kitten, market, scales, blond, companion, red, protests, second', ARRAY['The price of the deal was very fluffy', 'A new friendship cost an old shadow']::text[]),
  ('300-pop.webp', 'Кино: финальная карта', 'Старинный кинопроектор выпускает луч-лестницу к бирюзовой луне-попкорну; по ступеням шагает крошечное красное кресло.', 'кино кинопроектор плёнка кинозал красное кресло золотая лестница луч луна попкорн финал', ARRAY['Зритель ушёл туда, где начинается фильм', 'Последний сеанс ведёт прямо на луну']::text[], 'Final Cinema Card', 'An old projector casts a stair-shaped beam toward a turquoise popcorn moon as a tiny red theater chair climbs it.', 'final, cinema, card, projector, casts, stair, shaped, beam, toward, turquoise, popcorn, moon, red, theater, chair, climbs, finale', ARRAY['The viewer went where movies begin', 'The final screening leads straight to the moon']::text[]),
  ('401-pop.webp', 'Индиана Джонс и золотой идол', 'Археолог в шляпе и с кнутом тянется к улыбающемуся золотому идолу на постаменте в древнем храме.', 'Индиана Джонс археолог шляпа кнут золотой идол сокровище храм ловушка камень', ARRAY['Древняя находка улыбается слишком уверенно', 'Экскурсия закончится очень быстрым бегом']::text[], 'Indiana Jones and the Golden Idol', 'An archaeologist in a hat with a whip reaches for a smiling gold idol on a pedestal inside an ancient temple.', 'indiana jones golden idol archaeologist hat whip reaches smiling gold pedestal ancient temple', ARRAY['The ancient discovery smiles too confidently', 'The tour is about to end with a very fast run']::text[]),
  ('402-pop.webp', 'Моб Психо 100: брокколи над городом', 'Школьник в чёрной форме стоит под гигантской летающей брокколи, вокруг которой закручиваются дома и цветная энергия.', 'Моб Психо 100 Mob Psycho Моб Шигэо психическая сила телекинез брокколи дерево город школьник', ARRAY['Овощ вырос выше всех проблем', 'Когда обед получил собственную гравитацию']::text[], 'Mob Psycho 100: Broccoli Over the City', 'A schoolboy in black stands beneath giant floating broccoli as houses and colorful energy swirl around it.', 'mob psycho broccoli city schoolboy black stands beneath floating houses energy swirl', ARRAY['A vegetable grew taller than every problem', 'Lunch acquired its own gravity']::text[]),
  ('403-pop.webp', 'Блич: меч под луной', 'Рыжеволосый мечник в чёрном плаще несётся по белой лестнице из осколков к полной луне среди бумажных птиц.', 'Блич Bleach Ичиго Куросаки шинигами меч катана чёрный плащ оранжевые волосы луна осколки', ARRAY['Ночной подъём по лестнице, которой не было', 'Осколки решили показать дорогу к луне']::text[], 'Bleach: Sword Beneath the Moon', 'A red-haired swordsman in a black cloak races up a white staircase of shards toward the full moon.', 'bleach sword beneath moon red-haired swordsman black cloak races white staircase shards full', ARRAY['A midnight ascent on stairs that never existed', 'The fragments decided to show the way']::text[]),
  ('404-pop.webp', 'Дьявол носит Prada: гардероб', 'Строгая седовласая начальница в красном пальто осматривает бутик, где одинаковые синие свитеры выстроились спиральной лестницей.', 'Дьявол носит Prada Миранда Пристли Энди мода редактор начальница красное пальто голубой свитер магазин одежда', ARRAY['Один оттенок устроил целую карьеру', 'Здесь даже свитера стоят по иерархии']::text[], 'The Devil Wears Prada: Wardrobe', 'A stern gray-haired boss in red examines a boutique where identical blue sweaters form a spiral staircase.', 'devil wears prada wardrobe stern gray-haired boss red examines boutique where identical blue sweaters form spiral staircase', ARRAY['One shade built an entire career', 'Even the sweaters know their rank']::text[]),
  ('405-pop.webp', 'Достать ножи: пончик в детективе', 'Огромный пончик с дыркой обрамляет подозреваемых за столом и седого сыщика, подглядывающего за ними.', 'Достать ножи Knives Out Бенуа Блан сыщик детектив пончик дырка расследование семья ужин подозреваемые', ARRAY['В центре загадки оказалось ничего', 'Сыщик нашёл улику прямо за десертом']::text[], 'Knives Out: A Doughnut Mystery', 'A giant doughnut frames suspects at a table as a gray-haired detective watches them.', 'knives doughnut mystery frames suspects table gray-haired detective watches', ARRAY['At the center of the mystery was nothing', 'The detective found a clue behind dessert']::text[]),
  ('406-pop.webp', 'Секретные материалы: ночной свет', 'Двое следователей у стола смотрят на зелёный луч летающей тарелки, зависшей над городом и забирающей шкаф.', 'Секретные материалы X-Files Малдер Скалли ФБР НЛО летающая тарелка зелёный луч похищение кабинет', ARRAY['Архив забрали без разрешения', 'Ночные гости пришли за мебелью']::text[], 'The X-Files: Night Light', 'Two investigators watch a green UFO beam lift a cabinet above the city.', 'x-files night light investigators watch green ufo beam lift cabinet city', ARRAY['The archive was taken without permission', 'Night visitors came for the furniture']::text[]),
  ('407-pop.webp', 'Код Гиас: шахматный приказ', 'Юноша в чёрном плаще стоит на огромной шахматной доске среди фигур, а в его тени вспыхивает красный глаз.', 'Код Гиас Code Geass Лелуш шахматы король фигуры чёрный плащ красный глаз приказ', ARRAY['В этой партии даже тень отдаёт приказы', 'Фигуры ещё не знают, кто придумал правила']::text[], 'Code Geass: Chess Command', 'A cloaked young man stands among pieces on a huge chessboard as a red eye glows in his shadow.', 'code geass chess command cloaked man stands pieces chessboard red eye glows shadow', ARRAY['Even the shadow gives orders in this game', 'The pieces do not yet know who wrote the rules']::text[]),
  ('408-pop.webp', 'Футурама: доставка в космос', 'Рыжий курьер ведёт космический корабль, а рядом зубастый робот выглядывает в иллюминатор с посылкой.', 'Футурама Futurama Фрай Бендер робот космический корабль доставка посылка иллюминатор', ARRAY['Курьер снова свернул не в тот век', 'Посылка летит дальше адресата']::text[], 'Futurama: Space Delivery', 'A red-haired courier pilots a spaceship while a toothy robot peers through the window with a parcel.', 'futurama space delivery red-haired courier pilots spaceship toothy robot peers window parcel', ARRAY['The courier took a wrong turn into another century', 'The package is traveling farther than its addressee']::text[]),
  ('409-pop.webp', 'Фрирен: привал у сундука', 'Эльфийка с фиолетовыми волосами отдыхает возле лесного сундука, из которого высунулся огромный язык; рядом спутники.', 'Фрирен провожающая в последний путь Frieren эльфийка сундук мимик язык лес спутники приключение', ARRAY['Сокровище первым решило пообедать', 'Привал оказался не таким спокойным']::text[], 'Frieren: Rest by the Chest', 'A purple-haired elf rests by a forest treasure chest with a huge tongue sticking out as companions wait nearby.', 'frieren rest chest purple-haired elf rests forest treasure tongue sticking companions wait nearby', ARRAY['The treasure decided to have lunch first', 'This rest stop is less peaceful than it looks']::text[]),
  ('410-pop.webp', 'Берсерк: меч и затмение', 'Воин с огромным мечом стоит перед чудовищным лицом на фоне чёрного солнечного затмения и багрового неба.', 'Берсерк Berserk Гатс драконоборец огромный меч чудовище затмение красное небо доспехи', ARRAY['Когда небо выключило свет перед боем', 'За один меч пришлось отвечать целой тьме']::text[], 'Berserk: Sword and Eclipse', 'A warrior with a giant sword faces a monstrous figure under a black eclipse and crimson sky.', 'berserk sword eclipse warrior faces monstrous figure black crimson sky', ARRAY['The sky turned out the light before the battle', 'One sword must answer a whole darkness']::text[]),
  ('411-pop.webp', 'Волшебник страны Оз: красные башмачки', 'Девочка, пугало, лев и жестяной спутник выглядывают из-за дома среди красных маков; на земле блестят красные туфли.', 'Волшебник страны Оз Дороти пугало трусливый лев железный дровосек красные туфли маки дом', ARRAY['Дорога началась с пары неудобных башмаков', 'Цветочное поле собрало странную компанию']::text[], 'The Wizard of Oz: Ruby Slippers', 'A girl, scarecrow, lion and tin companion peek from behind a house among red poppies and shiny red shoes.', 'wizard ruby slippers girl scarecrow lion tin companion peek house red poppies shiny shoes', ARRAY['The road began with uncomfortable footwear', 'A strange group gathered in a field of flowers']::text[]),
  ('412-pop.webp', 'Острые козырьки: трое на улице', 'Трое мужчин в кепках и длинных тёмных пальто идут по мокрой промышленной улице мимо фабричных труб.', 'Острые козырьки Peaky Blinders Томми Шелби кепки костюмы пальто фабрика дым Бирмингем улица', ARRAY['Встреча назначена там, где даже туман суров', 'Шляпы идут вперёд хозяев']::text[], 'Peaky Blinders: Three on the Street', 'Three men in caps and dark coats walk down a wet industrial street past factory chimneys.', 'peaky blinders street men caps coats walk wet industrial past factory chimneys', ARRAY['The meeting is where even the fog looks stern', 'Their hats seem to walk ahead of them']::text[]),
  ('413-pop.webp', 'Бруклин 9-9: офисное кресло', 'Полицейский в участке катится на офисном кресле к висящей высоко полицейской фуражке, пока коллеги наблюдают.', 'Бруклин 9-9 Brooklyn Nine-Nine Джейк Перальта полицейский участок офисное кресло фуражка коллеги', ARRAY['Расследование потребовало разгона на колёсиках', 'Самый серьёзный отдел устроил гонку до потолка']::text[], 'Brooklyn Nine-Nine: Office Chair', 'A police officer rolls across the precinct in an office chair toward a cap hanging high above his colleagues.', 'brooklyn nine-nine office chair police officer rolls precinct cap hanging high colleagues', ARRAY['The investigation demanded wheels and a running start', 'The serious department raced toward the ceiling']::text[]),
  ('414-pop.webp', 'Пианист и весёлый наставник', 'Молодой музыкант играет на пианино в тёплом клубе, а стоящий рядом улыбающийся мужчина хлопает в ладоши.', 'пианист фортепиано пианино музыка джаз клуб наставник аплодисменты публика', ARRAY['Урок получился громче концерта', 'Мелодию одобрили раньше последней ноты']::text[], 'Pianist and Cheerful Mentor', 'A young musician plays piano in a warm club while a smiling man beside him claps along.', 'pianist cheerful mentor musician plays piano warm club smiling man beside him claps', ARRAY['The lesson was louder than the concert', 'The melody was approved before its last note']::text[]),
  ('415-pop.webp', 'Одержимость: барабанщик', 'Вспотевший барабанщик играет под ярким светом сцены, пока лысый дирижёр требовательно указывает на него.', 'Одержимость Whiplash Эндрю Флетчер барабаны барабанщик дирижёр джаз сцена палочки', ARRAY['Темп задаёт человек без барабанных палочек', 'Репетиция снова похожа на экзамен']::text[], 'Whiplash: Drummer', 'A sweaty drummer plays under bright stage lights as a bald conductor points at him demanding more.', 'whiplash drummer sweaty plays stage lights bald conductor points him demanding', ARRAY['The person without drumsticks sets the tempo', 'Rehearsal feels like an exam again']::text[]),
  ('416-pop.webp', 'Гинтама: пёс размером с лошадь', 'Белый гигантский пёс несёт по старой улице седовласого юношу и девушку в красном, как весёлый ездовой зверь.', 'Гинтама Gintama Гинтоки Кагура Садахару белый огромный пёс самурай город поездка', ARRAY['На прогулку вышли верхом на любимце', 'Пёс решил, что поводок ему не нужен']::text[], 'Gintama: Horse-Sized Dog', 'An enormous white dog carries a gray-haired youth and a girl in red along an old street.', 'gintama horse-sized dog enormous white carries gray-haired youth girl red street', ARRAY['They took the family pet for a ride', 'The dog decided a leash was unnecessary']::text[]),
  ('417-pop.webp', 'Парень-каратист: восковая тренировка', 'Подросток и пожилой наставник натирают светлый автомобиль во дворе солнечного дома.', 'Парень-каратист Karate Kid Дэниел мистер Мияги карате воск автомобиль полировка тренировка', ARRAY['Боевой приём пахнет автомобильным воском', 'Сначала блеск, потом чёрный пояс']::text[], 'The Karate Kid: Wax Training', 'A teenager and elderly mentor polish a pale car in the courtyard of a sunny house.', 'karate kid wax training teenager elderly mentor polish pale car courtyard sunny house', ARRAY['This fighting move smells of car wax', 'First the shine, then the black belt']::text[]),
  ('418-pop.webp', 'Одержимость: соло под прожектором', 'Молодой барабанщик бьёт по красной установке под прожектором, а строгий лысый наставник нависает за спиной.', 'Одержимость Whiplash барабанщик Эндрю Флетчер барабанная установка красные барабаны сцена прожектор', ARRAY['Каждый удар слышен даже за кулисами', 'Музыка потребовала больше, чем аплодисменты']::text[], 'Whiplash: Solo in the Spotlight', 'A young drummer pounds a red kit beneath a spotlight while a stern bald teacher looms behind him.', 'whiplash solo spotlight drummer pounds red kit beneath stern bald teacher looms him', ARRAY['Every beat can be heard backstage', 'The music demanded more than applause']::text[]),
  ('419-pop.webp', 'Джазовый клуб: взлетающие клавиши', 'Мужчина играет на пианино среди гостей клуба; клавиши поднимаются и извиваются в воздухе, а рядом артист с саксофоном.', 'джазовый клуб пианино рояль музыкант клавиши саксофон бар сцена публика', ARRAY['Клавиши решили танцевать без музыканта', 'Вечерний концерт вышел из инструмента']::text[], 'Jazz Club: Flying Piano Keys', 'A man plays piano in a club while keys rise into the air and a saxophonist performs nearby.', 'jazz club flying piano keys man plays rise air saxophonist performs nearby', ARRAY['The keys decided to dance without the pianist', 'The evening concert escaped the instrument']::text[]),
  ('420-pop.webp', 'Бейсбольный судья и удар', 'Мужчина в чёрной форме судьи широко разводит руки на бейсбольном поле, пока ловец в защитной маске сидит у базы.', 'бейсбол судья арбитр ловец мяч бита стадион домашняя база спорт трибуны', ARRAY['Решение было видно с последнего ряда', 'Сегодня спорить с человеком в чёрном бесполезно']::text[], 'Baseball Umpire and the Hit', 'An umpire in black spreads his arms on a baseball field as a masked catcher crouches by the plate.', 'baseball umpire hit black spreads arms field masked catcher crouches plate', ARRAY['The decision was visible from the last row', 'There is no arguing with the man in black today']::text[]),
  ('421-pop.webp', 'Охотник × Охотник: опасная горка', 'Двое мальчишек — один в зелёном, другой седой — бегут по крутой дорожке внутри огромного прозрачного тоннеля.', 'Охотник × Охотник Hunter x Hunter Гон Киллуа зелёная одежда белые волосы дети тоннель спуск приключение', ARRAY['Экзамен внезапно превратился в горку', 'Дружба проверяется на полном ходу']::text[], 'Hunter x Hunter: Dangerous Slide', 'Two boys in green and white run down a steep path inside an enormous transparent tunnel.', 'hunter dangerous slide boys green white run steep path enormous transparent tunnel', ARRAY['The exam turned into a slide', 'Friendship is tested at full speed']::text[]),
  ('422-pop.webp', 'Гинтама: пёс на волне', 'Огромный белый пёс везёт двух спутников сквозь бурную синюю волну на улице с японскими фонариками.', 'Гинтама Gintama Садахару Гинтоки Кагура белый огромный пёс волна вода японская улица фонари', ARRAY['Водный транспорт внезапно залаял', 'Улица решила выдать приключение с брызгами']::text[], 'Gintama: Dog on a Wave', 'A huge white dog carries two riders through a wild blue wave on a street with Japanese lanterns.', 'gintama dog wave white carries riders wild blue street japanese lanterns', ARRAY['The water transport suddenly barked', 'The street served an adventure with splashes']::text[]),
  ('423-pop.webp', 'Самурай Чамплу: схватка на мостках', 'Два самурая с мечами сходятся на узких деревянных помостах над водой у японских домов.', 'Самурай Чамплу Samurai Champloo Мугэн Дзин самураи катаны мечи деревянные мостки вода японский город', ARRAY['Места для спора осталось на одну доску', 'У кого-то сегодня слишком короткий мост']::text[], 'Samurai Champloo: Duel on Planks', 'Two swordsmen meet on narrow wooden boards above water beside Japanese houses.', 'samurai champloo duel planks swordsmen meet narrow wooden boards water beside japanese houses', ARRAY['There is only one plank of room for the argument', 'Someone has a very short bridge today']::text[]),
  ('424-pop.webp', 'Монолог Фармацевта: зелёный опыт', 'Девушка с заколотыми волосами внимательно смотрит на зелёный дым в стеклянном сосуде среди лекарственных трав.', 'Монолог Фармацевта The Apothecary Diaries Маомао аптекарь лекарство зелёный дым колба травы дворец', ARRAY['Рецепт светится подозрительно красиво', 'Любопытство снова закипело в стакане']::text[], 'The Apothecary Diaries: Green Experiment', 'A girl with pinned hair studies green vapor in a glass vessel amid medicinal herbs.', 'apothecary diaries green experiment girl pinned hair studies vapor glass vessel amid medicinal herbs', ARRAY['The recipe glows suspiciously beautifully', 'Curiosity is boiling in a glass again']::text[]),
  ('425-pop.webp', 'Аркейн: опыт двух сестёр', 'Две ярковолосые девушки стоят над светящимся механизмом и чертежами в сумрачном индустриальном городе.', 'Аркейн Arcane Вай Джинкс Пилтовер Заун синие волосы розовые волосы магия хекстек механизм чертёж', ARRAY['Две идеи встретились над опасным изобретением', 'Этот город светится даже во время ссоры']::text[], 'Arcane: The Sisters'' Experiment', 'Two brightly haired girls study a glowing machine and blueprints in a dark industrial city.', 'arcane sisters experiment brightly haired girls study glowing machine blueprints industrial city', ARRAY['Two ideas met over a dangerous invention', 'The city glows even when they argue']::text[]),
  ('426-pop.webp', 'Крутой учитель Онидзука: мотоцикл в классе', 'Светловолосый учитель в белом костюме присел на мотоцикл прямо в школьном классе у парт и доски.', 'Крутой учитель Онидзука GTO Онидзука учитель мотоцикл школа класс парты доска белый костюм', ARRAY['До урока добрались прямо на колёсах', 'Учебный план не предусматривал парковку']::text[], 'Great Teacher Onizuka: Motorcycle in Class', 'A blond teacher in white sits on a motorcycle in a classroom among desks and a blackboard.', 'great teacher onizuka motorcycle class blond white sits classroom desks blackboard gto', ARRAY['He arrived at the lesson on two wheels', 'The curriculum forgot to allow for parking']::text[]),
  ('427-pop.webp', 'Миссия невыполнима: спуск на тросах', 'Агент в чёрном висит горизонтально над сияющим объектом, уклоняясь от красных лазерных лучей в охраняемой комнате.', 'Миссия невыполнима Mission Impossible Итан Хант агент тросы лазеры ограбление охрана секретная комната', ARRAY['Пол не входит в план операции', 'Самое важное — не чихнуть посреди полёта']::text[], 'Mission: Impossible: Suspended Agent', 'A black-clad agent hangs above a glowing object, avoiding red lasers in a guarded room.', 'mission impossible suspended agent black-clad hangs glowing object avoiding red lasers guarded room', ARRAY['The floor is not part of the plan', 'The key is not to sneeze midair']::text[]),
  ('428-pop.webp', 'Рокки: бег по ступеням', 'Боксёр в сером спортивном костюме бежит вверх по широкой лестнице к огромной красной боксёрской перчатке на рассвете.', 'Рокки Rocky Бальбоа боксёр тренировка лестница Филадельфия перчатка бег рассвет', ARRAY['Победа начинается до первого удара', 'Самая трудная драка сегодня — с лестницей']::text[], 'Rocky: Running Up the Steps', 'A boxer in gray runs up broad steps toward a giant red boxing glove at sunrise.', 'rocky running steps boxer gray runs broad red boxing glove sunrise', ARRAY['Victory begins before the first punch', 'The hardest fight today is with the stairs']::text[]),
  ('429-pop.webp', 'Люди в чёрном: переход с пришельцами', 'Двое агентов в чёрных костюмах и очках стоят на улице среди нелепых инопланетян, такси и зебры.', 'Люди в чёрном Men in Black агенты Кей Джей чёрные костюмы очки пришельцы инопланетяне такси зебра город', ARRAY['Утренний переход проверяет паспорт у всех', 'Обычный город показал необычных пассажиров']::text[], 'Men in Black: Alien Crossing', 'Two agents in black suits and glasses stand among bizarre aliens, taxis and a zebra on a city street.', 'men black alien crossing agents suits glasses stand bizarre aliens taxis zebra city street', ARRAY['The morning crossing checks everyone''s passport', 'An ordinary city revealed unusual passengers']::text[]),
  ('430-pop.webp', 'Доктор Хаус: диагноз на доске', 'Уставший врач в белом халате рисует на доске человека, лимон и зонт, пока коллеги внимательно смотрят.', 'Доктор Хаус House доктор врач Грегори Хаус больница диагноз доска схема лимон зонт коллеги', ARRAY['Диагноз явно не помещается в учебник', 'Лимон оказался частью медицинской загадки']::text[], 'House M.D.: Diagnosis on the Board', 'A tired doctor in a white coat draws a person, lemon and umbrella on a board as colleagues watch.', 'house diagnosis board tired doctor white coat draws person lemon umbrella colleagues watch', ARRAY['The diagnosis will not fit in any textbook', 'A lemon became part of the medical mystery']::text[]),
  ('431-pop.webp', 'Магическая битва: городская воронка', 'Белокурый маг с закрытыми глазами и его ученик смотрят на огромную чёрно-фиолетовую воронку, втягивающую дома.', 'Магическая битва Jujutsu Kaisen Годзё Итадори маг проклятие воронка чёрная дыра город дома', ARRAY['На этой улице гравитация поссорилась с магией', 'Учитель снова оставил городу сложное домашнее задание']::text[], 'Jujutsu Kaisen: City Vortex', 'A blond magician with covered eyes and his student watch a black-and-purple vortex pull houses inward.', 'jujutsu kaisen city vortex blond magician covered eyes student watch black-and-purple pull houses inward', ARRAY['Gravity and magic quarreled on this street', 'The teacher assigned the city difficult homework']::text[]),
  ('432-pop.webp', 'Аватар: полёт над Пандорой', 'Синий наездник летит верхом на крылатом существе между парящими скалами и светящимся лесом.', 'Аватар Avatar Пандора На''ви синий всадник икран летающее существо парящие горы лес', ARRAY['Здесь даже дорога не держится земли', 'Поездка на работу проходит между облаками']::text[], 'Avatar: Flight Over Pandora', 'A blue rider flies a winged creature between floating cliffs and glowing forest.', 'avatar flight pandora blue rider flies winged creature between floating cliffs glowing forest', ARRAY['Even the roads here cannot stay on the ground', 'The commute runs between clouds']::text[]),
  ('433-pop.webp', 'Симпсоны: диван среди воды', 'Жёлтая семейная пара сидит на оранжевом диване в затопленной гостиной, пока телевизор льёт воду прямо в комнату.', 'Симпсоны The Simpsons Гомер Мардж жёлтые персонажи оранжевый диван гостиная телевизор потоп вода пончик', ARRAY['Вечер у телевизора вышел из берегов', 'Диван держится лучше всей гостиной']::text[], 'The Simpsons: Couch in Floodwater', 'A yellow couple sits on an orange couch in a flooded living room while the television pours water inside.', 'simpsons couch floodwater yellow couple sits orange flooded living room television pours water', ARRAY['The evening show overflowed its banks', 'The couch held up better than the room']::text[]),
  ('434-pop.webp', 'Фрирен: звёздный привал', 'Светловолосая эльфийка и спутники сидят у маленького костра над облаками под густым звёздным небом.', 'Фрирен провожающая в последний путь Frieren эльфийка спутники костёр звёзды ночь путешествие магия', ARRAY['Долгая дорога сделала ночь короче', 'У костра наконец хватило времени на молчание']::text[], 'Frieren: Camp Under Stars', 'A blond elf and companions gather around a small fire above clouds beneath a thick starry sky.', 'frieren camp stars blond elf companions gather fire clouds beneath thick starry sky', ARRAY['The long road made the night feel shorter', 'At the fire they finally had time for silence']::text[]),
  ('435-pop.webp', 'Рокки: тени в ринге', 'Боксёр в красных перчатках сражается на ринге; под прожекторами тени соперников играют в шахматы.', 'Рокки Rocky Бальбоа бокс ринг перчатки соперник судья прожекторы шахматы тень', ARRAY['Этот бой выиграют не только кулаками', 'На полу уже идёт другая партия']::text[], 'Rocky: Shadows in the Ring', 'A boxer in red gloves fights in the ring as the fighters'' shadows play chess beneath the lights.', 'rocky shadows ring boxer red gloves fights fighters play chess beneath lights', ARRAY['This fight will take more than fists', 'There is another game already underway on the floor']::text[]),
  ('436-pop.webp', 'Аватар: светящееся дерево', 'Двое синих жителей Пандоры касаются светящихся розовых корней огромного дерева в ночном лесу.', 'Аватар Avatar На''ви Джейк Нейтири Пандора дерево душ розовые корни биолюминесценция лес', ARRAY['Дерево ответило раньше собеседника', 'Самое древнее здесь светится сильнее фонаря']::text[], 'Avatar: Glowing Tree', 'Two blue inhabitants of Pandora touch pink glowing roots of an enormous tree in a night forest.', 'avatar glowing tree blue inhabitants pandora touch pink roots enormous night forest', ARRAY['The tree answered before its visitor', 'The oldest thing here shines brighter than a lamp']::text[]),
  ('437-pop.webp', 'Губка Боб: подводный ресторан', 'Губка, краб и соседи собрались в подводной закусочной вокруг стола; за окном плавают морские существа.', 'Губка Боб SpongeBob Спанч Боб мистер Крабс Бикини Боттом подводный ресторан закусочная море', ARRAY['Обед опять ушёл под воду', 'За смену здесь отвечают те, кто дышит пузырями']::text[], 'SpongeBob: Underwater Restaurant', 'A sponge, crab and neighbors gather around a table in an undersea diner as sea creatures swim outside.', 'spongebob underwater restaurant sponge crab neighbors gather table undersea diner sea creatures swim', ARRAY['Lunch went underwater again', 'The shift is run by creatures that breathe bubbles']::text[]),
  ('438-pop.webp', 'Крутой учитель Онидзука: урок с привидением', 'Светловолосый учитель в сером костюме указывает на класс, пока за его спиной маячит дружелюбное фиолетовое привидение.', 'Крутой учитель Онидзука GTO Онидзука учитель школьный класс костюм ученики привидение урок', ARRAY['На урок явился ученик без тела', 'Учитель делает вид, что ничего странного не происходит']::text[], 'Great Teacher Onizuka: Ghost Lesson', 'A blond teacher points across his classroom while a friendly purple ghost floats behind him.', 'great teacher onizuka ghost lesson blond points classroom friendly purple floats him gto', ARRAY['A student without a body came to class', 'The teacher pretends nothing strange is happening']::text[]),
  ('439-pop.webp', 'Один дома: ловушка у ёлки', 'Мальчик у рождественской ёлки натягивает верёвку, пока снизу к лестнице подбираются два незадачливых грабителя.', 'Один дома Home Alone Кевин ёлка Рождество грабители ловушка верёвка лестница дом', ARRAY['Подарок для незваных гостей уже заряжен', 'В этом доме ребёнок отвечает за безопасность']::text[], 'Home Alone: Trap by the Tree', 'A boy stretches a rope beside a Christmas tree while two hapless burglars approach the stairs.', 'home alone trap tree boy stretches rope beside christmas hapless burglars approach stairs', ARRAY['The gift for uninvited guests is armed', 'The child runs home security here']::text[]),
  ('440-pop.webp', 'Волшебник страны Оз: жёлтая дорога', 'Девочка и трое спутников идут по жёлтой кирпичной дорожке к зелёному городу среди маков; под ней будто клавиши пианино.', 'Волшебник страны Оз Дороти пугало железный дровосек трусливый лев дорога из жёлтого кирпича Изумрудный город маки', ARRAY['У маршрута оказался очень музыкальный характер', 'Четверо ищут ответы у зелёного горизонта']::text[], 'The Wizard of Oz: Yellow Road', 'A girl and three companions follow yellow bricks toward a green city through poppies above piano-like keys.', 'wizard yellow road girl companions follow bricks green city poppies piano-like keys', ARRAY['The route has a musical personality', 'Four travelers seek answers on the green horizon']::text[]),
  ('441-pop.webp', 'Бруклин 9-9: полицейская награда', 'Детектив в рубашке радостно поднимает блестящую награду в полицейском участке, пока коллеги смотрят с недоверием.', 'Бруклин 9-9 Brooklyn Nine-Nine Джейк Перальта капитан Холт полицейский участок детектив награда трофей', ARRAY['Триумф не убедил даже коллег', 'В участке опять празднуют непонятную победу']::text[], 'Brooklyn Nine-Nine: Police Award', 'A detective lifts a shiny award in the precinct while colleagues look on in disbelief.', 'brooklyn nine-nine police award detective lifts shiny precinct colleagues look disbelief', ARRAY['The triumph did not convince the colleagues', 'The precinct is celebrating another mysterious victory']::text[]),
  ('442-pop.webp', 'Моя геройская академия: наставник', 'Могучий герой в красно-синем костюме показывает большой палец мальчику в зелёном на крыше на фоне города.', 'Моя геройская академия My Hero Academia Всемогущий Деку Идзуку Мидория супергерой наставник костюм крыша', ARRAY['Одного жеста хватило для целой мечты', 'Будущее города начинается с неловкого ученика']::text[], 'My Hero Academia: Mentor', 'A mighty hero in red and blue gives a thumbs-up to a boy in green on a city rooftop.', 'hero academia mentor mighty red blue gives thumbs-up boy green city rooftop', ARRAY['One gesture carried a whole dream', 'The city''s future starts with an awkward pupil']::text[]),
  ('443-pop.webp', 'Код Гиас: красный плащ', 'Юноша в красном плаще руководит белыми шахматными фигурами на площади перед мрачным дворцом.', 'Код Гиас Code Geass Лелуш шахматы белые фигуры король красный плащ дворец приказ', ARRAY['Шахматная доска выросла до размеров площади', 'Один ход переставил целую страну']::text[], 'Code Geass: Red Cloak', 'A young man in red commands white chess pieces in a square outside a grim palace.', 'code geass red cloak man commands white chess pieces square grim palace', ARRAY['The chessboard grew to the size of a plaza', 'One move rearranged a whole country']::text[]),
  ('444-pop.webp', 'Паразиты: два этажа жизни', 'Роскошная светлая квартира стоит над тесным полуподвалом; лестница соединяет богатую семью наверху с жильцом внизу.', 'Паразиты Parasite фильм семья Ким семья Пак богатый дом полуподвал лестница дождь социальное неравенство', ARRAY['Один дом, а погода на этажах разная', 'Секрет этой лестницы хранится внизу']::text[], 'Parasite: Two Floors of Life', 'A bright luxury apartment sits above a cramped basement and stairs connect a rich family to a tenant below.', 'parasite floors life luxury apartment sits cramped basement stairs connect rich family tenant', ARRAY['One house, but the weather changes between floors', 'The secret of these stairs lives below']::text[]),
  ('445-pop.webp', 'Дрянные девчонки: розовая столовая', 'Три девушки за розовым столиком в школьной столовой перешёптываются над тетрадью, а вокруг закручиваются бумажные сердца.', 'Дрянные девчонки Mean Girls Регина Джордж Пластик школьная столовая розовый стол сплетни девочки тетрадь', ARRAY['Разговор за обедом разросся до торнадо', 'У этой тетради слишком много слушателей']::text[], 'Mean Girls: Pink Cafeteria', 'Three girls at a pink school cafeteria table whisper over a notebook as paper hearts swirl around them.', 'mean girls pink cafeteria school table whisper notebook paper hearts swirl', ARRAY['A lunch conversation became a tornado', 'That notebook has too many listeners']::text[]),
  ('446-pop.webp', 'Достать ножи: семейный ужин', 'Сыщик в белом костюме рассматривает странную улику на ковре, пока вокруг него стоят нарядные гости семейного дома.', 'Достать ножи Knives Out Бенуа Блан детектив сыщик семейный ужин подозреваемые богатый дом улика', ARRAY['На ужин подали новую загадку', 'У каждого гостя найдётся своя версия']::text[], 'Knives Out: Family Dinner', 'A detective in white studies a strange clue on a carpet while dressed-up family guests stand around.', 'knives family dinner detective white studies strange clue carpet dressed-up guests stand', ARRAY['A fresh mystery was served for dinner', 'Every guest has their own version']::text[]),
  ('447-pop.webp', 'Тихое место: вечер шёпотом', 'Семья сидит за столом при свече в тёмном доме; за окном длинная тревожная тень, и никто не решается шуметь.', 'Тихое место A Quiet Place семья молчание свеча дом окно тень ночь ужин монстр', ARRAY['Сегодня за ужином говорят только глазами', 'Одно слово может разбудить темноту']::text[], 'A Quiet Place: Whispered Evening', 'A family sits by candlelight at dinner as a long threatening shadow waits outside the dark house.', 'quiet place whispered evening family sits candlelight dinner threatening shadow waits house', ARRAY['At dinner they speak only with their eyes', 'One word could wake the darkness']::text[]),
  ('448-pop.webp', 'Секретные материалы: след на траве', 'Двое следователей с фонарями изучают круг на ночном поле, над которым зависла сияющая летающая тарелка.', 'Секретные материалы X-Files Малдер Скалли НЛО летающая тарелка фонари след трава поле ночь', ARRAY['Кто-то оставил подпись на газоне', 'Ночное небо опять не хочет давать показания']::text[], 'The X-Files: Mark in the Grass', 'Two flashlight-carrying investigators study a circle in a night field beneath a glowing UFO.', 'x-files mark grass flashlight-carrying investigators study circle night field beneath glowing ufo', ARRAY['Someone left a signature on the lawn', 'The night sky refuses to testify again']::text[]),
  ('449-pop.webp', 'Паразиты: дом на склоне', 'Нарядный освещённый дом стоит на верхнем краю обрыва, а человек из тёмного подвала снизу смотрит на него через узкое окно.', 'Паразиты Parasite богатый дом подвал бедность лестница окно склон семья социальное неравенство', ARRAY['Вид из окна зависит от этажа', 'До чужого праздника всего одна пропасть']::text[], 'Parasite: House on the Slope', 'A brightly lit mansion stands at a cliff edge while someone in a dark basement looks up through a narrow window.', 'parasite house slope brightly lit mansion stands cliff edge someone basement looks narrow window', ARRAY['The view depends on the floor', 'Only one chasm lies between them and the party']::text[]),
  ('450-pop.webp', 'Футурама: полёт через космос', 'Рыжий курьер, девушка с одним глазом и робот летят в открытом корабле мимо планет, а гигантская чашка кофе кружится над ними.', 'Футурама Futurama Фрай Лила Бендер космический корабль один глаз робот планеты кофе доставка', ARRAY['Маршрут проложили через завтрак галактики', 'Команда снова свернула слишком далеко']::text[], 'Futurama: Flight Through Space', 'A red-haired courier, one-eyed woman and robot fly past planets in an open ship beneath a giant floating coffee cup.', 'futurama flight space red-haired courier one-eyed woman robot fly past planets open ship beneath floating coffee cup', ARRAY['Their route ran through the galaxy''s breakfast', 'The crew took a wrong turn again']::text[]),
  ('451-pop.webp', 'Блич: мечи на закате', 'Рыжеволосый мечник в чёрном плаще стоит на мокрой улице перед двумя противниками; в лужах отражаются силуэты.', 'Блич Bleach Ичиго Куросаки шинигами катана мечи чёрный плащ мокрая улица закат', ARRAY['Дождь здесь отражает больше врагов, чем видно', 'На перекрёстке не осталось места для мирного разговора']::text[], 'Bleach: Swords at Sunset', 'A red-haired swordsman in a black cloak faces two opponents on a wet street, their silhouettes reflected in puddles.', 'bleach swords sunset red-haired swordsman black cloak faces opponents wet street silhouettes reflected puddles', ARRAY['The rain reflects more enemies than there are', 'There is no room left for small talk at this crossing']::text[]),
  ('452-pop.webp', 'О движении Земли: звёздная модель', 'Юноша при свече изучает сложную модель планет в старинной комнате; бумажные книги будто вылетают в открытый звёздный космос.', 'О движении Земли Orb астрономия гелиоцентризм планеты модель Солнце книги свеча учёный звёзды', ARRAY['Одна догадка переставила весь небосвод', 'Книги спорят о том, кто вокруг кого ходит']::text[], 'On the Movements of the Earth: Star Model', 'A young man studies a complex planetary model by candlelight in an old room as paper books drift into space.', 'movements earth star model man studies complex planetary candlelight room paper books drift space orb', ARRAY['One idea rearranged the entire sky', 'The books cannot agree on who orbits whom']::text[]),
  ('453-pop.webp', 'Шрек: гости у болота', 'Зелёный огр смотрит из своего домика на толпу сказочных гостей и деревянный мост над болотом.', 'Шрек Shrek огр болото домик осёл сказочные существа мост толпа зелёный великан', ARRAY['Домашний покой отменили сказочные гости', 'Самое уютное болото внезапно стало проходным двором']::text[], 'Shrek: Guests at the Swamp', 'A green ogre looks out of his cottage at a crowd of fairy-tale visitors by a wooden bridge over the swamp.', 'shrek guests swamp green ogre looks cottage crowd fairy-tale visitors wooden bridge', ARRAY['Peace at home has been canceled by guests', 'The coziest swamp became a public thoroughfare']::text[]),
  ('454-pop.webp', 'Наследники: маски на балу', 'Серьёзный мужчина в смокинге поправляет маску перед зеркалом; в отражении за ним кружится роскошный бал.', 'Наследники Succession семья Рой богатство власть смокинг маска зеркало бал дворец гости', ARRAY['Парадное лицо пришлось выбирать отдельно', 'На этом празднике каждый скрывает свою игру']::text[], 'Succession: Masks at the Ball', 'A stern man in a tuxedo adjusts a mask before a mirror; behind him a lavish ball spins in the reflection.', 'succession masks ball stern man tuxedo adjusts mask mirror him lavish spins reflection', ARRAY['He had to choose a formal face separately', 'Everyone at this party is hiding a different game']::text[]),
  ('455-pop.webp', 'Тихое место: дети на мосту', 'Двое детей осторожно идут по шаткому деревянному мосту ночью, глядя в сторону тёмных полей и необычного неба.', 'Тихое место A Quiet Place дети семья деревянный мост ночь поле осторожность тишина', ARRAY['Каждая доска звучит слишком громко', 'Мост безопасен, пока никто не заговорил']::text[], 'A Quiet Place: Children on the Bridge', 'Two children tiptoe across a shaky wooden bridge at night, looking toward dark fields and an unusual sky.', 'quiet place children bridge tiptoe shaky wooden night looking fields unusual sky', ARRAY['Every plank sounds far too loud', 'The bridge is safe as long as nobody speaks']::text[]),
  ('456-pop.webp', 'Шрек: дракон у замка', 'Зелёный огр, принцесса и осёл летят на красном драконе вокруг сказочной башни над пропастью.', 'Шрек Shrek Фиона Осёл Дракониха красный дракон огр башня замок полёт', ARRAY['Обратный путь из замка выбрали с крыльями', 'Спасение пришло слишком огненным транспортом']::text[], 'Shrek: Dragon at the Castle', 'A green ogre, a princess and a donkey fly on a red dragon around a fairy-tale tower over a chasm.', 'shrek dragon castle green ogre princess donkey fly red fairy-tale tower chasm', ARRAY['They chose the route home with wings', 'Rescue arrived on unexpectedly fiery transport']::text[]),
  ('457-pop.webp', 'Доктор Хаус: пациент в смотровой', 'Врач с тростью объясняет схему на доске, пока пациент в кресле и коллеги пытаются понять необычный диагноз.', 'Доктор Хаус House Грегори Хаус врач трость пациент больница доска схема диагноз коллеги', ARRAY['Пациент оказался сложнее всей доски', 'Доктор снова лечит загадку раньше человека']::text[], 'House M.D.: A Patient in the Exam Room', 'A doctor with a cane explains a diagram on a board while a patient and colleagues puzzle over an odd diagnosis.', 'house patient exam room doctor cane explains diagram board colleagues puzzle odd diagnosis', ARRAY['The patient was harder than the whole board', 'The doctor is treating the mystery before the person again']::text[]),
  ('458-pop.webp', 'Маска: зелёный танец', 'Человек с ярко-зелёным лицом в зелёном костюме взлетает над сценой клуба, окружённый танцовщицами и смехом.', 'Маска The Mask Стэнли Ипкис зелёное лицо костюм шляпа танец ночной клуб сцена', ARRAY['Скромность осталась где-то за кулисами', 'Вечеринка внезапно обрела сверхспособности']::text[], 'The Mask: Green Dance', 'A bright green-faced man in a green suit leaps above a nightclub stage amid dancers and laughter.', 'mask green dance green-faced man suit leaps nightclub stage amid dancers laughter', ARRAY['Modesty stayed somewhere backstage', 'The party suddenly developed superpowers']::text[]),
  ('459-pop.webp', 'Маска: собака в карнавале', 'Зелёнолицый танцор в шляпе показывает трюк перед зеркалом, а маленькая собака в ярком карнавальном наряде смотрит на него.', 'Маска The Mask зелёное лицо шляпа собака Майло карнавал зеркало танец жёлтые шарики', ARRAY['Даже пёс не ожидал такого номера', 'Зеркало не успело за новым лицом']::text[], 'The Mask: Dog at Carnival', 'A green-faced dancer in a hat performs before a mirror while a small dog in colorful carnival clothes watches.', 'mask dog carnival green-faced dancer hat performs mirror clothes watches', ARRAY['Even the dog did not expect that act', 'The mirror could not keep up with the new face']::text[]),
  ('460-pop.webp', 'Мэри Поппинс: полёт с зонтом', 'Няня с зонтом летит над крышами Лондона, пока дети и другие зонты следуют за ней в ветреном небе.', 'Мэри Поппинс Mary Poppins няня зонтик полёт дети крыши Лондон ветер', ARRAY['Домой сегодня возвращаются по воздуху', 'Прогулка началась выше дымоходов']::text[], 'Mary Poppins: Flight with an Umbrella', 'A nanny flies with an umbrella above London rooftops while children and other umbrellas follow through the windy sky.', 'mary poppins flight umbrella nanny flies london rooftops children other umbrellas follow windy sky', ARRAY['Everyone is going home by air today', 'The walk began above the chimneys']::text[]),
  ('461-pop.webp', 'Люди в чёрном: посетитель в офисе', 'Двое агентов в чёрном сидят за столом напротив огромного синего пришельца с щупальцами в городском офисе.', 'Люди в чёрном Men in Black агенты Кей Джей пришелец осьминог щупальца офис допрос костюмы', ARRAY['На собеседование явился гость без анкеты', 'В кабинете больше не хватает стульев']::text[], 'Men in Black: An Office Visitor', 'Two agents in black sit at a desk opposite an enormous blue tentacled alien in a city office.', 'men black office visitor agents sit desk opposite enormous blue tentacled alien city', ARRAY['A job applicant arrived without a form', 'This office suddenly needs more chairs']::text[]),
  ('462-pop.webp', 'Мэри Поппинс: уборка на потолке', 'Няня с зонтом смотрит, как дети, мебель и игрушки парят под потолком нарядной комнаты.', 'Мэри Поппинс Mary Poppins няня зонтик магия дети комната игрушки полёт уборка потолок', ARRAY['Комната решила убрать себя вверх', 'Домашнее задание оторвалось от пола']::text[], 'Mary Poppins: Cleaning the Ceiling', 'A nanny with an umbrella watches children, furniture and toys float beneath the ceiling of an elegant room.', 'mary poppins cleaning ceiling nanny umbrella watches children furniture toys float beneath elegant room', ARRAY['The room decided to tidy itself upward', 'Homework lifted right off the floor']::text[]),
  ('463-pop.webp', 'Король Лев: рассвет над саванной', 'Лев стоит на высокой скале над саванной, где солнце освещает жирафов, слона и других животных.', 'Король Лев Lion King Симба Муфаса скала Прайд-Рок саванна рассвет жирафы слон животные', ARRAY['Утро объявили с самой высокой трибуны', 'На это место смотрит вся саванна']::text[], 'The Lion King: Savannah Sunrise', 'A lion stands high on a rock above the savannah as sunshine reaches giraffes, an elephant and other animals.', 'lion king savannah sunrise stands high rock sunshine reaches giraffes elephant other animals', ARRAY['Morning was announced from the highest platform', 'The whole savannah is watching that place']::text[]),
  ('464-pop.webp', 'Один дома: засадный вечер', 'Мальчик спрятался у ёлки в тёплой гостиной, а грабители в чёрном неожиданно попали в его самодельную ловушку.', 'Один дома Home Alone Кевин грабители Рождество ёлка дом ловушка верёвка игрушечная машинка', ARRAY['Незваных гостей встречают по особой программе', 'Маленький хозяин подготовил большой сюрприз']::text[], 'Home Alone: An Evening Ambush', 'A boy hides by a Christmas tree in a warm living room while burglars fall into his homemade trap.', 'home alone evening ambush boy hides christmas tree warm living room burglars fall homemade trap', ARRAY['Uninvited guests get a special welcome', 'A little host prepared a very big surprise']::text[]),
  ('465-pop.webp', 'История игрушек: космонавт и ковбой', 'Ковбой в шляпе и космический рейнджер спорят среди детских кубиков и игрушечной ракеты в комнате.', 'История игрушек Toy Story Вуди Базз Лайтер ковбой космонавт игрушки ракета кубики детская', ARRAY['Кому принадлежит эта планета из кубиков?', 'Два героя не поделили детскую комнату']::text[], 'Toy Story: Astronaut and Cowboy', 'A hat-wearing cowboy and a space ranger argue among blocks and a toy rocket in a child''s room.', 'toy story astronaut cowboy hat-wearing space ranger argue blocks rocket child room', ARRAY['Who owns this planet made of blocks?', 'Two heroes could not share the playroom']::text[]),
  ('466-pop.webp', 'История игрушек: игрушки в космосе', 'Зелёные трёхглазые игрушки смотрят на огромную розовую плюшевую фигуру в ярком космическом автомате.', 'История игрушек Toy Story зелёные пришельцы трёхглазые игрушки плюшевый медведь космос автомат ракета', ARRAY['Маленькие зрители увидели слишком большую игрушку', 'Космическая экспедиция задержалась в детской']::text[], 'Toy Story: Toys in Space', 'Small green three-eyed toys stare at a huge pink plush figure inside a bright space-themed arcade machine.', 'toy story toys space green three-eyed stare pink plush figure space-themed arcade machine', ARRAY['The little spectators spotted a toy too big for them', 'The space mission got held up in the nursery']::text[]),
  ('467-pop.webp', 'Дрянные девчонки: школьный блокнот', 'Девушка в розовом листает книгу, из которой вихрем вылетают записки; одноклассницы тянутся к страницам.', 'Дрянные девчонки Mean Girls Регина Джордж школа розовая книга блокнот сплетни записки школьницы', ARRAY['Одна страница разнесла новости по всей школе', 'Записки устроили собственный ураган']::text[], 'Mean Girls: School Notebook', 'A girl in pink flips through a book as notes whirl from its pages and classmates reach for them.', 'mean girls school notebook girl pink flips book notes whirl pages classmates reach', ARRAY['One page spread news through the whole school', 'The notes started a storm of their own']::text[]),
  ('468-pop.webp', 'Дьявол носит Prada: примерка', 'Строгая женщина в ярко-розовом пальто показывает одежду молодой сотруднице перед зеркалом в роскошном магазине.', 'Дьявол носит Prada Миранда Пристли Энди мода одежда розовое пальто зеркало бутик примерка', ARRAY['Один взгляд решил судьбу гардероба', 'Примерка оказалась труднее собеседования']::text[], 'The Devil Wears Prada: Fitting Room', 'A stern woman in a vivid pink coat shows clothes to a young employee before a mirror in a luxury store.', 'devil wears prada fitting room stern woman vivid pink coat shows clothes employee mirror luxury store', ARRAY['One glance decided the wardrobe''s fate', 'Trying on clothes was harder than the interview']::text[]),
  ('469-pop.webp', 'Вверх: дом отправился в полёт', 'Небольшой домик поднимают в воздух большие птицы над морем, а пожилой мужчина с берега тянет к нему руки.', 'Вверх Up Карл Фредриксен дом полёт птицы море берег старик путешествие', ARRAY['Дом решил переехать без хозяина', 'На такой переезд не хватит грузовика']::text[], 'Up: The House Takes Flight', 'Large birds lift a small house above the sea while an elderly man reaches toward it from shore.', 'house takes flight large birds lift sea elderly man reaches shore', ARRAY['The house decided to move without its owner', 'No moving truck could handle this relocation']::text[]),
  ('470-pop.webp', 'Клан Сопрано: семейный ужин', 'Влиятельный мужчина во главе длинного стола пытается удержать огромное блюдо пасты, пока гости наблюдают и спорят.', 'Клан Сопрано The Sopranos Тони Сопрано мафия семья ужин паста ресторан длинный стол', ARRAY['На семейном совете даже ужин нервничает', 'Главное блюдо оказалось слишком влиятельным']::text[], 'The Sopranos: Family Dinner', 'An influential man at the head of a long table struggles to hold an enormous pasta dish as guests watch and argue.', 'sopranos family dinner influential man head table struggles hold enormous pasta dish guests watch argue', ARRAY['Even dinner is nervous at this family meeting', 'The main course has too much influence']::text[]),
  ('471-pop.webp', 'Прослушка: ночной телефон', 'Старый уличный телефон с длинным проводом висит над дождливым городом; в машине за окном наблюдает человек.', 'Прослушка The Wire телефон провод телефонная будка слежка детектив машина дождь город полиция', ARRAY['Разговор давно слушают не только собеседники', 'Провод знает слишком много о ночном городе']::text[], 'The Wire: Nighttime Telephone', 'An old public phone with a long cable hangs above a rainy city; someone watches from a car beyond the window.', 'wire nighttime telephone public phone cable hangs rainy city someone watches car beyond window', ARRAY['More than one person is listening to this call', 'The wire knows too much about the city at night']::text[]),
  ('472-pop.webp', 'Бруклин 9-9: бросок через улицу', 'Парень и полицейский в форме прыгают у баскетбольного кольца между высокими домами, пока мяч зависает над ними.', 'Бруклин 9-9 Brooklyn Nine-Nine полицейский баскетбол кольцо мяч город улица спортивный спор', ARRAY['Расследование перешло в дополнительное время', 'Сегодня у закона есть право на бросок']::text[], 'Brooklyn Nine-Nine: Street Basketball', 'A young man and a uniformed officer jump toward a basketball hoop between tall buildings as the ball hangs overhead.', 'brooklyn nine-nine street basketball man uniformed officer jump hoop between tall buildings ball hangs overhead', ARRAY['The investigation went into overtime', 'The law has a chance to shoot today']::text[]),
  ('473-pop.webp', 'Баффи: библиотечная схватка', 'Девушка с колом стоит среди старых книг и ящиков, отступая от тёмного чудовища в библиотеке.', 'Баффи истребительница вампиров Buffy девушка кол вампир монстр библиотека книги ящики', ARRAY['В библиотеке снова шумят после закрытия', 'На этот экзамен пришёл гость из темноты']::text[], 'Buffy: Library Fight', 'A girl with a stake stands among old books and crates, backing away from a dark monster in a library.', 'buffy library fight girl stake stands books crates backing away monster', ARRAY['There is noise in the library after closing again', 'A visitor from the dark came for this exam']::text[]),
  ('474-pop.webp', 'Баффи: кладбище ночью', 'Девушка с оружием перескакивает через могильные плиты к чёрному чудовищу под полной луной.', 'Баффи истребительница вампиров Buffy девушка охотница вампир кладбище могилы луна монстр ночь', ARRAY['Ночная прогулка оказалась рабочей сменой', 'У этого кладбища слишком активные жильцы']::text[], 'Buffy: Cemetery at Night', 'A girl with a weapon leaps across headstones toward a black monster under a full moon.', 'buffy cemetery night girl weapon leaps headstones black monster full moon', ARRAY['The night walk turned out to be a work shift', 'This cemetery has far too active residents']::text[]),
  ('475-pop.webp', 'Симпсоны: пончик на пульте', 'Огромный розовый пончик просочился внутрь комнаты с кнопками и рычагами, затопив панель управления глазурью.', 'Симпсоны The Simpsons Гомер пончик розовая глазурь пульт управления кнопки станция', ARRAY['Перерыв на перекус захватил управление', 'Самая сладкая авария случилась на смене']::text[], 'The Simpsons: Doughnut at the Controls', 'A giant pink doughnut spills into a room of switches and levers, flooding the control panel with frosting.', 'simpsons doughnut controls pink spills room switches levers flooding control panel frosting', ARRAY['A snack break seized control', 'The sweetest workplace accident happened on shift']::text[]),
  ('476-pop.webp', 'Острые козырьки: скачки в грязи', 'Трое мужчин в кепках едут на деревянной тележке вдоль грязной улицы промышленного города, выкрикивая что-то зрителям.', 'Острые козырьки Peaky Blinders Томми Шелби кепки тележка лошади скачки грязь фабрики город', ARRAY['Деловую встречу назначили прямо на скачках', 'Кепки снова в грязи, но настроение боевое']::text[], 'Peaky Blinders: Muddy Race', 'Three men in caps ride a wooden cart along a muddy street in an industrial city, calling to onlookers.', 'peaky blinders muddy race men caps ride wooden cart street industrial city calling onlookers', ARRAY['They scheduled the business meeting at the races', 'The caps are muddy again, but spirits are high']::text[]),
  ('477-pop.webp', 'Рик и Морти: овощной портал', 'Безумный учёный и мальчик заглядывают в холодильник, откуда вырываются зелёные спирали и живые овощи с испуганными лицами.', 'Рик и Морти Rick and Morty Рик Морти холодильник портал зелёная спираль овощи морковь огурец', ARRAY['Не открывай холодильник после полуночи', 'Ужин пришёл из другой вселенной']::text[], 'Rick and Morty: Vegetable Portal', 'A mad scientist and a boy peer into a refrigerator where green spirals and frightened living vegetables burst out.', 'rick morty vegetable portal mad scientist boy peer refrigerator where green spirals frightened living vegetables burst', ARRAY['Never open the refrigerator after midnight', 'Dinner arrived from another universe']::text[]),
  ('478-pop.webp', 'Рик и Морти: машины времени', 'Учёный и мальчик сидят за пультом среди ярких зелёных порталов, летающих чашек и круглых космических устройств.', 'Рик и Морти Rick and Morty Рик Морти порталы лаборатория космос пульт машины зелёная энергия', ARRAY['Пульт управления снова ведёт не домой', 'На карте вселенной не нашлось правильного поворота']::text[], 'Rick and Morty: Time Machines', 'A scientist and a boy sit at controls among glowing green portals, flying cups and round space devices.', 'rick morty time machines scientist boy sit controls glowing green portals flying cups round space devices', ARRAY['The controls do not lead home this time either', 'There was no correct turn on the map of the universe']::text[]),
  ('479-pop.webp', 'Сообщество: битва красками', 'Студенты прячутся за яркими баррикадами во дворе колледжа и стреляют цветными шариками друг в друга.', 'Сообщество Community Гриндейл студенты колледж пейнтбол краска баррикада флаг двор', ARRAY['Учебный день перешёл в цветной режим', 'За этот флаг придётся запачкать диплом']::text[], 'Community: Paintball Battle', 'Students hide behind colorful barricades in a college courtyard and fire paintballs at each other.', 'community paintball battle students hide barricades college courtyard fire paintballs other', ARRAY['The school day switched to full color', 'This flag will cost someone a clean diploma']::text[]),
  ('480-pop.webp', 'Сообщество: настольное подземелье', 'Группа студентов собралась вокруг огромного светящегося многогранного кубика и карты с фантастическими монстрами.', 'Сообщество Community Гриндейл настольная игра Dungeons and Dragons D&D кубик студенты фэнтези монстры карта', ARRAY['Домашняя игра стала больше всего класса', 'Один бросок изменил расписание']::text[], 'Community: Tabletop Dungeon', 'Students gather around an enormous glowing polyhedral die and a map filled with fantasy monsters.', 'community tabletop dungeon students gather enormous glowing polyhedral die map filled fantasy monsters dungeons dragons', ARRAY['The tabletop game outgrew the classroom', 'One roll changed the schedule']::text[]),
  ('481-pop.webp', 'Мандалорец: спутник в пустыне', 'Воин в серебристом шлеме присел перед маленьким зелёным существом на пыльной улице пустынного города.', 'Мандалорец The Mandalorian Дин Джарин Грогу малыш Йода броня шлем пустыня звёздные войны', ARRAY['Самый маленький попутчик задаёт маршрут', 'Броня не мешает быть няней']::text[], 'The Mandalorian: Desert Companion', 'A warrior in a silver helmet crouches before a small green creature on a dusty desert-town street.', 'mandalorian desert companion warrior silver helmet crouches green creature dusty desert-town street', ARRAY['The smallest traveler is setting the route', 'Armor does not stop you from babysitting']::text[]),
  ('482-pop.webp', 'Аркейн: погоня по трубам', 'Две девушки с синими и розовыми волосами несутся на самодельной машине по трубам над индустриальным городом.', 'Аркейн Arcane Джинкс Вай синие волосы розовые волосы Заун Пилтовер трубы машина погоня город', ARRAY['Городская труба оказалась скоростной трассой', 'Семейный спор перешёл на полный газ']::text[], 'Arcane: Chase on the Pipes', 'Two young women with blue and pink hair race a homemade vehicle along pipes above an industrial city.', 'arcane chase pipes women blue pink hair race homemade vehicle industrial city', ARRAY['A city pipe became an expressway', 'The family argument reached full speed']::text[]),
  ('483-pop.webp', 'О движении Земли: планеты на лестнице', 'Юноша в старинной одежде поднимается по библиотечной лестнице, вокруг которой парят большие модели планет и часов.', 'О движении Земли Orb астрономия планеты Сатурн Юпитер библиотека лестница учёный звёзды модель', ARRAY['До новой мысли пришлось подняться сквозь планеты', 'Библиотека незаметно стала вселенной']::text[], 'On the Movements of the Earth: Planets on the Stairs', 'A young man in old-fashioned clothes climbs a library ladder surrounded by floating planet models and clocks.', 'movements earth planets stairs man old-fashioned clothes climbs library ladder surrounded floating planet models clocks orb', ARRAY['A new thought required climbing through the planets', 'The library quietly became a universe']::text[]),
  ('484-pop.webp', 'Магическая битва: чёрный зверь', 'Двое юношей на мокрой улице убегают от огромного теневого чудовища с множеством глаз и зубов.', 'Магическая битва Jujutsu Kaisen Итадори Мэгуми проклятие чудовище много глаз зубы тёмный зверь город дождь', ARRAY['Ночная смена пришла за ними с зубами', 'На этой улице тени смотрят первыми']::text[], 'Jujutsu Kaisen: Black Beast', 'Two young men run down a wet street from a huge shadow creature covered in eyes and teeth.', 'jujutsu kaisen black beast men run wet street shadow creature covered eyes teeth', ARRAY['The night shift came after them with teeth', 'On this street the shadows look first']::text[]),
  ('485-pop.webp', 'Монолог Фармацевта: сад лекарств', 'Девушка в зелёной одежде исследует травы и чай во дворцовом саду, пока мужчина в красном наблюдает из-за дерева.', 'Монолог Фармацевта The Apothecary Diaries Маомао Цзиньши лекарственные травы чай сад дворец зелёная одежда', ARRAY['Одна чашка может выдать весь секрет', 'В саду опять растут ответы на чужие вопросы']::text[], 'The Apothecary Diaries: Medicinal Garden', 'A girl in green examines herbs and tea in a palace garden while a man in red watches from behind a tree.', 'apothecary diaries medicinal garden girl green examines herbs tea palace man red watches tree', ARRAY['One cup could give away the entire secret', 'Answers to other people''s questions grow in the garden again']::text[]),
  ('486-pop.webp', 'Охотник × Охотник: каменная арка', 'Двое мальчиков, в зелёном и фиолетовом, смотрят на огромную каменную арку, уходящую в небо над горами.', 'Охотник × Охотник Hunter x Hunter Гон Киллуа мальчики каменная арка горы мост приключение', ARRAY['Следующее испытание выше всех ожиданий', 'Дорога сама решила стать препятствием']::text[], 'Hunter x Hunter: Stone Arch', 'Two boys in green and purple gaze at a colossal stone arch stretching into the sky above the mountains.', 'hunter stone arch boys green purple gaze colossal stretching sky mountains', ARRAY['The next test is higher than anyone expected', 'The road decided to become the obstacle']::text[]),
  ('487-pop.webp', 'Берсерк: железная башня', 'Воин с огромным мечом стоит перед чудовищной башней из тёмного металла под красным небом.', 'Берсерк Berserk Гатс огромный меч чёрные доспехи чудовищная башня тёмный замок красное небо', ARRAY['Даже башня выглядит голодной', 'Один человек пришёл спорить с целой крепостью']::text[], 'Berserk: Iron Tower', 'A warrior with a massive sword faces a monstrous tower of dark metal beneath a red sky.', 'berserk iron tower warrior massive sword faces monstrous metal beneath red sky', ARRAY['Even the tower looks hungry', 'One person came to argue with an entire fortress']::text[]),
  ('488-pop.webp', 'Моя геройская академия: спасение на улице', 'Мальчик в зелёном героическом костюме летит к падающему автобусу, пока другие школьники и горожане смотрят снизу.', 'Моя геройская академия My Hero Academia Деку Идзуку Мидория герой зелёный костюм автобус спасение школьники', ARRAY['Экзамен начался посреди улицы', 'Когда опоздание превратилось в подвиг']::text[], 'My Hero Academia: Street Rescue', 'A boy in a green hero suit flies toward a falling bus while students and bystanders watch from below.', 'hero academia street rescue boy green suit flies falling bus students bystanders watch', ARRAY['The exam began in the middle of the street', 'Being late suddenly turned into heroism']::text[]),
  ('489-pop.webp', 'Крутой учитель Онидзука: странная лекция', 'Светловолосый учитель с тростью у доски объясняет ученикам сложные знаки, а мотоцикл стоит прямо между партами.', 'Крутой учитель Онидзука GTO Онидзука школьный учитель доска ученики мотоцикл класс урок', ARRAY['Правила дорожного движения внесли в учебник', 'Никто не ожидал такой наглядной лекции']::text[], 'Great Teacher Onizuka: Strange Lesson', 'A blond teacher with a cane explains symbols at the board as a motorcycle stands between classroom desks.', 'great teacher onizuka strange lesson blond cane explains symbols board motorcycle stands between classroom desks gto', ARRAY['Traffic rules made it into the lesson plan', 'Nobody expected quite such a visual aid']::text[]),
  ('490-pop.webp', 'Самурай Чамплу: прыжок с мечом', 'Двое молодых самураев в японском городе прыгают через наклонённый деревянный помост с обнажёнными мечами.', 'Самурай Чамплу Samurai Champloo Мугэн Дзин мечи катаны самураи прыжок японская улица деревянный помост', ARRAY['У этого спора нет ровной площадки', 'Прыжок решили закончить острым аргументом']::text[], 'Samurai Champloo: Sword Leap', 'Two young samurai leap across a slanted wooden platform with drawn swords in a Japanese town.', 'samurai champloo sword leap slanted wooden platform drawn swords japanese town', ARRAY['There is no level ground for this argument', 'They decided to end the leap with a sharp point']::text[]),
  ('491-pop.webp', 'Наследники: спор у стола', 'Несколько нарядных людей тянутся через длинный стол переговоров к папкам и портфелям в стеклянном офисе.', 'Наследники Succession семья Рой корпорация переговоры офис длинный стол папки портфели спор наследство', ARRAY['У кого достанутся документы, решат за столом', 'Семейный обед заменили переговорами']::text[], 'Succession: Argument at the Table', 'Well-dressed people stretch over a long conference table toward folders and briefcases in a glass office.', 'succession argument table well-dressed people stretch conference folders briefcases glass office', ARRAY['The papers will decide who gets what', 'They replaced family dinner with negotiations']::text[]),
  ('492-pop.webp', 'Сага о Винланде: лодка против волны', 'Викинги в деревянной лодке с парусом пытаются пройти мимо огромной рыбы, вынырнувшей из бурного моря.', 'Сага о Винланде Vinland Saga Торфинн викинги драккар деревянная лодка парус море волна гигантская рыба', ARRAY['Морской сосед оказался выше мачты', 'Этот маршрут никто не проверял на размер рыбы']::text[], 'Vinland Saga: Boat Against a Wave', 'Vikings in a wooden sailboat try to pass an enormous fish rising from stormy seas.', 'vinland saga boat against wave vikings wooden sailboat try pass enormous fish rising stormy seas', ARRAY['The neighbor at sea was taller than the mast', 'Nobody checked this route for the size of its fish']::text[]),
  ('493-pop.webp', 'Сага о Винланде: бой на берегу', 'Двое викингов с мечами сходятся на скалистом берегу среди разбитых лодок и бурного моря.', 'Сага о Винланде Vinland Saga Торфинн Аскеладд викинги мечи бой берег лодки шторм', ARRAY['Даже море остановилось посмотреть на спор', 'Остров не выдержал ещё одного поединка']::text[], 'Vinland Saga: Fight on the Shore', 'Two sword-wielding Vikings clash on a rocky beach among broken boats and rough surf.', 'vinland saga fight shore sword-wielding vikings clash rocky beach broken boats rough surf', ARRAY['Even the sea stopped to watch the argument', 'The island could not bear another duel']::text[]),
  ('494-pop.webp', 'Монстр: кукловод над городом', 'Светловолосый человек держит за нити маленькую тёмную фигуру над городом, словно марионетку; рядом висит красный шар.', 'Монстр Monster Йохан Либерт кукловод марионетка нити красный шар город тень психологический триллер', ARRAY['Чужая судьба висит на тонких нитях', 'Тот, кто смотрит сверху, не обязан быть великаном']::text[], 'Monster: Puppeteer Above the City', 'A blond person holds strings attached to a small dark figure over a city like a marionette; a red balloon floats nearby.', 'monster puppeteer city blond person holds strings attached figure like marionette red balloon floats nearby', ARRAY['Someone else''s fate hangs by thin threads', 'The one looking down need not be a giant']::text[]),
  ('495-pop.webp', 'Монстр: врач у весов', 'Врач в зелёной одежде тянется к ребёнку в больничной кровати, пока за ним возвышаются огромные золотые весы.', 'Монстр Monster Кэндзо Тэнма врач хирург больница ребёнок пациент весы выбор жизнь', ARRAY['Одно решение оказалось тяжелее больницы', 'У весов сегодня нет правильного ответа']::text[], 'Monster: Doctor at the Scales', 'A doctor in green reaches toward a child in a hospital bed while giant golden scales tower behind him.', 'monster doctor scales green reaches child hospital bed golden tower him', ARRAY['One choice outweighed the whole hospital', 'The scales have no right answer today']::text[]),
  ('496-pop.webp', 'Губка Боб: Патрик на дне', 'Розовая морская звезда сидит под камнем на песчаном морском дне, держа яркий воздушный шар с игрушечным домиком.', 'Губка Боб SpongeBob Патрик Стар морская звезда камень дом под камнем воздушный шар ананас Бикини Боттом', ARRAY['Самый спокойный сосед устроил праздник под камнем', 'Домашний уют здесь на самом дне']::text[], 'SpongeBob SquarePants: Patrick on the Seafloor', 'A pink starfish sits beneath a rock on the sandy seabed holding a bright balloon with a tiny house.', 'spongebob squarepants patrick seafloor pink starfish sits beneath rock sandy seabed holding balloon tiny house', ARRAY['The quietest neighbor threw a party beneath a rock', 'Home comforts are at the very bottom here']::text[]),
  ('497-pop.webp', 'Наследники: корона под водой', 'Богатые гости в костюмах склоняются с борта яхты к золотой короне, тонущей в прозрачной синей воде.', 'Наследники Succession богатая семья яхта море золотая корона наследство власть бизнес', ARRAY['Главный приз опять ушёл ко дну', 'За властью пришлось перегнуться через борт']::text[], 'Succession: Crown Underwater', 'Wealthy guests in suits lean over a yacht toward a gold crown sinking in clear blue water.', 'succession crown underwater wealthy guests suits lean yacht gold sinking clear blue water', ARRAY['The grand prize sank again', 'They had to lean overboard for power']::text[]),
  ('498-pop.webp', 'Мандалорец: погоня за малышом', 'Воин в металлическом шлеме летит над пустыней к маленькому зелёному существу, пока песчаная машина поднимает пыль.', 'Мандалорец The Mandalorian Дин Джарин Грогу малыш Йода броня шлем реактивный ранец пустыня погоня', ARRAY['Няня прилетела быстрее всех неприятностей', 'Самый ценный пассажир опять уехал вперёд']::text[], 'The Mandalorian: Chasing the Child', 'A helmeted warrior flies over the desert toward a small green creature as a sand vehicle kicks up dust.', 'mandalorian chasing child helmeted warrior flies desert green creature sand vehicle kicks dust', ARRAY['The babysitter arrived faster than trouble', 'The most precious passenger drove away again']::text[]),
  ('499-pop.webp', 'Индиана Джонс: каменный шар', 'Археолог в шляпе бежит из древнего храма от огромного круглого валуна по полу с нарисованной картой.', 'Индиана Джонс археолог шляпа кнут храм ловушка каменный шар валун побег карта сокровище', ARRAY['Сувенир из храма оказался слишком настойчивым', 'Когда история догоняет быстрее тебя']::text[], 'Indiana Jones: Rolling Boulder', 'A hat-wearing archaeologist flees an ancient temple ahead of a huge round boulder across a floor painted with a map.', 'indiana jones rolling boulder hat-wearing archaeologist flees ancient temple ahead round floor painted map', ARRAY['The temple souvenir proved far too persistent', 'When history catches up with you faster than you can run']::text[]),
  ('500-pop.webp', 'Губка Боб: улитка и морская звезда', 'Розовая морская звезда и улитка с разноцветной раковиной стоят возле розового дома в подводном городке.', 'Губка Боб SpongeBob Патрик Стар Гэри улитка морская звезда раковина дом Бикини Боттом под водой', ARRAY['Самые медленные соседи опять собрались у двери', 'Подводный день начинается с розового дома']::text[], 'SpongeBob SquarePants: Snail and Starfish', 'A pink starfish and a snail with a colorful shell stand by a pink house in an undersea town.', 'spongebob squarepants snail starfish pink shell stand house undersea town', ARRAY['The slowest neighbors gathered at the door again', 'An underwater day begins at the pink house']::text[])
